const Map<int, String> _mokhtasarKorean = {
  1000: "알-파티하 (개경장)\n계시분류: 메카\n•    계시 목적:    \n이 장은 하나님의 종복으로서 무슬림은 그분 한 분께만 모든 일의 향배를 맡겨야 함을 강조하고 있다.\n•    요약 주해:    \n명칭과 관련하여:\n이 장이 '개경장'으로 이름 지어진 이유는 하나님의 성서를 여는 첫 번째 장이기 때문이다. 이 장은 '꾸란의 모체' (움물 꾸란) 라는 이름을 지니는데 이 장이 하나님의 유일성, 경배 행위 등 꾸란의 다양한 주제를 담고 있기 때문이다. 개경장은 꾸란의 장들 중에 가장 위대한 장이며, '반복되는 일곱 개’ (앗-사브우 앗-마싸니) 라 불리기도 한다.",
  1001: "하나님의 이름으로 꾸란 낭송을 시작하며, 이는 지고하신 그분께 도움을 요청하고 그분의 이름을 언급함으로써 축복을 구하기 위함이다. '가장 자비로우시고 가장 자애로우신 하나님의 이름으로' (바스말라) 는 하나님의 아름다운 이름들 중 세 가지 이름을 포함하고 있다. 1. '알라' (하나님): 경배받으실 존재 라는 뜻을 지닌다. 이 이름은 하나님의 이름들 중 가장 독특한 이름이며, 완벽하신 하나님 이외에는 그 어떤 존재도 이 이름을 가질 수 없다. 2. '알-라흐만' (가장 자비로우신 분): 드넓은 자비를 지니신, 자비로운 속성을 가지신 분이라는 뜻이다. 3. '알-라힘' (가장 자애로우신 분): 영속적 자비를 지니신 분으로서 창조물 중 그분께서 원하는 이에게, 특히 그분의 종복들 중 믿는 자들에게 자비를 베푸시는 분이라는 뜻이다.",
  1002: "위대함과 완벽함 등 찬미받을 모든 종류의 속성은 오직 그분 한 분 만의 것이다: 그분은 존재하는 모든 것의 주님이시자 창조자이시자 일의 결정자이시기 때문이다. '알-알라문' (존재하는 모든 것, 만유) 은 '알람'의 복수형으로서, 지고하신 하나님 이외의 모든 것을 뜻한다.",
  1003: "이전 구절에서 하나님을 찬미한 후에 다시 한번 그분을 찬양하고 있다.",
  1004: "심판의 날에 있을 그 모든 것의 소유자이신 하나님의 영예를 드높이고 있다. 그날은 그 어떤 인간도 다른 이의 일에 간섭할 수 없다. '야우뭇 딘' (심판의 날) 은 보상과 계산이 이루어지는 날이다.",
  1005: "저희는 오직 당신 한 분만을 위하여 경배 행위와 복종 행위를 실시하며 저희는 당신 이외의 그 어떤 것으로도 당신께 대등한 존재를 두지 않습니다. 그리고 저희는 모든 일상사에 있어 당신 한 분께만 도움을 요청 드립니다. 그 모든 좋은 것은 당신의 손에 달려 있으며 도움을 줄 수 있는 자란 당신 이외에는 없기 때문입니다.",
  1006: "저희에게 올곧은 길을 가르켜 주시고 저희가 그 안에 들게 해주시고 저희가 그 길을 굳건히 걸을 수 있도록 해주시며 저희를 더욱 인도하여 주십시오. '앗-씨라뜨 알-무스타낌' (올곧은 길) 이란 구부러짐이 없는 넓은 길을 의미한다. 즉, 그것은 하나님께서 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 를 보내심으로써 완성하신 이슬람을 뜻한다.",
  1007: "그 길은 당신께서 당신의 종복들 중 은총을 베푸신 자들, 즉 선지자들과 진실된 신앙인들과 순교자들과 선량한 자들 -함께 하기에 참으로 훌륭한 자들- 의 길로서, 유대인들처럼 알면서도 진리를 따르지 않아 당신의 노여움을 산 자들의 길도 아니며 기독교인들처럼 진리 추구와 그 길로 들어서려는 노력에 소홀하여 진리로 인도되지 못하고 방황하는 자들의 길도 아닙니다.",
