  35045: "",
  36000: "야. 신\n계시 분류: 메카\n•    계시 목적    \n이 장은 사도가 받은 메시지와 부활의 날이 진리임을 밝히면서 그에 관한 증거들을 제시하고 있다.\n•    요약 주해",
  36001: "(야.신.) 꾸란의 일부 장들은 이러한 아랍어 문자의 조합(단절 문자)으로 시작한다. 문자의 조합 자체에는 표면적 의미가 없으나 그것이 가진 함의는 분명히 존재한다. 단절 문자에 표면적 의미가 없다 함은, 이러한 문자의 조합 자체로는 아랍인에게 그 어떤 의미도 전달하지 못하기 때문이다. 그럼에도 단절 문자에 함의가 존재하는 이유는, 모든 꾸란 구절에는 반드시 하나님의 지혜가 담겨 있기 때문이다. 단절된 아랍어 문자들이 내포하는 뜻은 아마도, 아랍어로 계시된 꾸란과 유사한 것을 가져와 보라는, 인간에 대한 하나님의 도전적 제안일 것이다. 그렇기에 이러한 단절 문자 뒤에 보통 꾸란과 관련된 사항들이 언급되며, 야신 장에서도 이 사실을 확인할 수 있다.",
  36002: "하나님께서는 꾸란을 두고 맹세하시니, 꾸란의 구절은 완벽한 형태로 계시되었으며 그 어떤 거짓도 꾸란의 앞이나 뒤에서 범접하지 못하노라.",
  36003: "진실로 그대-사도여! -는 하나님께서 사람들에게 보내신 여러 사도들 중의 한 명으로서, 그들에게 유일신 사상을 믿고 하나님 한 분만을 경배할 것을 명하노라.",
  36004: "그대는 올바른 믿음과 훌륭한 체계를 따르고 있노라. 이 믿음 체계는, 감히 누구도 제압하지 못하는 가장 존엄하신 분이시자 믿는 자들에게 가장 자애로우신 분이신 하나님으로부터 내려온 것이라.",
  36005: "그대는 올바른 믿음과 훌륭한 체계를 따르고 있노라. 이 믿음 체계는, 감히 누구도 제압하지 못하는 가장 존엄하신 분이시자 믿는 자들에게 가장 자애로우신 분이신 하나님으로부터 내려온 것이라.",
  36006: "하나님께서 이 길을 내리심은 그대-사도여! - 이전에 어떤 사도도 찾아오지 않아 믿음과 유일신 사상에 신경 쓰지 않았던 아랍인들을 경고하기 위해서라. 또한 이 길은 아랍인들과 유사한 환경에 있었기에, 이전에 경고를 받지 못하여 사도를 필요로 하는 모든 공동체를 위한 것이라.",
  36007: "사도가 전하는 하나님으로부터 진리가 그들에게 이미 도래하였으나 그들은 믿지 않고 불신을 고수하였고, 이에 하나님으로부터의 징벌이 그들에게 의무화 되었노라. 그리하여 그들은 하나님과 그분의 사도를 믿지 않을 것이며, 사도가 가져온 진리를 실천하지도 않을 것이라.",
  36008: "그들에 대한 비유는 마치 목덜미 위에 멍에가 씌여지고 손은 턱 아래로 채워진 자들과 같노라. 이 같은 상태에서 그들은 머리를 내리지 못하고 위로 치켜들 수 밖에 없노라. 그렇게 저들은 하나님에 대한 믿음을 가지지 않고 그분께 순종하지 않으니, 그들은 그분께 머리를 숙일 줄 모르더라.",
  36009: "하나님께서는 그들의 앞에 장막을 두시고 그들의 뒤에도 장막을 두시어 그들이 진리에 도달하지 못하게 하셨노라. 하나님께서는 그렇게 그들의 시각을 덮어버리셨으니 그들은 진리를 인식하지 못하더라. (이러한 조치는 그들이 지속적으로 불신을 고집했기 때문이다. )",
  36010: "진리에 대한 불신을 지속하는 자들은 그대-무함마드여! -가 경고하든 경고하지 않든 변함이 없을 것이니, 그대가 가져온 하나님의 메시지를 믿지 않을 것이라.",
  36011: "그대의 경고가 도움이 되는 자는 꾸란을 믿고 그 메시지를 따르는 자로서, 아무도 없는 곳에 혼자 있을 때도 그는 주님을 두려워하노라. 그대는 이러한 모습을 갖춘 자에게 기쁜 소식을 전할지니, 하나님께서 그의 죄를 용서해 주실 것이며 내세에서의 위대한 보상이 그를 기다릴 것이라. 그에게 주어질 보상은 다름 아닌 천국으로의 입성이라.",
  36012: "진실로 하나님께서는 부활의 날 사람들을 심판하기 위해 죽은 자들을 되살리실 것이라. 또한 그분께서는 사람들이 현세의 삶에서 내놓은 선행과 악행을 기록하시며, 지속되는 희사 (싸다까 자리야) 과 같은 훌륭한 흔적과 불신과 같은 사악한 흔적 등 죽음 후에도 그 영향이 계속되는 그들의 행적을 기록하시노라. 하나님께서는 실로 그 모든 것을 분명한 성서인 보존 서책 (라우흐 마흐푸드) 에 기록하여 두셨노라.",
  36013: "그대-사도여! -는 고집스레 부정하는 저들이 교훈을 얻을 수 있도록 예시를 들라. 그 예시는 한 도시의 거주자들로서, 그들에게 사도들이 찾아왔노라.",
  36014: "하나님께서 그들에게 두 명의 사도를 보내셨노라. 그 둘이 그들에게 유일신 신앙을 믿고 하나님을 경배하라 하였으나 그들은 두 사도를 부정하였노라. 이에 하나님께서는 세 번째 사도를 보내심으로써 기존의 두 사도를 보좌토록 하셨고, 이 세 사도는 도시의 거주민들에게 말하였노라. \"실로 우리 셋은 그대들에게 보내진 사도로서, 그대들은 하나님 한 분만을 믿고 그분의 법을 따르시오\"",
  36015: "도시의 거주민들이 사도들에게 말하였노라. \"그대들은 그저 우리와 같은 인간일 뿐이니 특별난 것도 없소. 가장 자비로우신 하나님께서는 그대들에게 그 어떤 것도 계시한 적이 없으며, 그대들은 단지 하나님께 관해 허위를 꾸미고 거짓 주장을 할 뿐이오\"",
  36016: "세 명의 사도는 도시의 거주민들에게 반박하며 말하였노라. \"우리의 주님께서는 진실로 우리가 그대들-거주민들이여! -에게 보내진 사도임을 알고 계시니, 증거는 그것만으로 충분하오\".",
  36017: "\"우리의 임무는 명령받은 대로 명백하게 메시지를 전달하는 것 뿐이며, 그대들이 인도될지의 여부는 우리 능력 밖의 일이오\"",
  36018: "도시의 거주자들이 사도들에게 말하였노라. \"실로 우리는 그대들로부터 흉조를 보오. 만일 그대들이 유일신 사상으로의 초대를 그만두지 않는다면 우리는 맹세코 돌을 던져 그대들을 죽여버릴 것이며, 우리는 맹세코 그대들에게 고통스런 벌을 내릴 것이라\"",
  36019: "사도들이 반박하며 말하였노라. \"흉조는 그대들과 함께 있으니, 그대들이 하나님을 불신하고 사도들을 따르지 않기 때문이라. 그대들은 하나님을 믿으라는 자에게서 불길한 징조를 발견하는 것인가? 그렇지 않노라. 그대들은 불신과 거역 행위로 도를 지나친 자들이라\"",
  36020: "한 남자가 도시로부터 저 멀리 떨어진 곳에서 서둘러 찾아왔으니, 자신의 백성들이 사도들을 부정하고 그들에게 살해 협박을 가하는 것에 크게 염려함이라. 그가 말하였노라. \"나의 백성들이여. 사도들이 가져온 메시지를 따르라.",
  36021: "\"그대들-나의 백성이여! -은 그들을 따르시오. 그들은 메시지를 전달하는 대가로 그대들로부터 어떠한 보상도 요구하지 않소. 실로 그들은 하나님의 계시를 전하며 올바른 길을 걷고 있으니, 그대들은 그들을 따르시오\"",
  36022: "조언하는 남자가 말하였노라. \"왜 내가 나를 창조하신 하나님을 경배하지 않는단 말인가? 실로 그대들은 부활한 뒤 하나님 한 분께로 돌아가 심판을 받게 될 것이라. 그런데도 그대들은 어찌하여 그대들을 창조하신 주님을 경배하지 않는 것인가?",
  36023: "나를 창조하신 하나님을 제쳐두고 내가 그분이 아닌 다른 것들을 신으로 숭배한단 말인가? 만약 가장 자비로우신 하나님께서 나쁜 것을 의지하실 때, 저 우상들의 중재는 나에게 어떤 도움도 되지 못하니, 저것들은 나를 위해 조금의 효용이나 해악도 통제하지 못하노라. 내가 만약 불신의 상태로 죽는다면 하나님께서 뜻하시는 나쁜 것이 나에게 닥친대도 저것들은 결코 나를 구해줄 수 없노라.",
  36024: "만약 내가 하나님 이외의 것을 숭배하였더라면 진실로 나는 명백한 오류를 범한 것이니, 경배받을 권리가 없는 것을 경배하고, 마땅히 경배받으셔야 할 분은 내가 경배하지 않았기 때문이라.",
  36025: "실로 나는 그대들 -백성들이여! - 모두의 주님이신 하나님을 믿었노라. 그러니 그대들은 나의 말을 들으시오. 그대들은 나를 살해하겠다고 하지만, 나는 그대들의 협박이 두렵지 않소\" 결국 그들은 그를 살해하였고 하나님께서는 그를 천국에 들게 하셨노라.",
  36026: "그가 순교한 뒤 그의 명예를 드높이는 목소리가 들렸노라. \"천국으로 들어가시오\". 결국 그는 천국에 들어갔고, 천국의 온갖 기쁨을 목격한 후에 그는 소망하며 말하였노라. \"나를 부정하고 결국에는 나를 살해하기까지 이르른 저 백성들이 알았더라면 좋았을 텐데! 하나님께서 나를 용서해 주시고 나의 명예를 드높여 주신 사실을 그들이 알았더라면 좋았을 텐데! 내가 믿은 것을 그들이 믿고, 그리하여 내가 얻은 보상을 그들도 얻었더라면 좋았을 텐데! \"",
  36027: "그가 순교한 뒤 그의 명예를 드높이는 목소리가 들렸노라. \"천국으로 들어가시오\". 결국 그는 천국에 들어갔고, 천국의 온갖 기쁨을 목격한 후에 그는 소망하며 말하였노라. \"나를 부정하고 결국에는 나를 살해하기까지 이르른 저 백성들이 알았더라면 좋았을 텐데! 하나님께서 나를 용서해 주시고 나의 명예를 드높여 주신 사실을 그들이 알았더라면 좋았을 텐데! 내가 믿은 것을 그들이 믿고, 그리하여 내가 얻은 보상을 그들도 얻었더라면 좋았을 텐데! \"",
  36028: "하나님께서는 그를 부정하고 살해한 자들을 파멸시키기 위해 하늘에서 어떤 천사의 군대도 내리시지 않으셨노라. 실로 하나님께서는 공동체를 파멸시키기 위해 천사들을 내려보내시는 일이 없노라. 그들의 일은 하나님께 있어 보잘것없기에, 그분께서는 그들의 파멸을 위해 징벌의 천사들을 보내시는 대신 한번의 굉음만을 운명 지으셨노라.",
  36029: "그렇게 그의 백성을 파멸시킨 것은 하나님께서 보내신 단 한번의 굉음 뿐이었노라. 보라, 그들은 이제 흔적도 없이 고꾸라진 자들이 되었노라. 그들의 예는 마치 꺼져버린 장작불과도 같으니, 이 장작에는 그 어떤 불의 흔적도 남아있지 않노라.",
  36030: "불신하던 인간이 심판의 날 징벌을 보게 될 때, 그들에게 들이닥칠 슬픔과 후회는 얼마나 막대한 것인가! 이러한 비통함은, 그들이 하나님의 사도가 찾아올 때면 예외없이 그를 깔보고 조롱했기 때문이라. 그렇게 그들은 하나님에 대한 의무를 소홀히 하였고 그에 대한 결과는 심판의 날에 있을 엄청난 낙담과 슬픔이라.",
  36031: "사도들을 거부하고 조롱하는 자들은 이전의 공동체들로부터 교훈을 얻지 않는가? 그들은 이미 죽은 자들로서 현세로 되돌아오지 못하노라. 오히려 그들은 (내세에서) 자신들이 저지른 행위를 맞닥뜨릴 것이며 하나님께서는 그에 관해 그들을 벌하실 것이라.",
  36032: "그 모든 공동체는 예외 없이 심판의 날에 부활하여 하나님 앞에 소환될 것이며, 그들은 자신들의 행위에 따라 보응을 받게 될 것이라.",
  36033: "죽어있는 불모의 대지는 부활을 부정하는 자들에게 그 부활이 진리임을 알려주는 징표가 되노라. 하나님께서는 대지에 비를 내리시어 그곳에서 각종 식물이 자라나게 하시고 다양한 곡물을 내시어 인간들이 그것을 먹도록 하셨노라. 이처럼 비를 내리어 대지를 살리시고 식물을 내시는 하나님께는 죽은 자들을 살리시고 그들을 부활시키시는 일도 가능한 것이라.",
  36034: "하나님께서는 비가 내린 이 대지에 야자수와 포도 나무로 이루어진 많은 정원을 만드셨고, 이 정원에 물을 길을 수 있도록 여러 샘도 두셨노라.",
  36035: "그리하여 그들이 정원에서 나온 열매를 먹도록 함이니 이는 하나님의 은총으로서, 그들이 일부러 수고해서 얻은 결과물이 아니라. 그러니 그들은 하나님 한 분만을 경배하고 그분의 사도들을 믿음으로써 하나님의 은총에 감사하지 않겠는가?",
  36036: "각종 초목을 자라나게 하시고, 사람을 남성과 여성으로 만드시고, 육지와 바다 등에서 인간이 알지 못하는 것들을 창조하시는 하나님께서는 그 어떤 결함도 없으신 지고하신 분이시라.",
  36037: "사람들에게 하나님의 유일성을 알려주는 징표는 그분께서 빛을 가져가 낮이 떠나가게 하고, 낮이 밤으로부터 벗어날 때 밤이 찾아오게 하는 것이라. 이렇게 하나님께서는 낮이 지나간 후에 어둠이 찾아오게 하시니, 사람들은 이 때부터 어둠을 맞이하노라.",
  36038: "하나님의 유일성을 알려주는 또 다른 징표는 태양이라. 태양은 정착지를 향해 움직이며 정해진 궤도를 벗어나지 않으니, 그 정착지의 실체는 하나님께서 가장 잘 알고 계시노라. 이것이야말로 누구도 감히 제압할 수 없는 가장 존엄하신 분이자 피조물의 모든 일을 알고 계신 분의 섭리라.",
  36039: "하나님의 한 분 되심을 드러내는 또 다른 징표는 달이라. 하나님께서는 매일 밤 달의 모습을 바꾸시니, 작아 보이던 달이 커지고 또 다시 작아지면서 결국에는 마치 구부러지고 오래된 대추야자 열매의 더미와 같이 변하노라. 달과 열매 더미는, 얇고 구부러지고 황색이며 오래된 속성에서 서로 닮았노라.",
  36040: "태양과 달, 낮과 밤이 가진 징표는 하나님께서 지정하신 대로 움직이며 그 지정된 경계를 넘지 않는 것이라. 달이 경로를 바꾼 나머지 태양이 달을 따라잡거나 태양이 달의 빛을 가져가는 일은 없노라. 또한 밤도 자신의 시간이 다하기 전에 낮을 앞서 가 그 안으로 들어가는 법이 없노라. 하나님께서 창조하신 이 별들과 행성들은 이렇듯 자신만의 궤도가 있어 그분께서 지정하신 대로 보호받으며 움직이노라.",
  36041: "하나님의 유일성과 인간에게 내리신 그분의 은총을 드러내는 징표 중의 하나는 하나님께서 노아 시대에 있었던 아담의 자손들을 방주에 실어 그들을 홍수로부터 구해 주신 것이라. 그리고 이 방주는 각종 피조물의 암수로 가득차 있었노라.",
  36042: "하나님의 유일성과 인간에게 내리신 그분의 은총을 드러내는 또 다른 징표는 하나님께서 노아의 방주와 유사한 이동 수단(선박)을 창조하신 것이라.",
  36043: "만약 하나님께서 그들의 익사를 원하셨다면 그들을 익사시키셨을 것이라. 그것은 하나님의 결정이기에 그때는 그 누구도 그들의 구호자가 되지 못하며 그들을 구조해 줄 자는 아무도 없노라.",
  36044: "그러나, 하나님께서 자비를 베푸시어 그들을 익사로부터 보호해 주시고 그들을 육지로 되돌리실 때는 예외라. 그리하여 그들은 정해진 기간 동안 현세의 편의를 누리도록 허락되는데, 이는 그들이 교훈을 얻어 믿음을 가질 기회를 갖기 위함이라.",
  36045: "누군가가 믿음을 거부하는 저 우상 숭배자들에게 \"그대들이 직면하게 될 내세의 혹독함과 곧 사라질 현세에 유의하시오. 그렇게 한다면 하나님께서는 그대들에게 자비를 베푸실 것이오\" 라고 말할 때면 그들은 이 말을 개의치 않고 무시해 버렸노라.",
  36046: "고집을 피우며 부정하는 저 우상 숭배자들에게 하나님의 유일성 및 그분 한 분만이 경배받을 권리가 있음을 드러내는 징표가 도래할 때마다 그들은 어김없이 그 징표에 등을 돌리며 교훈을 얻으려 하지 않았노라.",
  36047: "누군가가 아집을 부리는 이들에게 \"하나님께서 그대들에게 주신 재산으로 가난하고 불우한 자들을 도와주시오\"라고 말할 때면 이들은 이를 거부하면서 믿는 자들에게 응답하며 말하길 \"하나님께서 의지하셨다면 그에게 이미 음식을 주셨을 텐데 왜 우리가 굳이 그에게 음식을 주어야 한단 말이오? 우리는 하나님의 의지에 반하는 행동은 하지 않소. 그대들-믿는 자들이여! -은 진리를 벗어나 저 멀리 방황하고 있을 뿐이오\" 하더라.",
  36048: "부활을 부정하는 자들이 부활은 불가능한 일이라며 말하였노라. “그대들-믿는 자들이여! -은 부활의 날이 올 것이라 주장하는데, 도대체 그날은 언제쯤 오는 것이오? ”",
  36049: "부활은 불가능한 것이라며 부활의 날을 부정하는 자들은 (심판의 날에) 첫번째 나팔 소리가 내는 굉음만을 기다릴 뿐이라. 이 굉음은 그들이 사고 팔며 물을 대고 가축을 먹이는 등 일상의 일을 하고 있을 때에 그들을 급작스레 덮칠 것이라.",
  36050: "갑작스런 굉음이 덮치는 이날 그들은 서로가 서로에게 유언을 하지 못하고 그들의 집이나 기족에게 돌아가지도 못하며 일상의 현장에서 죽음을 맞이할 것이라.",
  36051: "두번째 나팔이 불리어 부활이 시작될 때, 보라, 실로 그들 모두는 신속히 자신의 무덤에서 빠져 나와, 심판과 보응을 진행하실 하나님께로 향하노라.",
  36052: "부활을 부정하며 불신하던 자들이 후회하며 말할 것이라. \"막심한 손실이도다! 우리를 무덤으로부터 부활시킨 자가 누구인가? \" 이에 대답하는 목소리가 들리니 \"이것은 가장 자비로우신 하나님께서 약속하신 것이니, 그분의 약속은 반드시 실현되노라. 사도들은 하나님의 메시지를 전달함에 진실하였도다\" 하더라.",
  36053: "무덤에서의 부활은 그저 두번째 나팔이 내는 단 한번의 굉음의 결과라. 보라, 이제 피조물 모두는 빠짐없이 하나님 앞에 높여 있게 되니, 심판의 날의 계산을 위해서라.",
  36054: "그리하여 그날에는 공정한 판결이 이루어질 것이니, 그대들-종복들이여! -은 그대들의 악행보다 더하여 벌을 받거나 그대들의 선행보다 적게 보상받지 않을 것이라. 그대들은 오직 그대들이 현세의 삶에서 행하던 것으로만 보응을 받을 것이라.",
  36055: "실로 천국의 거주자들은 심판의 날 타인에 대해 생각할 겨를도 없이 영원한 기쁨과 위대한 성공에 열중하면서 행복하고 즐거워할 것이라.",
  36056: "그들과 그들의 배우자들은 천국의 우거진 나무 그늘 밑에서, 침대 위에서 편히 쉴 것이라.",
  36057: "그들은 천국에서 포도, 무화과, 석류 등 각종 맛있는 과일을 먹을 것이며, 그들이 원하는 모든 기쁨과 쾌락을 가질 것이라.",
  36058: "이 모든 기쁨에 더하여 그들은 \"평안하라\"는 말씀을 얻을 것이니, 하나님께서 그들에게 하신 말씀이라. 이 말씀이 전해질 때 그들은 모든 방면에서의 평화를 얻을 것이며, 그들에게 이보다 더 고귀한 인사는 없노라.",
  36059: "부활의 날 우상 숭배자들에게 목소리가 들릴 것이라. \"너희들은 믿는 자들로부터 멀리 떨어지라. 너희들이 그들과 함께 있는 것은 합당치 않으니, 그들이 받을 보상과 너희들이 받을 징벌은 다른 것이며 그들의 속성과 너희들의 속성도 다르노라”",
  36060: "“내가 사도들을 통해 그대들에게 분부하였거늘, 불신과 거역 행위를 저질러 사탄에게 복종하는 없이 없도록 하라 명령하였노라. 사탄은 그대들의 명백한 적이며, 이성을 가진 자는 결코 자신에게 적의를 드러나는 자를 따르지 않노라.",
  36061: "그리고 나는 그대들-아담의 자손들이여! -에게 오직 나만을 경배하며 나에게 대등한 존재를 두지 말 것을 명령하였노라. 나만을 경배하고 나에게 순종하는 자는 나의 기쁨과 천국으로 인도해 주는 올바른 길을 걷는 것이라. 그러나 그대들은 나의 명령과 분부를 어기었노라.",
  36062: "실로 사탄은 이미 그대들 중에서 수많은 이들을 방황시켰노라. 그대들은 이성을 가지고 있지 않았던가? 그 이성이 그대들에게 주님께 순종하고 그분만을 경배하라 명하지 않는 것인가? 그대들의 이성은 그대들의 명백한 적인 사탄을 따르지 말라고 경고하지 않는 것인가?",
  36063: "이것은 너희들이 불신할 경우 들어갈 것을 약속받았던 바로 그 지옥이라. 너희들은 현세에서 지옥을 볼 수 없었으나, 오늘 너희는 지옥을 두 눈으로 직접 목격하고 있노라.",
  36064: "오늘 너희들은 이곳에 들어가 그 뜨거움으로 고통받으라. 이는 그대들이 현세에서 하나님을 불신한 대가라.",
  36065: "그날 하나님께서는 그들의 입을 틀어 막으시니, 그들은 벙어리가 되어 자신들의 불신과 거역 행위를 부정하지 못할 것이라. 대신 그들의 손이 그들이 현세에서 저지른 일을 하나님께 이야기할 것이며, 그들의 발은 그들이 저지르던 악행과 그들이 방문하던 곳을 증언할 것이라.",
  36066: "만약 하나님께서 뜻하셨다면 (내세에서) 그들의 시력을 앗아가시어 그들은 장님이 되었을 것이라. 그리하여 그들은 천국으로 가는 다리 (씨라뜨) 를 건너기 위해 서로 경쟁할 것이나, 그들은 이미 시력을 상실하였기에 그 다리를 건널 수가 없노라.",
  36067: "만약 하나님께서 뜻하였다면 실로 그분께서는 그들의 모양을 바꾸시고 그들을 자신들의 다리 위로 주저앉히셨을 것이라. 그리하여 그들은 자신들이 있던 자리에서 움직이지를 못할 것이니, 앞으로 나아가지도 뒤로 돌아갈 수도 없을 것이라.",
  36068: "하나님께서 누군가에게 긴 수명을 주실 때면 그분께서는 그를 허약했던 이전의 상태로 되돌리시노라. 그러니 그들은 자신이 가진 이성을 사용하여 이 현세가 영원한 거주지가 아님을 이해하지 않을 것인가? 내세의 거주지, 그곳이야말로 영원한 거주지라.",
  36069: "그들은 그가 시인이며 하나님께서 그에게 시를 가르쳤다 주장하노라. 그러나 하나님께서는 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 시를 가르치신 적이 없으며, 그러한 일은 그의 본성이나 경향에도 맞지 않노라. 그가 받은 것은 꾸란으로서 숙고하는 자를 위한 명백한 메시지라.",
  36070: "꾸란이 계시됨은 꾸란을 통해 효용을 얻을 수 있는 자들, 즉 마음이 살아 있고 진리를 볼 수 있는 시각을 가진 자들에게 경고하기 위함이라. 또한 꾸란은 불신자들에 불리한 증거가 되어 그들에 대한 징벌이 실현되는 원인이 되노라. 이는 그들이 꾸란을 믿으라는 말씀을 거부하였기에, 그들에게 어떠한 변명도 남아있지 않기 때문이라.",
  36071: "하나님께서 그들을 위해 가축을 창조해 주셨고, 그 덕분에 그들은 요긴한 대로 가축을 부릴 수 있게 되었노라. 그들은 이를 알지 못하는 것인가?",
  36072: "또한 하나님께서는 그들을 위해 가축을 길들여 놓으시어 그들의 명령에 순응토록 하셨으니, 어떤 종류의 가축은 그들이 등 위에 올라타고 짐을 실으며, 또 다른 종류의 가축은 그들이 식용으로 삼노라.",
  36073: "가축에는 탈 것 혹은 식용으로의 효용이 아닌, 여러 다른 효용도 있노라. 즉, 거래를 통한 이득과 다양한 종류의 털이 그 일부이니, 그대들은 그것으로 깔개와 의복을 만드노라. 또한 그대들은 가축에서 나오는 젖을 음료로 마시노라. 그러니 그들은 하나님께서 그들에게 베푸신 이러한 은총에 감사하지 않겠는가?",
  36074: "우상 숭배자들은 하나님이 아닌 우상들을 숭배하면서, 그것들이 자신들을 도와주고 하나님의 벌로부터 자신들을 구해 줄 것이라 생각하였노라.",
  36075: "그러나 우상들은 자기 자신조차도 돕지를 못하고, 하나님이 아닌 자신들을 숭배하는 자들도 돕지를 못하노라. 우상들과 우상 숭배자들 모두는 (심판의 날) 징벌 앞에 놓이게 되며, 그들은 서로가 서로에게 무고함을 주장할 것이라.",
  36076: "그러니 그대-사도여! -는 \"당신은 사도가 아니라\" \"당신은 시인일 뿐이오\" 등 그들이 내뱉는 허언에 슬퍼하지 말라. 실로 하나님께는 그 무엇도 감추어지지 않기에 그분께서는 그들이 숨기는 행위와 드러내는 행위 모두를 알고 계시며, 하나님께는 이에 의거하여 그들을 심판하실 것이라.",
  36077: "죽음 후에 있을 부활을 부정하는 인간은 숙고하지 않을 것인가? 하나님께서는 그를 정액으로부터 창조하시고 그 후 다양한 단계를 거쳐 결국 그가 태어나고 자라나게 하시노라. 그 후 그는 논쟁을 일삼는 자로 변모하였노라. 그는 그렇게 논쟁을 자주 벌이면서도, 부활이 실현될 것이라는 사실은 깨닫지 못하더라.",
  36078: "이 불신자는 썩어 있는 뼈를 근거로 부활이 불가능함을 논증하려 하나, 실제로 그는 무지한 자일 뿐이라. 그가 \"이 뼈를 누가 되살린단 말인가? \" 라고 말하나, 정작 자신이 무에서 창조되었음은 기억하지 못하노라.",
  36079: "그대-무함마드여! -는 그에게 대답하며 말하라. \"썩어 있는 뼈는 그것을 처음에 창조하신 하나님께서 살리실 것이라. 무에서 유를 창조하신 분께는 창조를 되풀이하는 일이 어렵지 않노라. 그분께서는 모든 창조에 대해 알고 계시는 분이며 그분께는 그 무엇도 감추어지지 않노라”",
  36080: "하나님께서는 그대들-사람들이여! -을 위해 촉촉하고 푸른 나무에 불을 두셨으니 그대들이 그것을 꺼내 사용하기 위함이라. 보라, 이제 그대들은 이 나무로부터 불을 지피노라. 이처럼 물기 있는 푸르른 나무로부터 불을 만드시는 분께서는 죽어있는 자를 살리는 일도 가능하노라.",
  36081: "엄청난 크기의 (일곱) 하늘과 땅을 창조하신 분이야말로 죽어 있는 인간을 살리는 능력을 갖춘 분이 아니시던가? 진정 그러하노라. 하나님께서는 모든 피조물을 창조하신 분이시며 피조물의 모든 것을 알고 계신 분이시기에 그분께는 그 무엇도 감추어지지 않노라.",
  36082: "하나님께서는 무엇이 있기를 원하실 때 그분께서는 단지 그것에 \"있어라\"라고 말씀하실 뿐이며 이에 그것이 있게 되니, 이것이야말로 완벽하신 하나님의 위엄이라. 하나님께서 죽이시고 살리시며 부활시키는 일 역시도 이와 마찬가지라.",
  36083: "우상 숭배자들은 감히 하나님께 무능함을 부여하나, 모든 것의 주권은 그분의 손에 있노라. 하나님께서는 원하시는 대로 결정하시며 그분께는 모든 것의 열쇠가 있도다. 그대들은 실로 내세에서 하나님 한 분께로 돌아가게 될 것이며, 그분께서는 그대들의 행위에 의거하여 보응하실 것이라.",
  37000: "앗-쌋파트 (대열을 지은 천사들)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님과 관련하여 우상 숭배자들이 부여하는 잘못된 속성들을 부정하는 한편, 그들이 가지고 있는 천사들과 진 (Jinn) 들에 관한 미신이 허위임을 밝히고 있다.\n•    요약 주해",
  37001: "하나님께서는 당신을 경배하기 위해 어깨를 맞대고 촘촘히 줄 지은 천사들을 두고 맹세하시고",
  37002: "하나님께서 원하시는 방향으로 구름을 내몰고 가는 천사를 두고 맹세하시며",
  37003: "하나님의 말씀을 낭송하는 천사들을 두고 맹세하시니",
  37004: "진실로 그대들이 경배해야 할 존재는 그 어떤 것도 견줄 데 없는 하나님 오직 한 분이라.",
  37005: "그분께서는 (일곱) 하늘과 땅 그리고 그 사이에 존재하는 것을 소유하신 주님이시며, 일년 내내 해가 뜨고 지는 장소들을 소유하신 주님이시라.",
  37006: "진실로 하나님께서는 지구에서 가장 가까운 하늘을 보석처럼 빛나는 별들로써 아름답게 꾸미셨으며",
  37007: "그분께서는 그 별들로써 불복을 일삼는 사탄들을 격퇴하여 그들로부터 현세의 하늘을 보호하셨노라.",
  37008: "하늘에 있는 천사들이 하나님께서 자신들에게 계시한 법률과 운명 등에 관해 이야기할 때 사탄들은 그들의 대화 내용을 들을 수 없으며, (그러한 시도가 있을 때) 사탄들은 모든 방면에서 쏟아지는 별똥별에 직면할 것이라.",
  37009: "이는 그들의 도청을 막는 격퇴와 추방이라. 또한 그들은 내세에서 끊이지 않는 고통의 벌을 받을 것이라.",
  37010: "그러나 가끔씩 사탄들 중에는 지구의 거주자들이 알지 못하는, 천사들이 나누는 대화의 일부 내용을 가로채는 자들이 있노라. 그 때는 빛나는 별똥별이 그들을 불태우지만 그들 중에는 별똥별을 맞기 전에, 그 가로챈 정보를 지구에 있는 사탄의 일당에게 보내기도 하노라. 이를 받은 무당은 그것에 백 개의 거짓을 보태 사람들에게 점을 치는 것이라.",
  37011: "그러니 그대-무함마드여! -는 부활을 부정하는 그들에게 질문해 보라. 강력함과 거대함을 봤을 때, 인간을 창조하는 것과 일곱 하늘과 지구와 천사들을 창조하는 것 중 어느 것이 더 어려운가? 하나님께서는 (최초의) 인간을 끈적한 진흙으로부터 창조하셨노라. 이렇게 미약한 피조물인 진흙으로부터 창조되었음에도 그들은 어떻게 감히 부활을 부정하는 것인가?",
  37012: "그러나 그대-무함마드여! -는 하나님의 위대한 창조 능력에 놀라워 하고, 부활을 부정하는 우상 숭배자들의 모습에도 놀라워 하노라. 반면 저 우상 숭배자들은 부활을 극렬히 부정하면서, 부활에 관한 그대의 말을 조롱하고 있노라.",
  37013: "저 우상 숭배자들에게 교훈이 전달되어도 그들은 그 교훈을 떠올리지 않고 그로부터 효용을 취하지도 않으니, 그들의 마음이 딱딱히 굳어 있기 때문이라.",
  37014: "그들에게 선지자의 진실성을 알리는 징표가 도래할 때마다 그들은 크게 비웃으며 조롱하더라.",
  37015: "그들이 말하노라. \"무함마드가 가져온 이것은 그저 속임수 강한 주술에 불과하오.",
  37016: "우리가 죽은 후에 흙과 썩어버린 뼛조각이 되었는데도 정녕코 우리가 다시 살아난단 말인가? 헛된 소리라.",
  37017: "이미 옛날에 죽은 우리의 조상들도 부활한단 말인가? \"",
  37018: "그대-무함마드여! -는 그들에게 대답하며 말하라. \"그렇소. 그대들이 흙이 되고 썩어버린 뼛조각이 된 후에 그대들은 부활할 것이며, 그대들의 옛 조상들도 부활할 것이오. 그대들 모두는 부활할 것이며, 그 때 그대들은 모욕과 능멸을 당할 것이오\"",
  37019: "실로 (두번째) 나팔 소리는 단 한 번의 굉음일 뿐이라. 보라, 이제 그들은 심판의 날의 무서움을 목격하고 있으며, 자신들에 관한 하나님의 처분을 기다리고 있노라.",
  37020: "부활을 부정하던 우상 숭배자들이 말할 것이라. \"우리는 망해버렸구나! 오늘은, 하나님께서 종복들의 행위를 심판하신다는 바로 그 심판의 날이구나\"",
  37021: "이에 목소리가 들릴 것이라. \"이날은 그대들이 부정해 오던 날로서, 인간을 판결하여 분리하는 날이라\"",
  37022: "그날 천사들에게 목소리가 들릴 것이라. \"하나님께 대등한 존재를 두어 부당함을 저지르던 우상 숭배자들과, 그들의 거짓말을 도우며 우상 숭배와 유사한 죄를 저지르던 자들과, 그들이 숭배하던 것들을 한 곳으로 모으라. 그들은 하나님이 아닌 것들을 숭배하였노라. 그러니 그들에게 불지옥으로 향하는 길(시라뜨)을 보여주고 그들을 불지옥으로 유인하여 끌고 가라. 그들의 거처는 지옥이라”",
  37023: "그날 천사들에게 목소리가 들릴 것이라. \"하나님께 대등한 존재를 두어 부당함을 저지르던 우상 숭배자들과, 그들의 거짓말을 도우며 우상 숭배와 유사한 죄를 저지르던 자들과, 그들이 숭배하던 것들을 한 곳으로 모으라. 그들은 하나님이 아닌 것들을 숭배하였노라. 그러니 그들에게 불지옥으로 향하는 길(시라뜨)을 보여주고 그들을 불지옥으로 유인하여 끌고 가라. 그들의 거처는 지옥이라”",
  37024: "“그들을 불지옥으로 집어넣기 전에, 심판을 위해 그들을 멈춰 세우라. 그들은 질문받을 것이라. 그 후에 그대들은 그들을 지옥 안으로 몰고 가라\"",
  37025: "그들을 질책하는 목소리가 들리노라. \"너희는 현세에서 서로가 서로를 도우며, 너희의 우상들이 너희를 도와줄 것이라 헛된 확신을 가졌노라. 그러나 지금은, 현세에서 했던 것처럼 너희가 서로를 도울 수가 없으니, 어떻게 된 일인가? \"",
  37026: "실제로 그들은 해결책을 가지지 못한 무능력한 자들로, 서로를 도울 수가 없노라. 이날 그들은 굴복하여 하나님의 명령에 철저히 복종하는 자들이 될 것이라.",
  37027: "그들은 서로를 비난하고 논쟁하면서 서로가 서로를 바라보나, 그들의 상호 비난과 논쟁은 소용이 없노라.",
  37028: "추종하던 자들이 추종 받던 자들에게 말할 것이라. \"실로 그대들-높은 지위를 가졌던 자들이여! -은 종교와 진리를 가장하여 우리에게 다가오곤 했소. 그대들은 우리에게 불신과 거역과 하나님께 대등한 존재를 두는 행위를 좋은 것이라 치장했고, 우리가 하나님의 사도들이 가져온 진리로부터 도망치도록 조장하였소\"",
  37029: "추종 받던 자들이 추종하던 자들에게 말할 것이라. \"그대들이 추측하는 것은 사실이 아니오. 그대들은 불신을 따랐고 믿는 자들이 아니었으며, 실제로 그대들은 부정하는 자들이었소\"",
  37030: "\"우리는 그대들에게 불신과 우상 숭배, 거역 행위 등을 강제할 능력을 가지고 있지 않았으며, 오히려 그대들 스스로가 불신과 방황의 경계를 넘어섰던 것이오\"",
  37031: "\"그렇게 우리와 그대들에게는 하나님의 경고 (\"진실로 나 (하나님) 는 너 (사탄) 와, 그들 중에서 너를 따르는 자들 그 모두로써 지옥을 가득 채울 것이라\". 싸드 장, 85절) 가 실현되었소. 우리는 필연코 주님께서 경고하신 그 징벌을 받게 될 것이오\"",
  37032: "\"그렇게 우리는 그대들을 방황과 불신으로 초대하였소. 진실로 우리는 올바른 길을 벗어난 자들이었소\"",
  37033: "그리하여 실로 추종하던 자들과 추종 받던 자들은 심판의 날에 벌을 함께 나눌 것이라.",
  37034: "실로 하나님께서는 저들에게 징벌을 맛 보게 하셨고, 마찬가지로 그들 이외에 악행을 저지르는 자들도 동일한 방법으로 벌하실 것이라.",
  37035: "실로 우상 숭배자들은 현세에서 \"하나님 이외에는 경배받을 존재가 없노라\"라는 말을 듣고, 그 메시지를 실천하면서 그에 반대되는 것을 그만두라 했을 때 그들은 이에 순종하지 않고 거부하였으니, 거만을 떨며 진리를 내치었노라.",
  37036: "불신을 옹호하는 자들이 말하였노라. \"한낱 미친 시인 (무함마드) 이 하는 말 때문에 우리가 우상 숭배를 그만둔단 말이오? \"",
  37037: "그들은 엄청난 거짓을 지어낸 것이라. 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 는 미친 자가 아니며 시인도 아니라. 그가 가져온 것은 꾸란으로, 그것은 사람들을 하나님의 유일성으로 초대하면서 하나님의 사도를 따라야 함을 알리고 있노라. 이전에 도래했던 하나님의 사도들은 유일신 신앙과 심판의 날을 알렸고, 사도 무함마드는 그들의 메시지 어느 것도 이의를 제기하지 않노라.",
  37038: "진실로 너희-우상 숭배자들이여! -는 심판의 날 고통스런 벌을 맛 볼 것이니, 너희가 저지른 불신과 사도들에 대한 부정 때문이라.",
  37039: "너희-우상 숭배자들이여! -는 오직 너희가 현세에서 저질렀던 하나님에 대한 불신과 거역 행위로 말미암아 벌을 받는 것이라.",
  37040: "그러나 하나님께서 선택하신 믿는 자들은 경배를 위해 선택받은 자들로서, 그들은 하나님만을 진실되게 경배하노라. 그들은 저러한 고통으로부터 안전한 곳에 있을 것이라.",
  37041: "하나님께서는 저 진실된 종복들에게 맛있고 보기 좋으며 상하지 않는 음식을 베푸실 것이니",
  37042: "그들이 원하는 맛있는 각종 과일이 주어질 것이라. 거기에 더하여 그들은 명예로운 대접을 받을 것이니, 그들은 천국에서의 단계가 상승할 것이며 하나님의 얼굴을 보는 영광을 얻을 것이라.",
  37043: "이 모든 것은 영원한 기쁨의 장소인 천국에서 얻을 것이며, 그곳에서의 즐거움은 멈추거나 사라지는 일이 없도다.",
  37044: "그들은 침대에 몸을 기댄 채 서로가 서로를 마주 보노라.",
  37045: "흐르는 물과 같은 술로 가득한 술잔이 그들을 맴도니",
  37046: "담겨진 술은 흰 색으로, 이 술을 마시는 자는 그 진미를 만끽하노라.",
  37047: "그 술은 현세의 술과는 달라서, 취해서 이성을 잃거나 두통이 찾아오지 않으며, 술을 즐기는 그들의 육체와 정신은 온전하노라.",
  37048: "천국에 거주하는 그들에게는 자신의 배우자만을 바라보는, 아름다운 눈을 가진 정숙한 여성들이 있으니",
  37049: "옅은 갈색기가 돌면서도 햐얀 색 피부를 가진 그녀들은 마치 그 어떤 손도 거치지 않은 잘 보존된 새알과도 같더라.",
  37050: "천국의 거주자들은 현세에서 자신의 처지가 어떠했는지 질문을 주고 받으며 서로가 서로를 바라보더라.",
  37051: "믿는 자들 중에서 누군가가 말하노라. \"실로 제가 현세에 있을 때 부활을 부정하는 친구가 한 명 있었습니다\"",
  37052: "\"그가 부정하며 비꼬듯 나에게 말하였습니다. '그대-친구여! -는 정녕코 죽은 자들이 부활함을 확신하는 것이오? '",
  37053: "'우리가 죽으면 흙이 되고 썩은 뼈다귀가 되는데, 정말로 우리가 부활하여 현세에서의 행위를 심판받는단 말이오? '\"",
  37054: "믿는 자가 자신과 함께 있는 천국의 거주자들에게 말하노라. \"부활을 부정하던 저의 친구가 어떻게 되었는지 그대들이 저와 함께 한번 들여다보시겠습니까? \"",
  37055: "그리하여 그가 들여다보았으니, 자신의 친구가 작열하는 불지옥의 한가운데에 있음을 보았노라.",
  37056: "그가 말하노라. \"하나님께 맹세코! 너-친구여! -는 나를 불신으로 초대하고 내가 부활을 부정하도록 하여 나를 불지옥으로 집어넣을 참이었구나\"",
  37057: "\"하나님께서 은총을 베푸시어 나를 신앙으로 인도해주지 않으셨더라면, 나는 너처럼 징벌 앞에 놓인 자가 되었을 것이라\"",
  37058: "지옥의 거주자인 친구에게 말을 끝낸 후 그는 자신의 동료인 천국의 거주자들에게 말하노라.  \"그러나 우리에게는 더 이상의 죽음이 없는 것이지요? \"",
  37059: "\"물론 현세에서 있었던 우리의 첫번째 죽음은 제외하고 말입니다. 그리고 불신자들은 벌을 받지만, 우리는 벌 받지 않을 것이지요? \"",
  37060: "\"우리의 주님께서 우리를 천국에 들게 해주시고, 그곳에서 영원히 머물게 해주시며, 불지옥의 고통으로부터 우리를 보호해 주시니, 진정 이것이야말로 그 무엇과도 비교되지 않는 가장 위대한 성공입니다\"",
  37061: "선행을 행하는 자들은 이와 같은 위대한 성공을 위해 선행을 실천하라. 이것이야말로 이익을 가져오는 진정한 거래라.",
  37062: "진실되게 경배하는 종복을 위해 하나님께서 준비하신 저 은총이 더 명예로운 것인가, 아니면 꾸란에 언급된 저주받은 작꿈 나무가 더 명예로운 것인가? 그 열매는 (내세에서의) 불신자들의 먹거리로, 자양분이 없으며 허기를 채워주지도 못하노라.",
  37063: "실로 하나님께서는 작꿈 나무를 시험으로 두셨으니, 불신과 거역 행위로 부당함을 저지르는 자들을 위한 시험이라. 그들이 말하더라. \"불은 나무를 태우니, 불지옥에 나무가 자랄 리 만무하오\"",
  37064: "실로 작꿈 나무는 더럽고 냄새나는 나무로, 작열하는 불지옥의 밑바닥에서 자라나는 나무라.",
  37065: "이 나무에서 나오는 열매는 소름 끼치는 형상을 가졌으니 그것은 마치 사탄들의 머리통과도 같노라. (흉악한 모습은 흉악한 실체를 드러내며, 그 열매의 맛이 매우 역겨움을 암시한다. )",
  37066: "진실로 불신자들은 작꿈 나무의 추악하고 쓰디쓴 열매를 먹을 것이며 그것으로 그들의 텅 빈 배를 채울 것이라.",
  37067: "그들은 작꿈 나무의 열매를 먹은 뒤에 실로 역겹고 뜨거우면서도 잡스런 음료를 마실 것이라.",
  37068: "그 후 진실로 그들은 작열하는 불지옥의 고통으로 되돌아갈 것이니, 그렇게 그들은 고통에서 고통으로 전전하노라.",
  37069: "실로 불신자들은 진리에서 벗어나 방황하는 자신들의 조상을 발견하였고, 그들은 근거도 없이 조상들을 맹목적으로 추종하였노라.",
  37070: "그렇게 그들은 방황하는 조상의 자취를 서둘러 따랐노라.",
  37071: "실로 그들 이전에 이미 대부분의 옛날 사람들이 방황하였으니, 그대-사도여! -의 백성이 최초로 방황한 것이 아니라.",
  37072: "실로 하나님께서는 이전의 공동체들에게 하나님의 벌을 경고하는 사도들을 보내셨으나 그들은 불신하였노라.",
  37073: "그러니 그대-사도여! -는, 사도로부터 경고를 받았으나 그 경고를 무시한 자들의 최후가 어떠했는지를 생각해 보라. 그들은 사도들을 불신하고 부정하였기에 결국 지옥으로 들어가게 되었노라.",
  37074: "그러나 하나님께서 신앙을 위해 선택해 주신 종복들은 예외로서, 그들은 불신자들이 겪을 고통으로부터 자유로우니라.",
  37075: "노아는 자신을 부정한 백성들에게 대항하여 하나님께 기도하였고, 이에 하나님께서는 그의 기도를 지체없이 들어주셨노라.",
  37076: "하나님께서는 노아와 그의 가족과 그와 함께 한 신앙인들을 불신자들의 해악으로부터 보호해 주셨고, 불신자들이 직면했던 대홍수로부터 그들을 구해 주셨노라.",
  37077: "하나님께서는 노아의 가족과 그를 따르던 신앙인들을 구해주셨으나, 노아의 백성 중에 불신하는 자들은 익사시키셨노라.",
  37078: "하나님께서는 이후에 있을 공동체가 그를 칭송할 수 있도록 그를 위한 훌륭한 언급을 남기셨노라.",
  37079: "노아는 이후에 있을 공동체가 그에 관해 부정적인 말을 하지 않도록 보호받으며, 그에 대한 칭송과 칭찬의 말을 지속할 것이라.",
  37080: "하나님께서는 당신을 위해 경배하고 순종하는 자에게, 노아에게 베푸신 보상과 유사한 방식으로 보상을 베푸시노라.",
  37081: "실로 노아는 하나님께 순종하며 믿음을 가졌던 하나님의 종복들 중의 하나였노라.",
  37082: "그 후 하나님께서는 그들 (불신자들)에게 대홍수를 일으키시어 그들을 익사시켰으니 그들 중의 누구도 살아남지 못했노라.",
  37083: "진실로 노아가 초대한 유일신 신앙에 동의하여 그와 같은 종교를 믿었던 자는 아브라함이라.",
  37084: "기억하라. 그는 그 어떤 형태로도 자신의 주님께 대등한 존재를 두지 않는 온전한 마음으로 하나님께로 왔노라. 그는 하나님의 길에서 사람들이 잘 되길 바랐노라.",
  37085: "아브라함은 우상을 숭배하는 아버지와 사람들을 비판하며 말하였노라. \"여러분은 하나님 이외에 무엇을 숭배하는 것입니까? \"",
  37086: "\"여러분은 정녕 하나님이 아닌 가짜 신들을 원하는 것입니까? \"",
  37087: "\"그렇다면 만유의 주님에 관해 여러분은 어떻게 생각하십니까? 여러분은 그분을 만날 때에 그분 이외의 것을 숭배하고 있을 텐데, 그분께서 여러분을 어떻게 하실 것이라 보십니까? \"",
  37088: "그 후 아브라함은 사람들로부터 빠져나오기 위한 방책을 생각하면서 하늘을 지그시 바라보았노라.",
  37089: "그는 사람들과 함께 그들의 축제 장소로 나가지 않으려 \"제가 몸이 좀 아픕니다\" 라고 말하였노라.",
  37090: "이에 그들은 그를 뒤로 내버려둔 채 길을 떠났노라.",
  37091: "그리하여 그는 그들이 숭배하는 우상들에게로 곧장 가서 야유하면서 말하였노라. \"우상 숭배자들이 너희들을 위해 음식을 준비했는데 왜 너희들은 먹지를 않는가? \"",
  37092: "\"어찌하여 너희들은 말도 못하고 질문에 답도 하지 못하는 것인가? 우리가 하나님을 제쳐두고 이러한 것들을 숭배해야 한단 말인가? \"",
  37093: "그리하여 그는 그들의 우상들에게로 다가가 오른손으로 타격하여 그것들을 부수어 버렸노라.",
  37094: "이에 이 우상을 숭배하던 자들은 후다닥 방향을 바꿔 그에게로 향하였노라.",
  37095: "이에 아브라함은 그들을 굳건히 맞섰으며, 그들을 비판하며 말하였노라. \"여러분은 하나님이 아닌, 여러분 자신의 손으로 만든 조각상을 신으로 숭배하는 것입니까? \"",
  37096: "\"하나님께서 여러분을 창조하셨고, 여러분의 행위를 창조하셨으며, 이 우상들도 결국은 여러분의 행위로 나온 피조물입니다. 그렇기에 경배받을 권리는 오직 하나님 한 분께만 있으며, 그분께는 어떠한 대등한 존재도 없습니다”",
  37097: "그들은 논리로써 그를 이겨낼 수 없었고, 결국에는 무력에 의존하기로 하였노라. 그들은 아브라함을 어떻게 처리할 것인지 의견을 나누며 말하였노라. \"그에게 구조물을 만들어 그 안에 장작을 채운 뒤, 불을 지르고 그 안에 아브라함을 던져 넣으시오\"",
  37098: "그렇게 그들은 성가신 아브라함을 없애 버리려 계략을 꾸몄으나 하나님께서는 그들을 실패자로 전락시키셨으니 (그들이 지핀) 불을 (아브라함을 위해) 서늘하고 안전한 것으로 바꾸셨노라.",
  37099: "아브라함이 말하였노라. \"실로 나는 하나님을 제대로 경배하기 위해 내 마을을 떠나 주님께로 향합니다. 하나님께서는 현세와 내세에서 나에게 좋은 것을 가리켜 주실 것입니다\".",
  37100: "\"저의 주님이시여! 저에게 선량한 아이 하나를 자식으로 주시어, 그 아이가 사람들을 떠나 홀로 있는 저에게 보상과 도움이 되도록 해주십시오\"",
  37101: "이에 하나님께서는 그에게 태어날 아들에 대한 기쁜 소식을 알려 주셨노라. 그는 자라서 인내심 강한 자가 될 것이니, 이 아들은 다름 아닌 이스마엘이라.",
  37102: "그리하여 이스마엘이 소년으로 성장하여 아버지 아브라함과 유사한 기력을 갖추었을 때 그의 아버지는 꿈을 꾸었노라. 선지자들의 꿈은 계시의 일종으로, 그는 아들에게 꿈의 내용을 알려주며 말하였노라. \"사랑하는 아들아. 실로 나는 꿈에서 내가 너를 희생물로 바치는 것을 보았는데, 너의 생각은 어떠하니? \" 이스마엘이 아버지께 대답하며 말하였노라. \"아버지! 하나님께서 명령하신 대로 저를 바치십시오. 당신께서는 곧 -하나님께서 원하신다면- 제가 하나님의 운명에 인내하고 만족하는 자임을 발견하실 것입니다\"",
  37103: "그리하여 아버지와 아들은 하나님의 명령에 순종하였고, 아브라함은 아들의 한쪽 이마를 땅에 대어 그를 희생할 준비를 하였노라.",
  37104: "그렇게 아브라함이 하나님의 명령을 실행하기 위해 자신의 아들을 희생시키려 할 때 하나님께서는 그를 부르셨노라. \"아브라함아\"",
  37105: "\"아들을 바치려 굳게 결심하였으니 그대는 이미 꿈을 실천에 옮긴 것과 다름없노라. 내가 그대를 이 위대한 시험으로부터 구해준 것처럼 나는 최선을 다하는 자들을 시험과 시련으로부터 구해주노라\"",
  37106: "진실로 이것이야말로 분명한 시험으로, 아브라함은 이 시험을 통과하였노라.",
  37107: "하나님께서는 커다란 양을 보내시어 이스마엘의 희생을 대신하셨노라.",
  37108: "하나님께서는 이후에 있을 공동체가 아브라함을 칭송할 수 있도록 그를 위한 훌륭한 언급을 남기겼노라.",
  37109: "아브라함은 하나님의 가호로써 모든 종류의 해악과 재앙으로부터 안전할 것이라.",
  37110: "하나님께서는 당신을 경배하고 순종하는 자에게, 아브라함에게 베푸신 보상과 유사한 방식으로 보상을 베푸시노라.",
  37111: "실로 아브라함은 믿음을 가지고 하나님의 종복으로서 그 의무를 다한 자들 중의 하나였노라.",
  37112: "하나님께서는 아브라함에게 또 다른 아들이 태어날 것이라는 기쁜 소식을 주셨고, 그 아들은 선지자이자 선량한 종복이 될 것이라 알려주셨노라. 그 아들의 이름은 바로 이삭 (이스학) 으로 그는, 하나님께 순종하며 자신의 외동 아들인 이스마엘을 바치려 한 아브라함에 대한 보상이었노라.",
  37113: "하나님께서는 아브라함과 이삭에게 축복을 내리셨고 그들에게 은총을 더하셨노라. 그리하여 그들에게는 많은 후손이 있었고, 그들의 후손 중에는 하나님을 경배함에 최선을 다하는 자들이 있고, 반면 불신과 거역 행위 등 명백한 방식으로 자신을 부당히 대하는 자들도 있노라.",
  37114: "진실로 하나님께서는 모세와 아론 (하룬) 에게 선지자직의 은혜를 베푸셨노라.",
  37115: "그리고 하나님께서는 파라오의 박해과 홍해의 익사로부터 모세와 아론 및 그들의 백성인 이스라엘의 자손들을 구해 주셨노라.",
  37116: "하나님께서는 파라오와 그의 군대에 대항하여 그들을 도와주셨고, 이에 그들은 적들을 압도하였노라.",
  37117: "그리고 하나님께서는 모세와 그의 형 아론에게 토라를 주셨노라. 이 토라는 하나님으로부터 온 것으로, 의심의 여지가 없는 명백한 성서라.",
  37118: "하나님께서는 모세와 아론을 구부러짐이 없는 올바른 길로 인도하셨으니, 이 길은 창조주의 기쁨으로 인도하는 이슬람의 길이라.",
  37119: "하나님께서는 이후에 있을 공동체가 모세와 아론을 칭송할 수 있도록 그들을 위한 훌륭한 언급을 남기겼노라.",
  37120: "하나님께서는 모세와 아론을 훌륭히 칭송하시고, 모든 종류의 해로부터 그 둘을 안전히 보호하시노라.",
  37121: "하나님께서는 당신을 경배하고 순종하는 자에게, 모세와 아론에게 베푸신 보상과 유사한 방식으로 보상을 베푸시노라.",
  37122: "실로 모세와 아론은 하나님의 법률을 따르며 믿음을 가졌던 하나님의 종복들 중의 하나였노라.",
  37123: "진실로 엘리야 (일야스) 는 주님께서 보내신 여러 사도들 중의 한 명으로서, 하나님께서는 그에게 사도직과 선지자직을 부여하셨노라.",
  37124: "기억하라. 엘리야는 이스라엘의 자손들에게 보내진 사도로서, 그들에게 말하였노라. \"하나님께서 명령하신 유일신 사상 등을 지키고 우상을 숭배하지 않는 등 하나님께서 금지하신 것을 멀리하라. 이것이 하나님을 경외하는 방법이거늘 어찌하여 그대들은 이를 따르지 않는 것인가? \"",
  37125: "\"그대들은 하나님이 아닌 우상 \"바알\"을 숭배하고, 가장 훌륭한 실행자이신 하나님을 내버려 두는 것인가? \"",
  37126: "\"하나님께서는 그대들을 창조하신 주님이시자 그대들의 옛 조상들의 주님이시라. 그러하니 오직 하나님만이 경배받을 권리를 지니시며, 유용함도 해악도 끼치지 못하는 우상들은 경배의 대상이 될 수 없노라\"",
  37127: "그러나 그들 모두는 예외 없이 엘리야 (일야스) 를 부정하였고 이로 인해 그들은 징벌에 노출될 것이라.",
  37128: "그러나 그의 백성들 중에서 진실되게 하나님을 경배하는 자들은 예외로서, 그들은 징벌 앞에 놓이지 않고 안전할 것이라.",
  37129: "하나님께서는 이후에 있을 공동체가 엘리야를 칭송할 수 있도록 그를 위한 훌륭한 언급을 남기겼노라.",
  37130: "엘리야에게 하나님의 칭송이 있을지라.",
  37131: "하나님께서는 당신을 경배하고 순종하는 자에게, 엘리야 에게 베푸신 보상과 유사한 방식으로 보상을 베푸시노라.",
  37132: "실로 엘리야는 하나님께 순종하며 믿음을 가졌던 하나님의 종복들 중의 하나였노라.",
  37133: "진실로 롯은 주님께서 보내신 여러 사도들 중의 한 명으로서, 사도들은 그들의 백성들에게 기쁜 소식을 전하고 닥쳐올 징벌을 경고하였노라.",
  37134: "기억하라. 하나님께서는 롯의 백성들에게 보내진 징벌로부터 롯과 그의 가족 모두를 구해 주었으나",
  37135: "롯의 아내는 예외로서, 그녀는 롯의 백성들과 같은 불신자였기에 결국 징벌이 그녀를 덮쳤노라.",
  37136: "그 후, 하나님께서는 남아 있던 롯의 백성들을 파멸시키셨노라. 이는 롯의 백성들이 그를 부정하고 그가 가져온 메시지를 거부하였기 때문이라.",
  37137: "진실로 그대들-메카의 거주민들이여! -은 샴 (레반트) 지역으로 장거리 이동을 하면서 아침 시간에 그들이 살았던 곳을 지나치곤 하였노라.",
  37138: "또한 그대들은 밤 시간에도 그 지역을 지나치곤 하였노라. 그러니 그대들은, 이전에는 없었던 초유의 악행 (동성애) 과 불신을 저질렀던 자들의 결말을 보고서도 교훈을 얻지 않는 것인가?",
  37139: "진실로 요나 (유누스) 는 주님께서 보내신 여러 사도들 중의 한 명으로서, 사도들은 그들의 백성들에게 기쁜 소식을 전하고 닥쳐올 징벌을 경고하였노라.",
  37140: "기억하라. 그는 주님의 허락 없이 도주하였고, 자신의 백성들을 떠나 승객과 짐으로 가득 찬 선박에 올라탔노라.",
  37141: "그 선박은 가득 찬 짐으로 인해 침몰 직전이었고, 선박에 있던 자들은 침몰을 막기 위해 승객의 일부를 바다로 내보내기로 하였노라. 이를 결정하기 위해 제비뽑기를 하였고, 요나는 제비에 걸린 자들 중의 하나였기에 그들은 요나를 바다로 내던졌노라.",
  37142: "그렇게 요나가 바다에 내던져졌을 때 물고기가 그를 집어삼켰노라. 재앙의 원인은 그에게 있으니, 그는 자신의 주님이신 하나님께 허락을 구하지도 않고 바다로 향했기 때문이라.",
  37143: "그러니 요나가 이 재앙 이전에 하나님을 자주 떠올리는 자가 아니었다면",
  37144: "물고기의 배 속이 그의 무덤이 되어, 부활의 날까지 그는 정녕 그곳에서 머물렀을 것이라.",
  37145: "그리하여 하나님께서는 그를 물고기의 배에서 꺼내시어, 나무도 집도 없는 허허벌판에 그를 내던지셨노라.",
  37146: "하나님께서는 어떤 나무도 없던 그곳에 박 나무를 자라게 하시어, 그가 그 나무 그늘에서 쉬고 그 열매를 먹도록 하셨노라.",
  37147: "그리고 하나님께서는 그를 십만 명 이상의 무리에게로 보내셨고",
  37148: "그리하여 그들은 그가 가져온 메시지를 믿었으니, 하나님께서는 현세에서 그들의 정해진 삶이 다할 때까지 그들이 즐거움을 누리도록 하셨노라.",
  37149: "그러니 그대-무함마드-는 우상 숭배자들에게 반문하라. \"하나님께는 그대들이 싫어하는 딸들이 있는 것이고, 그대들에게는 그대들이 좋아하는 아들들이 있는 것인가? 이것은 도대체 어떤 계산법인가? \"",
  37150: "그들은 하나님께서 천사들을 창조하실 때 그 현장을 목격하지도 않았음에도 어떻게 천사들이 여성임을 확신하는 것인가?",
  37151: "보라. 실로 우상 숭배자들은 하나님께 거짓말을 지어내며 말하니 “하나님께 자식이 있다” 하더라. 그러나 실로 그들의 주장은 거짓이라.",
  37152: "보라. 실로 우상 숭배자들은 하나님께 거짓말을 지어내며 말하니 “하나님께 자식이 있다” 하더라. 그러나 실로 그들의 주장은 거짓이라.",
  37153: "하나님께서 그대들이 좋아하는 아들들을 놓아두시고 그대들이 싫어하는 딸들을 선택하신단 말인가? 그렇지 않노라.",
  37154: "그대들-우상 숭배자들이여! -에게 무슨 일이 일어난 것인가? 하나님께는 딸들을 두고 그대들에게는 아들들을 두니, 이 불공정한 판결은 도대체 어떻게 나온 것인가?",
  37155: "그대들의 이 같은 그릇된 믿음에 대해 깊이 생각해 보지 않겠는가? 그대들이 숙고했더라면 이러한 말은 하지 않았을 것이라.",
  37156: "아니면 그대들에게 성서나 사도의 말씀 같은 명백한 증거라도 있단 말인가?",
  37157: "그대들의 주장이 진실이라면 그대들의 그릇된 믿음을 뒷받침해 줄 증거가 있는 성서를 가져와 보라.",
  37158: "우상 숭배자들은 하나님과 보이지 않는 천사들 사이에 혈연 관계를 가정하더라. 그들은 천사들이 하나님의 딸이라 생각하나, 천사들은 하나님께서 우상 숭배자들을 모아 (그들의 이와 같은 주장을) 심판하실 것이라는 사실을 이미 알고 있었노라.",
  37159: "우상 숭배자들은 하나님의 위대함과 전혀 어울리지 않게 그분을 묘사하면서, 하나님께 자식이나 대등한 존재가 있다고 주장하노라. 그러나 하나님께서는 그러한 묘사와 무관하신 완벽한 분이시라!",
  37160: "그러나 하나님께서 선택해 주신 종복들은 예외로서, 그들은 하나님의 위대한 속성에 배치되는 그 어떤 불경스런 말도 하지 않노라.",
  37161: "그러니 그대들-우상 숭배자들이여! -과 그대들이 숭배하는 하나님 이외의 것들은",
  37162: "진리의 종교로부터 그 누구도 방황시키지 못하노라.",
  37163: "그러나 하나님께서 불지옥의 거주자로 운명 지으신 자는 예외로서, 그분께서는 지정하신 운명을 집행하시니 그는 불신을 저질러 불지옥에 들어가게 될 것이라. 그러나 그대들 (우상 숭배자들) 과 우상들은 이러한 운명에 관하여 어떠한 권한도 없노라.",
  37164: "천사들은 하나님께 관한 자신들의 종복 됨을 설명하고 우상 숭배자들이 헛되이 확신하는 자신들의 지위를 부정하며 말하였노라. \"우리들 각자는 모두, 하나님을 경배하기 위한 일정한 장소를 가지고 있노라\"",
  37165: "진실로 우리 천사들은 하나님을 경배하기 위해 대열을 지어 서 있으며 저들이 감히 하나님께 부당한 속성을 부여하나 실로 우리 천사들은 하나님의 완벽함을 찬양하노라.",
  37166: "진실로 우리 천사들은 하나님을 경배하기 위해 대열을 지어 서 있으며 저들이 감히 하나님께 부당한 속성을 부여하나 실로 우리 천사들은 하나님의 완벽함을 찬양하노라.",
  37167: "실로 메카의 거주민 중에서 우상을 숭배하던 자들은 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 사도의 임무를 받기 전에 이렇게 말하곤 하였노라. \"만약 우리가 이전 사람들이 보유하고 있던 토라와 같은 성서를 가지고 있었더라면 정녕 우리는 하나님만을 진실되게 경배했을 것이라\" 그러나 그들은 거짓말을 하는 것이니, 무함마드가 꾸란을 가져왔으나 그들은 꾸란을 불신하였기 때문이라. 그들은 부활의 날 그들을 기다리고 있는 혹독한 징벌이 무엇인지 장차 알게 될 것이라.",
  37168: "실로 메카의 거주민 중에서 우상을 숭배하던 자들은 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 사도의 임무를 받기 전에 이렇게 말하곤 하였노라. \"만약 우리가 이전 사람들이 보유하고 있던 토라와 같은 성서를 가지고 있었더라면 정녕 우리는 하나님만을 진실되게 경배했을 것이라\" 그러나 그들은 거짓말을 하는 것이니, 무함마드가 꾸란을 가져왔으나 그들은 꾸란을 불신하였기 때문이라. 그들은 부활의 날 그들을 기다리고 있는 혹독한 징벌이 무엇인지 장차 알게 될 것이라.",
  37169: "실로 메카의 거주민 중에서 우상을 숭배하던 자들은 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 사도의 임무를 받기 전에 이렇게 말하곤 하였노라. \"만약 우리가 이전 사람들이 보유하고 있던 토라와 같은 성서를 가지고 있었더라면 정녕 우리는 하나님만을 진실되게 경배했을 것이라\" 그러나 그들은 거짓말을 하는 것이니, 무함마드가 꾸란을 가져왔으나 그들은 꾸란을 불신하였기 때문이라. 그들은 부활의 날 그들을 기다리고 있는 혹독한 징벌이 무엇인지 장차 알게 될 것이라.",
  37170: "실로 메카의 거주민 중에서 우상을 숭배하던 자들은 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 사도의 임무를 받기 전에 이렇게 말하곤 하였노라. \"만약 우리가 이전 사람들이 보유하고 있던 토라와 같은 성서를 가지고 있었더라면 정녕 우리는 하나님만을 진실되게 경배했을 것이라\" 그러나 그들은 거짓말을 하는 것이니, 무함마드가 꾸란을 가져왔으나 그들은 꾸란을 불신하였기 때문이라. 그들은 부활의 날 그들을 기다리고 있는 혹독한 징벌이 무엇인지 장차 알게 될 것이라.",
  37171: "실로 하나님의 사도들에 대한 운명은 이미 확정되었고, 그 누구도 그것을 되돌릴 수 없노라. 실로 사도들은 적들에 대해 승리를 거둘 자들로서, 하나님께서 그들에게 논거와 힘을 부여하시기 때문이라. 그리고 하나님의 군대는 우위를 점할 자들로서, 그들은 하나님의 말씀을 드높이기 위해 그분의 길에서 분투하는 자들이라.",
  37172: "실로 하나님의 사도들에 대한 운명은 이미 확정되었고, 그 누구도 그것을 되돌릴 수 없노라. 실로 사도들은 적들에 대해 승리를 거둘 자들로서, 하나님께서 그들에게 논거와 힘을 부여하시기 때문이라. 그리고 하나님의 군대는 우위를 점할 자들로서, 그들은 하나님의 말씀을 드높이기 위해 그분의 길에서 분투하는 자들이라.",
  37173: "실로 하나님의 사도들에 대한 운명은 이미 확정되었고, 그 누구도 그것을 되돌릴 수 없노라. 실로 사도들은 적들에 대해 승리를 거둘 자들로서, 하나님께서 그들에게 논거와 힘을 부여하시기 때문이라. 그리고 하나님의 군대는 우위를 점할 자들로서, 그들은 하나님의 말씀을 드높이기 위해 그분의 길에서 분투하는 자들이라.",
  37174: "그러니 그대-사도여! -는 하나님께서 고집스런 우상 숭배자들을 벌하실 그 때까지 그들에게서 잠시 돌아서 있으라.",
  37175: "그리고 결국 그들에게 벌이 도래할 때 그대는 그들을 바라보라. 그 때 그들은 (진리를 인지하는) 시각을 가질 것이나 그 때는 이미 늦은 것이라.",
  37176: "그런데도 저 우상 숭배자들은 다름 아닌 하나님의 벌을 재촉하는 것인가?",
  37177: "그리하여 그들에게 하나님의 벌이 내려졌을 때, 그들이 맞이하는 아침은 얼마나 비참할 것인가?",
  37178: "그러니 그대-사도여! -는 하나님께서 그들의 벌을 결정하실 때까지 그들에게서 잠시 돌아서 있으라.",
  37179: "그리고 보라. 그들도 결국 자신들에게 내려질 하나님의 벌과 그 결말을 보게 될 것이라.",
  37180: "우상 숭배자들은 하나님의 속성을 결점들로 묘사하나, 그대-무함마드여! -는 강력하시고 성스러우신 주님의 완벽함을 찬양하라.",
  37181: "하나님께서는 당신의 명예로운 사도들을 칭송하시노라.",
  37182: "모든 감사와 찬양은 존재하는 모든 것의 주님이신 하나님 한 분께만 있노라.",
  38000: "싸드\n계시 분류: 메카\n•    계시 목적    \n이 장은 허위로 논쟁하는 자들의 비참한 결말에 대해 이야기하고 있다.\n•    요약 주해",
  38001: "(싸드.) (단절 문자에 관한 설명은 야신 장 첫 번째 구절 참조) 하나님께서는 현세와 내세의 유용한 교훈들로 가득한 꾸란을 두고 맹세하시니, 하나님께는 우상 숭배자들의 생각과는 달리 그 어떤 대등한 존재도 있을 수 없노라.",
  38002: "그러나 불신하는 자들은 유일신 사상에 오만해 하고, 하나님의 사도에 적의를 드러내노라.",
  38003: "하나님께서 그들 이전의 세대 중 그분의 사도를 부정한 자들을 얼마나 많이 파멸시키셨는가? 그리하여 하나님의 벌이 도래하였을 때 그들은 도움을 구하며 외쳐보지만, 그 때는 그 누구도 그들을 구조해 줄 수 없노라.",
  38004: "그들은 자신들과 같은 인간이 사도가 되어, 그들에게 불신을 지속할 경우에 있을 징벌을 경고함에 신기해 하더라. 불신자들은 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 가져온 명백한 증거를 목격한 후에도 \"이 작자는 사람들에게 주술을 거는 주술가이며, 자신이 하나님의 사도로서 계시를 받았다 주장하는 거짓말쟁이라\" 라고 말하였노라.",
  38005: "\"그는 여럿의 신들을 하나의 신으로 두어 다른 신들을 부정하는 것인가? 실로 그의 행동은 참으로 어처구니가 없노라\"",
  38006: "그들의 원로들은 자리에서 일어나면서 그들에게 말하였노라. \"그대들은 해오던 일을 지속하고 무함마드의 종교를 따르지 말며 우상을 숭배함에 흔들리지 마시오. 무함마드가 주장하는 유일신 사상은 계략일 뿐이며, 그는 자신의 지위를 높이고 추종하는 세력을 가지고 싶어하는 것이오\"",
  38007: "\"무함마드가 주장하는 유일신 사상은 우리의 조상들에게서 발견되지 않고 예수 (그에게 평화가 깃들기를) 의 종교에서도 들어보지 못한 것이오. 우리가 듣는 저 말은 오직 거짓말과 조작일 뿐이오\"",
  38008: "\"지도자인 우리 모두는 제쳐두고 그에게만 꾸란이 계시된다니, 이것은 과연 올바른 처사인가? \" 실상은 저 우상 숭배자들이 계시에 관해 의심을 품고 있는 것이라. 그들은 아직 하나님의 벌을 맛 보지 않았고, 그들에게 주어진 이러한 유예로 인해 그들은 기만당하고 있는 것이라. 만일 그들이 벌을 맛 보았다면 하나님에 대한 불신이나 우상 숭배, 계시에 대한 의심은 감히 할 수 없었을 것이라.",
  38009: "그 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 원하시는 자에게 원하시는 것을 베푸시는 하나님께는 당신의 보물 창고가 있노라. 사도직은 이 보물 창고에 보관된 보물 중의 하나로, 하나님께서 원하시는 자에게 그것을 선사하시노라. 반면 그들은 사도직에 관하여 그 어떤 권한도 없노라.",
  38010: "아니면 그들이 (일곱) 하늘과 땅과 그 사이에 존재하는 것의 주권을 소유하고 있단 말인가? 그래서 그들에게는 원하는 대로 주거나 막을 권리가 있단 말인가? 그렇다면 그들은 모든 수단을 동원하여 하늘로 올라가, 원하는 대로 금하고 허하는 판결을 내려 보라. 그들은 결코 그렇게 할 수 없을 것이라.",
  38011: "무함마드를 부정하는 저들은, 그들 이전에 사도들을 부정했던 자들처럼 군대를 이룬 후에 곧 패배할 것이라.",
  38012: "그들이 최초로 이슬람을 부정한 것이 아니라, 이미 그들 이전에도 노아의 백성과 아드 부족과 무력으로 사람들을 학대하던 파라오도 이슬람을 부정하였노라.",
  38013: "싸무드 부족과 롯의 백성과 슈아입의 백성도 이슬람을 부정하였노라. 저들은 사도들을 부정하고 그들의 메시지를 불신함에 행동을 같이 하는 동맹자들이라.",
  38014: "저들 모두는 예외 없이 사도들을 부정하였고, 그리하여 그들에게 내려질 하나님의 징벌과 응징은 -그 실현이 잠시 늦추어지언정- 피할 수 없는 것이 되었노라.",
  38015: "무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 를 부정하는 저들이 기다리는 것은 되돌릴 수 없는 두 번째 나팔 소리일 뿐으로, 저들이 부정을 지속한다면 그날 그들은 징벌에 노출될 것이라.",
  38016: "그들이 비웃으며 말하더라. \"우리의 주님이여. 심판의 날을 기다릴 필요도 없이, 우리에게 지정된 징벌을 현세에서 서둘러 내려 주십시오\"",
  38017: "그대-사도여! -는 부정하는 저들이 하는 내뱉는 말에 인내하라. 그리고 다윗 (다우드) 을 기억하라. 그는 하나님의 종복으로서, 적과의 전투와 경배 행위에서 힘을 발휘하던 자라. 실로 다윗은 하나님께 자주 참회하면서 열심히 그분의 기쁨을 구하던 자였노라.",
  38018: "실로 하나님께서는 산들을 굴복시키셨노라. 다윗이 하나님을 찬양할 때면 그 산들도 그와 함께, 해 지는 저녁과 해 뜨는 아침 시간에 하나님을 찬양하더라.",
  38019: "하나님께서는 새들도 굴종시키셨으니, 그것들이 공중에서 한데 모여 다윗을 따라 하나님을 찬양하더라.",
  38020: "하나님께서는 다윗에게 위엄과 군사력과 적들에 대한 승리를 주시어 그의 왕국을 강력하게 만드셨노라. 또한 하나님께서는 그에게 선지자직을 선사하셨고, 매사에 정확한 판단력과 판결을, 말을 할 때는 달변을 구사하는 능력을 주셨노라.",
  38021: "논쟁을 벌이던 두 명이 담장을 타고 다윗 (그에게 평화가 깃들기를) 의 경배소로 넘어왔노라. 그대-사도여! -에게 이 소식이 전해졌는가?",
  38022: "그 두 명은 사람들에게 잘 알려지지 않은 기이한 방식으로 다윗에게 들어왔기에 그는 갑작스런 그들의 출현에 두려움을 느꼈노라. 그들은 다윗이 놀라는 것을 보고서 말하였노라. \"두려워 마십시오. 저희는 논쟁을 벌이며 서로의 부당함을 주장하고 있습니다. 그러니 당신께서 저희를 공정히 판결해 주시고, 부당한 판결은 내려주지 마시며, 저희를 올바른 길로 인도해 주십시오\"",
  38023: "둘 중의 하나가 다윗 (그에게 평화가 깃들기를) 에게 말하였노라. \"실로 이 자는 나의 형제로서 암양을 아흔 아홉 마리나 가졌습니다. 반면 저에게는 암양이 한 마리밖에 없습니다. 그런대도 그는 저에게 그 양마저 자기에게 달라고, 증거를 대며 저를 위압하였습니다.",
  38024: "다윗은 그들을 판결하면서 원고에게 말하였노라. \"정녕 그대의 형제는 그대를 부당히 대우하였도다. 이는, 그가 기존에 있던 자신의 암양에 더하여 그대의 암양까지도 요구하였기 때문이라. 동업으로 장사를 하는 자들의 대다수는 상대의 몫을 갈취하고 불공정한 행위를 저지르는 등 서로가 넘어서지 말아야 할 경계를 넘어서노라. 그러나 신앙인으로서 선행을 실천하는 자들은 동업자들에게 공정을 기하고 부당 대우를 저지르지 않지만, 그들의 숫자는 적으니라\" 다윗은 하나님께서 이 사건으로 그를 시험하셨음을 확신하였고, 이에 자신의 주님께 용서를 구하고 그분을 위해 엎드려 절하면서 참회하였노라.",
  38025: "이에 하나님께서는 다윗의 죄를 용서해 주셨노라. 실로 다윗은 하나님께 가까이 있을 명예를 누릴 것이며 내세에서 훌륭한 거주지를 가질 것이라.",
  38026: "\"(하나님께서 말씀하셨노라) 다윗이여! 실로 나는 그대를 현세의 일과 종교적 사안을 판결하고 집행하는 지상에서의 계승자로 두었노라. 그러니 그대는 사람들 사이를 공정하게 판결하고 사리사욕을 추구하지 말라. 친척이나 친구라는 이유로 그에게 유리한 판결을 하거나, 적대 관계에 있는 자에게 불리한 판결을 내린다면, 그러한 사욕은 그대를 방황케 하여 그대를 하나님의 길에서 벗어나게 할 것이라. 실로 하나님의 길을 벗어나 방황하는 자들에게는 가혹한 벌이 있을 것이니, 그들은 심판의 날을 망각하였기 때문이라. 만약 그들이 심판의 날을 기억하고 그날을 두려워했더라면 그렇게 자신들의 욕망을 따르지 않았을 것이라\".",
  38027: "하나님께서는 하늘과 땅과 그 사이에 있는 것을 아무 의미 없이 창조하지 않으셨노라. 이러한 추측은 불신자들의 억측일 뿐이라. 불신하는 자들이 자신의 불신과 하나님에 대한 이러한 사악한 생각을 버리지 않고 죽는다면 그들은 심판의 날 불지옥의 고통에 직면하게 될 것이라.",
  38028: "하나님을 믿고 사도를 따르며 선행을 실천하는 자들이 있고, 불신과 거역 행위로 지상에 해악을 퍼뜨리는 자들이 있으니, 하나님께서는 그 두 무리를 동일히 대하지 않으시노라. 또한 하나님께서 명령하신 사항을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하는 자들이 있고, 마음이 거역 행위로 물든 불신자들과 위선자들이 있으니, 하나님께서는 그 두 무리 역시도 동일히 대하지 않으시노라. 그들을 동등히 두는 것은 하나님께 적합하지 않은 부당 행위라. 하나님께서는 당신을 경외하는 신앙인들을 천국에 들게 하시며, 당신을 불신하는 사악한 자들을 지옥에 들게 하시노라. 하나님 보시기에 이 두 무리는 동일하지 않기에 그 보응도 다르게 두시는 것이라.",
  38029: "이 꾸란은 하나님께서 그대에게 내리신 축복 가득한 성서라. 꾸란이 계시된 것은 그들이 그 징표들을 숙고하기 위함이며, 슬기를 지닌 자들이 그 의미를 깊이 생각하여 교훈을 얻기 위함이라.",
  38030: "하나님께서는 다윗 (다우드) 에게 축복을 내리시어 그가 기뻐할 수 있도록 그에게 솔로몬 (술라이만) 을 아들로 주셨노라. 솔로몬은 참으로 훌륭한 종복이도다. 실로 솔로몬은 하나님께 자주 참회하며 그분께 귀의하는 자라.",
  38031: "기억하라. 솔로몬에게 오후에 즈음하여 순혈의 천리마가 대령되었으니, 이 말은 세 발을 땅에 붙이고 네 번째 발은 들고 있는 준마라. 천리마는 그렇게 해 질 녘까지 솔로몬에게 놓여져 있었노라.",
  38032: "그리하여 솔로몬이 말하였노라. \"실로 나는 준마와 같은 재물을 심히 사랑한 나머지 나의 주님을 떠올리는 일에 소홀하였고, 해가 질 때까지도 오후 예배를 드리지 못했구나\"",
  38033: "\"그대들은 나에게서 이 말을 가져가라\" 그리하여 그들은 그에게서 말을 치웠고, 그는 말의 다리와 목을 칼로 내리치기 시작하였노라.",
  38034: "진실로 하나님께서는 솔로몬을 시험하셨으니, 그분께서는 솔로몬의 권좌에 사람의 모양을 한 사탄을 놓으시어 그가 (솔로몬 대신) 짧은 기간 동안을 통치하도록 하셨노라. 그 후 하나님께서는 솔로몬에게 권력을 되돌려 주셨고, 그에게 사탄들을 지배할 수 있는 권능을 부여하셨노라.",
  38035: "솔로몬이 말하였노라. \"저의 주님! 저의 죄들을 용서해 주시옵고, 저에게 저 이후의 그 누구도 가질 수 없는 위대한 왕권을 주십시오. 진실로 당신-주님이시여! -께서는 조건 없이 베푸시며 풍성히 주시는 분입니다\"",
  38036: "하나님께서는 그의 기도에 응하셨고, 솔로몬을 위해 바람을 굴종시키셨노라. 거칠고 빠른 바람이지만 그것은 솔로몬의 명령에 따라 흔들림 없이 부드럽게 움직이고, 솔로몬이 원하는 곳으로 그를 이동시켜 주었노라.",
  38037: "하나님께서는 솔로몬을 위해 사탄들도 굴종시키셨으니, 그들 중에는 건축을 하는 부류가 있고, 바다로 잠수하여 진주를 가져오는 부류도 있었노라.",
  38038: "또 다른 사탄은 고집스런 부류이며, 그들은 굴복되었노라. 그들은 사슬로 묶여 있어 움직이지를 못하노라.",
  38039: "\"솔로몬이여! 이것은 하나님께서 그대의 기도에 응답하여 그대에게 주신 것이라. 그러니 그대는 원하는 자에게 주거나, 원하는 자에게 주지 말라. 어떤 선택을 하든 그대는 하나님으로부터 질책받지 않을 것이라\"",
  38040: "실로 솔로몬은 하나님께 가까이 있을 명예를 누릴 것이며 내세에서 천국이라는 훌륭한 귀착지를 가질 것이라.",
  38041: "그대 -사도여! -는 하나님의 종복 욥 (아이윱) 이 자신의 주님인 하나님을 불렀을 때를 기억하라. \"실로 사탄은 어렵고 고통스런 일로 저를 덮쳤습니다\"",
  38042: "이에 하나님께서 그에게 말씀하셨노라. \"그대의 발로 땅을 내려치라\" 그가 그렇게 하니 그곳에서 물이 솟아올랐노라. 이 물은 마시는 샘물이자 씻는 물로서, 정신과 신체의 고통이 사라지게 할 물이라.",
  38043: "그렇게 하나님께서는 그의 기도에 응답하시어 그의 병을 없애 주셨노라. 또한 하나님께서는 그에게 가족을 되돌려 주시고, 그들에 더하여 자식들과 손자들을 늘려 주셨노라. 이는 그가 인내한 것에 대한 보상이며 슬기를 가진 자들이, 인내의 결말은 문제의 해결과 보답이라는 것을 다시 한번 상기하기 위함이라.",
  38044: "욥 (아이윱) 은 아내에게 화가 난 나머지 그녀를 백 번을 때리겠다고 맹세하였고, 이에 하나님께서 그에게 말씀하셨노라. \"그대-욥이여! -의 손으로 꽃자루 뭉치를 잡아 그것으로 그녀를 때리라. 그렇게 하여 그대의 맹세를 어기지 말라\" 그는 하나님의 시험에 굳건히 안내하였으니, 그 얼마나 훌륭한 종복인가. 욥은 하나님께 자주 참회하면서 열심히 그분의 기쁨을 구하던 자였노라.",
  38045: "그대-무함마드-는, 하나님께서 선택하신 종복이자 그분께서 보내신 사도 아브라함과 이삭과 야곱을 기억하라. 그들은 하나님께 복종함에 있어 강인하였으며, 진리를 볼 수 있는 눈을 지녔던 자들이라.",
  38046: "실로 하나님께서는 그들을 특별히 선택하셨노라. 이는 그들이 내세에서의 거주지 (천국) 를 자주 떠올리고, 선행을 실천함으로써 그곳에서의 삶을 준비하고, 사람들에게 천국을 준비하며 선행을 실천하라 말하던 그들의 훌륭함 때문이라.",
  38047: "진실로 그들은 하나님께 순종하고 그분만을 경배하였기에 하나님께서는 그들을 선택하시어 그들이 사람들에게 하나님의 메시지를 전달하도록 하셨노라.",
  38048: "그대-무함마드-는 아브라함의 아들 이스마엘 (이스마일) 과 엘리사 (알야사으) 와 둘 키플을 기억하고, 그들을 훌륭한 방식으로 칭송하라. 그들은 칭송받을 자격이 있는 자들이라. 이들 모두는 하나님으로부터 선택받은 자들 중의 일부라.",
  38049: "이것은 아름다운 칭송을 받을 자들을 위한 꾸란의 언급이라. 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하는 자들에게는 내세에서의 훌륭한 귀착지가 있노라.",
  38050: "그곳은 심판의 날에 들어가게 될 영원의 천국으로서, 그곳의 문들은 그들을 환영하기 위해 열려 있노라.",
  38051: "그들은 그들을 위해 꾸며진 차양 침대에 몸을 기대고, 자신들이 만끽할 다양한 종류의 과일과 자신들이 즐겨 마실 술 등의 음료를 갖다 놓으라고 시중 드는 자들에게 말할 것이라.",
  38052: "그들에게는 자신의 배우자만을 바라보는 여성들이 있으니 그녀들은 다른 남성들에게 시선을 주지 않으며, 그녀들은 배우자와 동갑내기라.",
  38053: "이 훌륭한 보상은 심판의 날 그대들-경외하는 자들이여! -에게 약속된 것으로, 그대들이 현세에서 실천하던 선행에 대한 보상이라.",
  38054: "하나님께서 언급한 이 풍성한 은혜는 심판의 날 (하나님을) 경외하는 자들을 위해 그분께서 베푸실 양식으로, 그 어떤 끊김이나 고갈도 없노라.",
  38055: "하나님께서 언급한 이 축복은 그분을 경외하는 자들을 위한 보상이라. 진실로 불신과 거역 행위로써 하나님의 경계를 넘어선 자들에게는 경외하는 자들과 대치되는 보응이 있을 것이니, 그들은 심판의 날 사악한 귀착지로 들어가야만 할 것이라.",
  38056: "그 보응이란 그들을 에워쌀 지옥으로, 그들은 그 뜨거움과 불길로 고통받을 것이라. 그곳에는 그들이 드러누울 장소가 있이니, 얼마나 사악한 거처인가.",
  38057: "이것은 그 뜨거움의 끝을 알 수 없는 음료와, 지옥의 거주자들이 고통받으며 흘러 내는 고름이니, 그들은 이를 마시도록 하라. 아무리 마셔도 갈증은 해소되지 않을 것이라.",
  38058: "그들에게는 이와 유사한 형태의 다른 벌들이 내려져 고통받을 것이며, 그 종류는 다양하노라.",
  38059: "불지옥의 거주자들이 지옥에 들어갈 때 그들 사이에서는 심각한 논쟁이 벌어질 것이며, 그들은 서로가 서로로부터의 무고함을 주장할 것이라. 그들 중의 한 무리가 말하노라. \"이들은 너희들과 함께 지옥에 들어갈 집단이라\" 이에 그들이 답하노라. \"우리는 결코 저들을 환영하지 않소. 우리가 불지옥의 고통을 받는 것처럼 저들도 고통을 받을 것이오\"",
  38060: "추종자 무리가 그들의 지도자들에게 말하노라. \"그렇지 않고, 우리는 당신들-추종받던 지도자들아! - 을 환영하지 않소. 우리가 고통받는 것은 다 당신들 때문이오. 당신들이 우리의 방황과 일탈을 조장했소. 그러니 우리 모두가 들어갈 이 불지옥은 얼마나 비참한 거주지요\"",
  38061: "추종자들이 말하노라. \"저희의 주님이시여! 인도의 길이 도래한 후에 우리를 방황시킨 자들이 저들입니다. 그러니 저들이 불지옥에서 곱절의 벌을 받게 해 주십시오\"",
  38062: "경계를 넘어서며 거만해 하던 자들이 말하노라. \"현세에서 우리가 생각하기로 벌을 받아 마땅한 사악한 자들이 있는데, 그들은 정작 우리와 함께 불지옥에 있지 아니하니 이 어찌 된 영문인가? \"",
  38063: "\"우리가 그들을 조롱한 것이 틀려서 그들이 벌을 받지 않는 것인가? 아니면 우리의 조롱이 옳았으나 그들은 이미 불지옥에 들어가 우리의 시각을 벗어난 것인가? \"",
  38064: "진실로 심판의 날 불신자들 사이에서 발생할 이 논쟁은 의심의 여지 없는 실제라.",
  38065: "그대-무함마드여! -는 그대의 백성들 중 불신하는 자들에게 말하라. \"나는 그대들에게 하나님의 벌을 경고하노라. 그 벌은 그대들이 하나님을 불신하고 그분의 사도를 부정하기 때문이라. 하나님 이외의 그 어떤 존재도 경배받을 권리를 가지지 못하노라. 하나님께서는 당신의 위대함과 속성과 이름이 유일무이한 분으로서, 모든 것은 그분께 제압되어 굴종되노라\"",
  38066: "\"그분께서는 (일곱) 하늘과 땅 그리고 그 사이에 존재하는 것의 주님이시며, 그 누구에게도 제압되지 않는 주권을 가지신 분이자 용서를 구하는 종복의 죄를 용서하시는 분이라\"",
  38067: "그대-사도여! -는 부정하는 저들에게 말하라. \"실로 꾸란은 위대한 일에 관한 소식을 전하지만\"",
  38068: "\"이 위대한 소식에 그대들은 등을 돌리며 거들떠 보지도 않노라\"",
  38069: "\"하나님께서 나에게 계시로써 가르쳐 주지 않으셨더라면 나는 아담의 창조에 관해 천사들 사이에 어떤 대화가 오갔는지 알지 못했을 것이라\"",
  38070: "\"하나님께서 나에게 계시를 내리신 것은 내가 그대들을 위한 경고자이기 때문이며, 나는 그대들에게 닥칠 하나님의 벌을 경고하노라\"",
  38071: "그대의 주님께서 천사들에게 말씀하셨을 때를 기억하라. \"실로 나는 진흙으로 인간 아담 (그에게 평화가 깃들기를) 을 창조할 것이라\"",
  38072: "그리하여 하나님께서는 아담을 균형 있게 조정하시고 창조를 마치셨을 때 천사들에게 말씀하였노라. \"내가 명령하니 그에게 부복하며 인사하라\"",
  38073: "그리하여 천사들은 자신들의 주님이신 하나님의 명령에 따라 아담에게 명예의 부복을 하였고, 그들 중의 그 어떤 누구도 그에게 부복하지 않은 자가 없었노라.",
  38074: "그러나 이블리스는 거만해 하며 부복하지 않았고, 그는 자신의 주님의 명령에 불복한 이유로 불신자들 중의 하나가 되었노라.",
  38075: "하나님께서 말씀하셨노라. \"이블리스여! 너는 무슨 연유로 나의 두 손으로 창조한 아담에게 부복하길 거부하는 것인가? 너는 거만해 했던 것인가, 아니면 하나님께 오만을 떨며 군림하려 드는 자들 중의 하나였던 것인가? \"",
  38076: "이블리스가 말하였노라. \"제가 그보다 더 훌륭하기 때문입니다. 당신께서는 저를 불로부터 창조하셨지만, 그는 진흙으로부터 창조하셨습니다. 불이 진흙보다 더 명예롭습니다\"",
  38077: "하나님께서 이블리스에게 말씀하셨노라. \"그렇다면 너는 천국에서 나가라. 실로 너는 하나님의 자비를 박탈 당했기 때문이라\"",
  38078: "\"실로 너는 천국으로부터 추방되었으니 보응의 날, 즉 심판의 날이 올 때까지라\"",
  38079: "이블리스가 말하였노라. \"저의 주님이시여! 그러시면 당신께서 사람들을 부활시키실 그날까지 저를 잠시만 늦추어 주십시오\"",
  38080: "하나님께서 말씀하셨노라. \"\"실로 그렇다면 너는 유보된 자들 중의 하나라\"",
  38081: "\"네가 죽음을 맞이할 그 날의 지정된 시간까지라\"",
  38082: "이블리스가 말하였노라. \"그렇다면 당신의 전능하심과 압도하심을 두고 맹세하니, 저는 결단코 아담의 자손들 모두를 방황시키겠습니다\"",
  38083: "\"그러나 당신께서 나의 유혹으로부터 보호해 주시고 당신만을 경배하도록 선택해 주신 종복들은 예외가 될 것입니다\"",
  38084: "하나님께서 말씀하셨노라. \"실로 진실은 나에게서 비롯되는 것이며, 나는 오직 진실만을 말할 뿐 그 이외의 것은 말하지 않노라.",
  38085: "\"진실로 나는 심판의 날 지옥을 가득 채울 것이니, 너와 아담의 자손들 중 불신으로 너를 따르는 자들 그 모두를 지옥에 들게 할 것이라\"",
  38086: "그대-사도여! -는 저 우상 숭배자들에게 말하라. \"나는 그대들에게 충언을 전달하면서 그대들에게 그 어떤 보상도 바라지 않노라. 또한 나는 명령받지 않은 말씀을 임의로 덧씌워 말하는 자가 아니라\"",
  38087: "이 꾸란은 다름 아닌 인간과 진을 위한 일깨움의 메시지라.",
  38088: "그대들은 머지 않은 시간에 죽음을 맞이할 것이며, 그 때 그대들은 꾸란이 정녕 진실이었다는 사실을 알게 될 것이라.",
  39000: "앗-주마르 (무리, 떼)\n계시 분류: 메카\n•    계시 목적    \n이 장은 유일신 신앙과 진실성으로 사람들을 초대하고, 하나님과 대등한 존재를 두지 말 것을 강조하면서, 내세에서 믿음과 불신의 결과가 어떠할 것인지를 밝히고 있다.\n•    요약 주해",
  39001: "꾸란의 계시는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 하나님에게서 비롯한 것으로, 그분 이외의 그 누구도 그것을 계시할 수 없노라.",
  39002: "실로 하나님께서는 그대-사도여! -에게 진리로 가득한 꾸란을 내리셨으니, 꾸란의 모든 내용은 진실이며 꾸란의 모든 판결은 공정이라. 그러니 그대는 하나님을 경배하며 그분을 위해 진정으로 종교에 임하라.",
  39003: "하나님께는 그 어떤 다신 사상으로부터도 물들지 않은 진실된 종교 (이슬람) 가 있노라. 하나님이 아닌 우상들을 가호자로 삼는 자들은 변명을 하며 말하노라. \"우리가 우상을 숭배하는 이유는 그들이 우리를 하나님께 가까이 다가가게 해 주고, 우리가 필요한 부분을 하나님께 전달해 주며, 하나님 앞에서 우리를 중재해 줄 것이기 때문이라\" 실로 하나님께서는 심판의 날 유일신 사상의 신앙인과 다신 사상의 우상 숭배자 사이의 의견 차이를 판결하실 것이라. 하나님께 대등한 존재를 두고 자신에게 내려진 그분의 은총을 부정하는 자는 하나님께서 그를 인도해 주시지 않으실 것이라.",
  39004: "만약 하나님께서 자식을 두길 원하셨다면 하나님께서는 당신께서 창조하신 것 중 원하시는 피조물을 선택하시어 당신의 아들과 같은 위치로 두셨을 것이라. 우상 숭배자들이 하나님을 함부로 묘사하나, 그분께서는 완벽하신 분이라! 하나님께서는 당신의 존재와 속성과 행위에 있어 유일무이하신 분이시기에 그분께 대등한 존재란 없으며, 하나님께서는 그 모든 피조물을 제압하시는 분이라.",
  39005: "하나님께서는 (일곱) 하늘과 땅을 진리에 걸맞게 창조하셨으니, 이는 하나님의 무한한 지혜에 기인한 것이며, 부당한 자들이 주장하는 것처럼 아무도 목적 없이 창조하신 것이 아니라. 하나님께서는 낮 위에 밤을 들게 하시고 밤 위에 낮을 들게 하시어, 하나가 오면 나머지가 사라지게 하셨노라. 또한 하나님께서는 해를 굴종시키시고 달을 굴종시키시어, 해와 달 모두가 현세가 종료되는 정해진 시간까지 운행토록 하셨노라. 적들을 응징하시며 그 누구에게도 제압되지 않는 가장 존엄하신 분, 참회하는 종복들의 모든 죄를 용서하시는 분이 바로 하나님이시라!",
  39006: "그대들-인간들이여! -의 주님께서는 아담으로부터 그대들을 창조하셨으며, 그 후 아담으로부터 그의 배우자인 이브 (하와) 를 창조하셨노라. 그리고 하나님께서는 그대들을 위해 낙타와 소와 양과 염소를 창조하셨고, 각 종류에 암수를 두시니 여덟 종류라. 하나님께서는 그대들의 어머니 배 속에 그대들 (태아) 을 창조하셨고, 복부와 자궁과 태반의 세 가지 어둠과 함께, 단계에 단계를 거쳐 성장토록 하셨노라. 이 모든 것을 창조한 분이 바로 그대들의 주님이신 하나님이시라. 하나님만이 주권을 소유하시며, 오직 그분께만 경배받을 권리가 있노라. 그런데도 그대들은 어떻게 유일신 사상은 제쳐두고, 아무 것도 창조하지 못하는 한낱 피조물들을 숭배한단 말인가?",
  39007: "만일 그대들-인간들이여! -이 그대들의 주님을 불신한다면 실로 하나님께서는 그대들의 신앙을 필요로 하지 않으시노라. 그대들이 불신한대도 하나님께서는 어떤 해악도 받지 않으시며, 그 해악은 오직 그대 자신들에게 돌아갈 뿐이라. 하나님께서는 당신의 종복들이 저지르는 불신에 만족하지 않으시며 그들에게 불신을 명하지도 않으시노라. 그러함은 하나님께서는 추악한 행위나 비난받을 행위를 명령하지 않으시기 때문이라. 그러나 만일 그대들이 하나님의 은총에 감사하고 그분을 믿는다면, 하나님께서는 그대들의 감사함에 흡족해 하시고, 그대들에게 보상을 내려주실 것이라. 인간은 타인의 죄를 짊어지지 않으며, 모든 영혼은 자신의 행위로 전당 잡혀 있노라. 그런 후 심판의 날 그대들은 하나님 한 분께로 돌아갈 것이며, 그날 그분께서는 그대들이 현세에서 행하던 행위를 알려 주신 후, 그에 의거하여 그대들을 보응하실 것이라. 실로 하나님께서는 그대들의 마음속에 숨겨진 것조차 다 알고 계시는 분으로, 그분께는 그 무엇도 감추어지지 않노라.",
  39008: "불신자에게 질병, 재산 손실, 익사의 위험 등이 닥칠 때면 그는 재앙을 없애 달라고 주님을 간절히 부르며 하나님께 돌아가노라. 그런 후 하나님께서 친히 은총을 선사하시어 그에게 내린 재앙을 거두어 주시면, 그는 이전에 그분을 부르던 것을 잊어 버리고 하나님 이외의 것들을 숭배하니, 사람들을 하나님의 길에서 벗어나 방황케 하더라. 그대-사도여! -는 이러한 상태에 빠져 있는 자에게 말하라. \"남은 짧은 생애 동안 그대의 불신을 즐겨 보라. 실로 그대는 심판의 날 불지옥의 거주자가 되어 그곳에서 머물게 될 것이라\"",
  39009: "하나님께 부단히 복종하는 자가 있으니, 그는 한밤중에 서서 예배 드리고 엎드려 절하며, 내세의 징벌을 두려워하고 주님이신 하나님의 자비를 염원하노라. 이 자가 더 훌륭한가? 아니면 어려울 때는 하나님을 경배하다가 쉬울 때는 하나님을 불신하며 그분께 대등한 존재를 두는 저 자가 더 훌륭한가? 그대-사도여! -는 말하라. \"하나님의 존재를 인정하고 그분께서 의무로 지정한 사항들을 아는 자들과, 그러한 사항들 중 어떤 것도 알지 못하는 자들이 같을 수 있단 말인가? \" 오직 건전한 이성을 지닌 자들만이 이 두 부류의 차이를 인식하노라.",
  39010: "그대-사도여! -는 하나님과 그분의 사도들을 믿는 자들에게 말하라. \"그대들은 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 그대들의 주님을 두려워하라. 현세에서 선행을 실천함에 최선을 다한 자는 승리와 건강과 재산 등 현세에서 좋은 것을 얻을 것이며, 내세에서는 천국으로 입성하게 될 것이라. 하나님의 대지는 넓으니 그대들은 이주 (히즈라) 를 단행함으로써 자유롭게 하나님을 경배할 수 있는 곳을 찾으라. 실로 인내하는 자들은 심판의 날 따짐 없는 보상을 받을 것이니, 이 보상은 수나 양, 종류에 제한이 없는 풍성한 보상이라\"",
  39011: "그대-사도여! -는 말하라. “실로 나는 하나님 한 분만을 경배하라 명령받았으며, 그분을 위해 진정으로 종교에 임하길 명령받았도다”",
  39012: "\"그리고 나는 이슬람 공동체의 구성원 중에서 첫 번째 무슬림이 되어 하나님께 복종하라는 명령을 받았노라\"",
  39013: "그대 -사도여! -는 말하라. \"실로 나는 하나님께 불복하고 거역하였을 때 받게 될 심판의 날의 벌이 두렵소\"",
  39014: "그대-사도여! -는 말하라. \"나는 진심으로 오직 하나님 한 분만을 경배하며, 그분 이외의 다른 존재는 숭배하지 않노라\"",
  39015: "\"그러니 그대들-우상 숭배자들이여! -은 하나님이 아닌 우상들을 숭배해 보라\" 그대-사도여! -는 말하라. \"진정한 손실자들이란 실로 부활의 날에 자기 자신과 가족을 잃어 버릴 자들로서, 그들과 함께 천국에 들지 못하여 헤어지거나 그들과 함께 지옥에 들어가 영원히 서로를 만날 수 없는 자들이라. 실로 이것이야말로 의심할 바 없는 명백한 손실이 아니던가! \"",
  39016: "그들의 위에는 연기와 불길과 뜨거움이 있으며, 그들의 아래에도 연기와 불길과 뜨거움이 있노라. 하나님께서는 이러한 징벌을 언급하심으로써 당신의 종복을 두렵게 하시노라. 그러니, 하나님의 종복들이여! 하나님께서 명령하신 사항을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하라.",
  39017: "(하나님께서는 이전 구절에서 죄짓는 자들의 상태를 언급하셨고, 여기서부터는 선량한 종복들의 상태를 언급하신다)  우상 및 하나님 이외의 것들을 숭배하지 않으며 하나님께로 참회하며 돌아가는 자들은 임종 시에, 무덤에 머물 때, 그리고 부활의 날에 천국이라는 기쁜 소식을 받을 것이라. 그러니 그대-사도여! -는 하나님의 종복들에게 기쁜 소식을 알리라.",
  39018: "그들은 사람들의 말을 들은 후 좋은 말과 나쁜 말을 구분하여 효용이 있는 좋은 말만을 따르는 자들이라. 저들은 하나님께서 인도해 주신 자들이며 저들이야말로 건전한 이성을 지닌 자들이라.",
  39019: "그러나 불신과 방황을 지속하여 징벌의 말씀이 의무화된 자가 있으니, 그대-사도여! -는 그 무엇으로도 그를 인도할 수 없노라. 이러한대도 그대-사도여! -가 저들을 지옥 불에서 구해 줄 수 있단 말인가?",
  39020: "그러나 하나님께서 명하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 자신의 주님을 경외하던 자들은 (천국에서) 명예로운 거처를 가질 것이니, 그곳의 방은 차곡히 위로 올려진 방들이며, 그 아래에는 강이 흐르노라. 하나님께서는 그들에게 이와 같은 약속을 하셨고, 하나님께서는 결코 약속을 어기지 않으시노라.",
  39021: "그대들은 이미 목격하여 잘 알고 있노라: 하나님께서는 하늘에서 비를 내리시어 그것을 대지의 우물과 냇물로 들어가게 하신 후 그것으로써 다양한 색깔의 농작물을 꺼내시노라. 그 후 농작물은 메말라 버리고 그대-목격하는 자여! -는 푸르던 농작물이 누렇게 변함을 보며, 그 후 하나님께서는 건조해진 그 누런 농작물을 부서진 조각으로 만드시노라. 건전한 이성을 지닌 자들은 이러한 자연 현상을 통하여 깨달음을 얻을 것이라.",
  39022: "그러할진대, 하나님께서 마음을 열어 주시어 이슬람으로 인도되고 주님께서 주신 통찰의 지식을 따르는 자와, 마음이 모진 나머지 하나님을 떠올리지 못하는 자가 같을 수 있는가?! 결코 같을 수 없노라. 인도된 자들은 성공한 자들이며, 마음이 모질어 하나님을 기억하지 않는 자는 실패한 자들이라. 저들은 분명 진리로부터 멀어져 방황하고 있노라.",
  39023: "하나님께서는 당신의 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 가장 훌륭한 말씀인 꾸란을 계시하셨노라. 이 꾸란은 진실성과 아름다움 및 상호 부합성에 있어 그 구절들이 서로 유사하며, 그 안에는 역사와 규정 및 약속과 경고 그리고 천국과 지옥의 거주자들에 관한 이야기가 다양하게 반복되어 언급되노라. 하나님을 두려워하는 자들은 꾸란의 경고 메시지를 들을 때면 피부로 온 몸의 전율을 느끼노라. 그 후 그들이 꾸란의 기쁜 소식과 희망의 메시지를 들을 때면 그들의 피부와 마음은 다시금 하나님을 떠올림으로 평정을 되찾노라. 꾸란과 꾸란이 지닌 이 같은 감동은 하나님의 인도이며, 하나님께서는 이를 통해 원하시는 자를 인도하시노라. 그러나 만약 하나님께서 누군가를 내버려 두시어 그에게 올바른 길로 들어가는 성공을 주지 않으신다면 그 어떤 이도 그를 인도할 수 없노라.",
  39024: "그렇게, 하나님께서 인도해 주시어 현세에서 성공을 주시고 내세에서는 천국에 들게 하시는 자가 있고, 불신으로 죽음을 맞이하였기에 손발이 묶여 얼굴이 처박힌 채로 지옥 불에 들어가는 자가 있노라. 그 둘이 같을 수 있는가? 불신과 거역 행위로 자신의 영혼을 부당히 대우하던 자들에게 힐책의 목소리가 들릴 것이라. \"너희가 저지르던 불신과 거역 행위를 맛 보라. 이것이 바로 그에 대한 징벌이라\"",
  39025: "저 우상 숭배자들 이전의 공동체들도 부정하였노라. 이로 말미암아 그들이 예상치 못한 곳에서 갑자기 징벌이 찾아왔으니, 그들은 참회를 준비할 시간도 갖지 못하였노라.",
  39026: "그렇게 하나님께서는 그들에게 현세의 삶에서 모욕과 불명예의 벌을 맛 보게 하셨노라. 그러나 그들이 알고만 있다면, 실로 내세에서 그들을 기다리는 징벌은 그보다 더 무겁고 혹독하노라.",
  39027: "진실로 하나님께서는 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 계시된 이 꾸란을 통해 선과 악, 진리와 허위, 신앙과 불신 등 사람들을 위한 다양한 예시를 들었노라. 이는 그들이 예시를 통해 교훈을 얻고, 진리를 실천하면서 허위를 멀리하도록 유도하기 위함이라.",
  39028: "하나님께서는 꾸란을 아랍어로 계시하시어 그 안에 어떠한 어긋남이나 일탈, 혼동도 없게 하셨노라. 이는 그들이 하나님께서 명령한 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외토록 하기 위함이라.",
  39029: "하나님께서는 다신을 숭배하는 자와 하나님 한 분만을 경배하는 자의 예시를 드시노라. 사이가 나쁜 동업자들이 노비 한 명을 소유할 경우, 노비가 무슨 일을 하더라도 일부는 그의 일에 만족하지만 다른 일부는 못마땅해 하니, 노비는 어찌할 바를 모르노라. 반면 주인 한 명이 노비 한 명을 소유할 경우, 노비는 주인이 원하는 것을 잘 알고 있기에 마음이 평안하고 정신이 안정되노라. 이 두 노비의 상태는 결코 같을 수 없노라. 모든 찬미는 하나님의 것이라. 그러나 그들 대부분은 무지하여 하나님께 대등한 존재를 두더라.",
  39030: "실로 그대-사도여! -는 죽음을 맞이할 운명이며, 그들 역시도 결코 죽음을 피할 수 없노라.",
  39031: "그 후 실로 그대들-사람들이여! -은 심판의 날, 서로 의견이 엇갈리던 사안을 두고서 그대들의 주님 앞에서 논쟁할 것이며, 하나님께서는 그대들 중 누가 올바르고 그른지를 판결하실 것이라.",
  39032: "그러니 하나님께 대등한 존재나 배우자, 자식 등을 두어 그분께 거짓말을 하는 자보다 더 부당한 자는 없으며, 하나님의 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 가져온 계시를 부정하는 자보다 더 부당한 자는 없노라. 하나님을 불신하고 그분의 사도가 가져온 메시지를 불신하는 자들은 지옥에서 영원히 머무를 운명이 아니던가? 그러하도다. 실로 그들의 거처는 불지옥이라.",
  39033: "(하나님께서는 이전 구절에서 거짓말을 일삼는 자들을 언급하셨고 여기서부터는 진실된 자들에 관하여 말씀하신다)  말씀과 행동에 진실된 선지자들과 그들이 가져온 것을 믿고 실천하는 신앙인들, 그들이야말로 주님의 명령을 따르고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하는 자들이라.",
  39034: "그들은 하나님께 가까운 곳에서 영원한 기쁨을 누릴 것이라. 이것이야말로, 하나님을 위한 경배와 인간과의 교류 모두에 있어 최선을 다하던 자들이 가질 보상이라.",
  39035: "그리하여 하나님께서는 그들을 위하여 그들이 현세에서 저질렀던 가장 나쁜 악행을 용서해 주실 것이니, 그들은 악행을 저지른 후 하나님께 돌아가며 진심으로 참회하였기 때문이라. 또한 하나님께서는 그들의 행위 중에서도 가장 훌륭한 선행으로써 그들을 보상해 주실 것이라.",
  39036: "현세와 내세에서 하나님의 종복 무함마드를 지켜줄 자는 하나님 한 분만으로 충분하지 않던가? 그러나, 무지하고 우둔한 그들은 그대-사도여! -를 위협하면서 우상들이 그대에게 재앙을 내릴 것이라 말하더라. 하나님께서 내버려 두시어 인도받는 성공을 주지 않으시는 자는 그 누구도 그를 인도해 줄 수 없노라.",
  39037: "하나님께서 인도해 주시는 자라면 그 누구도 그를 방황시킬 수 없노라. 실로 하나님께서는 그 누구에게도 제압당하지 않으시는 가장 존엄하신 분이며, 당신을 불신하고 거역하는 자들을 응징하시는 분이라.",
  39038: "그대-사도여! -가 저 우상 숭배자들에게 \" (일곱) 하늘과 땅을 창조하신 분이 누구인가? \"라고 묻는다면 그들은 정녕코 \"하나님께서 창조하셨소\"라고 말할 것이라. 그대는 우상들의 무능력을 드러내기 위해 말하라. \"그대들은 나에게 알려주시오: 그대들은 하나님 이외의 우상들을 숭배하고 있음에, 만일 하나님께서 나에게 재앙을 원하신다면 그 우상들이 나에게서 그분의 재앙을 걷어내 줄 수 있단 말인가? 아니면 만일 하나님께서 나에게 자비를 내리시길 원하신다면 그것들이 그분의 자비를 막을 수 있단 말인가? \" 그대는 그들에게 말하라. \"나는 하나님 한 분 만으로 충분하며, 나의 모든 일을 그분께 의탁하였노라. (진정으로) 의탁하는 자들 역시도 오직 하나님 한 분께만 의탁하노라\"",
  39039: "그대-사도여! 는 말하라. \"나의 사람들이여! 그대들이 만족해 하는 우상 숭배를 계속해 보라. 나도 하나님께서 나에게 명령하신 유일신 사상으로의 초대와, 진정으로 하나님을 섬기는 일을 계속할 것이라. 우리 각자가 어떠한 결과를 맞이할지는 그대들이 곧 알게 될 것이라.",
  39040: "현세에서 치욕의 벌을 받고 내세에서 영원한 고통이 내릴 자가 과연 누구인지, 그대들은 곧 알게 될 것이라”",
  39041: "실로 하나님께서는 그대-사도여! -에게 진리로써 인류를 위한 꾸란을 계시하셨으니, 그대가 그들에게 경고하기 위함이라. 그리하여 올바른 길을 걷는 자가 있다면 그것은 오직 그 자신에게 효용을 가져다 줄 뿐, 필요를 초월하신 하나님께서는 그를 통해 효용을 얻지 않으시노라. 또한, 방황하는 자는 그 해악이 자신에게로 돌아갈 뿐, 하나님께서는 그의 방황으로 인해 해를 입지 않으시노라. 그대는 그들을 강제로 인도할 책임을 지지 않으며, 그대의 임무는 오직 명령받은 메시지를 전달하는 일 뿐이라.",
  39042: "하나님께서는 정해진 삶의 기간이 종료된 자의 영혼을 거두어 가시며, 아직 그 기간이 종료되지 않은 자의 영혼도 그가 잠들어 있을 때 거두어 가시노라. 그리하여, 죽음이 지정된 자는 거두어 가신 영혼을 그대로 두시고, 아직 죽음이 찾아오지 않은 자는 (그가 잠에서 깨었을 때) 그의 영혼을 다시 육체로 보내시어 정해진 기한 동안 삶을 영위토록 하시노라. 진실로 영혼을 거두시고 되보내심, 생명을 부여하시고 죽음을 지정하심에는 숙고하는 자들을 위한 징표가 있노라: 하나님께서는 이러한 일이 가능한 분이시며, 따라서 인간을 부활시킨 후 심판하는 일도 그분께는 가능한 일이라.",
  39043: "우상 숭배자들은 하나님이 아닌 우상들을 중재자로 삼아 그것들로부터 효용을 얻으려 한단 말인가? 그대-사도여! -는 말하라. \"우상들은 그대들을 통제하지도, 하물며 자기 자신도 제어하지 못하고 이성을 갖추지도 않았는데, 어떻게 그대들은 그것들을 중재자로 삼는 것인가? 고체에 불과한 그것들은 말을 하지도, 듣거나 보지도 못하며, 효용을 주거나 해를 끼칠 능력도 없노라\"",
  39044: "그대-사도여! -는 저 우상 숭배자들에게 말하라. \"그 모든 중재는 오직 하나님만의 소유이기에, 그분께서 허락하시고 흡족해 하시는 자만이 (심판의 날) 그분 앞에서 중재를 시행할 수 있노라. (일곱) 하늘과 땅의 주권은 실로 하나님의 소유라. 그런 후 실로 그대들은 부활의 날 하나님 한 분께로 돌아가게 될 것이며, 그분께서는 그날 그대들의 행위를 계산하시고 그에 의거하여 그대들을 보응하실 것이라\"",
  39045: "하나님 한 분만이 언급되고 부활과 심판, 보응 등이 거론될 때면 내세를 믿지 않는 우상 숭배자들의 마음은 혐오감을 느끼노라. 그러나 하나님이 아닌 우상이 언급될 때면, 보라, 실로 그들은 심히 기뻐하더라.",
  39046: "그대-사도여! -는 말하라. \"하나님이시여! 전례 없는 방식으로 (일곱) 하늘과 땅을 창조하신 분이시여! 보이지 않는 것과 보이는 것을 알고 계시는, 그 무엇도 감추어지지 않는 분이시여! 실로 당신께서는 심판의 날 당신의 종복들이 현세에서 의견을 달리하던 것을 판결하실 것이며, 이로써 진리를 따르던 자와 거짓을 좇던 자, 행복할 자와 불행할 자가 구분될 것입니다 \"",
  39047: "우상 숭배와 거역 행위로 자신의 영혼을 부당히 대하던 자들은 설령 지구상의 모든 금은보화와 그에 곱절을 더한 것을 소유했다 할지라도 그들은 정녕 그것을 부활의 날에 펼쳐질 극심한 벌로부터 벗어나기 위한 몸값으로 바쳤을 것이라. 그러나 그들에게는 그러한 막대한 재산이 없으며, 설령 있다 한들 그들의 몸값은 받아들여지지 않노라. 그리고 이날 하나님께서 내리는 다양한 벌들이 그들에게 전개될 것이며, 이는 그들이 전혀 예상치 못했던 것들이라.",
  39048: "우상 숭배와 거역 행위 등 그들이 저지른 악행이 그들에게 드러날 것이며, 그들이 현세에서 경고받을 때마다 조롱하던 징벌이 그들을 에워쌀 것이라.",
  39049: "한편, 불신자에게 질환이나 가난 등이 닥칠 때면 그는 하나님께 그것을 거두어 달라 기도하노라. 그런 후 하나님께서 그에게 건강과 재산 등의 은총을 선사할 때면 불신자는 \"하나님께서 이것을 주신 것은 그분께서 내가 이것을 받을 자격이 있음을 알고 계시기 때문이라\"고 말하더라. 그렇지 않노라. 그것은 시험이자 서서히 옥죔이나, 대부분의 불신자들은 이를 알지 못한 채 하나님께서 주신 은총에 기만되고 있노라.",
  39050: "그들 이전의 불신자들도 이미 동일한 말을 말하였으나, 그들이 습득한 재산이나 지위 그 어떤 것도 그들에게 도움이 되지 못하였노라.",
  39051: "그리하여 우상 숭배와 거역 행위 등 그들이 저지른 악행에 대한 징벌이 그들에게 내려졌노라. 우상 숭배와 거역 행위 등의 악행을 저지르고 있는 저들에게도 이전의 자들에게 내려진 징벌이 닥칠 것이며, 그들은 하나님을 피해갈 수도, 감히 그분을 이길 수도 없노라.",
  39052: "저 우상 숭배자들이 저러한 말들을 하는 것은 그들이, 원하는 자에게 양식을 증가시키고 감소시키는 분은 다름아닌 하나님이심을 모르기 때문이라. 하나님께서 양식을 늘리시는 것은 시험으로, 인간이 감사하는지 아니면 부정하는지를 보시며, 양식을 줄이시는 것은 시련으로, 인간이 하나님의 운명에 인내하는지 아니면 역정을 내는지를 보시는 것이라. 진실로 양식의 증가와 감소에는 하나님의 위대한 계획을 알려 주는 징표가 있으며, 그 징표는 오직 믿는 자들을 위한 것이라. 그러함은 믿는 자들은 징표를 통해 효용을 얻어 가는 반면, 불신하는 자들은 징표를 가까이 지나갈 때도 등을 돌리며 그 징표를 거부하기 때문이라.",
  39053: "그대-사도여! -는, 하나님께 대등한 존재를 두고 거역 행위를 저지름으로써 자기 자신에 대한 경계를 넘어선 하나님의 종복들에게 말하라. “그대들은 하나님의 자비를 체념하지 말고 하나님께서 그대들의 죄를 용서해 주실 것이라는 희망을 버리지 말라. 하나님께서는 진실로 참회하는 자의 모든 죄를 용서하시노라. 진실로 하나님께서는 뉘우치는 자들을 너그러이 용서하시는 분이며 그들에게 가장 자애로우신 분이라”",
  39054: "그대들은 참회와 선행으로써 그대들의 주님께 귀의하고 그분께 순종하라. 그대들에게 징벌이 찾아올 심판의 날까지도 그렇게 하지 않는다면, 그대들은 우상이나 가족 중에서 그대들을 구해 줄 어떤 누구도 찾지 못할 것이라.",
  39055: "그대들이 참회할 준비도 되어 있지 않은 상황에서 예상치도 못한 시기에 갑자기 징벌이 찾아올 수 있노라. 그 시간이 오기 전에 그대들은 꾸란을 따르라. 꾸란은 그대들의 주님께서 당신의 사도에게 계시하신 가장 훌륭한 성서이니, 꾸란에 명령된 사항을 지키고 금지된 사항은 멀리하라.",
  39056: "그러함은 영혼이 부활의 날에 크게 후회하며 이렇게 말하지 않기 위함이라. \"비통하도다! 나는 하나님께 소홀하여 그분을 불신하고 거역하였으며, 믿음을 가지고 순종하는 자들을 멸시하기에 바빴구나\"",
  39057: "아니면 운명을 탓하며 \"만일 하나님께서 나를 인도해 주셨다면 나는 하나님을 경외하는 자가 되어 그분께서 명령한 것을 지키고 그분께서 금지하신 것을 멀리했을 텐데”라고 말하거나,",
  39058: "징벌을 목격했을 때 소망하며 말하길 \"만일 현세로 되돌아갈 수만 있다면 나는 하나님께 참회하고 모든 일에 최선을 다하는 자가 되었을 텐데\"라고 하지 않기 위함이라.",
  39059: "목소리가 들릴 것이라. \"네가 인도되기를 소망해 보지만 현실은 그와 다르노라. 너에게는 이미 (현세에서) 하나님의 징표들이 도래한 적이 있노라. 그러나 너는 그것을 부정하였고 거만해 하였으며, 너는 하나님과 그분의 징표와 사도들을 불신하는 자들 중의 하나였노라\"",
  39060: "부활의 날 그대는, 하나님께 대등한 존재를 두거나 그분께 자식이 있다고 거짓말을 하던 자들의 얼굴이 어두워짐을 볼 것이라. 하나님에 대한 믿음과 그분의 사도들에 대해 거만해 하던 자들의 거주지는 불지옥으로서, 그들은 그 안에서 영원히 머물 것이라.",
  39061: "하나님께서 명령하신 사항을 지키고 그분께 금지하신 사항을 멀리함으로써 하나님을 경외하던 자들은 하나님께서 그들을 징벌에서 구해주시어 구원의 장소인 천국에 들게 하실 것이라. 그들에게는 징벌이 닥치지 않을 것이며, 그들은 현세에 두고 온 향락에 슬퍼하지도 않을 것이라.",
  39062: "모든 것은 하나님께서 창조하셨으니, 그 분 이외에는 창조자가 없노라. 하나님께서는 모든 것의 보호자이시고 모든 일을 주관하시며 원하시는 대로 결정하시노라.",
  39063: "(일곱) 하늘과 땅에 있는 부 (富) 의 곳간 열쇠를 소유하고 계신 분이 하나님이시라. 그분께서는 원하시는 자에게 그것을 열어 주시고 원하시는 자에게 그것을 닫아 놓으시노라. 하나님의 징표를 불신하는 자들, 그들이야말로 진정한 손실자들이니, 그들은 현세에서 신앙을 가지는 성공을 얻지 못했고 내세에서는 불지옥에 들어가 그곳에서 영원히 머물기 때문이라.",
  39064: "저 우상 숭배자들은 그대에게, 자신들이 숭배하는 우상을 그대도 섬기라 종용하니, 그대-사도여! -는 그들에게 말하라. \"그대들은 지금 나에게 하나님 이외의 것을 숭배하라 명령하는 것인가? 그대들은 자신의 주님이 누구인지도 모르는 무지한 자들이라! 오직 하나님 한 분만이 경배받으실 권리를 가지시기에, 나는 그분 이외에 그 누구도 숭배하지 않을 것이라\"",
  39065: "진실로 하나님께서는 그대-사도여! -와 그대 이전의 사도들에게 계시를 내리셨노라. “만일 그대가 정녕 하나님을 경배하면서 다른 존재도 숭배한다면 맹세코 그대의 선행은 보상받지 못한 채 쓸모 없게 되어 버릴 것이며, 맹세코 그대는 현세에서 종교를 잃고 내세에서는 징벌을 받는 손실자가 될 것이라”",
  39066: "그들의 종용과는 달리 그대는 하나님께 대등한 존재를 두지 말고, 그분 한 분만을 경배할 것이며, 하나님께서 그대에게 내리신 은총에 감사하는 자가 되어라.",
  39067: "우상 숭배자들은 미약하고 무능력한 피조물들을 하나님과 대등한 존재로 둠으로써 하나님의 위엄을 제대로 높이지 않았으며, 그들은 하나님의 능력에 관해 제대로 알지 못하였노라. 하나님의 위대한 능력에 대한 징표 중의 하나는 심판의 날 그분께서 산과 나무와 강과 바다가 있던 땅을 그분의 손으로 움켜 쥐신다는 것이며, 일곱 개의 하늘 그 모두가 그분의 오른손 안에서 말려진 것이 된다는 것이라. 우상 숭배자들이 하나님께 관하여 함부로 말하고 상상하나, 하나님께서는 그 어떤 결점도 없으시며 신성하시며 지고하시노라.",
  39068: "그날 나팔을 부는 임무를 맡은 천사가 나팔을 불 것이라. 이에 (일곱) 하늘에 있던 자들과 땅에 있던 자들 모두는 죽음을 맞이할 것이나, 하나님께서 죽음을 원하시지 않는 자는 예외라. 그런 후 천사가 부활을 위해 다시 한번 나팔을 불 것이니 이제 되살아난 그들 모두는 선 채로, 하나님께서 그들에게 무엇을 하실지를 기다릴 것이라.",
  39069: "존엄하신 하나님께서 종복들 사이를 구분하시러 당신의 모습을 드러내실 때 대지는 그분의 빛으로 가득할 것이라. 그리고 사람들의 행위 기록부가 펼쳐지게 되며, 선지자들이 대령되고, 사람들의 행위를 기록하고 증언하는 천사들이 대령될 것이라. 하나님께서는 그들 모두를 공정으로써 판결하시기에 그들은 그날 부당히 다루어지지 않을 것이라. 그렇게 인간은 그 어떤 악행도 증가됨이 없이, 그 어떤 선행도 감소됨이 없이 공정히 판결받을 것이라.",
  39070: "선행이든 악행이든 하나님께서는 모든 이의 행위를 완전히 계산하여 보상하시니 그분께서는 그들이 행한 것을 그 누구보다도 잘 아시노라. 그들의 행위 중 선행이든 악행이든 그 어떤 것도 하나님께 감추어진 것이란 없으며 이날 그들의 좋은 행위와 나쁜 행위에 대해 하나님께서 그들을 보응하실 것이라.",
  39071: "천사들이, 불신하던 자들을 무리 지어 치욕적으로 지옥으로 몰고 가노라. 결국 그들이 지옥에 도달하고, 지옥의 문을 관리하는 문지기 천사들이 그들을 위해 지옥의 문을 열더라. 그들은 불신자들을 쳐다보며 꾸짖노라. “너희로부터 나온 사도들이 너희에게 이르러, 너희에게 계시된 너희 주님의 징표를 낭송하고, 너희에게 심판의 날의 만남과 그날에 있을 엄중한 벌을 경고하지 않았던가? ” 불신자들이 그들의 잘못을 인정하면서 말하노라. “그렇습니다. 그러나 징벌의 말씀이 불신자들에게 의무화 되었고 저희는 불신자들이었습니다”",
  39072: "목소리가 들리니, 이 목소리는 그들이 굴욕을 맛 보고 하나님의 자비나 지옥으로부터의 탈출을 체념토록 하기 위함이라. “너희는 지옥의 문을 거쳐 지옥으로 들어가 그 안에서 영원히 머물라” 그러니 진리에 대해 오만해 하던 자들의 거주지란 얼마나 흉악한 곳인가.",
  39073: "천사들이, 하나님께서 명령하신 것을 지키고 그분께서 금지하신 것을 멀리하며 자신들의 주님을 두려워하던 자들을 무리지어 부드럽게 천국으로 몰고 가노라. 결국 그들이 명예롭게 천국에 도달하고, 천국의 문을 관리하는 문지기 천사들이 그들을 위해 천국의 문을 열더라. 그리고는 그들에게 말하노라. “그대들이 모든 해악과 그대들이 기피하는 모든 것들로부터 안전하기를. 그대들의 마음과 행위는 훌륭하였으니 천국으로 들어가 그곳에서 영원히 머무시오”",
  39074: "믿는 자들은 천국에 들어갈 때 이렇게 말할 것이라. “모든 찬미는 하나님께 있습니다. 하나님께서는 당신의 사도들을 통해 하신 약속, 즉 저희가 천국에 들어갈 것이라는 당신의 약속을 지켜주셨습니다. 그리고 하나님께서는 저희에게 천국의 땅을 물려주시어, 저희가 바라는 어디서든지 살 수 있게 해주셨습니다” 그러니 주님의 얼굴을 바라며 선행을 실천하는 자들의 보상이란 얼마나 훌륭한 것인가.",
  39075: "증언이 이루어지는 이날 천사들은 권좌 주위를 맴돌 것이며, 그들은 불신자들이 하나님께 관해 함부로 내뱉는 말을 부정하며 하나님의 완벽함을 드높일 것이라. 하나님께서는 그 모든 창조물들을 공정함으로써 판결하시어, 명예를 받을 자는 명예를 받고 징벌을 받을 자는 징벌을 받을 것이라. 이에 목소리가 들리노라. “하나님께서는 믿는 자들에게는 자비를, 불신자들에게는 징벌을 판결하셨습니다. 그러니, 모든 찬미는 피조물들의 주님이신 하나님께 있습니다”",
  40000: "가피르 (용서하시는 분)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님의 징표를 두고 논쟁하는 자들을 응대하고 있다. 이 장은 그들과 대화하면서 그들이 진리로 돌아올 것을 말한다.\n•    요약 주해",
  40001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  40002: "꾸란은, 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 인간에게 유용한 것이 무엇인지를 알고 계신 하나님에게서 비롯한 것으로, 하나님께서 당신의 사도인 무함마드에게 내린 계시라.",
  40003: "하나님께서는 죄지은 자들의 죄를 용서하시고 뉘우치는 자들의 참회를 받아 주시노라. 그러나 그분께서는 죄를 저지른 후에도 참회하지 않는 자들을 엄하게 응징하시며, 그분께서는 풍성한 은총을 가지신 분이라. 하나님 이외에는 경배받을 권리를 지닌 자 없으며, 심판의 날 인간이 돌아갈 곳은 실로 하나님 한 분으로, 그분께서는 그대들의 몫을 빠짐없이 보상하실 것이라.",
  40004: "하나님의 한 분 되심과 사도들의 정직함을 드러내는 하나님의 징표들을 부정하는 자들은 건전한 이성을 가지지 못한 불신자들 뿐이라. 그러니 그대는 그들로 인해 슬퍼하지 말라. 불신자들이 누리는 많은 은총과 양식과 그들의 벌이 유예됨은 그들을 서서히 옥죄는 징벌의 과정일 뿐이라.",
  40005: "저들 이전에도 노아의 백성이 하나님을 부인하였노라. 그리고 노아 이후 시대의 아드 부족, 싸무드 부족, 롯의 백성, 미디안의 부족, 파라오 등 불신으로 동맹을 이룬 자들도 하나님을 부인하였노라. 이 모든 공동체는 그들에게 보내진 사도에 악의를 품고 그를 붙잡아 살해하려 하였노라. 또한 그들은 자신들이 가진 거짓으로 논쟁을 벌여 진리를 없애려 하였노라. 이에 하나님께서 저 공동체들 모두를 파괴하셨음에, 그대는 하나님의 엄벌이 얼마나 엄중했는지를 숙고하라.",
  40006: "하나님께서 이전에 불신하던 공동체에게 멸망을 판결하셨던 것처럼 불신자들에게 그대-사도여! - 주님의 말씀이 의무화되었느니, 실로 그들은 불지옥의 거주자들이 될 것이라.",
  40007: "그대-사도여! - 주님의 권좌를 떠받치는 천사들과 그분의 권좌 주위에 있는 천사들은 하나님의 무결하심을 찬미하며 그분을 믿노라. 그리고 그들은 하나님을 믿는 자들을 용서해 달라고 요청하니, 기도를 하면서 이렇게 말하노라. \"저희의 주님이시여! 당신의 자비와 지식은 모든 것을 아우릅니다. 그러니 자신의 죄를 뉘우치고 당신의 종교를 따르는 자들을 용서해 주시옵고, 타오르는 지옥 불로부터 그들을 보호해 주십시오\"",
  40008: "천사들이 말하노라. \"저희의 주님이시여! 그들이 당신께서 입성을 약속하신 천국으로 들어갈 수 있도록 해 주십시오. 그리고 선행을 행한 그들의 선조들과 배우자들과 후손들도 그들과 함께 천국에 들게 해 주십시오. 실로 당신께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이십니다\"",
  40009: "\"그리고 그들의 악행이 낳은 사악함으로부터 그들을 구해 주시어 그들을 벌하지 말아 주십시오. 부활의 날 악행에 기인한 징벌을 받지 않도록 당신께서 보호해주신 자는 진실로 당신께서 그에게 자비를 베푸신 것입니다. 징벌로부터 보호되고, 자비를 받아 천국으로 입성하는 것이야말로 그 무엇과도 비교되지 않는 위대한 성공입니다\"",
  40010: "하나님과 그분의 사도들을 불신한 자들은 심판의 날 지옥으로 들어가면서 자기 자신을 혐오하고 저주하노라. 이 때 목소리가 그들을 부르노라. \"현세에서 그대들에게 하나님을 믿으라는 말이 있었으나, 그대들은 이를 거부하고 우상을 숭배하였노라. 믿음으로 초대받았으나 너희가 불신하였을 때, 하나님께서 너희를 혐오하심은 너희가 자기 자신을 혐오하는 것보다 더 크노라\"",
  40011: "불신자들은, 죄를 인정하거나 참회하는 일이 소용 없는 심판의 날에 뒤늦게 자신들의 죄를 인정하며 말할 것이라. \"저희의 주님이시여! 당신께서는 저희에게 두 번 죽음을 부여하셨습니다: 존재하지 않는 죽음의 상태에서 저희를 존재하도록 하셨고, 존재하여 살아 있던 저희를 다시 죽게 하셨습니다. 그리고 당신께서는 저희에게 두 번 생명을 불어넣으셨습니다: 없던 저희에게 생명을 주시어 있게 하셨고, 부활을 위해 저희를 또 한 번 되살리셨습니다. 이에 저희는 저희가 저지른 죄를 인정합니다. 그러니 저희가 불지옥으로부터 빠져나갈 어떤 방도라도 있겠습니까? 저희가 현세로 돌아갈 수만 있다면 저희는 당신의 기쁨을 사는 선량한 행위를 하겠습니다\"",
  40012: "너희가 이러한 벌을 받는 이유는, 너희에게 하나님께 대등한 존재를 두지 말고 그분 한 분만을 믿으라 했을 때 너희는 하나님을 불신하면서 그분께 우상을 두었기 때문이라. 반면 하나님께 대등한 존재가 두어져 우상이 숭배될 때는 너희가 믿었노라. 이제 판결의 권리는 하나님 한 분께 있도다. 하나님께서는 당신의 존재와 능력이 지고하신 분이며, 그 무엇과도 비교될 수 없는 가장 위대하신 분이라.",
  40013: "하나님께서는 지평선에서, 그리고 그대들 자신에게서 당신의 전능하심과 한 분 되심을 가리키는 징표를 그대들에게 보여 주시노라. 그리고 하나님께서는 그대들을 위해 하늘에서 비를 내리시어, 그로 인해 그대들이 채소와 곡물 등의 양식을 얻을 수 있도록 하시노라. 하나님의 징표로부터 깨달음을 얻는 자는 오직 참회하며 하나님께 돌아가는 자들 뿐이라.",
  40014: "그러니 그대들-믿는 자들이여! -은 불신자들이 혐오하고 화를 낼지언정 하나님께 기도하고 순종함으로써 진정으로 종교에 임하고, 그분께 대등한 존재를 두지 말지어다.",
  40015: "그렇게 진정어린 기도와 순종을 받으실 분이 하나님으로, 그분께서는 위상이 무한히 드높으시어 그 어떤 피조물과도 비교되지 않으시는 분이라. 그분께서는 위대한 권좌의 주님이시며, 당신의 종복들 중 원하시는 자에게 계시를 내리시는 분이라. 그리하여 계시를 받은 자들이 소생하고, 그들이 다른 이들을 소생시키며, 선대와 후대의 모든 이들이 만나게 될 부활의 날을 사람들에게 경고하기 위함이라.",
  40016: "그날 실로 그들은 하나의 평원에 모인 채 자신의 모습을 드러낼 것이며, 그들의 그 어떤 것도 하나님께 숨겨지지 않을 것이니, 그들의 자아와 행위와 보응 등 그 모든 것이 공개될 것이라. 그분께서 물으실 것이라. \"이날의 주권은 누구의 소유인가? \" 그날의 대답은 오직 하나로, 그날의 주권은 그 존재와 속성과 행위가 유일무이하신 분, 모든 것을 제압하시고 모든 것이 굴종할 수 밖에 없는 하나님 한 분만의 소유라.",
  40017: "그날 모든 영혼은 자신의 행위로 보응을 받을 것이라: 그것이 선행이라면 선으로 보상받고, 그것이 악행이라면 악으로 응징받노라. 이러한 판결을 내리시는 분은 가장 공정하신 하나님이시기에 그날에 부당함이란 있을 수 없노라. 실로 하나님께서는 인간의 행위를 아우르고 계시며, 따라서 그것을 계산하실 때도 신속히 하시노라.",
  40018: "그대-사도여! -는 그들에게 부활의 날이 다가오고 있음을 경고하라. 그날 인간의 심장은 엄청난 두려움으로 터져버릴 지경이며, 가장 자비로우신 분께서 허락하신 경우가 아닌 이상 그들 중 누구도 말을 하지 못하노라. 우상 숭배와 거역 행위로 자신의 영혼을 부당히 다룬 자들에게는 그를 도와줄 절친한 친구도, 영향력을 발휘할 중재자도 없도다.",
  40019: "하나님께서는 인간이 곁눈으로 슬그머니 보는 것과, 마음속에 감추고 있는 내밀한 것도 다 알고 계시니, 그분께는 그 무엇도 감추어지지 않노라.",
  40020: "하나님께서는 판결함에 공정하시기에 선행에 대한 보상을 감소시키거나 악행에 대한 징벌을 증가시키지 않으시노라. 우상 숭배자들이 숭배하는 하나님 이외의 것들은 그 어떤 것으로도 판결을 내리지 못하니, 그들은 아무 것도 소유하지 않고 있기 때문이라. 진실로 하나님께서는 종복들의 말을 듣고 계시는 분이시며, 그들의 의도와 행위를 보고 계시는 분이라. 그리고 그분께서는 이에 의거하여 그들을 보응하실 것이라.",
  40021: "저 우상 숭배자들은 대지를 지나가면서 그들 이전에 있었던 불신자 공동체들의 말로가 어떠했는지를 보지 않았단 말인가? 그들의 마지막은 처참하였노라. 이 공동체들은 저들보다 더 강력한 힘을 가지고 있었으며, 대지에 그 누구도 짓지 못한 건축물들을 남겼노라. 그러나 하나님께서는 그들의 죄로 말미암아 그들을 멸망시키셨으니, 그 누구도 하나님의 징벌로부터 그들을 보호해 줄 수 없었노라.",
  40022: "그들에게 재앙이 닥친 이유는, 하나님의 사도들이 분명한 증거를 가지고 그들에게 찾아왔음에도, 그들이 하나님을 불신하고 그분의 사도들을 거짓말쟁이로 몰아갔기 때문이라. 이에 하나님께서는 그들을 움켜쥐셨고, 강력한 힘을 가진 그들이었건만 그들은 그로 인해 멸망해 버렸노라. 실로 하나님께서는 강하신 분이며, 당신을 불신하고 사도를 부정하는 자를 응징함에 엄하신 분이라.",
  40023: "(사람들은 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 를 부정하였다. 이에 하나님께서는 무함마드에게 모세가 겪은 파라오와의 일을 언급하심으로써 결국에는 그가 승리를 거둘 것이라는 기쁜 소식을 전하고 계신다. )  진실로 하나님께서는 모세에게 당신의 명백한 징표들과 확실한 근거를 주시어 그를 사도로 보내셨으니",
  40024: "파라오와 그의 참모인 하만과 까룬에게로 보내셨노라. 이에 그들이 말하였노라. \"모세는 주술가일 뿐이며, 거짓말을 해대며 자신을 사도라 주장하고 있노라\"",
  40025: "모세가 그들에게 자신의 사도직을 증명하는 명백한 증거를 가져왔을 때 그들이 말하였노라. \"모세와 함께 하며 믿음을 가진 자들을 능욕하라. 그들의 사내아이는 죽이고 그들의 여인네는 남겨 두라\" 그러나 믿는 자들의 숫자를 줄이려는 불신자들의 계략은 원하는 바를 이루지 못하고 방황할 뿐이라.",
  40026: "파라오가 말하였노라. \"나를 내버려두라, 나는 모세를 죽이고야 말 것이라. 그러니 그는 자신의 주님에게 기도하여, 어디 한번 나를 막아보도록 하라. 나는 그의 기도에 개의치 않노라. 내가 염려하는 것은 모세가 그대들이 따르는 종교를 바꾸거나 그가 지상에서 살해나 파괴 등의 해악을 퍼뜨리는 것이라\"",
  40027: "파라오로부터의 협박에 모세가 말하였노라. \"실로 나는 나의 주님이자 그대들의 주님께, 보상과 징벌이 있을 심판의 날을 믿지 않으며 진리와 신앙에 거만해 하는 자로부터 보호와 구원을 요청하였노라\"",
  40028: "파리오의 가문 중에는 믿음을 가진 남자가 하나 있었으니, 그는 사람들에게 자신의 믿음을 감추었노라. 그는 모세를 죽이려 작정한 자들을 비판하며 말하였노라. \"그대들은 '나의 주님은 하나님이오'라고 말했다는 이유로 죄 없는 남자를 살해하려는 것입니까? 실로 그는 그대들에게 자신의 사도직을 증명하는, 하나님으로부터의 분명한 증거들을 가지고 왔습니다. 만일 그가 거짓을 말하는 자라면 그의 거짓말은 자기 자신을 해칠 뿐이며, 만일 그가 진실을 말하는 자라면 그가 그대들에게 경고한 징벌의 일부가 그대들을 덮칠 것입니다. 실로 하나님께서는 당신께서 지정하신 경계를 넘어서면서 당신께 관해 거짓말을 일삼는 자를 진리로 인도하지 않으십니다\"",
  40029: "\"나의 사람들이여! 그대들은 오늘날 이집트의 땅에서 압도하는 자들로서 권력을 소유하고 있습니다. 그렇지만 그대들이 만약 모세를 죽인다면 그로 말미암아 우리에게 하나님의 엄벌이 찾아올 것입니다. 그 때 과연 누가 우리를 도와줄 수 있단 말입니까? \" 파라오가 말하였노라. \"나의 견해만이 견해이며, 나의 판결만이 판결이라. 나의 견해는 모세를 살해하는 것이며, 그로써 해악을 방지할 것이라. 나는 그대들을 오직 올바르고 정확한 길로 인도할 뿐이라\"",
  40030: "믿는 자가 사람들에게 조언하며 말하였노라. \"나의 사람들이여! 만일 그대들이 적의로써 부당히 모세를 살해한다면 그대들에게 징벌이 내려질 것입니다. 마치 사도들을 상대로 이전에 폭거를 일으킨 동맹군들이 하나님의 징벌로 멸망한 것처럼, 그대들도 그렇게 될까 두렵습니다\"",
  40031: "\"나는 노아의 백성과 아드 부족과 싸무드 부족과 그들 이후에 있었던 자들이 겪은 전례와 유사한 것이 그대들에게 닥칠까 두려운 것입니다. 그들은 불신을 저지르고 사도들을 거부한 나머지 하나님의 벌을 받아 멸망하고 말았습니다. 그들이 받은 벌은 오직 그들의 죄 때문이며, 하나님께서는 그 어떤 종복들에게도 부당함을 원치 않으십니다\"",
  40032: "\"나의 사람들이여! 실로 나는 그대들에게 심판의 날이 닥칠까 두렵습니다. 그날은 사람들이 무서움에 떨면서 서로가 서로에게 소리 질러, 가까운 친척이나 권력자에게 도움을 구걸하는 날입니다\"",
  40033: "\"그날 그대들은 불지옥이 무서워 도망칠 테지만, 그대들에게는 하나님의 징벌을 막아 줄 그 어떤 수호자도 없을 것입니다. 하나님께서 내버려 두시어 믿음이라는 성공을 주지 않으시는 자는 그를 위한 그 어떤 인도자도 없을 것입니다. 인도받는 성공은 오직 하나님의 손에 달려 있기 때문입니다\"",
  40034: "\"실로 모세 이전에 요셉이 그대들에게 유일신 신앙에 관한 분명한 증거를 가지고 찾아온 바 있습니다. 그럼에도 그대들은 그가 가져온 메시지를 지속적으로 의심하며 그 메시지를 거짓으로 치부하였습니다. 결국 그가 돌아가셨을 때 그대들은 의심을 더하며 '하나님께서는 요셉 이후에 어떤 사도도 보내지 않으실 것이라'고 말하였습니다. 그대들이 진리에서 멀어져 방황하는 것처럼 그렇게 하나님께서는 당신의 경계를 넘어서면서 유일신 신앙에 의심을 품는 자를 방황케 하십니다\"",
  40035: "\"그들은 하나님의 징표를 부정하기 위해 근거도 없이 논쟁을 벌이는 자들로서, 그들의 논쟁은 하나님께 있어, 그리고 그분과 그분의 사도를 믿는 자들에게 있어 매우 혐오스러운 것입니다. 하나님께서 논쟁을 벌이는 저들의 마음을 봉하신 것처럼 그렇게 하나님께서는 진리 앞에서 거만해 하며 거드름을 부리는 모든 자의 마음을 봉하십니다. 그리하여 그들은 올바름이나 선으로 인도받지 못하게 됩니다\"",
  40036: "파라오는 자신의 참모 하만에게 말하였노라. \"하만이여! 나를 위해 마천루를 지어라. 내가 통로에 도달하기 위함이라\"",
  40037: "\"그 통로는 하늘로 향하는 통로로서, 내가 모세가 경배하는 소위 진짜 신을 들여다 보기 위함이라. 진실로 나는 모세의 주장이 거짓임을 확신하노라\" 파라오가 하만에게 이러한 것을 요구할 때 파라오에게는 자신이 저지르는 악행이 선행으로 치장되었노라. 그리고 진리로의 길이 차단되어 파라오는 결국 방황의 길로 들어섰노라. 파라오는 자신이 따르는 허위를 옹호하고 모세가 가져온 진리를 파괴하려 하였으나, 그의 이러한 계략은 오직 궤멸 속에 있었을 뿐이라: 그가 맞이할 결말은 실패이며, 그의 노력은 헛되었고, 그에게 닥칠 불행은 끊이질 않노라.",
  40038: "파라오 가문 출신의 믿는 남성은 진리로 향하는 길을 제시하면서 사람들에게 조언하였노라. \"나의 사람들이여! 나를 따르십시오. 내가 여러분을 올바른 길로 인도하겠습니다\"",
  40039: "\"나의 사람들이여! 이 현세에서의 삶은 그저 짧은 기간 동안의 유희일 뿐입니다. 그러니 여러분은 얼마 후에 스러질 유희에 속지 마십시오. 반면 내세의 거주지에는 끊이지 않는 영원한 기쁨이 있습니다. 그러니 하나님께 순종함으로써 영원의 거주지를 준비하십시오. 온통 현세의 삶에만 신경을 쓴 나머지 내세를 위한 준비를 소홀히 해서는 안 됩니다\"",
  40040: "\"악을 행한 자는 오직 그가 저지른 악행과 유사한 것으로써 징벌을 받을 뿐이며 그 이상으로는 벌받지 않을 것입니다. 그러나 남자든 여자든, 하나님과 그분의 사도를 믿는 자로서, 하나님의 얼굴을 소망하며 선을 행한 자가 있다면 그러한 자들은 심판의 날 천국에 들어갈 것입니다. 하나님께서는 그곳에서 그들을 위해 과일과 영원한 기쁨을 준비해 두셨고, 그들은 그 끊이지 않는 기쁨을 누리면서 무한정으로 양식을 제공받을 것입니다\"",
  40041: "\"나의 사람들이여! 내가 그대들에게 믿음과 선행을 통해 현세와 내세의 손실로부터 보호받으라 하는데, 그대들은 나에게 하나님을 불신하고 거역하라 하면서 나를 불지옥으로 초대하는 것입니까? \"",
  40042: "\"그대들은 나를 그대들이 믿는 허위로 초대하고 있습니다. 내가 하나님을 불신하고 내가 그 근거를 알지 못하는 우상 숭배를 저질러 하나님께 대등한 존재를 두고 그것들을 숭배토록 종용하고 있는 것입니다. 그러나 나는 그대들을 하나님에 대한 믿음으로 있는 것입니다. 그분께서는 그 누구도 감히 제압할 수 없는 가장 존엄하신 분이며, 사람들을 가장 너그러이 용서하시는 분이십니다\"",
  40043: "\"실로 그대들이 나에게 믿고 따를 것을 종용하는 그 우상들은 현세와 내세에서 그 어떤 기도받을 권리도 지니지 못하며, 기도에 응답할 능력도 없습니다. 실로 우리 모두가 돌아갈 곳은 하나님 한 분이며, 실로 불신과 거역 행위로 도를 지나친 자들, 그들이야말로 심판의 날 불지옥의 거주자들이 될 사람들입니다\"",
  40044: "그러나 그들은 그의 조언을 거부하였고, 이에 그가 말하였노라. \"그대들은 내가 그대들에게 건넨 조언을 곧 기억할 것이며, 나의 조언을 거부한 것을 두고 후회하게 될 것입니다. 저는 저의 모든 일을 하나님 한 분께 맡깁니다. 실로 하나님께는 종복들의 어떤 행위도 감추어지지 않습니다\"",
  40045: "그들이 그를 살해하려 했을 때 하나님께서는 그들의 사악한 책략으로부터 그를 구해 주셨노라. 반면 파라오의 추종자들에게는 익사의 벌이 도래하였으니, 하나님께서는 현세에서 파라오와 그의 군대 모두를 익사시키셨노라.",
  40046: "그들은 죽음 후에 무덤에서 아침 저녁으로 불길에 휩싸여 고통받을 것이라. 심판의 날이 시작되는 날 목소리가 들릴 것이라. “파라오의 추종자들을 가장 혹독한 벌 속에 집어넣으라. 그들은 불신하고 부정하였으며 하나님의 길을 방해하였노라”",
  40047: "그대-사도여! -는 기억하라. 불지옥의 거주자들 중 추종하던 자들과 추종받던 자들이 그곳에서 서로 언쟁을 벌이니, 추종하던 허약한 자들이 추종받던 거만한 자들에게 말하노라. “진실로 우리는 방황하는 당신들을 따르던 자들이었습니다. 그러니 당신들이 우리를 위해 하나님의 징벌의 일부라도 대신 막아줄 수 있겠습니까? ”",
  40048: "추종받던 거만한 자들이 말하노라. “추종한 자든 추종받던 자든 우리들 모두는 불지옥 안에 머물 것이며, 그 누구도 타인의 벌을 막아줄 수 없소. 진실로 하나님께서는 종복들 사이를 판결하시면서 그 모두에게 합당한 징벌을 주셨소”",
  40049: "추종자들과 추종받던 자들은 지옥의 불 속에서 벌을 받으면서, 자신들은 지옥에서 빠져 나가지 못할 것이란 확신이 들었을 때, 그리고 참회할 기회를 얻기 위해 현세로 되돌아가지도 못함을 확신하였을 때, 그들은 지옥의 문지기 천사들에게 말하노라. “그대들의 주님께 기도하여 우리들을 위해 단 하루만이라도 이 영원한 벌을 경감시켜 달라 하십시오”",
  40050: "지옥의 문지기들이 불신자들에게 답하며 말하노라. “하나님의 사도들이 너희에게 분명한 증거를 가지고 오지 않았던가? ” 불신자들이 말하노라. “그렇습니다. 그들은 정녕 우리에게 분명한 증거를 보여 주었습니다” 지옥의 문지기들이 말하노라. “그러면 너희 스스로가 기도해 보라, 우리는 너희를 중재하지 않을 것이라. 불신자들의 기도는 헛될 뿐이니, 불신은 기도가 응답받지 못하는 원인이기 때문이라”",
  40051: "(하나님께서는 이전 구절에서 파라오와 그의 추종자들이 현세와 내세에서 직면할 결말에 대해 말씀하셨다. 이제 여기서부터는 사도들과 신앙인들이 현세와 내세에서 발견할 성공에 대해 언급된다)  진실로 하나님께서는 당신의 사도들과 믿는 자들을 도우실 것이라: 현세에서는 명백한 논거와 적들에 대한 승리로 그들을 도우시며, 내세에서는 그들을 천국으로 입성케 하시고 그들의 적들을 지옥에 들게 함으로써 그들을 도우시노라. 그리고 이 내세에서의 도움은, 선지자들과 천사들과 신앙인들이 메시지가 전달되었음을 증언하고 불신의 공동체들이 그 메시지를 부정하였음을 인정한 후에 이루어지노라.",
  40052: "그날, 불신과 거역 행위로 자신을 부당히 대했던 자들은 자신들의 부당 행위에 대해 변명을 늘어놓지만, 아무 소용이 없는 일이라. 하나님께서는 그들로부터 당신의 자비를 박탈하셨으며, 그들은 고통의 벌이 내려지는 흉악한 곳에서 거주할 것이라.",
  40053: "진실로 하나님께서는 모세에게 지식을 주시어 이스라엘의 자손들이 이를 통해 진리로 인도될 수 있도록 하셨노라. 또한 하나님께서는 이스라엘의 자손들이 세대를 걸쳐 토라를 물려받도록 하셨노라.",
  40054: "토라는 진리로 인도하는 길잡이이며 건전한 이성을 지닌 자들을 위한 깨우침이었노라.",
  40055: "그러니 그대-사도여! -는 그대의 백성이 그대를 부정하고 해악을 끼침에 인내하라. 하나님께서 그대를 도울 것이라는 약속은 의심할 바 없는 진리라. 그대는 그대의 죄를 용서해 달라고 기도하고, 아침 저녁으로 그대 주님의 완벽한 영광을 찬미하라.",
  40056: "실로 하나님의 징표를 부정하기 위해 근거도 없이 논쟁을 벌이는 자들은 진리 앞에 거만해 하면서 그 위로 군림하려 하나, 그들은 결코 자신들이 원하는 바를 이루지 못할 것이라. 그러니 그대-사도여! -는 하나님께 보호를 구하라. 진실로 하나님께서는 종복들이 하는 말을 듣고 계시며, 그들의 행위를 지켜보고 계시노라. 그분께서는 그들의 그 어떤 언행도 놓치지 않으시며, 그들의 언행에 의거하여 그들을 보응하실 것이라.",
  40057: "엄청난 크기의 (일곱) 하늘과 땅을 창조하는 행위가 인간을 창조하는 행위보다 더욱 위대하도다. 그렇게 막대한 넓이의 하늘과 땅을 창조하신 분이시기에 하나님께서는 심판과 보응을 위해 무덤에서 죽어 있는 자들도 부활시킬 수 있으시노라. 그러나 대부분의 인간은 이러한 명백한 사실을 알지 못하며 이를 통해 교훈을 얻으려 하지도 않노라.",
  40058: "보지 못하는 자와 보는 자가 같지 않노라. 또한, 하나님과 그분의 사도들을 믿으며 선행을 실천하는 자들과 그릇된 믿음과 거역 행위로써 악을 저지르는 자가 같지 않노라. 그대들의 깨우침이 참으로 적도다: 만약 그대들이 두 무리의 차이를 인식하였다면 그대들은 하나님의 기쁨을 바라면서 그분을 믿고 선행을 실천하였을 것이라.",
  40059: "종말의 날 하나님께서는 죽어 있던 인간들을 부활시키시어 그들을 심판하실 것이라. 실로 그날은 의심할 여지가 없으며, 실로 그날은 기필코 도래하고야 말 것이라. 그러나 대다수의 인간은 이날의 도래를 믿지 않으며, 이날을 준비하지도 않더라.",
  40060: "그대들-사람들이여! -의 주님께서 말씀하셨노라. “나만을 경배하고 나에게만 요청하라. 그러면 내가 그대들의 기도에 응답하고 그대들을 용서하며 그대들에게 자비를 베풀 것이라. 실로 나를 위한 경배 행위에 거만해 하는 자는 심판의 날 굴종의 모습으로 지옥에 들어갈 것이라”",
  40061: "하나님께서는 그대들을 위해 밤을 어둡게 하시어 그대들이 그 안에서 휴식할 수 있도록 하시고, 낮을 빛으로 밝게 하시어 그대들이 활동할 수 있도록 하셨노라. 진실로 하나님께서는 인간을 위해 보이는 은혜와 보이지 않는 은혜를 내리시는 분이시나, 대부분의 인간들은 자신들이 받은 은혜에 감사하지 않더라.",
  40062: "이렇게 하나님께서는 그대들을 위해 은총을 베푸시는 분이며, 그분께서는 모든 것을 창조하신 분이라. 하나님 이외에는 창조자가 없으며, 그분 이외에는 그 누구도 경배받을 권리가 없노라. 그런데도 그대들은 하나님을 위한 경배 행위에 등을 돌리면서, 아무런 효용이나 해악도 끼치지 못하는 것들을 숭배한단 말인가?",
  40063: "저들이 한 분이신 하나님을 믿지 않고 그분을 경배하지 않으며 돌아섰던 것처럼, 하나님의 유일성을 나타내는 징표를 부정하는 자들도 시간과 장소를 가리지 않고 돌아서노라. 그렇게 그들은 진리로 향하는 올바른 길로 들어서지 못하더라.",
  40064: "하나님께서는 지구를 두심에 그대들을 위한 안정된 정착지로 하시고, 하늘을 두심에 완벽하게 지어진 건축물로 하시어 그대들 위로 떨어지지 않도록 하셨노라. 그리고 하나님께서는, 어머니의 배 속에 태아로 있는 그대들에게 훌륭한 형상을 부여하셨으며, 허락되고 맛있는 음식으로써 그대들에게 양식을 베푸시노라. 그대들에게 이러한 은총들을 베푸시는 분이 바로 그대들의 주님인 하나님이시라. 모든 피조물의 주님이신 하나님께 축복이 가득하며 그분 이외에는 그 어떤 주님도 없도다.",
  40065: "하나님께서는 살아 계시며 죽지 않으시노라. 하나님 이외에는 그 누구도 경배받을 권리가 없노라. 그러니 그대들은 하나님의 얼굴을 바라면서 그분만을 경배하고, 하나님께 대등한 존재를 두지 말되 그분께만 기도하라. 감사와 찬양은 존재하는 모든 것의 주님이신 하나님 한 분께 있노라.",
  40066: "그대-사도여! -는 말하라. \"나에게 우상 숭배가 헛된 것임을 알리는 분명한 증거가 도래하였노라. 이 증거를 통해 하나님께서 나에게 금지하신 일은, 하나님 이외의 우상을 숭배하는 것으로서 그대들은 그것들에 기도하지만 그것들은 그 어떤 효용이나 해악도 끼칠 수 없노라. 그리고 하나님께서 나에게 명령하신 일은, 경배 행위로써 하나님 한 분께만 순종하라는 것으로서 그분 이외에는 그 어떤 주님도 없기 때문이라\"",
  40067: "하나님께서는 그대들의 조상인 아담을 흙에서 창조하셨고, 그 이후에 그대들을 정액 방울에서 창조하셨노라. 그 후 하나님께서는 정액을 고체의 핏덩어리로 만드시고, 그 후 그대들을 어머니 배 속에서 꺼내시어 갓난아이로 태어나게 하시노라. 그 후 그대들은 혈기왕성한 체력에 이르고, 그 후 그대들은 노약자가 되더라. 그대들 중에는 그 이전에 죽음을 맞이하는 자들도 있으니, 이는 그대들이 하나님께서 지정하신 불변의 기한에 이르기 위함이라. 그대들은 이러한 확실한 증거를 통해 하나님의 전능하심과 유일하심을 이해하게 될 것이라.",
  40068: "생명을 불어넣으시는 분은 하나님 한 분이시며, 죽음을 부여하시는 분도 하나님 한 분이시라. 그러하기에 하나님께서는 어떤 일을 결정하셨을 때 단지 그 일에 “있어라”라고 말씀하실 뿐이며, 이에 그것이 있게 되노라.",
  40069: "그대-사도여! -는, 하나님의 분명한 징표를 부정하며 그에 관해 논쟁을 벌이는 자들을 보지 않았던가. 그들의 상태가 놀랍도다. 진리의 선명성에도 불구하고 그들은 진리에 등을 돌리더라.",
  40070: "그들은 꾸란을 부정하였고, 하나님께서 당신의 사도들에게 보내신 진리를 부정하였노라. 진리를 부정하는 자들은 자신들의 부정이 어떠한 결과를 초래하는지 곧 알게 될 것이며, 그 처참한 결말이 무엇인지 곧 보게 될 것이라:",
  40071: "그들의 목에는 멍에가 채워질 것이며, 그들의 다리에는 사슬이 묶일 것이라. 지옥의 벌을 담당하는 천사들은 그들을 끌고 갈 것이니",
  40072: "그들은 부글거리는 물 속으로 끌려갈 것이라. 그런 후 그들은 화염 속에서 불탈 것이라.",
  40073: "그 후 그들을 힐책하는 목소리가 들릴 것이라. \"너희가 하나님과 대등한 존재로 생각하며 숭배해 오던 우상들은 어디에 있는가? \"",
  40074: "\"효용이나 해악도 끼치지 못하는 하나님 이외의 그 우상들은 어디에 있는 것인가? \" 불신자들이 말하노라. \"그것들은 우리를 버려두고 사라져 버렸고 우리는 그들을 볼 수가 없습니다. 실로 우리는 현세에서 경배받을 권리가 없는 것들에게만 기도하였습니다\" 저들을 방황케 하신 것처럼 하나님께서는 그렇게 언제 어디서나 불신자들을 진리로부터 방황시키시노라.",
  40075: "그들에게 목소리가 들릴 것이라. \"너희가 이 같은 고통스런 벌을 받는 이유는 너희가 하나님께 대등한 존재를 둠에 만족하고 크게 기뻐했기 때문이라\"",
  40076: "“너희는 지옥의 문을 거쳐 지옥으로 들어가 그 안에서 영원히 머물라” 그러니 진리에 대해 오만해 하던 자들의 거주지란 얼마나 흉악한 곳인가!",
  40077: "(하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 는 불신자들로부터 많은 고충을 겪었다. 이에 하나님께서는 그에게 인내할 것을 명령하시면서, 그에게 승리를 약속하심으로써 그를 위안하셨다. 하나님께서 말씀하셨다: )  그러니 그대-사도여! -는 사람들이 그대를 거부하고 해악을 끼침에 인내하라. 실로 하나님께서 그대에게 주신 승리의 약속은 의심의 여지 없는 진리라. 그리하여 만약 하나님께서 그들에게 약속한 징벌의 일부 -예를 들어 바드르 전투-를 그대에게 보여주시거나, 아니면 그 이전에 정녕 그대의 영혼을 거두어가신대도, 실로 그들은 심판의 날 하나님 한 분께로 돌아갈 것이며, 그들의 악행에 의거하여 그들을 불지옥의 영원한 고통에 들게 하실 것이라.",
  40078: "진실로 하나님께서는 그대-사도여! - 이전의 공동체에 많은 사도를 보내셨노라. 그들은 사도들을 부인하며 그들에게 해를 끼쳤으나 사도들은 그들의 불신과 해악에 인내하였노라. 이 사도들 중에는 하나님께서 그대에게 그 소식을 알려주신 자가 있으며, 그들 중에는 그대에게 그 소식을 알려주시지 않은 자가 있노라. 그 어떤 사도도 지고하신 하나님의 허락 없이 사람들에게 주님의 징표를 가져올 수 없노라. 그렇기에 불신자들이 사도들에게 징표를 가져오라 요구하는 것은 부당한 일이었노라. 그리하여 하나님의 명령이 도래했을 때 그분께서는 사도들과 그들의 백성을 공정히 판결하셨으며, 불신자들을 파멸시키시고 사도들을 구하셨노라. 허위를 따르던 자들은 판결이 있었던 그곳에서 자기 자신을 잃어버렸으니, 불신으로써 자기 자신을 파멸로 이끈 결과라.",
  40079: "그대들을 위해 낙타와 소와 양 등의 가축을 창조하신 분이 하나님이시라. 그리하여 그대들은 가축의 일부 종류를 탈 것으로 부리고, 다른 가축의 일부는 먹을 고기로 사용하노라.",
  40080: "이러한 피조물에는 시대에 따라 변하는 다양한 유용함이 있노라. 그대들은 이를 통해 마음속에 바라는 것들을 성취해 나가니, 육지와 해양의 교통 수단이 그 예시라.",
  40081: "하나님께서 그대들에게 당신의 전능하심과 유일성을 알려주는 여러 징표들을 보여주시는데도, 그대들은 하나님의 징표들 중 무엇을 부정하려 드는가?",
  40082: "메시지를 부정하는 자들은 대지를 이동하면서, 그들 이전에 있었던 불신자 공동체들의 최후가 어떠했는지 숙고하고, 그로부터 교훈을 얻지 않는가? 이 공동체들은 저들보다 더 많은 인구를 보유하였고 재산과 힘, 지상에서의 흔적 이 더 강하였으나, 그들이 가지고 있었던 이러한 강력함은 정작 하나님이 벌이 닥쳤을 때 그들에게 어떠한 도움도 되지 못하였노라.",
  40083: "그렇게 그들을 위한 사도들이 분명한 증거를 가지고 그들에게 도래하였건만 그들은 이 증거를 부정하였노라. 그들은 자신들이 가지고 있던, 사도들이 가져온 메시지와 배치되는 지식에 집착하였고 결국, 그들이 조롱하고 사도들이 경고한 그 징벌이 그들을 에워싸고 말았노라.",
  40084: "그리하여 그들이 하나님의 엄벌을 보았을 때 -이 때는 어떤 새로운 믿음도 소용이 없을 때라- 믿음을 선언하며 말하노라. \"저희는 하나님 한 분만을 믿으며 저희가 숭배하던, 하나님 이외의 우상들을 불신합니다\"",
  40085: "그러나 그들의 믿음은, 그것이 하나님의 엄벌을 두 눈으로 목격할 때 형성된 것이라면, 그들에게 어떠한 도움도 되지 못하노라. 이것은 하나님의 섭리로서, 그분의 종복들 사이에서 이미 법칙으로 지정된 것이라. 엄벌이 닥쳐 온 그 때 불신자들은 자기 자신을 잃어버릴 것이니 이러한 손실은 그들이 하나님을 불신했기 때문이며, 징벌을 목격하기 전까지도 참회하지 않음으로써 자기 자신을 파멸로 이끌고 간 결과라.",
  41000: "풋씰라트 (상세히 설명된)\n계시 분류: 메카\n•    계시 목적    \n이 장은 꾸란에 등을 돌리는 자들을 유연하게 대처해야 함을 가르치고 있으며, 꾸란은 진리이며 꾸란을 거부하는 자들의 말로가 어떠한지를 알려주고 있다.\n•    요약 주해",
  41001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  41002: "이 꾸란은 가장 자비로우시고 가장 자애로우신 하나님으로부터 내려진 계시라.",
  41003: "이 계시서는 그 징표가 분명하고 상세히 설명된 성서이자 아랍어로 내려진 꾸란이라. 꾸란은 지식을 가진 사람들을 위한 것으로, 그들이야말로 그 의미를 통해 효용을 얻고 진리로 인도되는 길을 받아들이기 때문이라.",
  41004: "이 꾸란은 기쁜 소식을 전하고 있으니, 하나님께서 믿는 자들을 위해 준비하신 풍성한 보상을 알리고 있노라. 또한 꾸란은 경고의 메시지를 보내니, 불신자들에게 하나님의 고통스런 징벌이 있음을 알리노라. 그러나 그들 대부분은 돌아서며 꾸란을 받아들일 의향 없이 듣는 척만 할 뿐이라.",
  41005: "그들이 말하였노라. “우리의 마음은 여러 겹의 덮개로 싸여 있어 그대가 초대하는 내용을 이해하지 못하고, 우리의 귓속에는 마개가 있어 귀먹었으며, 우리와 그대 사이에는 가리개가 있어 무슨 말을 해도 전달되지 않소. 그러니 그대는 그대의 방식대로 행하시오. 우리도 우리의 방식대로 행할 것이며, 우리가 그대를 따르는 일은 없을 것이오”",
  41006: "그대-사도여! -는 거부하는 저들에게 말하라. “나는 그저 그대들와 같은 인간일 뿐이며, 나에게 계시가 내려졌으니 진정코 그대들이 경배해야 할 존재는 오직 한 분의 신이신 하나님 한 분 뿐이라. 그러니 그대들은 하나님께로 향하는 올바른 길로 들어서고 그대들의 죄에 관해 하나님께 용서를 구하라” 우상 숭배자들은 하나님께 대등한 존재를 두면서 그것들을 마치 하나님처럼 숭배하니, 그들에게 파멸과 징벌이 있노라.",
  41007: "그들은 자신의 재산에 부과되는 자카 (의무 희사금) 를 내지 않으며, 영원한 기쁨과 고통의 징벌이 있는 내세에 관하여는 불신하는 자들이라.",
  41008: "실로 하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들은 천국이라는 끊이지 않는 보상을 받을 것이라.",
  41009: "그대-사도여! -는 우상 숭배자들에게 반문하라. \"어찌하여 그대들은 일요일과 월요일 이틀 만에 지구를 창조하신 하나님을 불신하고, 그분께 대등한 존재를 두어 그것들을 숭배하는 것인가? 존재하는 모든 피조물의 주님이 바로 그분이시라\"",
  41010: "하나님께서는 지구의 표면 위에 견고한 산을 두시어 땅이 흔들리지 않도록 하셨고, 지구에 축복을 내리시어 지구의 거주자들이 언제나 좋은 것을 얻도록 하셨노라. 또한 하나님께서는 지구의 먹거리와 가축을 창조하셨으니, 이 모두는 앞서 있었던 이틀 후의 화요일과 수요일에 이루어진 것으로 도합 나흘이며, 이는 창조에 관해 질문하는 자들을 위한 답이라.",
  41011: "그런 후 하나님께서는 가스 상태인 하늘로 오르신 후에, 하늘에게 그리고 지구에게 말씀하셨노라. “너희는 자발적으로 혹은 강제적으로 나의 명령을 따르라. 나의 명령을 따라야 함에는 선택의 여지가 없노라” 하늘과 지구가 말하였노라. “저희는 자발적으로 복종합니다. 저희는 당신께서 원하시는 대로 원할 뿐입니다\"",
  41012: "그 후 하나님께서는 목요일과 금요일 이틀 만에 일곱 하늘을 창조하셨으니, 그렇게 그분께서는 엿새 동안에 일곱 하늘과 지구의 창조를 완성하셨도다. 그리고 하나님께서는 각각의 일곱 하늘에 필요한 일을 지정하시고 순종의 명령을 계시하셨노라. 또한 하나님께서는 가장 가까운 현세의 하늘을 별들로 아름답게 하시고, 그 별들로써 사탄이 (하늘의) 정보를 듣지 못하도록 조치하셨노라. 이 모든 것은, 누구도 감히 제압하지 못하는 가장 존엄하신 분이자 피조물의 모든 것을 알고 계신 하나님의 섭리라.",
  41013: "그럼에도 만일 그들이 그대-사도여! -가 가져온 메시지에 등을 돌린다면, 말하라. \"나는 이미 그대들에게 징벌을 경고하였노라. 그 징벌은 후드의 백성인 아드 부족과 쌀리흐의 백성인 싸무드 부족에게 닥친 징벌과 유사한 것으로, 그들이 메시지를 부정한 결과라\"",
  41014: "사도들이 그들 (아드와 싸무드 부족) 에게 전방위로 찾아와 \"오직 하나님 한 분만을 경배하라\"고 명하였으나 그들 중에 있던 불신자들은 이렇게 대꾸하였노라. “만약 우리의 주님이 의지하셨다면 그분께서는 정녕코 천사들을 사도로 내려 보내셨을 것이오. 그러나 그대들은 우리와 같은 인간에 불과하니, 실로 우리는 그대들이 받은 것을 불신하오\"",
  41015: "후드의 백성이었던 아드 부족은 하나님을 불신하고 지상에서 가당찮게 거만해 하며 주위 사람들을 부당히 대하였노라. 그들은 자신들이 가진 힘을 뻐기면서 말하였노라. \"우리보다 더 힘이 센 자가 누구인가? \" 이에 하나님께서 답하셨노라: “그들은 자신들이 가진 힘을 이유로 경계를 벗어나고 있으나, 그들에게 힘을 주신 분은 다름아닌 하나님이시라. 그들은 실로 자신들을 창조하신 하나님께서 그들보다 더 강력하심을 알지 못하는 것인가?! 그들은 후드 (그에게 평화가 깃들기를) 가 가져온 하나님의 징표를 줄곧 부인하였노라”",
  41016: "이에 하나님께서는 그들 위로 굉음을 내는 바람을 보내셨으니, 이 날은 징벌이 찾아 온 불길한 날들이라. 이렇게 하나님께서는 그들이 현세에서 치욕의 징벌을 맛보도록 하셨고, 그들을 기다리고 있는 내세의 징벌은 그보다 더욱 치욕적이라. 그날 그들은 자신들을 징벌로부터 구해 줄 어떤 이도 발견하지 못할 것이라.",
  41017: "한편 싸무드 부족은 하나님께서 그들에게 진리의 길을 상세히 설명해 주셨으나, 그들은 올바른 길은 내버려두고 맹목적 방황을 선호하였노라. 그리하여 치욕스런 벼락의 고통이 그들을 덮쳤으니, 그들이 저질러 오던 불신과 거역 행위 때문이라.",
  41018: "그러나 하나님께서는 믿는 자들을 불신자들에게 내려진 벌로부터 보호해 주셨으니, 그들은 하나님과 그분의 사도들을 믿으며, 하나님의 명령을 지키고 그분께서 금하신 것을 멀리 함으로써 하나님을 경외하던 자들이었노라.",
  41019: "그날 하나님의 적들은 불지옥으로 소집될 것이라. 지옥의 천사들이 그들의 처음과 마지막을 줄 세우니, 그 누구도 불지옥으로부터 도망치지 못하노라.",
  41020: "그리하여 그들은 불지옥으로 이끌려 가고, 거기서 그들은 현세에서 자신들이 저질렀던 악행을 부정할 것이라. 그러나 그들의 청각과 시각과 피부가 그들이 현세에서 범한 불신과 거역 행위를 증언할 것이라.",
  41021: "불신자들이 자신의 피부에게 말하노라. \"너희는 왜 현세에서 저지른 우리의 행위를 증언하여 우리를 불리하게 하는 것인가? \" 피부가 신체의 주인에게 말할 것이라. \"모든 것을 말하게 하시는 하나님께서 우리에게 말하도록 하신 것이라. 실로 하나님께서는 그대들이 현세에 있었을 때부터 이미 그대들을 창조하셨노라. 그리고 그대들은 하나님 한 분께로 돌아가 내세에서 보응을 받게 될 것이라\"",
  41022: "너희는 너희의 시각과 청각과 피부가 너희에게 불리한 증언을 할까 두려워 너희가 저지르는 거역 행위를 숨기려 한 적이 없노라. 이는 너희가 죽음 이후에 있을 심판과 보응을 믿지 않았기 때문이라. 오히려 너희는 하나님께서 너희의 행위 중 많은 것을 알지 못할 것이라 생각하면서, 그분께 행위를 숨길 수 있을 것이라 추측하였노라. 그렇게 그대들은 기만된 자들었노라.",
  41023: "이는 너희 주님에 대한 너희의 사악한 생각으로서, 그것이 너희를 몰락케 하였으니 이로 인해 너희는 현세와 내세에서 손실자들이 되었노라.",
  41024: "그러하니, 자신의 청각과 시각과 피부에게 불리한 증언을 당한 저들이 인내한다 하더라도, 불지옥이 그들의 거처임은 변함이 없노라. 만약 그들이 용서를 빈대도 실로 그들은 용서받지 못할 것이라.",
  41025: "하나님께서는 저 불신자들에게 사탄을 동료로 붙여 주셨으니, 사탄들은 그들이 저지른 현세의 악행을 훌륭한 것으로 치장하노라. 또한 사탄들은 그들이 죽음 후에 맞이할 내세와 그에 대비한 선행의 실천을 잊도록 하노라. 저들 이전에 있었던 진과 인간의 공동체에게 징벌의 말씀이 의무화 되었던 것처럼 저들에게도 징벌은 반드시 찾아오고야 말 것이라. 실로 그들 모두는 손실자들이니, 그들은 심판의 날 불지옥에 들어가게 되어 자신과 자신의 가족을 잃어버릴 자들이라.",
  41026: "불신자들은 이슬람의 논리에 제대로 대응하지 못하자 서로가 서로에게 조언하며 말하였노라. \"그대들은 무함마드가 그대들에게 낭송하는 꾸란을 듣지 말고, 그 안에서 언급되는 명령도 따르지 말라. 무함마드가 꾸란을 낭송할 때는 시끄럽게 소리를 높이라. 그렇게 하면 그대들은 그에 대항하여 승리를 거둘 것이고 그는 낭송을 그만둘 것이며 꾸란을 믿으라 말하지도 않을 것이라. 그러면 그대들은 편히 쉴 수 있을 것이라\"",
  41027: "이에 하나님께서는 심판의 날, 하나님과 당신의 사도를 불신하던 자들에게 혹독한 벌을 맛 보게 할 것이며, 우상 숭배와 거역 행위 등 그들이 저지르던 가장 사악한 악행을 징벌하실 것이라.",
  41028: "이러한 징벌은 하나님을 불신하고 그분의 사도들을 부정한 하나님의 적들이 받을 벌로서, 그들의 징벌은 불지옥이라. 그들은 그곳에서 영원히 거주할 것이니, 그러함은 그들이 하나님의 명백한 징표들을 믿지 않으며 부인했기 때문이라.",
  41029: "하나님을 불신하고 그분의 사도들을 부정한 자들이 말할 것이라. \"저희의 주님! 저희를 방황케 한 진 (Jinn) 과 인간이 있으니 저희에게 그들을 보여 주십시오. 이블리스는 최초로 불신을 자행한 후 그것을 부추겼으며, 아담의 아들은 최초로 살인을 자행하였습니다. 그들을 저희에게 보여주시면 저희는 불지옥에서 그들을 저희의 발 아래에 두겠습니다. 그렇게 하여 그들이 불지옥에서 가장 혹독한 벌을 받는 더없이 비천한 자들이 되도록 하겠습니다\"",
  41030: "(이전에 하나님께서 당신의 적들이 받을 징벌에 대해 말씀하셨다면, 여기서부터는 진실한 신앙인들이 받을 보상에 대해 말씀하신다. )  실로 \"우리의 주님은 하나님 한 분 뿐입니다\"라고 말하고, 하나님께서 명하신 것을 꾸준히 지키고 그분께서 금하신 것을 멀리한 자들은 임종의 순간 그들에게 천사들이 내려와 말할 것이라. \"그대들은 죽음을 무서워 말고 그 후에 있을 일도 두려워 말라. 그대들이 남긴 현세의 일에 대해서도 슬퍼할 필요가 없노라. 그대들은 현세에서 믿음을 가졌고 선행을 실천하였기에 천국을 약속받았고, 이제 그대들은 그 천국의 소식으로 기뻐하라”",
  41031: "“우리는 현세에서 그대들의 조력자로 (하나님의 허락으로) 그대들을 올바른 길로 인도하고 보호해 주었고, 우리는 내세에서도 그대들의 동료라. 그대들은 천국에서 그대들의 영혼이 갈망하는 즐거움과 쾌락을 가질 것이며, 그대들은 천국에서 그대들이 요청하는 모든 것을 가질 것이니”",
  41032: "\"이는 주님께서 그대들을 위해 준비해 주시는 훌륭한 양식으로 마치 손님이 받는 후한 대접과 같은 것이라. 실로 주님께서는 참회하는 종복들을 너그러이 용서하시는 분이며 그들에게 자애로우신 분이라.\"",
  41033: "사람들을 하나님에 대한 믿음으로 초대하고 그분께서 알려 주신 선행을 권장하며, 주님을 기쁘게 하는 선행을 몸소 실천하면서 “실로 나는 하나님께 순종하는 자들 중의 하나입니다”라고 말하는 자보다 더 훌륭한 말을 하는 자는 없노라.",
  41034: "하나님의 기쁨을 사는 선행과 순종은 그분의 분노를 초래하는 악행이나 거역 행위와 결코 같지 않노라. 그대에게 악행을 저지르는 자에게 더 훌륭한 행위로 응대하라. 그렇게 악을 선으로 응할 때, 보라, 그대에게 적의를 드러내던 자가 이제는 그대의 절친한 친구가 될 것이라.",
  41035: "이러한 고귀한 성품을 가지는 자는 사람들의 악행과 그들이 야기하는 고충에 인내하는 자들이며 축복받은 운명을 지정받은 자들이니, 이러한 품성에는 많은 훌륭함과 유용함이 있노라.",
  41036: "만일 사탄이 그대에게 악을 속삭인다면, 그대는 하나님께 보호를 요청하고 그분께 피난처를 구하라. 진실로 하나님께서는 그대의 말을 들으시고 그대의 상태를 알고 계신 분이라.",
  41037: "하나님의 위대함과 유일성을 드러내는 그분의 징표들 중의 하나는 교체를 반복하는 밤과 낮, 그리고 해와 달이라. 그대들-사람들이여! -이 하나님을 진정으로 경배한다면 태양을 위해 엎드려 절하지 말고, 달에게도 절하지 말며, 오직 그것들을 창조하신 하나님을 위해서만 엎드려 절하라.",
  41038: "그럼에도 만일 그들이 거만해하고 돌아서며 창조주를 위해 엎드려 절하지 않는다면, 실로 하나님께 가까운 곳에 있는 천사들은 밤낮으로 하나님의 완벽함을 찬양하고 그분을 경배함에 전혀 지치지 않노라.",
  41039: "하나님의 위대함과 유일성을 드러내고 그분께서 사람들을 부활시키실 능력을 보여주는 징표가 있노라: 그대는 식물이 자라지 못하는 거친 땅을 목격하지만, 하나님께서 그곳에 비를 내리실 때면 그 안에 숨겨져 있던 씨앗들이 자라 그 땅이 움직이고 솟아오르노라. 이처럼 죽어있던 땅에 식물이 자랄 수 있는 생명을 불어넣으신 하나님께서는 죽은 자들을 되살리시고 부활시키신 후 그들을 심판하시고 보응하실 것이라. 실로 하나님께서는 모든 것이 가능한 분이시기에 죽어 있던 땅을 되살리실 수 있으며, 무덤에 있던 사람들도 부활시키실 수 있노라.",
  41040: "실로 하나님의 징표들을 비난하고 부정하거나 왜곡함으로써 진리로부터 벗어나는 자들이 있으니, 하나님께서는 그들의 일을 모르시는 분이 아니며 오히려 그들의 상태를 잘 알고 계시노라. 그렇다면, 불지옥에 내던져지는 자가 더 훌륭한가, 아니면 심판의 날 징벌로부터 안전한 자가 더 훌륭한가? 그대들-사람들이여! -은 선행이든 악행이든 원하는 대로 해보라. 하나님께서는 이미 선과 악이 무엇인지 설명하셨노라. 실로 하나님께서는 그대들이 무엇을 하든 그대들의 행위를 보고 계시는 분으로, 그분께는 그대들의 행위 중 그 무엇도 감추어지지 않노라.",
  41041: "실로 하나님으로부터 내려진 꾸란이 자신들에게 도래했음에도 그것을 불신하는 자들은 심판의 날 그들에게 징벌이 내려질 것이라. 실로 꾸란은 존엄한 성서로서, 그 어떤 왜곡이나 수정도 꾸란에 범접할 수 없노라.",
  41042: "추가나 삭제, 변경이나 왜곡 등 그 어떤 방면에서의 거짓 시도도 꾸란에게는 통하지 않노라. 꾸란은 창조와 계획과 법의 제정에 있어 가장 지혜로우신 분, 언제 어디서나 찬미 받으시는 분으로부터 내려진 계시라.",
  41043: "(하나님께서는 메시지를 부정하는 자들의 모습을 묘사하신 후, 이전의 사도들이 이미 겪었던 고충들을 언급하심으로써 당신의 사도에게 인내심을 부여하시고 그에게 위안을 주고 계신다. )  사람들이 그대-사도여! -를 거짓말쟁이라 말하지만, 이는 그들이 그대 이전의 사도들에게 내뱉은 말들과 다를 바 없노라. 그러니 그대는 인내하라. 진실로 그대의 주님께서는 참회하는 종복을 용서하시는 분이며, 죄를 지속하면서 참회하지 않는 자에게는 고통스런 벌을 내리시는 분이라.",
  41044: "만약 하나님께서 이 꾸란을 아랍어가 아닌 다른 언어로 계시했더라면 실로 그들 중에서 불신하는 자들은 \"꾸란에 담긴 징표라는 것이 좀 더 자세히 설명되었더라면 우리가 그것을 이해했을 것이오. 어떻게 꾸란이 비아랍어로 계시되는데, 그것을 전하는 이는 아랍인인 것인가? \" 라고 말했을 것이라. 그대-사도여! -는 저들에게 말하라. \"꾸란은 하나님과 그분의 사도들을 믿는 자들을 위한 것이라. 그리고 꾸란은 그들이 방황하지 않도록 올바른 길로 인도해 주며, 무지 및 그와 유사한 것들에서 비롯된 마음의 병을 치유해 주노라. 그러나 믿지 않는 자들의 귓속에는 마개가 있으며, 그들의 눈은 멀어 꾸란을 제대로 이해하지 못하노라. 저들의 상태는 마치 누군가가 저 머나먼 곳에서 그들을 부르는 것과 같으니, 그들이 부르는 자의 목소리를 어떻게 들을 수 있단 말인가? ”",
  41045: "진실로 하나님께서는 모세에게 타우라 (토라) 를 주셨노라. 그러나 사람들 중에는 타우라를 믿는 자들이 있었고 다른 이들은 타우라를 불신하였으니, 그렇게 그들은 타우라에 관해 의견을 달리하였노라. 하나님께서 이미 약속하신 바, 그분께서는 심판의 날 인간들이 의견을 달리하는 것들을 판결하실 것이라. 이 약속만 아니었더라면 하나님께서는 타우라에 관한 그들의 이견을 판결하신 후, 진실된 자에게 명예를 부여하시고 거짓된 자에게 불명예를 주시어 그들을 구분하셨을 것이라. 실로 불신자들은 꾸란에 대한 의혹의 눈길을 거두지 않고 있노라.",
  41046: "선행을 실천하는 자는 그 효용이 자기 자신에게로 돌아가는 것이며, 하나님께서는 누군가의 선행으로 득을 얻으시는 것이 아니라. 또한 악행을 저지르는 자는 그 해악이 자기 자신에게로 돌아갈 뿐, 하나님께서는 누군가의 악행으로 해를 입지 않으시노라. 하나님께서는 선행이든 악행이든 그 모든 것을 정당히 보응하실 것이라. 그대-사도여! -의 주님께서는 결코 당신의 종복들을 부당히 대우하지 않으시기에, 받아야 할 보상보다 적게 주시거나 치르지 않아도 될 벌을 부가하시는 법이 없노라.",
  41047: "종말의 시간에 관한 지식은 하나님 한 분께로만 귀착하니, 그 때가 언제인지는 오직 하나님만이 아시노라. 열매가 자신을 보호해주던 포엽으로부터 나올 때도, 여성이 아이를 배거나 낳을 때도, 그 어떤 것도 하나님의 지식을 거치지 않는 것이 없노라. 심판의 날 하나님께서는 당신께 대등한 존재를 두어 그것을 숭배하던 자들을 부르실 것이니, 그들을 힐책하며 말씀하실 것이라. \"너희들이 주장하던 나와 대등한 존재라던 것들은 지금 어디에 있는가? \" 우상 숭배자들이 말할 것이라. \"저희는 당신 앞에 고백합니다. 저희 중 그 누구도 감히 당신께 대등한 존재가 있다고 증언하지 않습니다\"",
  41048: "그들이 이전에 기도하던 우상들은 그들을 버려 둔 채 사라져 버리고, 그들은 이제 하나님의 징벌로부터 자신들을 보호해줄 어떤 은신처도 없음을 확신하노라.",
  41049: "인간은 건강이나 재물, 자식 등의 은총을 요청할 때 지치는 법이 없노라. 그러나 그에게 나쁜 것이 스치기라도 한다면, 그는 하나님의 자비를 포기하며 쉽사리 체념해 버리더라.",
  41050: "그에게 시련과 병환이 닥쳤고 그 후 하나님께서 그에게 건강과 재산과 평안함을 선사하실 때면 그는 이렇게 말하노라. \"이것은 나의 당연한 몫으로, 내가 자격이 되었기에 이것을 가지는 것이오. 내가 생각컨대 종말의 시간 따위는 시작되지 않을 것이오. 행여나 종말의 시간이 도래하더라도 하나님께서는 나에게 부와 재산을 주실 것이오. 마치 내가 현세에서 자격을 갖추어 부와 재산을 가졌던 것처럼 말이오\" 그러나 하나님께서는 정녕코 불신자들에게 그들의 불신과 거역 행위를 알려주실 것이며, 하나님께서는 정녕코 그들에게 혹독한 징벌을 맛 보게 하실 것이라.",
  41051: "하나님께서 인간에게 건강과 평안함 등의 은총을 베푸실 때면 그는, 하나님을 떠올리고 그분께 순종해야 함을 잊고 거만해하며 돌아서노라. 그러나 그에게 병환이나 가난 등 나쁜 것이 스치기라도 할 때면 그는 열심히 다방면으로 하나님께 기도를 올리노라. 그는 하나님께 호소하며 자신이 겪는 해악을 걷어내 달라 하니, 은총이 있을 때는 주님께 감사하지 않았으면서 시험이 있을 때는 저렇게 인내하지를 못하노라.",
  41052: "그대-사도여! -는 부정하는 저 우상 숭배자들에게 말하라. \"그대들은 생각해보라. 꾸란이 만약 하나님으로부터 계시된 것임에도 그대들이 꾸란을 불신하고 부정한다면, 그대들의 상태는 과연 어떨게 될 것인가? 명백하고 강력한 논거의 진리를 앞에 두고서도 그 진리를 고집스레 거부하는 자, 그보다 더 방황하는 자는 누구인가? \"",
  41053: "하나님께서는 장차 무슬림들을 위해 열어 주실 땅들로써 꾸라이쉬 부족에게 당신의 징표들을 보여주실 것이며, 그분께서는 메카 무혈 입성으로써 그들 자신 속에 있는 징표를 보여 주실 것이라. 이는 그들이 꾸란이 진리임을 확실히 알고 그들이 가지고 있는 꾸란에 관한 의심이 사라지도록 하기 위함이라. 하나님께서 꾸란이 당신에게서 비롯한 진리임을 증언하시니, 저 우상 숭배자들은 이것으로도 충분하지 않단 말인가? 하나님의 증언보다 더 위대한 증언이 있는가? 그들이 정녕 진리를 원하였더라면 그들의 주님이신 하나님의 증언만으로 충분했을 것이라.",
  41054: "보라. 실로 우상 숭배자들은 심판의 날 자신의 주님을 만나게 될 것임에 의문을 품고 있노라. 그들은 부활을 부정하며 내세를 믿지 않기에, 선행으로써 다가올 내세를 준비하지도 않는 것이라. 진실로 하나님께서는 지식과 능력으로 모든 것을 아우르시는 분이라.",
  42000: "앗-슈라 (자문)\n계시 분류: 메카\n•    계시 목적    \n이 장은 무함마드가 받은 계시와 메시지의 실체에 대해 이야기하고 있다. 그가 받은 계시는 이전의 선지자들이 받은 계시의 연장선상에 있다.\n•    요약 주해",
  42001: "(하.밈.아인.신.까프.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  42002: "(하.밈.아인.신.까프.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  42003: "이와 같은 계시는 그대에게 그리고 그대 이전의 자들에게 내려진 계시로서, 적들을 응징하심에 가장 존엄하시며, 결정하시고 창조하심에 가장 지혜로우신 하나님께서 내리신 계시라.",
  42004: "(일곱) 하늘에 있는 것과 땅에 있는 것의 창조와 소유와 관리는 오직 하나님 한 분의 것이라. 하나님께서는 그 존재와 능력에 있어 가장 지고하신 분이시며, 가장 위엄하신 속성을 지니신 분이라.",
  42005: "땅 위에 있는 엄청난 크기의 드높은 (일곱) 하늘도 하나님에 대한 두려움으로 파열하려 하노라. 천사들은 자신들의 주님이신 하나님께 복종하며 그분의 완벽함을 찬미하노라. 또한 그들은 하나님께 지상에 있는 자들을 용서해 달라고 기도하노라. 진실로 하나님께서는 참회하는 자들의 죄를 너그러이 용서하시고 그들에게 가장 자애로우신 분이시라.",
  42006: "그들은 하나님이 아닌 우상들을 가호자로 삼고 숭배하나, 하나님께서는 그들을 지켜보고 계시노라. 하나님께서는 그들의 행위를 기록하고 계시며 그들의 행위에 따라 그들을 보응하실 것이라. 그러니 그대-사도여! -는 그들의 행위를 감시할 의무가 없으며 그들의 행위를 책임지지도 않으니, 그대는 그저 메시지를 전달하는 자일 뿐이라.",
  42007: "하나님께서 그대-사도여! - 이전의 선지자들에게 계시를 내리셨던 것처럼, 그분께서는 그대에게 아랍어로 된 꾸란을 계시하였노라. 이는 그대가 메카와 그 주위의 아랍 도시에게 경고하고, 더 나아가 모든 인류에게 경고하기 위함이라. 하나님께서는 심판의 날 최초와 최후의 모든 인간들을 한 곳에 모으신 후 그들에게 보상과 징벌을 내리실 것이라. 이 날이 도래함에는 의심의 여지가 없으니, 이 계시가 내려진 것도 그대가 사람들에게 이 날을 경고하기 위함이라. 이 날, 인간은 두 부류로 나누어질 것이니, 신앙인의 무리는 천국에 있을 것이며 불신자의 무리는 화염으로 가득한 지옥에 있을 것이라.",
  42008: "만약 하나님께서 의지하셨다면 그들의 종교를 이슬람으로 통일하시어 그들을 하나의 공동체로 두시고 그들 모두를 천국에 들게 하셨을 것이라. 그러나 하나님의 지혜가 있었기에 당신께서는 원하시는 자들만을 천국에 거주토록 하시노라. 불신과 거역 행위로 자신의 영혼을 부당히 대우한 자들은 (심판의 날) 그들을 보호해 줄 어떠한 가호자도, 하나님의 징벌로부터 그들을 구해 줄 어떠한 조력자도 없을 것이라.",
  42009: "그러나 우상 숭배자들은 하나님 이외의 것을 가호자로 두고 그것들에게 보호를 요청하더라. 그러나 실로 하나님만이 진정한 가호자이시며, 그분 이외의 것들은 어떤 효용이나 해악도 끼치지 못하노라. 실로 하나님께서는 인간의 심판과 보응을 위해 죽은 자들을 부활시키시는 분이시며, 그 어떤 것도 그분을 제지할 수 없노라.",
  42010: "그대들-사람들이여! -이 그 어떤 종교적 사안에 의견을 달리하더라도, 그것이 원칙이나 실천 그 어떤 것에 관한 것일지라도, 그에 대한 판결은 하나님께 있노라. 그리고 (현세에서의) 그 판결은 하나님의 성서 (꾸란) 와 그분의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 가 남긴 전통 (순나) 를 통해 결정되노라. 그러한 분이 바로 나의 주님이신 하나님이시라. 나는 나의 모든 일을 오직 그분께만 의탁하였으며, 오직 그분께만 용서를 구하며 참회하노라. ​",
  42011: "하나님께서는 전례 없는 방식으로 (일곱) 하늘과 땅을 창조하셨노라. 하나님께서는 그대들을 위해 그대들과 동일한 종 (種) 의 남녀를 두셨고, 낙타와 소와 양 등의 가축을 창조하심에 암컷과 수컷을 두시어 그것들이 그대들을 위해 번식하도록 하셨노라. 이렇게 하나님께서는, 그대들이 서로 결혼하도록 하여 그대들을 창조하시는 것이며, 가축을 통하여 그대들의 생활에 필요한 동물의 고기와 젖을 주시는 것이라. 그 어떤 피조물도 하나님과 유사한 것은 없노라. 하나님께서는 종복들의 말을 들으시며 그들의 행위를 지켜보고 계시니, 그 무엇도 놓치시는 법이 없노라. 그리고 하나님께서는 그들의 언행에 기초하여 그들을 보응하실 것이라: 그 언행이 훌륭하였다면 결과는 훌륭할 것이며, 그 언행이 나빴다면 결과도 나쁠 것이라.",
  42012: "(일곱) 하늘과 땅에 있는 부 (富) 의 곳간 열쇠를 소유하고 계신 분이 하나님이시며, 그분께서는 원하시는 자에게 양식을 증가시키고 감소시키시노라. ​하나님께서 양식을 늘리시는 것은 시험으로, 인간이 감사하는지 아니면 부정하는지를 보시노라. 반면 하나님께서 양식을 줄이시는 것은 시련으로, 인간이 하나님의 운명에 인내하는지 아니면 역정을 내는지를 보시는 것이라. 실로 하나님께서는 모든 것을 알고 계신 분으로, 종복들에게 효용이 되는 것이 무엇인지를 가장 잘 알고 계시노라.",
  42013: "하나님께서 그대들을 위해 제정한 종교에는 노아에게 명령하시고 하나님께서 그대-사도여! -에게 계시하시고 아브라함과 모세와 예수에게 명령하신 것이 있으니 \"그대들은 종교에 있어 굳건하고 그 안에서 분열하지 말라\" 하셨노라. 그대가 우상 숭배자들에게 초대하는 유일신 사상과 하나님 이외의 것을 숭배하지 말라는 메시지는 그들에게 무척이나 어려운 일이라. 하나님께서는 당신의 종복들 중에서 원하시는 자를 선택하시어 그가 하나님을 경배하고 순종하는 일에 성공을 주시노라. 또한 하나님께서는 죄를 저지른 종복들 중에서 참회하며 하나님께로 돌아가는 자를 인도해 주시노라.",
  42014: "불신자들과 우상 숭배자들이 분열함은 오직 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 도래하여 그들에게 불리한 증거를 확립한 이후라. ​그들이 분열한 이유는 다름 아닌 적개심과 부당함 때문이라. 그들에 대한 징벌이, 정해진 기간까지 -즉, 심판의 날까지- 연기될 것이라는 하나님의 운명이 아니었더라면 하나님께서는 정녕 그들 사이를 판결하셨을 것이며, 그들이 그분을 불신하고 그분의 사도들을 부정한 것에 관하여 그들을 벌하셨을 것이라. 우상 숭배자들 이후에, 그리고 자신들의 선임자들 이후에 타우라 (토라) 를 물려받은 유대인들과 인질 (복음) 을 물려받은 기독교인들은 무함마드가 가져온 이 꾸란에 관하여 의심하며 그것을 부정하노라.",
  42015: "그러니 그대는 사람들을 올바른 종교로 초대하고, 명령받은 대로 이슬람을 굳건히 지키며, 그들의 거짓된 욕망을 따르지 말라. 그대는 그들과 논쟁할 때 말하라. \"나는 하나님을 믿고, 하나님께서 당신의 사도들에게 계시하신 성서를 믿노라. 그리고 하나님께서는 나에게 그대들 사이를 공정히 판결할 것을 명령하셨노라. 내가 경배하는 하나님은 우리의 주님이시자 그대들의 주님이시라. 우리에게는 선행이든 악행이든 우리의 행위가 있고, 그대들에게도 선행이든 악행이든 그대들의 행위가 있노라. 우리들 사이와 그대들 사이에 논거는 확립되었고 나아가야 할 길은 선명해졌으니 더 이상의 논쟁은 필요치 않노라. 하나님께서 심판의 날 우리 모두를 모으실 것이며, 우리는 그분께로 돌아갈 것이라. 하나님께서는 그날 우리에게 합당한 조치를 취하실 것이니, 그 때는 진실된 자와 거짓된 자, 진리를 따르는 자와 허위를 좇는 자가 선명히 구별될 것이라\".",
  42016: "하나님께서 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에 종교를 내리셨고, 사람들은 이 종교에 응답하였노라. 그럼에도 거짓된 논거로 이슬람에 관하여 논쟁을 벌이는 자들이 있으니, 그들의 주장은 하나님과 믿는 자들에게 있어 곧 사라져버릴 허약한 주장이라. 하나님께서는 불신하고 진리를 거부한 그들에게 당신의 노여움을 내리실 것이며, 그들은 심판의 날 혹독한 벌을 맞이할 것이라.",
  42017: "(하나님께서는 이전 구절들에서 불신자들의 논거가 거짓임을 밝히셨고, 이제 여기서부터는 무슬림들이 증거로 삼는 올바른 논거, 즉 꾸란에 관해 말씀하고 계신다)  의심의 여지 없는 진리로 가득한 꾸란을 내리시고 사람들 사이를 정확히 판결할 수 있도록 공정을 내리신 분이 하나님이시라. 저들은 심판의 날을 부정하지만, 그 날은 가깝도다. 다가오는 모든 것은 가까운 것이라.",
  42018: "종말의 날을 믿지 않는 자들은 그 날을 어서 가져와 보라며 재촉하니 그들은 심판도, 보상이나 징벌도 믿기 않기 때문이라. 반면 하나님을 믿는 자들은 종말의 날을 두려워하니, 그들은 자신들이 그 날에 어떠한 운명을 맞이할지 걱정하면서 그 날이 반드시 도래할 것임을 확신하고 있노라. 보라! 실로 종말의 날에 관해 논쟁을 벌이며 의심을 조장하는 자들은 진리로부터 저 멀리 떨어져 방황하고 있도다.",
  42019: "하나님께서는 당신의 종복들에게 자상하신 분이며, 당신의 지혜와 자상함에 따라 원하시는 자에게 양식을 늘리시거나 줄이시노라. 하나님께서는 그 누구에게도 제압되지 않으시는 분이며, 하나님께서는 당신의 적들을 응징하시는 분이라.",
  42020: "내세에서의 보상을 바라며 선행을 행하는 자가 있다면 하나님께서는 그의 보상을 증가시켜 줄 것이니, 최소 열 배부터 시작하여 많게는 칠 백 배 혹은 그 이상으로 보상을 더해 주시노라. 그러나 현세만을 바라는 자는 하나님께서 그에게 정해진 몫을 주실 것이나 내세에서 그는 그 어떤 몫도 갖지 못하니, 그는 내세를 버리고 현세를 선택했기 때문이라.",
  42021: "우상 숭배자들에게 하나님 이외의 신들이 있단 말인가? 그리하여 그 신들이 하나님께서 허용하지 않으신 우상 숭배를 법으로 제정하고, 하나님께서 금하신 것을 허락하며, 그분께서 금하신 것을 허락한단 말인가? 하나님께서 일정한 기한을 두시어 의견을 달리하는 자들의 판결을 그 기한까지 유예하지만 않으셨다면 정녕 그들에 관한 판결은 집행되고 말았을 것이라. 하나님께 대등한 존재를 두고 거역 행위를 저지름으로써 자신을 부당히 대우하는 자들은 실로 고통스런 벌에 직면할 것이라.",
  42022: "(심판의 날) 그대-사도여!-는 하나님께 대등한 존재를 두고 거역 행위를 저지름으로써 자신을 부당히 대우하는 자들을 볼 것이니, 그들은 자신들이 저지른 죄로 말미암아 받게 될 벌을 두려워하노라. 이 벌은 의심의 여지 없이 그들을 덮칠 것이지만, 뉘우침 없는 그들의 단순한 두려움은 그들에게 아무런 도움도 되지 않노라. 그러나 하나님과 그분의 사도를 믿고 선행을 실천하는 자들은 그들과는 정반대의 상태에 있을 것이니, 그들은 천국의 정원에 영원히 머물며 주님께 가까운 곳에서 원하는 것을 만끽하고 온갖 종류의 은총을 누릴 것이라. 정녕 이것이야말로 그 무엇과도 비교될 수 없는 커다란 은혜라.",
  42023: "하나님의 사도를 통해 전달되는 이 위대하고도 기쁜 소식은, 하나님과 그분의 사도를 믿고 선행을 실천하는 자들에게 전하는 하나님의 기쁜 소식이라. 그대-사도여! -는 말하라. \"나는 진리를 전한다는 이유로 그대들에게 어떠한 보상도 요구하지 않노라. 그대들에게 바라는 단 하나는 친척으로서의 온정으로, 그 효용은 그대들 자신에게로 돌아가노라\" 선행을 실천하는 자는 하나님께서 그 대가를 증가시키시니, 그는 최소 열 배의 보상을 받을 것이라. 실로 하나님께서는 당신의 종복들 중에서 참회하는 자를 너그러이 용서하시는 분이시며, 당신의 기쁨을 추구하며 선행을 실천하는 자에게 풍성히 보답하시는 분이라.",
  42024: "우상 숭배자들은 무함마드가 꾸란을 지어내었으며, 꾸란은 하나님의 계시가 아니라 무함마드의 말일 뿐이라고 생각하노라. 하나님께서는 그들에게 답하시노라. \"만약 그대 (무함마드) 가 거짓말을 지어냈다면 나는 그대의 마음을 닫아 버리고, 그 거짓말을 소멸시킨 후 진리만을 남겼을 것이라\" 그러나 실제로 그러한 일은 발생하지 않았고, 이는 선지자가 하나님으로부터 계시를 받았다는 증거가 되노라. 실로 하나님께서는 인간들의 가슴 속에 있는 것을 알고 계시는 분이니 그 어떤 것도 그분께는 감추어지지 않노라.",
  42025: "누군가가 불신이나 거역 행위를 저질렀다 하더라도 그가 진심으로 뉘우친다면 그 뉘우침을 흔쾌히 받아 주시는 분이 하나님이시며, 그분께서는 그들이 저지른 악행을 용서해 주시노라. 하나님께서는 그대들이 행하는 모든 일을 알고 계시니, 그대들의 행위 그 무엇도 그분께는 감추어지지 못하며 하나님께서는 그대들의 행위에 근거하여 그대들을 보응하실 것이라.",
  42026: "하나님께서는 당신을 믿고 당신의 사도를 따르며 선행을 실천하는 자들의 기도를 들어주시노라. 또한 하나님께서는 당신의 은혜로써 그들이 요청하지 않은 것들조차 선사해 주시노라. 그러나 하나님과 그분의 사도들을 불신하는 자들은 심판의 날에 있을 강력한 벌이 그들을 기다리고 있노라.",
  42027: "만약 하나님께서 당신의 종복들 모두에게 무제한의 양식을 베푸셨다면 실로 그들은 지상에서 경계를 넘어선 부당함을 저질렀을 것이라. 그러나 하나님께서는 당신께서 뜻하시는 일정량의 양식만을 내리시어 그들의 양식을 증가시키거나 감소시키시노라. 실로 하나님께서는 인간의 상태에 밝으신 분이시며 그들을 지켜보고 계시는 분으로서, 당신의 지혜에 따라 인간에게 양식을 주시기도 하며, 당신의 지혜에 따라 인간에게 양식을 제한하기도 하시노라.",
  42028: "사람들이 더이상 비가 내리지 않을 것이라 체념했을 때 그들에게 해갈의 비를 내려 주시고, 이 비를 대지에 퍼뜨리시어 식물이 자라나게 하시는 분이 바로 하나님이시라. 하나님께서는 당신의 종복들의 일을 관장하시는 분이시며, 언제나 찬미받으시는 가장 영광되신 분이라.",
  42029: "하나님의 무한한 능력과 그분의 한 분 되심을 나타내는 징표 중의 하나는 (일곱) 하늘과 땅의 창조와 그 안에 퍼뜨리신 놀라운 피조물들이라. 하나님께서는 원하실 때 (심판의 날에 있을) 소집과 보응을 위해 그들을 모으는 것이 가능한 분이시라: 창조든 소집이든 그 누구도 그분을 막을 자 없노라.",
  42030: "그대들-사람들이여! -의 신체나 재산에 닥친 시련은 그대들 자신이 저지른 죄악 때문이라. 그러나 하나님께서는 그대들이 저지른 죄악의 많은 부분에 관용을 베푸시어 그것으로 그대들을 당장 벌하지 않으시노라.",
  42031: "하나님께서 지상에서 그대들을 벌하고자 하실 때 그대들은 그분의 벌을 피해갈 수 없노라. 그대들의 일을 관장하시는 분은 오직 하나님 한 분이시며, 그분께서 그대들에게 벌을 내리실 때 그 벌을 막아줄 조력자는 아무도 없노라.",
  42032: "하나님의 무한한 능력과 그분의 한 분 되심을 나타내는 징표 중의 하나는 바다를 항해하는 선박으로, 그 크기와 높이가 거대한 산과도 같더라.",
  42033: "하나님께서 원하신다면 바람을 멈추게 하실 것이니 이에, 바람으로 움직이던 선박들은 바다 위에서 기약없이 정지해 버리고 말았을 것이라. 하나님의 의지로 선박이 창조되고 바람이 움직이는 이러한 현상은 하나님의 능력을 드러내는 명백한 징표로서, 시련에 굳게 인내하고 하나님의 은총에 늘 감사하는 자들을 위한 징표라.",
  42034: "하나님께서 원하셨다면 사람들이 저지른 죄에 대한 벌로서 폭풍을 보내시어 그들의 선박을 침몰시키실 수도 있노라. 그러나 하나님께서는 그들의 죄악에 관용을 베푸시기에 그들을 서둘러 벌하지 않으시노라.",
  42035: "하나님의 징표를 부정하기 위해 논쟁을 벌이는 자들은 폭풍으로 선박이 침몰하려 할 때 자신들에게 그 어떤 피난처도 없음을 알게 될 것이라.",
  42036: "그러하니, 재산과 명예와 자식 등 그대들-사람들이여! -이 받은 그 모든 것은 얼마 후에 사라질 현세 삶의 유희에 불과하노라. 그러나 영원한 즐거움이란 천국에서의 즐거움으로, 그것은 하나님과 그분의 사도들을 믿고 그들의 주님께 모든 일을 의탁하는 자들에게 하나님께서 선사해 주시는 훌륭한 즐거움이라.",
  42037: "그들은 대죄와 추행을 저지르지 않는 자들로, 누군가가 그들에게 말이나 행동으로 잘못을 범했을 때 그들은 그의 과오를 용서해 주고 그에게 보복하지 않노라.",
  42038: "그들은 의무 사항을 실천하고 금지 사항을 멀리함으로써 하나님의 명령에 응하고, 꾸준하고 훌륭히 예배를 드리노라. 그리고 그들의 중요 사안은 서로 간의 자문을 통해 결정되며, 그들은 하나님의 보상을 바라면서 그분께서 제공해 주신 양식으로 희사하노라.",
  42039: "누군가가 그들을 부당히 대할 때면 그들은 부당한 자들에 대항하여 승리를 거두노라. 이는 그들의 명예와 존엄을 보호하는 조치로서, 부당한 자를 용서해 주는 것이 아무런 효용이 없을 때라.",
  42040: "부당한 대우를 받은 자가 자신의 권리를 취한다면 그러해도 좋으나, 침해받은 권리 그 이상을 요구하지 말지어다. 누군가가 자신을 악하게 대한 자를 용서해 주고 그를 벌하지 않는다면 그에 대한 보상은 하나님께서 직접 해 주실 것이라. 실로 하나님께서는 사람들의 생명, 재산, 명예 등을 부당히 침해하는 자들을 사랑하지 않으시노라.",
  42041: "부당히 권리를 침해받은 자가 자신의 권리를 실현하였다면 그들의 권리 획득에는 어떠한 비난의 소지도 없노라.",
  42042: "힐책과 징벌은 오직 사람들을 부당히 대하고 지상에서 죄악을 퍼뜨리는 자들에게 있으니, 실로 이들은 내세에서 고통스런 벌에 직면할 것이라.",
  42043: "그러나 자신을 악하게 대한 자에 인내하고 관용을 베푼다면 그의 인내심은 자기 자신과 사회에 선을 가져다 줄 것이라. 이러한 일은 권장되지만, 오직 축복받은 자들만이 해낼 수 있는 위대한 일이라.",
  42044: "하나님께서 내버려두시어 인도받지 못하고 진리로부터 방황하는 자는 하나님 이외의 그 누구도 그를 지켜줄 수 없노라. 그대는 불신과 거역 행위로 자신을 부당히 다룬 자들을 볼 것이니, 심판의 날 징벌을 두 눈으로 목격하는 순간 그들은 애통해 하면서 말할 것이라. \"정녕 현세로 돌아가 참회할 방법은 없는 것입니까? \"",
  42045: "그대-사도여! -는 부당한 자들이 굴욕과 치욕의 상태로 지옥에 노출됨을 볼 것이라. 그들은 지옥에 대한 두려움으로 그곳을 제대로 응시하지 못하노라. 한편 하나님과 그분의 사도들을 믿는 자들은 말할 것이라. \"실로 진정한 손실자들이란 부활의 날 하나님의 징벌을 받아 자기 자신과 가족을 잃어 버릴 자들이라\" 불신과 거역 행위로 자신을 부당히 다룬 자들은 끊임없이 지속되는 벌을 받게 될 것이라.",
  42046: "심판의 날 그 어떤 이도 그들을 하나님의 징벌로부터 구해 줄 수 없노라. 그리고 하나님께서 진리로부터 멀어지게 내버려 두신 자는 결코 진리로 향하는 올바른 길로 들어서지 못하노라.",
  42047: "돌이킬 수 없는 부활의 날이 오기 전에 그대들-사람들이여! -은 하나님께서 명령하신 사항을 지키고 그분께서 금지한 사항을 멀리함으로써 지체 없이 그대들의 주님께 응답하라. 그날 그대들은 몸을 숨길 어떤 곳도 찾지 못할 것이며, 현세에서 저지른 죄를 부정할 어떤 힘도 없을 것이라.",
  42048: "그럼에도 그들이 그대가 명령한 것에 등을 돌린다면 하나님께서는 그대-사도여! -를 그들의 행위를 감시하기 위해 보내신 것이 아니라. 그대의 임무는 오직 하나님께서 명령한 메시지를 사람들에게 전하는 일이며, 그들에 대한 심판은 하나님께서 하실 것이라. 실로 하나님께서 인간에게 부와 건강 등 그분의 자비를 맛보게 하시면 그는 그것으로 희희낙락하더라. 그러나 그들의 죄로 말미암아 어려운 일이 닥쳐 그들이 시험받을 때면 실로 인간은 하나님의 은혜를 부정하고 그분의 은총에 감사하지 않으며 하나님께서 당신의 지혜로 지정하신 운명에 역정을 내더라.",
  42049: "(일곱) 하늘과 땅의 주권은 하나님께 있노라. 하나님께서는 원하시는 대로 남성과 여성을 창조하시니, 원하시는 자에게 여아만을 주시고 남아는 주지 않으시며, 원하시는 자에게 남아만을 주시고 여아는 주지 않으시노라.",
  42050: "혹은 그들에게 남아와 여아를 동시에 주기도 하시며, 원하시는 자를 아이를 갖지 못하는 불임으로 두시노라. 실로 하나님께서는 지금 무엇이 존재하고 앞으로 무엇이 존재할지도 다 알고 계시며, 이는 그분의 전지하신 능력과 무한한 지혜에 의함이라. 그분께는 그 무엇도 감추어지지 않으며, 그 누구도 감히 그분을 막을 수 없노라.",
  42051: "하나님께서 인간에게 말씀하실 때는 다음과 같은 방법으로 말씀하시노라: 직접적으로 계시를 내리시거나, 아니면 사도에게 말씀을 건네시나 사도는 그분을 보지 못하고 오직 듣기만 하거나, 아니면 가브리엘과 같은 천사를 보내시어 그 천사가 하나님의 허락으로 사도에게 하나님의 계시를 전달하노라. 실로 하나님께서는 당신의 존재와 속성이 가장 지고하신 분이시며 창조와 운명의 결정 및 법률의 제정에 있어 가장 지혜로우신 분이라.",
  42052: "하나님께서 그대-사도여! - 이전의 선지자들에게 계시(루흐, 영혼)를 내리신 것처럼 그분께서는 그대에게 친히 꾸란을 계시하셨노라. 그대는 계시를 받기 전에 사도에게 내려진 성서가 무엇인지, 신앙이 무엇인지 알지 못하였노라. 그러나 하나님께서는 꾸란을 광명으로 두셨고 그것으로써 당신의 종복들 중에서 원하시는 자를 인도하시노라. 진실로 그대는 사람들에게 올바른 길인 이슬람을 알려 주노라.",
  42053: "그 길은 (일곱) 하늘에 있는 것과 땅에 있는 것을 창조하시고 소유하시며 관리하시는 하나님의 길이라. 모든 일의 운명을 결정하시는 분은 오직 하나님 한 분이시도다.",
  43000: "앗-주크루프 (황금)\n계시 분류: 메카\n•    계시 목적    \n이 장은 꾸란이 제시하는 정확한 원칙들을 설명하면서 무지하고 조작된 관념들을 부정하고 있다.\n•    요약 주해",
  43001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  43002: "하나님께서는 진리로 인도하는 길을 분명히 설명해 주는 꾸란을 두고 맹세하시노라.",
  43003: "실로 하나님께서는 꾸란을 아랍어로 계시하셨노라. 이는 그대들-꾸란의 계시 언어를 쓰는 자들이여! -이 그 뜻을 이해한 후 그 내용을 다른 공동체에 전달하기 위함이라.",
  43004: "실로 이 꾸란은 보존 서책 (알-라우흐 알-마흐푸드) 안에 있으며, 이 꾸란은 지고한 명예를 지닌 지혜로 가득한 성서로서, 그 구절들은 완벽한 형태로 명령 사항과 금지 사항을 전하노라.",
  43005: "그러할진대, 그대들이 우상 숭배와 거역 행위를 반복한다는 이유로 하나님께서 꾸란의 계시를 중단하시고 그대들로부터 돌아서신단 말인가? 그대들에게 베푸시는 하나님의 자비가 있기에 그분께서는 그렇게 하지 않으실 것이라.",
  43006: "하나님께서는 이전 공동체에게 얼마나 많은 선지자를 보내셨던가?",
  43007: "이전 공동체에게 하나님께서 보내신 선지자가 찾아올 때마다 그들은 언제나 그를 비웃곤 하였노라.",
  43008: "그리하여 하나님께서는 저 이전 공동체보다 더 강한 괴력을 지닌 자들을 이미 멸망시키셨고, 따라서 그들보다 허약한 자들을 멸망시키는 일은 그분께 어려운 일도 아니라. 그리고 이전 공동체에 관하여는 이미 아드 부족, 싸무드 부족, 롯의 사람들, 미디안의 거주자들의 이야기가 꾸란에 언급되었노라.",
  43009: "만일 그대-사도여! -가 정녕 이슬람을 부정하는 저 우상숭배자들에게 \" (일곱) 하늘과 땅을 창조하신 분이 누구인가? ”라고 묻는다면 실로 그들은 “누구도 감히 제압할 수 없는 가장 존엄하신 분이자 모든 것을 알고 계신 하나님께서 그것을 창조하였소”라고 대답할 것이라.",
  43010: "하나님 그분께서는 그대들을 위해 대지를 요람으로 두시어 그대들이 그 위를 밟고 서 있을 수 있도록 하신 분이며, 그대들을 위해 산과 계곡에 길을 두시어 그대들이 방향을 잡을 수 있도록 하신 분이라.",
  43011: "그리고 하나님께서는 하늘에서 비를 내리시니 그대들과 가축과 작물이 필요한 양 만큼이며, 그분께서는 그 비로써 불모의 대지를 되살리시노라. 하나님께서 죽어 있던 땅에 식물이 자라나게 하시는 것처럼, 죽어있던 그대들은 (심판의 날을 위해) 부활하여 되살아날 것이라.",
  43012: "하나님께서는 쌍으로 이루어진 것들, 예를 들어 낮과 밤, 남성과 여성 모두를 창조하셨으며, 그분께서는 그대들을 위해 바다에서 탈 것이 되는 선박과 육지에서 탈 것이 되는 가축을 창조하셨노라.",
  43013: "하나님께서 이 모든 것을 창조하신 것은 장거리 이동시, 그대들이 탈 것 위에 올라 자리를 잡은 후 그대들 주님의 은총을 떠올리기 위함이라. 그대들은 말하니 “저희를 위해 이 탈 것을 유용케 해주시고 저희가 이것을 통제할 수 있게 해 주신 하나님께서는 완벽하신 분이십니다. 하나님께서 허락해 주지 않으셨다면 저희는 이것을 부릴 능력이 없었을 것입니다\"",
  43014: "\"그리고 진실로 저희는 죽음 이후에 저희의 주님, 그분 한 분께로만 돌아가 심판과 보응을 받게 될 것입니다\"",
  43015: "우상 숭배자들은, 어떤 피조물들은 하나님께서 낳은 것이라 주장하면서 \"천사들은 하나님의 딸들이라\"라고 말하더라. 이러한 말을 하는 인간은 실로 그 불신과 방황이 명백한 자들이라.",
  43016: "그대들-우상 숭배자들이여! -은 \"하나님께서는 당신 자신을 위해 피조물 중의 일부를 딸로 삼으시고, 우리들을 위해서는 아들을 선택해 주셨다\"고 말하는 것인가? 그대들이 주장하는 이러한 배분법은 도대체 어디서 나온 것인가?",
  43017: "그들 중의 누군가에게 딸이 태어났다는 소식이 전해질 때면 -그는 이전에 자신의 주님께 딸이 있다고 주장해 왔노라- 그는 슬픔과 근심으로 얼굴이 어둡게 변하고 깊은 시름에 잠기더라. 그는 이렇게 딸을 선호하지 않으면서도 정녕 자신의 주님께는 딸이 있다고 말하는 것인가?",
  43018: "그들은, 예쁘게 꾸며진 장식품 속에서 길러지고 논쟁을 벌일 때 논지가 분명하지 못한 여아를 하나님의 자식이라 주장하는 것인가?",
  43019: "천사들은 가장 자비로우신 하나님의 종복이라. 그럼에도 그들은 천사들이 여성이라 주장하더라. 하나님께서 천사들을 창조하실 때 그들이 그 현장에 있기라도 했단 말인가? 천사들이 그들의 거짓 증언을 기록할 것이고, 심판의 날 그들은 이에 관해 질문받을 것이며, 그들은 자신들의 거짓말로 인해 징벌을 받을 것이라.",
  43020: "운명을 핑계로 삼는 자들이 말하더라. \"만일 하나님께서 뜻하셨다면 우리는 천사들을 숭배하지 않았을 것이오. 그러나 우리는 그들을 숭배하고 있고, 이는 하나님께서 우리의 행위에 만족하신다는 뜻이오\" 그들은 그 어떤 지식도 없이 그저 거짓을 말하고 있을 뿐이라.",
  43021: "꾸란이 계시되기 이전에 하나님께서 저 우상 숭배자들에게 성서를 주시기라도 하셨단 말인가? 그리고 그 성서가 그들에게 하나님 이외의 것을 숭배하는 일을 허락했단 말인가? 그리하여 그들이 그 성서의 내용을 굳건히 지키고, 그것을 행동의 근거로 삼는 것인가?",
  43022: "아니라. 그러한 일은 발생한 적이 없노라. 한편, 전통을 핑계로 삼는 자들이 말하더라. \"실로 우리는 조상들이 우상을 숭배함을 알게 되었고, 그들의 전통을 모범 삼아 우리도 그들처럼 우상을 숭배하는 것이오\"",
  43023: "저들 (메카의 우상 숭배자들) 이 이슬람을 부정하고 조상의 전통을 변명거리로 삼는 것처럼 그대-사도여! - 이전의 자들도 동일한 변명을 하였도다. 하나님께서 도시에 사도를 보내시어 그곳의 거주민들에게 경고의 메시지를 보낼 때면, 도시의 부유한 우두머리들은 어김없이 이렇게 말하였노라. \"실로 우리는 우리의 조상들이 따르는 종교를 알게 되었고, 실로 우리는 그들의 전통을 따르는 자들이오\" 그러니 그대 (무함마드) 와 함께 있는 자들이 내놓는 변명은 결코 새로운 것이 아니라.",
  43024: "그들의 사도가 말하였노라. \"만약 내가 그대들에게 그대들의 조상들이 따르던 종교보다 더 훌륭한 종교를 가져왔다 하더라도 그대들은 계속해서 조상들의 종교만을 고집할 텐가? \" 그들이 말하였노라. \"실로 우리는 그대와 그대 이전의 사도들이 받은 메시지를 불신하오\"",
  43025: "그리하여 하나님께서는 그대 이전의 사도들을 부정하던 자들을 멸망시키셨노라. 그러니 그대는 사도들을 부정하던 자들의 고통스런 최후가 어떠했는지 숙고해 보라.",
  43026: "그대-사도여! -는 기억하라. 아브라함이 그의 아버지와 그의 백성에게 말하였노라. \"실로 여러분들은 하나님이 아닌 우상들을 숭배하지만, 나는 그러한 우상들과 아무 상관도 없으며 그들로부터 결백합니다\"",
  43027: "\"그러나 나를 창조하신 하나님은 예외로서, 실로 그분께서는 저를 진실된 종교로 인도해 주시어 저를 도우실 것입니다\"",
  43028: "아브라함은 \"라 일라하 일랄라\" (하나님 이외에는 경배받을 존재가 없다) 를 자신의 후손들 사이에 지속적으로 남아 있을 말씀으로 만들었고, 이로써 그들 중에서 유일신 사상을 견지하고 하나님께 대등한 존재를 두지 않는 자들이 꾸준히 배출되었노라. 아브라함은 그렇게, 그들이 우상 숭배와 거역 행위를 참회하면서 하나님께로 되돌아오기를 희망하였던 것이라.",
  43029: "저들의 우상 숭배와 불신에도 불구하고 하나님께서는 그들을 멸하심에 서두르지 않으셨고 그들이 현세에 머물도록 하셨노라. 하나님께서는 그들과 그들 이전의 조상들에게 현세의 기쁨을 누리도록 하셨으니, 그들에게 꾸란이 도래하고 분명한 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 찾아오기 전까지 그렇게 하셨노라.",
  43030: "그들에게 의심의 여지가 없는 진리의 성서 꾸란이 도래했을 때 그들은 말하였노라. \"꾸란은 무함마드가 우리에게 거는 주술이며, 실로 우리는 꾸란을 불신하며 믿지 않겠소\"",
  43031: "이슬람을 부정하는 우상 숭배자들이 말하였노라. \"하나님께서는 왜 메카나 따이프 출신의 위대한 두 명의 남성 중의 한 명에게 꾸란을 내리지 않고, 이 가난한 고아 출신의 무함마드에게 꾸란을 내리셨는가? \"",
  43032: "정녕 그들이 그대-사도여! - 주님의 자비를 나누어 주기라도 한단 말인가? 그리하여 그들은 원하는 자에게 그것을 주기도 하고 막기도 한단 말인가? 아니면 하나님께서 그렇게 하시는 것인가? 하나님이야말로 현세의 삶에서 그들의 양식을 분배하시니, 그들 중에는 부유한 자도 있고 가난한 자도 있어 어떤 이들은 다른 이들을 일꾼으로 고용하노라. 그러나 내세에서 주어질 그대 주님의 자비는 그들이 현세에서 모으는 덧없는 재물보다 더 훌륭하노라.",
  43033: "인간들 모두가 불신으로 통일된 공동체를 이룰 우려만 없었더라면 실로 하나님께서는 불신하는 자들의 집에 은으로 된 천장과, 그들이 밟고 올라갈 수 있는 (은으로 된) 계단을 두셨을 것이라.",
  43034: "그들의 집에는 여러 대문을 두고, 그들이 몸을 기댈 침대도 두었을 것이니, 이것은 그들에 대한 시험이며 그들을 서서히 옥죄는 징벌이라.",
  43035: "또한 그들에게 황금도 주었을 것이라. 그러나 이 모두는 그저 현세 삶에서의 짧은 유희에 불과하며, 영원하지 않기에 그 효용도 적도다. 그러나 그대-사도여! - 의 주님 가까운 곳에서 받을 내세에서의 기쁨은 그보다 더 훌륭하며, 그 기쁨은 명령 사항을 지키고 금지 사항을 멀리함으로써 하나님을 경외하던 자들의 것이라.",
  43036: "하나님의 메시지를 경시하며 메시지에 등을 돌리는 자는 하나님께서 사탄에게 그를 점거할 능력을 허락하시고, 이에 사탄은 그와 언제나 함께하면서 그의 방황을 더하노라.",
  43037: "꾸란에 등을 돌리는 자들과 함께하는 이 사탄들은 그들이 하나님의 종교로 들어서지 못하도록 그 길을 가로막노라. 그리하여 그들은 하나님의 명령을 지키지 않고, 그분께서 금지한 것을 멀리하지도 않으며, 그들은 자신들이 진리를 따른다고 생각하기에 자신들의 방황에 대해 참회하지도 않노라.",
  43038: "하나님의 메시지에 등을 돌리던 자는 심판의 날 소망하며 말할 것이라. \"아, 나와 너 (사탄) 가 동쪽과 서쪽 만큼이나 멀리 떨어져 있었다면 좋았을 것을! 너는 참으로 사악한 동료구나\"",
  43039: "하나님께서 심판의 날 불신자들에게 말씀하실 것이라. \"너희들이 오늘 다 같이 벌을 받는다고 해서 그것이 너희에게 도움이 되지 못하니, 너희의 우상들이 너희의 벌을 대신 짊어질 수 없음이라. 너희는 이미 우상 숭배와 거역 행위로 너희 자신들을 부당히 다루었노라”",
  43040: "저들은 진리를 듣지 못하는 귀머거리들이며 진리를 보지 못하는 맹인들이라. 그런데도 그대-사도여! -는 귀먹은 저들을 듣게 하거나 눈먼 저들을 인도한단 말인가? 아니면 그대가 올곧은 길에서 벗어나 크게 방황하고 있는 저들을 인도한단 말인가?",
  43041: "만일 하나님께서 그들을 벌하시기 전에 그대-사도여! -를 죽게 하신다면, 실로 하나님께서는 현세와 내세에서 그들에게 징벌을 내리심으로써 그들을 응징하실 것이라.",
  43042: "아니면 하나님께서 정녕 그들에게 약속한 징벌을 그대에게 보여줄 것이라. 실로 하나님께서는 그들을 제압할 힘을 지닌 분으로서, 그들은 결코 그분을 막을 수 없노라.",
  43043: "그러니 그대-사도여! -는 주님으로부터 그대에게 계시된 것을 확고히 붙잡고 그것을 실천하라. 실로 그대는 혼동의 여지가 없는 진리의 길을 따르고 있노라.",
  43044: "진실로 이 꾸란은 그대와 그대의 백성을 위한 명예라. 그대들은 꾸란을 믿어야 하고 그 안에 있는 지침을 따라야 하며 꾸란으로의 초대에 응해야 하노라. 심판의 날 그대들은 이 모두에 관하여 질문 받을 것이라.",
  43045: "그대 -사도여! - 이전에 하나님께서 보내신 사도들에게 물어보라: 하나님께서 가장 자비로우신 당신이 아닌 것들을 숭배의 대상으로 두신 적이 있던가?",
  43046: "진실로 하나님께서는 모세에게 당신의 징표들을 주시어 파라오와 수장들에게 보내셨으니, 모세가 말하였노라. \"실로 나는 모든 피조물의 주님이신 하나님께서 보내신 사도라\"",
  43047: "그리하여 모세가 그들에게 하나님의 징표를 가져왔을 때, 보라, 그들은 징표를 깔보며 조롱하더라.",
  43048: "하나님께서 파라오와 수장들에게 모세가 가져온 메시지가 진실임을 알려주는 징표를 보여주실 때면 그분께서는 언제나 그 이전의 징표보다 더 위대한 징표를 보이셨노라. 하나님께서는 그들에게 현세의 고난을 내리셨으니 그들이 불신을 참회하고 하나님께로 되돌아오도록 하기 위함이었으나, 그들에게는 아무 소용도 없었노라.",
  43049: "그들에게 여러 고난이 닥치자 그들은 모세 (그에게 평화가 깃들기를) 에게 말하였노라. \"주술가여! 그대의 주님은 우리가 믿으면 벌을 걷어내 주실 것이라 그대에게 약속하셨소. 그러니 우리를 위해 기도해 주시오. 하나님께서 이 고난을 걷어내 주신다면 진실로 우리는 올바른 길을 걷는 자들이 될 것이오\"",
  43050: "그리하여 하나님께서 그들에게서 그 고난을 걷어내셨을 때, 보라, 실로 그들은 자신들이 맹세한 약속을 깨뜨리더라.",
  43051: "파라오는 백성들 사이에서 자신의 왕권을 뽐내며 외쳤노라. \"나의 백성들이여! 이집트의 주권이 나에게 있지 아니하던가? 이 나일 강조차도 내 궁궐 밑으로 흐르고 있노라. 그러니 그대들은 나의 왕국과 나의 위대함을 보지 않겠는가? \"",
  43052: "“그러니 나는 이 모세보다 더 훌륭하도다. 그는 실로 도망친 전력이 있는 허약한 자로서, 말도 제대로 하지 못하노라”",
  43053: "“자, 그가 정말 하나님의 사도라면 어찌하여 그에게 금팔찌가 내려 와 그의 사도직을 증거하지 않는 것인가? 왜 천사들이 그와 함께 줄지어 나타나지도 않는 것인가? ”",
  43054: "그렇게 파라오는 자신의 백성들을 선동하였고, 그들은 그의 방황에 동조하였노라. 실로 그들은 하나님께 순종하길 거부하는 무리였도다.",
  43055: "그리하여 결국 그들이 불신을 지속함으로써 하나님의 분노를 초래하였을 때 그분께서는 그들을 응징하였으니 한 명도 빠짐없이 그들 모두를 익사시키셨노라.",
  43056: "그리하여 하나님께서는 파라오와 수장들을 사람들과 그대의 백성들을 위한 선례와 교훈으로 두시어, 이후의 사람들이 그들과 동일한 행위를 저지르지 않고 그들이 받은 징벌을 피할 수 있도록 하셨노라.",
  43057: "우상 숭배자들은 기독교인들이 숭배하는 예수가 지옥에 있을 것이라 생각했고 (꾸란 제 21장 98절 참조), 그대-사도여! -의 백성들은 그들 중의 한 명 (이븐 앗-지바으라) 이 \"예수가 지옥에 있다면 우리 우상들도 지옥에 있는 것에 만족하오\"라는 말하는 것을 듣고선 그의 논리에 감탄하며 쾌재를 불렀노라. (이에 하나님께서는 계시를 통해 예수는 지옥에 있지 않음을 밝히셨다 (꾸란 제 21장 101절)).",
  43058: "그들이 말하였노라. \"누가 더 훌륭한가? 우리의 우상들인가, 아니면 예수인가? \" 이븐 앗-지바으라, 그리고 그와 유사한 자들은 진리에 도달하기 위하여 예수를 예로 드는 것이 아니며, 그저 논쟁이 좋아 그러는 것이라. 실로 그들은 천성적으로 언쟁을 즐기는 자들이라.",
  43059: "마리아의 아들 예수는 그저 하나님의 종복들 중의 한 명으로, 하나님께서는 그에게 메시지를 전하는 사도직의 은총을 베푸셨노라. 하나님께서는 예수를 당신의 능력을 나타내는 징표로 두시어 이스라엘의 자손들이 이를 통해 교훈을 얻도록 하셨으니, 하나님께서는 예수를 아버지 없이 창조하셨고 아담은 아버지와 어머니 없이 창조하셨노라.",
  43060: "만약 하나님께서 그대들-아담의 자손들이여! -의 멸망을 뜻하셨다면 실로 그분께서는 그대들을 멸망시킨 후 그대들 대신에 천사들을 두시어 그들이 지상에서 뒤를 잇도록 하셨을 것이며, 그들은 하나님 한 분만을 경배하고 그분께 그 어떤 대등한 존재도 두지 않았을 것이라.",
  43061: "진실로 예수는 종말의 날이 가까워졌음을 알리는 대징조 중의 하나로서, 심판의 날이 다가올 때 예수는 지구로 재림할 것이라. 그러니 그대들은 종말의 날이 도래할 것임을 의심하지 말고, 내(무함마드)가 가져온 하나님의 메시지를 따르라. 이것이야말로 구부러짐이 없는 올바른 길이라.",
  43062: "사탄이 그대들을 유혹하고 기만하여 그대들이 올바른 길로 들어섬을 막으려 하니, 그대들은 결코 사탄을 따르지 말라. 실로 그는 그대들의 분명한 적으로서 그대들에게 명백한 적의를 표출하노라.",
  43063: "예수 (그에게 평화가 깃들기를) 가 백성들에게 자신이 사도임을 알리는 분명한 증거를 가지고 왔을 때 예수는 그들에게 말하였노라. \"실로 나는 그대들에게 하나님에게서 비롯한 지혜를 가지고 왔으며, 그대들이 종교에 있어 의견을 달리하는 부분을 그대들에게 분명히 설명하고자 하노라. 그러니 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하고, 내가 그대들에게 명하고 금하는 것을 지키라\"",
  43064: "\"실로 하나님께서는 나의 주님이시자 그대들의 주님이시며, 그분 이외에는 그 어떤 주님도 없노라. 그러니 그대들은 하나님 한 분만을 경배하라. 이 유일신 사상이야말로 구부러짐이 없는 올바른 길이라\"",
  43065: "이에 기독교의 분파들은 예수에 대해 의견을 달리하였노라. 그들의 일부는 예수가 하나님이라 말하고, 다른 이들은 예수가 하나님의 아들이라 말하며, 또 다른 이들은 예수와 그의 어머니 모두가 신이라 주장하였노라. 삼위일체 등으로 예수에 신성을 부여함으로써 자신의 영혼을 부당히 다룬 자들에게는 재앙이 있을 것이니, 심판의 날 그들에게 준비된 고통의 징벌이 그것이라.",
  43066: "예수에 관해 의견을 달리하는 분파들이 기다리는 것은 심판의 날일 뿐이니, 그날은 그들이 느끼지 못하는 사이에 갑작스레 도래할 것이라. 그들이 불신을 버리지 않는 상태에서 그날이 찾아온다면, 그들이 맞이할 최후는 오직 고통스런 징벌 뿐이라.",
  43067: "불신과 방황을 기반으로 우정을 나누던 친구들은 심판의 날 서로가 서로에게 적이 될 것이라. 그러나 하나님의 명령 사항을 실천하고 그분의 금지 사항을 멀리함으로써 하나님을 두려워하던 자들은 예외로서, 그들의 우정은 그날에도 지속되노라.",
  43068: "“하나님께서 그들에게 말씀하실 것이라. \"나의 종복들이여! 오늘 그대들은 앞으로 있을 일에 대해 두려워하지 않을 것이며 현세에 남기고 간 것에 대해서도 슬퍼하지 않을 것이라\"",
  43069: "(이러한 말을 들을 자들은) 사도에게 내려진 꾸란을 믿고, 꾸란의 명령 사항을 실천하고 금지 사항을 멀리함으로써 꾸란의 지침에 순종하던 자들이라.",
  43070: "\"그대들은 그대들의 믿음과 유사한 믿음을 가진 자들과 함께 천국으로 들어가라. 그대들은 그곳에서 고갈되지도 끊기지도 않을 영원한 기쁨을 발견할 것이니, 그 기쁨을 만끽하라\"",
  43071: "시중 드는 자들이 금으로 된 접시와 술잔을 가지고 그들 주위를 돌 것이라. 천국에는 영혼이 욕망하는 것과 보는 눈이 즐거워 할 것이 있으며, 그대들은 그곳에서 나가지 않고 영원히 거주할 것이라.",
  43072: "그대들에게 묘사된 이 천국은 하나님께서 그대들에게 물려주시는 것으로, 하나님께서 그대들의 선행을 보시고 친히 선사해 주시는 당신의 은혜라.",
  43073: "그대들은 천국에서 풍성한 과일을 끊임없이 받을 것이며 그대들은 그 과일을 먹을 것이라.",
  43074: "(이전에 하나님께서는 선행을 실천하는 자들의 보상을 언급하셨고, 이제부터는 그들과 반대의 경우인 악행을 저지르는 자들의 징벌을 언급하신다)  불신과 거역 행위 등으로 악행을 저지르는 자들은 심판의 날 지옥에 들어가 고통을 받을 것이며 그곳에서 영원히 머무를 것이라.",
  43075: "그들에게 벌이 경감되는 일은 없으며, 그들은 벌을 받으면서 하나님의 자비를 체념하게 되노라.",
  43076: "그들이 지옥에 들어가는 것은 하나님께서 그들을 부당히 대우하셨기 때문이 아니며, 그들 자신이 불신으로써 자신들의 영혼을 부당히 다루었기 때문이라.",
  43077: "그들은 지옥의 문지기인 말리크를 소리쳐 부르노라. \"말리크여! 당신의 주님께서 우리를 죽게 하시어 우리가 고통에서 해방되도록 조치해 주시오\" 이에 말리크가 대답하며 말하노라. \"너희들은 죽지 않고 지옥에서 영원히 머물 것이며, 고통의 벌은 지속될 것이라\"",
  43078: "“실로 이전에 하나님께서는 현세에서 너희들에게 의심의 여지가 없는  진리를 가져오셨으나 너희들 대다수는 진리를 혐오하였노라”",
  43079: "만약 그들이 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 를 해치기 위해 계략을 꾸민다면, 실로 하나님께서는 책략하심에 있어 그들의 술수를 능가하시노라.",
  43080: "아니면 그들은 하나님께서 그들의 마음속에 감추는 비밀이나 그들이 나누는 비밀스런 대화를 듣지 못한다고 생각하는 것인가? 그렇지 않노라. 하나님께서는 그 모든 것을 듣고 계시며, 그분의 천사들은 그들 곁에서 그들의 모든 언행을 기록하고 있노라.",
  43081: "그대-사도여! -는 하나님께 딸들이 있다는 허황된 주장을 하는 자들에게 말하라. \"완벽하신 하나님께서는 자식을 두지 않으시노라. 그렇기에 나는 하나님 한 분만을 경배하는 자들 중에서도 첫 번째로 경배하는 자라\"",
  43082: "우상 숭배자들은 하나님께 대등한 존재나 배우자 또는 자식이 있다고 말하더라. 그러나 (일곱) 하늘과 땅의 주님이시자 권좌의 주님이신 하나님께서는 그 어떤 결함도 없으신 분이라!",
  43083: "그러니 그대 - 사도여! - 는 그들을 놓아두라; 그들은 허위를 지속하고 유흥을 즐기다가 결국에는 그들이 약속받은 심판의 날을 직면하게 될 것이라.",
  43084: "하나님께서는 하늘에서 경배받으실 권리를 지닌 분이시며 지구에서도 경배받으시실 권리를 지닌 분이라. 그리고 하나님께서는 피조물의 창조와 운명과 계획에 있어 가장 현명하신 분이며, 종복들의 모든 상황을 가장 잘 알고 계신 분으로서, 그 어떤 것도 그분께는 감추어지지 않노라.",
  43085: "(일곱) 하늘과 땅과 그 사이에 존재하는 모든 것을 소유하신 하나님께 축복이 가득하도다. 심판의 날이 전개될 종말의 시간이 언제인지는 오직 하나님 한 분만이 알고 계시노라. 그대들은 실로 내세에서 하나님 한 분께로 돌아가 그분으로부터 행위의 계산과 보응을 받게 될 것이라.",
  43086: "우상 숭배자들이 숭배하는, 하나님 이외의 우상들은 하나님 앞에서 누군가를 중재할 권한을 가지지 못하노라. 그러나 예수나 우자이르 (에즈라) 나 천사들처럼 지식을 가지고서 하나님 이외에는 경배받을 존재가 없음을 증언한 자들은 예외라.",
  43087: "만일 그대가 정녕 그들에게 \"그대들을 창조한 자가 누구인가? \"라고 묻는다면 실로 그들은 \"하나님께서 우리를 창조하셨소\"이라고 말할 것이라. 이러한 인정 이후에도 그들은 하나님 한 분만을 경배하지 않으니, 이 어찌 된 일인가?",
  43088: "하나님의 사도는 자신의 백성이 믿지 않음을 하나님께 호소하였고, 하나님께서는 그의 하소연을 잘 알고 계시노라. 그가 말하였노라. \"저의 주님이시여! 실로 저들은 당신께서 저에게 주신 메시지를 부정하고 있습니다\"",
  43089: "그렇다면 그대는 그들을 멀리하고, 그들의 해악을 물리치는 말을 하라. (이 명령은 메카 시절의 명령이었다. ) 그들은 장차 그들에게 닥칠 벌이 무엇인지 알게 될 것이라.",
  44000: "앗-두칸 (연기)\n계시 분류: 메카\n•    계시 목적    \n이 장은 이슬람을 부정하는 자들에게 현세와 내세의 벌이 있음을 주지시킴으로써 얼마 후에 닥쳐올 벌을 경고하고 있다.\n•    요약 주해",
  44001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  44002: "하나님께서는 진리로 인도하는 명백한 길을 제시하는 꾸란을 두고 맹세하셨으니",
  44003: "실로 하나님께서는 꾸란을 축복이 가득한 운명의 밤 (라일라툴 까드르) 에 내리셨고, 실로 하나님께서는 꾸란을 통해 경고의 메시지를 전하시노라.",
  44004: "그날 밤에는 인간의 양식과 수명 등 하나님의 의지로 발생할 그 해에 있을 모든 중요한 사안들이 결정되노라.",
  44005: "그리고 그 모든 사안들은 하나님께서 친히 조정하여 결정하시는 것이라. 실로 하나님께서는 이전부터 계속하여 사도들을 보내셨으니,",
  44006: "이는 그대-사도여! -의 주님께서 사도들의 메시지를 받을 사람들에게 자비를 베푸셨기 때문이라. 진실로 하나님께서는 인간의 모든 말을 들으시고, 그들의 모든 행위와 의도를 알고 계신 분으로, 그분께는 그 어떤 것도 감추어지지 않노라.",
  44007: "사도를 보내신 분은 (일곱) 하늘과 땅 그리고 그 사이에 존재하는 것의 주님이시라. 그대들이 이 사실을 확신한다면 하나님의 사도를 믿으라.",
  44008: "하나님 이외에는 그 누구도 경배받을 권리가 없노라. 그분께서는 생명을 불어넣으시고 죽음을 부여하시며, 그분 이외에는 그 누구도 그렇게 할 수 없도다. 하나님께서는 그대들의 주님이시자 그대들의 옛 조상들의 주님이시라.",
  44009: "그러나 저 우상 숭배자들은 이러한 사실에 의심을 품고 있으며, 허위를 즐기면서 유흥에 빠져 있노라.",
  44010: "그러니 그대-사도여! -는 그대의 동시대 사람들이 받을 징벌을 기다려 보라. 그날 그들은 고통으로 인해 하늘에서 자욱한 연기를 목격할 것이라.",
  44011: "연기가 그대와 함께 있는 사람들을 덮치고, 사람들이 말할 것이라. \"그대들이 받는 이 벌은 고통의 벌이라\"",
  44012: "이에 그들은 간절히 주님께 요청할 것이라. \"저희의 주님이시여! 저희에게 보내신 벌을 거두어 주소서. 이 벌만 없애 주신다면 저희는 당신과 당신의 사도를 믿겠습니다\"",
  44013: "이미 그들에게 사도가 도래하여 분명한 메시지를 전달하 바 있고, 그들은 그의 정직성과 진실됨을 알고 있었노라. 그러니, 지금에서야 깨닫고 주님께 참회한들 그들에게 무슨 소용이 있겠는가?",
  44014: "그럼에도 그들은 사도를 믿지 않고 돌아섰으며, 그에 관해 이렇게 말하였노라. \"그는 누군가로부터 가르침을 받은 것일 뿐 사도는 아니라\" \"그는 광기 들린 자라\"",
  44015: "실로 하나님께서는 그대들로부터 얼마간의 벌을 거두어 주실 것이나, 실로 그대들은 다시 불신과 부정으로 되돌아갈 것이라.",
  44016: "그대-사도여! -는 하나님께서 그대의 불신자 백성을 가장 강력한 징벌로 제압하실 바드르 전투의 날을 기다리라. 하나님께서는 그날, 당신을 불신하고 당신의 사도를 부정하던 그들을 응징하실 것이라.",
  44017: "실로 하나님께서는 그들 이전에 이미 파라오의 백성을 시험하신 바 있노라. 그들에게 명예로운 사도 한 명이 도래하여 그들을 유일신 사상으로 초대하였으니 그의 이름은 모세 (그에게 평화가 깃들기를) 라.",
  44018: "모세는 파라오와 그의 백성들에게 말하였노라. \"그대들은 이스라엘의 자손들을 풀어주라. 그들은 하나님의 종복들이기에, 그대들은 그들을 노비로 삼을 권리가 없노라. 나는 하나님께서 그대들을 위해 보내신 사도이며 하나님으로부터 명령받은 대로 가감없이 메시지를 전하노라\"",
  44019: "\"그대들은 하나님을 경배하지 않고 그분의 종복들을 억압함으로써 하나님 앞에서 오만하지 말라. 실로 나는 그대들에게 확실한 근거를 보여줄 것이라\"",
  44020: "\"실로 나는 그대들이 나를 투석하여 살해하지 못하도록 나의 주님과 그대들의 주님께 보호를 요청하였노라”",
  44021: "\"그대들이 정녕 내가 가져온 메시지를 믿지 못하겠거든 나에게 해를 끼치지 말고 나에게서 물러나시오\"",
  44022: "그리하여 모세가 자신의 주님께 기도하였노라. \"실로 저들-파라오와 수장들-은 악행을 저지르는 무리들로서 서둘러 벌 받아야 할 자들입니다\"",
  44023: "그리하여 하나님께서는 모세에게 한밤중에 그의 백성들을 데리고 떠날 것을 명령하셨고, 파라오와 그의 백성들이 그들을 뒤쫓을 것임을 알려주셨노라.",
  44024: "하나님께서 명령하시길, 모세와 이스라엘의 자손들이 바다를 건넌 후 바다를 있는 그대로 내버려 두라 하셨고, 파라오와 그의 백성들은 바다에서 익사할 것이라 말씀하셨노라.",
  44025: "파라오와 그의 백성들은 얼마나 많은 정원과 물 흐르는 샘터를 내버려둔 채 익사한 것인가?",
  44026: "그들은 또 얼마나 많은 농작물과 아름다운 거처를 내버려두고",
  44027: "그들이 만끽하던 호화스런 삶을 뒤로 한 채 익사한 것인가?",
  44028: "그들에게 있었던 일은 저와 같노라. 하나님께서는 그들의 정원과 샘터와 농작물과 거처를 다른 백성에게 물려주셨으니 그들은 바로 이스라엘의 자손들이라.",
  44029: "파라오와 그의 백성이 익사할 때 하늘과 땅은 그들을 이유로 통곡하지 않았으며, 더 이상 그들에게 참회할 시간도 주어지지 않았노라.",
  44030: "파라오와 그의 백성들은 이스라엘의 자손들 중 남아들을 살해하고 여성들은 살려두었노라. 그러나 하나님께서는 이러한 치욕스런 고난으로부터 이스라엘의 자손들을 구해 주셨으니",
  44031: "파라오의 박해로부터 그들을 구하신 것이라. 실로 파라오는 하나님의 명령과 종교에 거만을 떨면서 도를 지나친 자들 중의 하나였노라.",
  44032: "진실로 하나님께서는 당신의 지식에 근거하여 당시에 존재하던 모든 이들 중에서도 특히 이스라엘의 자손들을 선택하셨고, 그들 중에서 많은 선지자들을 배출하셨노라.",
  44033: "그리고 하나님께서는 그들에게 모세의 사도직을 명백히 드러내는 분명한 징표들을 주셨으니, 만나와 메추리 등의 커다란 은총이 그것이라.",
  44034: "실로 부활을 부정하는 우상 숭배자들이 말하더라.",
  44035: "\"우리에게는 그저 첫번째 죽음만이 있을 뿐으로 그 이후의 삶이란 없소. 죽음 후의 부활 따위는 존재하지 않는단 말이오\"",
  44036: "\"그대 무함마드와 그대를 따르는 자들은, 하나님이 심판과 보응을 위해 죽은 자들을 부활시킨다고 하는데, 그대들의 말이 진실이라면 죽어 있는 우리의 조상들을 살려서 데려와 보시오\"",
  44037: "강력함과 저지력에 있어 더 월등한 자들은 누구인가? 그대를 부정하는 저 우상 숭배자들인가? 아니면 툽바의 백성과 아드와 싸무드 부족 등 그들 이전에 있었던 자들인가? 하나님께서는 그들 모두를 멸망시키셨으니, 그들은 악행을 저지르던 자들이었기 때문이라.",
  44038: "하나님께서는 (일곱) 하늘과 땅과 그 사이에 존재하는 것을 장난 삼아 창조하신 것이 아니라.",
  44039: "하나님께서는 (일곱) 하늘과 땅을 원대한 지혜로 창조하셨으나 우상 숭배자들 대부분은 이를 알지 못하노라.",
  44040: "하나님께서 당신의 종복들을 구분하실 심판의 날은 모든 피조물에게 약속된 시간이며, 그 때 하나님께서는 그들을 불러 모으실 것이라.",
  44041: "그날 그 어떤 친구나 친척도 서로에게 도움이 되지 못하며 하나님의 벌로부터 그들을 막아 주지도 못하노라. 그날에 모든 권한은 하나님께 있으며, 어느 누구도 감히 그 권한을 주장하지 못하기 때문이라.",
  44042: "그러나 하나님께서 자비를 베푸시는 자는 예외로서 그는 자신이 실천한 선행으로 효용을 얻을 것이라. 진실로 하나님께서는 감히 누구도 제압할 수 없는 가장 존엄하신 분이며, 참회하는 종복에게 가장 자애로우신 분이라.",
  44043: "(하나님께서는 이전에 부활을 언급하셨고, 여기서부터는 사람들이 부활 후에 맞이할 다양한 보응의 양상을 언급하고 계신다)  하나님께서 지옥의 밑바닥에서 길러내시는 앗-작꿈 나무가 있노라.",
  44044: "그 더러운 열매는 불신이라는 대죄를 저지른 자들이 먹을 음식으로",
  44045: "이 열매는 검은 기름과도 같아 그 뜨거움을 인해 그들의 배 속에서 끓어 오르니",
  44046: "극한의 뜨거움으로 끓어오르는 물의 부글거림과도 같노라.",
  44047: "지옥의 천사들에게 명령이 내려지노라. \"그를 매섭게 잡아 작열하는 불지옥의 한가운데로 끌고 가라\"",
  44048: "\"그 후 그의 머리 위에 끓어오르는 물을 퍼부어 그에게서 고통이 사그러지지 못하도록 하라”",
  44049: "그에게 목소리가 들릴 것이라. “고통의 징벌을 맛 보라. 진실로 너는 누구도 함부로 대하지 못하는 존엄한 자였고, 사람들 사이에서 명예로운 자였지 않았던가? \"",
  44050: "\"실로 이 징벌은 너희가 '심판의 날에 과연 일어날 일인가? ' 하며 의문을 품었던 것으로, 이제 그것을 두 눈으로 직접 목격하였으니 그 의심이 사라졌노라”",
  44051: "실로 하나님의 명령 사항을 실천하고 금지 사항을 멀리하는 자들은 안전한 곳에 있어 그 어떤 것도 그들에게 해를 끼치지 못하노라.",
  44052: "그들 곁에는 정원과 흐르는 샘물이 있을 것이며",
  44053: "그들은 부드러운 비단과 두꺼운 비단으로 만들어진 옷을 입은 채, 질투심 없이 서로가 서로를 바라볼 것이라.",
  44054: "하나님께서는 그들을 아름답고 큼직한 눈을 가진 여성들과 짝지어 주셨노라.",
  44055: "그들은 그곳에서 시중드는 자들에게 원하는 온갖 종류의 과일을 주문하는데 그 공급이 끊기지 않으며, 행여나 있을 과일의 부작용으로부터 그들은 안전하노라.",
  44056: "그들은 현세에서 첫 번째 죽음을 맛보았을지언정 천국에서만큼은 어떠한 죽음도 없이 영생할 것이라. 그들의 주님께서는 타오르는 불지옥의 벌로부터 그들을 구해 주셨으니",
  44057: "그대의 주님께서 그들에게 베푸시는 은혜라. 천국으로 들어가고 지옥을 모면하는 일, 정녕 이것이야말로 그 어떤 성공과도 비교될 수 없는 위대한 성공이라.",
  44058: "하나님께서 그대-사도여! -가 말하는 아랍어로 꾸란을 쉽게 해 주신 것은 오직 그들이 교훈을 얻도록 함이라.",
  44059: "그러니 그대는 그대의 승리와 저들의 패망을 기다려 보라. 실로 저들도 그대의 패망을 기다리고 있노라.",
  45000: "알-자씨야 (무릎 꿇린)\n계시 분류: 메카\n•    계시 목적    \n이 장은 욕망을 따르며 진리 앞에 거만해 하는 자들에게 하나님의 징표를 보여주면서 내세를 상기시키고 있다.\n•    요약 주해",
  45001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  45002: "꾸란의 계시는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 하나님에게서 비롯한 것이라.",
  45003: "진실로 (일곱) 하늘과 땅에는 하나님의 전능하심과 유일성을 알려주는 징표들이 있으며, 이는 믿는 자들을 위한 것으로서, 그들만이 징표를 통해 깨달음을 얻기 때문이라.",
  45004: "그리고 실로 그대들-인간들이여! -이 정액, 그 후의 작은 살점, 그 후의 매달린 덩어리로부터 창조되었다는 사실과 하나님께서 지상에 퍼뜨리신 기어 다니는 동물에는 하나님의 유일성을 드러내는 징표가 있노라. 이 징표는, 창조주는 곧 하나님이라는 사실을 굳건히 믿는 자들을 위한 것이라.",
  45005: "또한 밤과 낮의 교체와 하나님께서 하늘에서 내리시는 비와 그 비로써 죽어 있던 불모의 대지에 파릇한 식물을 내시어 그곳에 생명을 불어넣으심과 여러 방향에서 불어오는 바람의 변화무궁함에는 이성을 가진 자들을 위한 징표들이 있으니, 그들은 이를 통해 하나님께서 유일하심을 그리고 그분께서는 부활을 비롯한 모든 일이 가능하심을 인지하노라.",
  45006: "이것은 하나님의 징표로서 하나님께서 그대-사도여! - 에게 진리로써 그것을 낭송하시노라. 하나님께서 종복에게 내리신 이 말씀을 믿지 않는다면, 그들은 도대체 무슨 말씀을 믿겠다는 것인가?",
  45007: "지속적으로 죄를 짓고 거짓말을 일삼는 자들 모두에게 하나님의 벌과 파멸이 있도다.",
  45008: "이 불신자는 자신에게 낭송되는 하나님의 징표 꾸란을 듣고서도 마치 꾸란의 낭송을 듣지 않은 것처럼 불신과 거역 행위를 지속하고, 속으로 거만해 하면서 진리를 따르길 거부하노라. 그러니 그대-사도여! -는 내세에서의 고통스런 벌이 그를 기다리고 있음을 알리라.",
  45009: "그에게 꾸란의 일부가 전해질 때면 그는 그것을 조롱거리로 삼더라. 꾸란을 조롱하는 이들은 심판의 날 치욕스런 벌을 받게 될 것이라.",
  45010: "그들 앞에는 내세에서의 불지옥이 그들을 기다리고 있노라. 그들이 얻은 재물은 하나님 앞에서 그 어떤 도움도 되지 못하고, 하나님 이외에 그들이 숭배하던 우상들도 그들을 위해 그 무엇도 막아줄 수 없노라. 그들은 심판의 날 참혹한 벌을 받게 될 것이라.",
  45011: "하나님의 사도 무함마드에게 내려진 이 꾸란은 진리로의 길잡이라. 주님께서 당신의 사도에게 내리신 징표를 부정하는 자들은 엄중하고 고통스런 벌을 받을 것이라.",
  45012: "그대들-인간들이여! -을 위해 사나운 바다를 진정시키신 분이 하나님이시라. 그리하여 배들이 하나님의 명령에 따라 바다를 순항할 수 있게 되었고, 그대들은 하나님의 은혜를 추구하며 다양한 종류의 허락된 이익을 얻고, 그렇게 그대들은 하나님께서 베푸신 은총에 감사하게 되노라.",
  45013: "또한 하나님께서는 그대들을 위해 하늘에 있는 해와 달과 별, 땅에 있는 강과 나무, 산 등을 유용케 하셨으니 이 모든 은총은 하나님의 은혜로부터 비롯되었노라. 이처럼 하나님께서 그대들을 위해 자연을 순종시키심은 하나님의 전능하심과 유일성을 드러내는 징표로서, 숙고하는 자들은 이러한 징표를 통해 교훈을 얻을 것이라.",
  45014: "그대-사도여! -는 하나님과 그분의 사도를 믿는 자들에게 말하라. \"하나님의 은총이나 시험에 개의치 않으면서 그대들에게 나쁜 일을 저지르는 불신자들을 용서해 주라” 그러함은, 인내하는 신앙인이나 경계를 넘어서는 불신자나 하나님께서 그들 모두를 현세에서의 행위에 의거하여 보응하실 것이기 때문이라.",
  45015: "선행을 실천하는 자는 자기 자신에게 그 효용이 돌아가며, 하나님께서는 그의 선행을 필요로 하지 않으시노라. 악행을 저지르는 자는 그 불행한 결과로 자기 자신을 해치는 것이며, 하나님께서는 그의 악행으로 어떠한 해도 입지 않으시노라. 그 후 그대들은 하나님 한 분께로 돌아갈 것이며, 그분께서는 모든 이들을 정당히 보응하실 것이라.",
  45016: "진실로 하나님께서는 이스라엘의 자손들에게 타우라 (토라) 를 주셨고, 그들이 타우라의 규정으로 사람들 사이를 판결토록 하셨으며, 대부분의 선지자들을 그들 중의 아브라함 (그에게 평화가 깃들기를) 의 자손들로 하셨노라. 또한 하나님께서는 그들에게 다양한 종류의 좋은 것들로 양식을 주셨으며, 당시에 존재하던 모든 이들에 더하여 은혜를 베푸셨노라.",
  45017: "그리고 하나님께서는 그들에게 진리를 허위로부터 구분하는 증거들을 주셨노라. 하나님의 사도 무함마드가 도래하여 그들에게 불리한 증거가 확립되었을 때 그들은 의견을 달리하였고, 이러한 의견 차이는 권력과 명예를 목적으로 경쟁하던 그들 사이의 적개심 때문이라. 실로 그대-사도여! -의 주님께서는 그들이 현세에서 의견을 달리하던 것에 관하여 심판의 날 그들의 옳고 그름을 판결하실 것이라.",
  45018: "그 후에 하나님께서는 그대가 이슬람의 길을 따르도록 하셨으니, 그 길은 그대 이전의 사도들이 사람들을 믿음과 선행으로 초대하던 방식이라. 그러니 그대는 샤리아 (이슬람법) 를 따르고, 진리를 알지 못하는 자들의 욕망은 따르지 말라. 그들의 욕망은 진리로부터 그대를 멀어지게 할 뿐이라.",
  45019: "실로 진리를 알지 못하는 자들은 그대가 그들의 욕망을 따른대도 하나님의 징벌로부터 그대를 보호해 주지 못하노라. 실로 모든 거짓 종교에 속한 부당한 자들은 서로가 서로의 조력자이며, 믿는 자들에게 대항하는 동맹자들이라. 그러나 하나님께서는, 당신의 명령 사항을 실천하고 금지 사항을 멀리함으로써 당신을 경외하는 자들을 위한 조력자이시라.",
  45020: "하나님의 사도에게 계시된 이 꾸란은 사람들 사이에서 진리와 허위를 구분하는 근거가 되노라. 그리고 꾸란은 굳건한 믿음을 가진 자들을 위한 진리의 길잡이이자 자비라. 그러함은 그들이야말로 꾸란을 통해 올바른 길을 걷기 때문이라. 이로써 그들은 하나님의 기쁨을 얻으며 결국에는 하나님께서 그들을 천국으로 들게 하시고 지옥으로부터 멀어지게 하시노라.",
  45021: "불신과 거역 행위 등 악행을 저지른 자들은 하나님께서 현세와 내세에서 그들을 마치 신앙인들처럼 보상하실 것이라 생각했던 것인가? 그들의 판단이 참으로 추하도다.",
  45022: "하나님께서 (일곱) 하늘과 땅을 창조하신 것은 위대한 지혜를 실현하기 위함이며 그것을 부질없이 창조하신 것이 아니라. 그리하여 모든 이는 자신의 선행과 악행에 의해 보상이나 징벌을 받을 것이니, 하나님께서는 그들의 선행을 인색하게 보상하시거나 그들의 악행을 실제보다 더하여 벌하지 않으실 것이라.",
  45023: "욕망이 마치 신 (神) 인 양 자신의 욕망에 절대 복종하는 자를 그대-사도여! -는 보지 않았던가. 하나님께서는 그가 방황할 모든 조건을 갖추었음을 아셨음으로 그를 방황 속에 빠뜨리셨노라. 그렇게 하나님께서 그의 마음을 봉인하셨고 그로 인해 그는 유용한 사실을 듣지 못하고, 그의 눈에 덮개를 두셨기에 그는 진리를 보지 못하노라. 하나님께서 이렇게 그를 방황시키신 상황에서 그 누가 그를 진리로 인도할 수 있단 말인가? 그러니 그대들은, 욕망을 따르는 것이 얼마나 해가 되며 하나님의 법률을 따르는 것이 얼마나 득이 되는지 깊이 생각해 보지 않겠는가?",
  45024: "부활을 부정하는 불신자들이 말하노라. “삶이라는 것은 오직 우리가 살고 있는 이 현세에서의 삶 뿐이며 내세의 삶이란 존재하지 않소. 한 세대가 죽으면 다시 돌아오지 않고 그 후에 또 새로운 세대가 나타나는 것이오. 우리는 그저 시간의 흐름에 따라 죽을 뿐이오” 부활을 부정하는 저들은 그에 관한 일말의 지식도 없노라. 그들은 오직 추측만을 할 뿐이니, 실로 추측은 진리에 어떠한 도움도 되지 않노라.",
  45025: "부활을 부정하는 우상 숭배자들에게 하나님의 분명한 징표가 낭송될 때면 그들이 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 와 그의 교우들에게 할 수 있는 주장은 그저 다음과 같은 말 뿐이었노라. “그대들의 말처럼 우리가 죽은 후에 부활한다면, 그리고 그대들의 주장이 사실이라면 이미 죽어 있는 우리의 조상들을 되살려 보라”",
  45026: "그대-사도여! -는 그들에게 말하라. “하나님께서는 그대들을 창조하시어 생명을 불어 넣으시고 그 후 죽음에 이르게 하시노라. 그 후 하나님께서는 그 도래에 의심의 여지가 없는 심판의 날로 그대들을 모으실 것이며, 그날에 그대들의 행위를 심판하시고 보응하실 것이라. 그러나 대다수의 사람들은 이를 알지 못하여 선행으로써 그날을 준비하지 않고 있노라\"",
  45027: "(일곱) 하늘의 주권과 땅의 주권은 오직 하나님께만 있노라. 그러니 하늘과 땅에서 경배받을 권리는 오롯이 하나님만이 소유하시노라. 심판의 날이 시작되는 순간 하나님께서는 죽어 있던 모든 이들을 부활시키시어 그들을 심판하고 보응하실 것이라. 그날 하나님 이외의 것들을 경배하며 허위를 따르고, 진리를 부정하며 거짓에 힘을 실어주려던 자들은 심각한 손실에 직면할 것이라.",
  45028: "그대-사도여! -는 그날 모든 공동체가 무릎을 꿇은 채 자신들에게 어떤 조치가 내리질지 기다리는 모습을 볼 것이라. 모든 공동체는 천사들이 기록해 둔 각자의 행위 기록부로 불려 갈 것이라. \"오늘 그대들-사람들이여! -은 그대들이 현세에서 행하던 선행과 악행으로 보응을 받을 것이라\"",
  45029: "\"이것은 하나님의 책으로서 천사들이 기록한 그대들의 행위 기록부라. 이 책은 그대들에 관해 진리로써 증언하니 그대들은 이 책을 읽으라. 실로 하나님께서는 기록 천사들에게 그대들의 현세에서의 행위를 기록하라 명하셨노라\"",
  45030: "하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들은 그들의 주님이신 하나님께서 당신의 자비로써 그들을 천국에 들게 하시노라. 하나님께서 주시는 이러한 보상이야말로 그 어떤 성공과도 비교될 수 없는 분명한 성공이라.",
  45031: "하나님을 불신하는 자들은 그들을 힐책하는 목소리가 들릴 것이라. \"나의 징표가 이전에 너희들에게 낭송되지 않았던가? 그러나 너희들은 징표를 믿지 않고 거만해 하였으며, 너희들은 불신과 죄악 등의 악행을 저지르는 무리였노라\"",
  45032: "\"'하나님께서 사람들을 부활시키신 뒤 그들을 보응하겠다고 약속하셨고, 실로 그분의 약속은 추호의 의심도 없는 진실이라. 또한 심판의 날은 의문의 여지 없이 도래할 것이니, 그대들은 선행으로써 그 날을 준비하라'라는 말이 전해질 때면 너희들은 대답하였노라. '우리는 심판의 날이 무엇인지 당최 알 수가 없고, 우리는 그저 어렴풋한 추측만을 할 뿐이오. 우리는 심판의 날이 올 것이라는 확신이 들지 않소'\"",
  45033: "(심판의 날) 그들이 현세에서 저지른 불신과 거역 행위 등 악행의 처참한 결과가 그들에게 드러날 것이며, 그들이 현세에서 경고받을 때마다 조롱하던 징벌이 그들을 에워쌀 것이라.",
  45034: "하나님께서 그들에게 말씀하실 것이라. \"너희는 너희에게 약속된 이 만남의 날을 잊었고 믿음과 선행으로써 이날을 준비하지 않았노라. 그렇기에 오늘 나는 너희를 불지옥에 내버려둔 채 너희를 잊을 것이라. 너희가 거주할 곳은 불지옥이며, 너희에게는 하나님의 벌로부터 너희를 구해 줄 어떤 조력자도 없노라\"",
  45035: "\"너희가 벌을 받는 이유는 너희가 하나님의 징표를 조롱거리로 삼고 비웃었기 때문이며, 현세의 삶이 주는 쾌락과 욕망에 너희가 속아 넘어갔기 때문이라\" 그리하여 이날, 하나님의 징표를 비웃던 불신자들은 지옥에서 빠져 나오지를 못하고 그곳에서 영원히 거주할 것이라. 그들은 다시 현세로 돌아가 선행을 행할 수 없으며 하나님께서는 그들에 기뻐하지도 않으시노라.",
  45036: "그러하니 (일곱) 하늘의 주님이시고 땅의 주님이시자 모든 피조물의 주님이신 하나님 한 분께만 찬미가 있노라.",
  45037: "(일곱) 하늘과 땅에서의 위엄과 위대함은 오직 하나님만이 가지시노라. 하나님께서는 감히 누구도 제압할 수 없는 가장 존엄하신 분이시며, 창조와 운명과 계획과 판결에 있어 가장 지혜로우신 분이라.",
  46000: "알-아흐까프 (사막 지대)\n계시 분류: 메카\n•    계시 목적    \n이 장은 이슬람을 거부하는 자들이 변명할 수 없도록 증거를 제시하면서 그들에게 닥쳐올 벌을 경고하고 있다.\n•    요약 주해",
  46001: "(하.밈.) 이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다.",
  46002: "꾸란의 계시는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의  창조와 운명의 결정과  법의 제정에 있어 가장 지혜로우신  하나님에게서  비롯한  것이라.",
  46003: "하나님께서는 (일곱) 하늘과 땅과 그 사이에 존재하는 것을 부질없이 창조하신 것이 아니라. 이를 창조하심은 하나님의 무한한 지혜에 의한 것이며, 그 지혜 중의 하나는 하나님의 종복들이 창조물을 통해 하나님을 인지하여, 그들이 하나님께 대등한 존재를 두지 않고 그분 한 분만을 경배하게 되는 것이라. 이를 통해 그들은 정해진 기간 동안 -그 기간이 얼마인지는 하나님만이 아시노라- 지구상의 계승자로서 그들의 의무를 다하게 되노라. 그러나 하나님을 불신하는 자들은 하나님의 성서가 경고하는 바를 무시하면서 그로부터 등을 돌리고 있노라.",
  46004: "그대는 진리에 등을 돌리는 우상 숭배자들에게 말하라. \"그대들은 하나님이 아닌 우상들을 숭배하지만, 그것들이 땅에서 무엇이라도 창조하였다면 나에게 그것을 보이라. 그들이 산을 창조하였는가, 강을 창조하였는가? 아니면 그것들이 (일곱) 하늘을 창조하신 하나님의 창조 행위에 어떤 대등한 기여라도 하였단 말인가? 그대들은 우상들이 숭배받을 자격이 있다고 말하고 있으니, 만약 그대들의 주장이 사실이라면 꾸란 이전에 계시된 하나님의 성서나 이전 사람들이 남긴 지식의 흔적이라도 가져와 보라\"",
  46005: "우상은 심판의 날까지 자신들에게 기도하는 자에게 응답하지 못할 것이니, 하나님이 아닌 우상을 숭배하는 자보다 더 방황하는 자는 없노라. 그들이 숭배하는 우상은 그들의 기도를 의식하지 못하며, 그들에게 효용을 주거나 해악을 끼치지도 못하노라.",
  46006: "우상들은 현세에서 그들에게 어떤 도움도 되지 못하며, 이에 더해 심판의 날 그것들은 자신들을 숭배하던 자들에게 적으로 돌변할 것이라. 그것들은 그들로부터 결백함을 주장하면서 그들이 자신들을 숭배했음을 알지 못했다고 말할 것이라.",
  46007: "하나님께서 사도에게 내리신 분명한 징표가 그들에게 낭송될 때면 불신하는 자들은 사도를 통해 그들에게 도래한 꾸란을 두고서 \"이것은 분명한 주술일 뿐 하나님의 계시가 아니오\"라고 말하더라.",
  46008: "저 우상 숭배자들은 \"무함마드는 꾸란을 지어내고선 그것이 하나님의 성서라 거짓말을 하는 것이라\"라고 말하는 것인가? 그대-사도여! 는 그들에게 말하라. \"만일 내가 마음대로 꾸란을 지어낸 것이라면 하나님께서 나를 벌하실 것이며, 그대들은 그분의 벌로부터 결코 나를 구해줄 수 없을 것이라. 그러할진대 어떻게 내가 꾸란을 꾸며내어 하나님의 벌에 내 자신을 노출시킨단 말인가? 하나님께서는 그대들이 꾸란을 비방하고 나를 모욕하면서 내뱉는 말들을 그 누구보다 더 잘 알고 계시노라. 나와 그대들 사이에 증언자는 하나님 한 분만으로 충분하노라. 하나님께서는 죄를 저지른 후 참회하는 종복들을 가장 너그러이 용서하시는 분이며 그들에게 가장 자애로우신 분이라”",
  46009: "그대-사도여! -는 그대의 사도직을 부정하는 저 우상 숭배자들에게 말하라. “하나님께서는 나를 최초의 사도로 보내신 것이 아니라. 그러니 내가 그대들을 이슬람으로 초대함에 놀라지 말지니, 나 이전에 이미 많은 사도들이 지나갔노라. 하나님께서 나를 그리고 그대들을 현세에서 어떻게 하실지 나는 알지 못하노라. 나는 그저 나에게 주어지는 계시를 따를 뿐이며, 그 계시에 근거하여 말하고 행동하노라. 나는 오직 그대들에게 하나님의 징벌을 명백히 경고하는 경고자일 뿐이라\"",
  46010: "그대-사도여! -는 부정하는 자들에게 말하라. “그대들은 생각해 보라: 꾸란이 하나님의 성서임에도 그대들은 꾸란을 불신하였도다. 이스라엘의 자손이었던 한 남자가 토라에 내려진 사실에 기초하여 꾸란이 하나님의 성서임을 증언하고 믿음을 가졌노라. 그럼에도 그대들은 꾸란을 믿지 않고 거만해 하였노라. 이러함에도 그대들은 부당한 자들이 아니란 말인가? 실로 하나님께서는 부당한 무리를 진리로 인도하지 않으시노라.",
  46011: "꾸란을 부정하고 사도가 가져온 메시지를 불신하는 자들은 믿는 자들에게 말하노라. \"만약 무함마드가 가져온 것이 진정 좋은 것을 위한 길잡이었다면 저 가난하고 힘없는 자들이 우리보다 먼저 그것을 차지하지 못했을 것이라\" 그들은 사도가 가져온 것으로도 인도되지 못했기에 곧 이렇게 말할 것이라. \"이것은 낡고 오래된 거짓말일 뿐이기에 우리는 이 거짓말을 따르지 않겠소\"",
  46012: "꾸란 이전에는 모범과 자비의 성서인 모세의 토라가 있노라. 그리고 아랍어로 계시된 이 꾸란은 이전의 성서들을 확증하고 있으니 이는 꾸란이, 하나님께 대등한 존재를 두고 그분을 거역함으로써 부당함을 저지르는 자들을 경고하고, 하나님과의 관계와 인간과의 관계에 최선을 다하는 자들에게 훌륭한 소식을 전하기 위함이라.",
  46013: "실로 \"우리의 주님은 하나님이시며, 우리에게 그분 이외에 주님은 없습니다\"라고 말한 후, 믿음에 굳건하고 선행에 꾸준했던 자들은 내세에 있을 일에 대해 두려워하지 않을 것이며, 그들이 현세에서 얻지 못한 것이나 그곳에 남기고 간 것에 대해 슬퍼하지 않을 것이라.",
  46014: "저들은 천국의 거주자들로 그곳에서 영원히 머물 것이니, 그들이 현세에서 실천하던 선행에 대한 보상이라.",
  46015: "하나님께서는 인간에게 명령하시길 부모님께 효도하라 하셨으니, 인간은 -샤리아 (이슬람법) 를 어기지 않는 선에서- 부모님께 살아계실 때는 물론 돌아가신 후에도 효도해야 하노라. 어머니에게는 더욱 그러하니, 어머니는 임신 중에 무거운 몸으로 힘겨운 시기를 견디었고, 출산시에는 고통스런 시간을 보냈기 때문이라. 임신 기간과 젖을 떼기 전까지의 기간은 총 삼 십 개월이라. 그리하여 그가 지력과 체력의 정점에 이르고 마흔 살에 이르렀을 때 그가 말하였노라. \"주님이시여! 저에게 영감을 불어넣으시어 제가, 당신께서 저와 부모님에게 베푸신 은총에 감사할 수 있도록 해주십시오. 또한 저에게 영감을 불어넣으시어 제가 당신께서 흡족해 하실 선행을 실천할 수 있게 하시고 저의 선행을 받아 주십시오. 그리고 저를 위해 제 후손들을 선량한 자들로 만들어 주십시오. 실로 저는 당신께 저의 죄를 참회하였고, 실로 저는 당신의 명령에 순종하는 자들 중의 하나입니다\".",
  46016: "하나님께서는 그들의 행위 중 가장 훌륭한 것을 받아주실 것이며, 그들의 악행을 덮어 주시어 그들을 질책하지 않으실 것이라. 그들은 천국의 거주자들과 함께할 것이니, 그들이 약속받은 이 약속은 반드시 실현될 진실의 약속이라.",
  46017: "(이전의 구절이 효자의 경우를 언급하며 효도의 중요성을 강조한 반면, 이 구절은 불효자의 경우를 언급하며 불효의 추악함을 경고하고 있다)  기억하라. 자신의 부모님에게 이처럼 말하는 자가 있노라. \"어머니, 아버지께 짜증이 납니다. 실로 저 이전에 많은 세대가 지나갔고 이전 사람들이 죽어나갔지만 그들 중 누구도 부활한 적이 없습니다. 그런데도 어머니, 아버지는 죽어 있을 제가 부활하여 무덤에서 나올 것이라 저에게 다짐하는 것입니까? \" 이 와중에 그의 부모님은 아들을 믿음으로 인도해 달라며 하나님께 도움을 요청하노라. \"큰일 날 소리를 하는구나. 네가 부활을 믿지 않았다면 지금이라도 믿거라. 하나님께서는 죽은 자를 되살릴 것이라 약속하셨고, 그 약속에는 의심의 여지가 없단다\" 이에 아들은 다시금 부활을 부정하며 말하더라. \"부활에 관한 이야기는 그저 옛날 사람들의 책에 나오는 설화일 뿐입니다\"",
  46018: "저들은 그들 이전에 사멸한 진 (Jinn) 과 인간으로 이루어진 불신 공동체와 함께 징벌을 받을 자들로, 실로 그들은 지옥으로 들어감으로써 자신의 영혼과 가족을 잃어버릴 자들이로다.",
  46019: "천국의 거주자와 지옥의 거주자 모두는 자신의 행위에 걸맞는 위치와 보응을 받을 것이라. 천국의 거주자는 명예롭고 높은 곳에 머물고, 지옥의 거주자는 비천하고 낮은 곳에 머무르노라. 이는 하나님께서 그들의 행위를 남김없이 보응하시기 위함이라. 실로 그들은 심판의 날 부당히 대우받지 않을 것이니, 선행을 인색하게 보상받거나 그들의 악행을 실제보다 더하여 벌받지 않을 것이라.",
  46020: "그날, 하나님을 불신하고 사도들의 메시지를 부인하던 자들은 불지옥에 놓여 징벌을 받을 것이라. 그들에게 힐책하는 목소리가 들리노라. \"너희는 현세의 삶에서 유흥에만 전념하며 쾌락을 좇았노라. 그리하여 오늘 너희는 굴욕의 벌을 받을 것이니, 너희가 거만해 하던 것에 대한 대가이며, 하나님에 대한 불신과 거역 등 너희가 저지르던 일탈 행위에 대한 대가라\"",
  46021: "그대-사도여! -는  아드 부족의 형제인 후드가 자신의 백성에게 하나님의 징벌을  경고했을 때를 기억하라. 그들은 아라비아 반도의 남부 지역인  알-아흐까프에 거주하던 자들이었노라. 선지자  후드 전후로  이미 많은  사도들이 도래한 바 있으며, 그들은 자신의 백성들에게 경고하며 말하였노라.   \"그대들은 오직 하나님 한 분만을 경배하고 그분 이외의 것들은  숭배하지 말라. 나의 백성들이여! 실로 나는 위대한 심판의 날 그대들에게 내려질 징벌이 두렵노라\"",
  46022: "후드의 백성들이 그에게 말하였노라. \"그대는 우상 숭배를 금하려고 우리에게 온 것인가? 그대는 감히 그럴 자격이 없노라. 그대의 말이 사실이라면 그대가 다짐하는 그 징벌을 우리에게 내려 보라\"",
  46023: "후드가 말하였노라. \"징벌이 언제 내려질지 나는 알지 못하며, 그것은 오직 하나님만이 아실 뿐이라. 나는 그저 하나님께서 보내신 사도로서, 그대들에게 하나님의 계시를 전달할 뿐이라. 그러나 실로 나는 그대들을 무지한 백성으로 생각하노라: 그대들이 도움이 되는 것은 버리고 해악이 되는 것은 취하기 때문이라\"",
  46024: "그들은 그렇게 징벌을 재촉했고, 막상 그 징벌이 다가왔을 때 그들은 하늘을 넓게 가로지르는 구름이 자신들이 머무는 골짜기로 다가온다고 생각하였노라. 그들이 말하였노라. “이것은 우리에게 비를 내려줄 구름이라” 후드가 그들에게 말하였노라. \"그렇지 않노라. 저것은 그대들이 생각하는 그런 구름이 아니라. 저것은 그대들이 재촉했던 징벌로, 고통스런 벌을 동반한 바람이라\"",
  46025: "바람이 하나님의 명령에 따라 자신이 스쳐간 모든 것을 파괴시키니 그들은 모두 멸망하였고, 그들이 살던 집들만이 남아, 그들이 한 때 그곳에 거주하였음을 증언하노라. 그렇게 하나님께서는 불신과 거역 행위를 지속하는 무리를 벌하시노라.",
  46026: "하나님께서는 후드의 백성에게 커다란 능력을 주었으니 그대들에게는 주지 않은 능력이라. 또한 하나님께서는 그들에게 들을 수 있는 청각과 볼 수 있는 시각과 인지할 수 있는 마음을 주셨노라. 그러나 하나님의 징벌이 도래했을 때 그들의 청각과 시각과 마음은 그들에게 그 어떤 도움도 되지 못하였으니, 그들이 계속해서 하나님의 징표를 부인했기 때문이라. 후드 (그에게 평화가 깃들기를) 는 그들에게 징벌이 도래함을 경고하였으나 그들은 그를 비웃었고, 결국 그들이 조롱하던 징벌이 그들을 에워쌌노라.",
  46027: "진실로 하나님께서는 아드 부족과 싸무드 부족과 롯의 백성과 미디안의 거주자들이 살던 마을을 파괴하셨고, 이는 그대들-메카의 거주민들이여! - 주위의 도시들이라. 하나님께서는 그들에게 다양한 논거를 보여 주신 바, 그들이 불신을 뉘우치고 하나님께로 돌아오도록 하기 위함이었노라.",
  46028: "그들은 하나님이 아닌 우상들을 신으로 삼으면서, 숭배 행위와 희생물로 그것들에 가까이 다가가길 바랐노라. 그런데도 왜 그것들은 그들을 도와주지 않는 것인가? 우상들은 그들을 도와주지 못할 뿐만 아니라, 오히려 가장 필요할 때에 그들을 내버려 둔 채 사라져 버렸도다. 우상들이 그들을 도와주고 하나님 앞에서 중재할 줄 것이라는 희망은 거짓이며, 그들이 지어낸 허상에 불과하노라.",
  46029: "그대-사도여! -는 기억하라. 하나님께서 그대에게 몇 명의 진 (Jinn) 을 보냈고 그들은 그대에게 내려진 꾸란을 경청하였노라. 그리하여 그들이 꾸란을 듣기 위해 예배 장소에 참석했을 때 그들은 서로에게 \"낭송을 들을 수 있게 조용히들 하시오\"라고 말하였노라. 그 후 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 가 낭송을 마쳤을 때 그들은 자신의 백성으로 돌아가, 꾸란을 믿지 않는 자들에게 하나님의 벌이 있을 것이라 경고하였노라.",
  46030: "그들이 말하였노라. \"우리의 백성이여. 실로 우리는 모세 이후에 내려진 성서를 들었노라. 이 성서 (꾸란) 는 이전의 성서들을 확증하면서, 우리를 진리이자 올곧은 길인 이슬람의 길로 안내해 주노라\"",
  46031: "\"우리의 백성이여. 그대들을 진리로 초대하는 무함마드의 부름에 응하고 그가 하나님의 사도임을 믿으라. 그리하면 하나님께서 그대들의 죄를 용서해 주실 것이며, 그대들이 부름에 응하지 않았을 때 받을 고통스런 벌로부터 그대들을 구해 주실 것이라\"",
  46032: "진리로 초대하는 무함마드의 부름에 응하지 않는 자는 지상에서 하나님으로부터 도망칠 수 없으며 그에게는 하나님의 벌을 막아줄 어떤 보호자도 없노라. 저들은 진리를 벗어나 분명한 방황 속에 빠져 있도다.",
  46033: "하나님께서는 (일곱) 하늘과 땅을 창조하셨고, 그분께서는 그 거대하고도 광활한 하늘과 땅을 창조하신 후에도 지치지 않으셨노라. 저 우상 숭배자들은 이러한 하나님께서 죽은 자들을 부활시키시어 그들을 심판하실 능력을 갖추신 분이심을 알지 못한단 말인가? 당연히 하나님께서는 그러한 부활의 능력을 가지신 분이라. 실제로 하나님께서는 모든 것이 가능하신 분이라.",
  46034: "심판의 날 하나님과 그분의 사도들을 불신한 자들은 불지옥에 놓여 고통받을 것이라. 그들을 힐책하는 목소리가 들리노라. \"너희가 목격하는 이 벌은 진실인가, 아니면 너희가 현세에서 말하던 것처럼 거짓인가? \" 그들이 말할 것이라. \"그렇습니다, 저희의 주님께 맹세코 이것은 진실입니다\" 이에 그들에게 목소리가 들릴 것이라. \"너희들은 벌을 맛 보라. 이것은 하나님에 대한 너희들의 불신으로 말미암은 것이라\"",
  46035: "그러니, 그대의 백성들이 거부함에 인내하라. 단호한 의지를 소유했던 사도들, 즉 노아, 아브라함, 모세, 예수 (그들에게 평화가 깃들기를) 가 그랬듯이 그대도 인내하라. 그리고 그들에게 내려질 벌을 재촉하지 말라. 그대의 백성들이 자신들에게 약속된 징벌을 보는 내세의 날, 그들은 현세에서 마치 짧은 한 순간만을 머무른 것처럼 느낄 것이니 그날에 있을 기나긴 징벌 때문이라. 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 내려진 이 꾸란은 인간과 진에게 충분하고 완전한 메시지를 전달하노라. 실로 파멸할 자는 하나님께 순종하지 않고 불신과 거역 행위로 일탈하는 무리들 뿐이라.",
  47000: "무함마드\n계시 분류: 메디나\n•    계시 목적    \n이 장은 전투에 참여하는 믿는 자들의 의지를 북돋우고 불신자들의 사기를 꺾고 있다.\n•    요약 주해",
  47001: "하나님을 불신하면서 사람들이 하나님의 종교를 믿지 못하게 방해하는 자들은 하나님께서 그들의 행위를 쓸모없게 만드실 것이라.",
  47002: "하나님을 믿고 선행을 실천하며 하나님께서 당신의 사도 무함마드에게 내리신 것-그것은 그들 주님으로부터 온 진리라-을 믿는 자들은 하나님께서 그들의 악행을 용서해 주실 것이며 그들의 현세와 내세에서의 상황을 개선시켜 주실 것이라.",
  47003: "두 부류에 이러한 보응이 주어지는 이유는 하나님을 불신하는 자들은 거짓을 따르기 때문이며, 하나님과 그분의 사도를 믿는 자들은 그들 주님으로부터의 진리를 따르기 때문이라. 그들의 노력이 다르기에 그들이 받을 보응도 다르노라. 그렇게 하나님께서는 인간들을 위해 그들의 예시를 언급하셨으니, 믿는 자들과 유사한 자라면 그들과 유사한 보상을 받을 것이며, 불신하는 자들과 유사한 자라면 그들과 유사한 벌을 받을 것이라.",
  47004: "그러니, 그대들-믿는 자들이여! -과 전쟁을 벌이는 불신자들을 만났을 때는 무기로 적군의 목을 타격하라. 그렇게 전투를 지속하고, 적군의 사상자가 증가하여 그들의 전력이 무력화되었을 때는 포로의 오랏줄을 단단히 묶으라. 체포한 포로에 관하여는 상황에 따른 선택이 가능하노라: 아무런 조건 없이 포로를 해방할 수 있으며, 몸값 등을 받은 후에 해방할 수도 있노라. 적군이 항복하거나 정전 협정으로 전쟁이 끝날 때까지 그렇게 전투를 지속하고 포로를 다루라. 믿는 자들이 이처럼 불신자들로 인해 시험을 받고, 그들간의 흥망성쇠가 반복되며, 그들 중의 일부가 다른 일부로부터 승리를 거둠은 하나님의 지혜에 기인하는 것이라. 만약 하나님께서 의지하셨다면 믿는 자들이 전투 없이도 불신자들로부터 승리를 거두게 하셨을 것이나, 하나님께서는 지하드 (물리적 분투) 를 두시어 그대들을 시험하시노라: 믿는 자들 중에 전투에 임한 자와 임하지 않는 자를 구분하시고, 불신자들을 믿는 자들로써 시험하시니, 믿는 자가 전사하면 그는 천국에 들 것이며 믿는 자를 살해한 자는 지옥에 들 것이라. 하나님의 길에서 죽음을 맞이한 자들은 그분께서 그들의 행위를 헛되게 하지 않으실 것이라.",
  47005: "하나님께서 현세에서 그들이 진리를 따르도록 성공을 주실 것이고, 그들의 상황을 개선시켜 주실 것이며",
  47006: "심판의 날 그들을 천국으로 입성케 하실 것이라. 하나님께서는 현세에서 믿는 자들에게 천국을 묘사해 주셨기에 그들은 그곳을 알고 있으며, 내세에서는 하나님께서 그들에게 천국에 있을 각자의 거주지를 알려 주실 것이라.",
  47007: "하나님을 믿고 그분께서 지정하신 법률을 실천하는 자들이여! 그대들이 하나님의 사도와 종교를 돕고 불신자들과의 전투를 치름으로써 하나님을 돕는다면 그분께서는 그대들이 그들에 대항하여 승리하도록 해주실 것이며, 전쟁터에서 그들을 맞딱뜨렸을 때 그대들의 발이 흔들리지 않도록 다잡아 주실 것이라.",
  47008: "하나님과 그분의 사도를 불신한 자들은 손실과 멸망에 직면할 것이며, 하나님께서는 그들의 행위에 어떠한 보상도 주지 않으실 것이라.",
  47009: "그들이 저러한 벌을 받는 이유는 그들이 하나님께서 사도에게 계시한 유일신 신앙의 꾸란을 혐오했기 때문이라. 이에 하나님께서는 그들의 행위를 쓸모없게 만드셨으며, 그리하여 그들은 현세와 내세에서 손실자가 될 것이라.",
  47010: "메시지를 부정하는 자들은 대지를 이동하면서 그들 이전에 있었던 불신자들이 어떠한 최후를 맞이했는지 숙고하지 않는가? 그들의 최후는 고통스런 말로였노라. 하나님께서는 그들의 거주지를 파괴하셨고, 그들과 그들 자식들의 생명과 재산 모두를 앗아가셨노라. 불신자들에게는 시대와 장소를 초월하여 그와 유사한 벌이 있을 것이라.",
  47011: "그렇게 두 부류의 보응이 다른 이유는, 하나님께서는 당신을 믿는 자들의 조력자이시나, 하나님을 불신하는 자들은 그 어떤 조력자도 없기 때문이라.",
  47012: "하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들은 하나님께서 그들을 천국에 들게 하실 것이니, 그곳의 궁궐과 나무 아래에는 강이 흐르노라. 하나님과 그분의 사도를 불신하는 자들은 현세의 욕망을 좇으며 향락을 추구하노라. 그들이 먹는 것은 마치 가축이 먹는 것과 같아서 그들의 관심사는 오직 배를 채우고 성욕을 해결하는 것 뿐이라. 그러나 심판의 날 그들이 돌아갈 거처는 다름아닌 지옥이라.",
  47013: "메카의 거주민들은 그대가 살고 있는 그곳으로부터 그대를 추방하였으나, 하나님께서는 메카보다 더 강력하고 더 많은 재산과 자식을 가졌던 이전 공동체의 마을들을 파멸시키신 바 있노라. 이는 그들이 사도들을 부정했기 때문이며, 그 누구도 하나님의 벌로부터 그들을 구해줄 수 없었노라. 이와 마찬가지로, 만약 하나님께서 메카의 거주민들에게 벌을 내리길 원하신다면 그분을 막을 자 아무도 없도다.",
  47014: "어떤 이는 자신의 주님에게서 온 확실하고 분명한 증거를 따르고 그 지식에 근거하여 하나님을 경배하노라. 다른 이는 사탄이 그의 악행을 아름답게 치장한 나머지 자신의 욕망에 따라 우상을 숭배하고 죄를 지으며 사도들을 부정하노라. 이 둘이 같을 수 있는가?",
  47015: "하나님께서 명령한 것을 지키고 그분께서 금한 것을 멀리함으로써 하나님을 경외하는 자들은 천국으로 들어갈 것을 약속받았노라. 이 천국에는, 아무리 고여 있어도 그 맛이나 향이 변하지 않는 물로 된 강들이 있고, 그 풍미가 변하지 않을 젖으로 된 강들이 있으며, 마시는 자들에게 진미가 될 술로 된 강들이 있고, 찌꺼기가 걸러진 맑은 꿀로 된 강들이 있노라. 그들에게는 천국에서 온갖 열매들이 주어질 것이며, 이에 더한 은총으로서 하나님께서는 그들을 용서하시어 그들의 죄를 질책하지 않으실 것이라. 이러한 보상을 누리는 자들이, 불지옥에 영원히 머물면서 부글거리는 뜨거운 물을 들이켜 그 뜨거움으로 인해 그들의 내장이 끊어질 자들과 서로 같을 수 있는가?",
  47016: "위선자들 중에는 그대-사도여! -를 경청하는 척 하는 자가 있도다. 그들은 들으나 받아들이지 아니하고 오히려 돌아서는 자들이라. 결국 그들은 그대가 있던 자리에서 빠져나온 뒤 무지와 거부를 드러내면서 하나님께서 지식을 주신 자들에게 말하더라. \"그가 방금 얘기하면서 뭐라고 한 것이오? \" 저들은 하나님께서 마음을 봉하셨기에 좋은 것을 받아들이지 못하는 자들이며, 자신들의 욕망을 따르기에 진리를 보지 못하는 자들이라.",
  47017: "그러나 진리로 향하는 올바른 길을 걷고 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 가 가져온 것을 믿는 자들은 그들의 주님께서 인도를 더해 주시노라. 하나님께서는 그들이 선을 얻을 수 있도록 성공을 주시고, 그들에게 영감을 불어넣어 그들이 선행을 실천함으로써 지옥으로부터 멀어지도록 하시노라.",
  47018: "그럼에도 그들은 종말의 시간이 찾아오길 고대하는 것인가? 그 시간은 그들이 모르는 사이에 갑자기 찾아올 것이라. 사도 무함마드의 출현, 달의 갈라짐 (꾸란 제 53장 1절 참조) 등 종말의 징조는 이미 도래하였도다. 실제로 종말의 시간이 시작될 때 그들은 비로소 깨닫게 될 터이나, 그 때의 깨달음은 아무런 소용이 없노라.",
  47019: "그러니 그대-사도여! -는 하나님 이외에 경배받을 존재가 없음을 확신하라. 그대의 죄에 대해 용서를 구하고, 믿는 남성들과 믿는 여성들의 죄에 대해서도 용서를 빌어주라. 하나님께서는 그대들이 낮에 벌이는 활동과 그대들이 밤에 돌아가는 거처를 알고 계시니, 그분께는 그 무엇도 감추어지지 않노라.",
  47020: "믿는 자들은 하나님께서 사도에게 전투 규정을 담고 있는 장 (章) 을 내리시길 바라며 말하였노라. \"하나님께서 전투가 언급되는 꾸란의 장 (章) 을 내려주신다면 이 얼마나 좋겠습니까\" 그리하여 하나님께서는 규정이 명확히 설명된 장을 내리셨고, 그 안에는 전투가 언급되어 있었노라. 이 때 그대-시도여! -는 마음속에 병이 있는 위선자들을 보니, 그들은 마치 죽음의 공포로 뒤덮인 자의 눈으로 그대를 바라보더라. 이에 하나님께서는 그들을 경고하심에, 전투에 대한 그들의 도주와 두려움으로 말미암아 그들에게 재앙이 가까이 다가왔도다.",
  47021: "하나님의 명령에 순종하고, 잘 알려진 훌륭한 말을 하는 것이 그들에게 더 좋은 것이라. 그 후 전투 명령이 의무화되고 그 비장함이 더해졌을 때, 만약 그들이 하나님에 대한 믿음과 순종으로 진실했더라면, 실로 그것이 그분에 대한 위선과 불복 행위보다 그들에게 더 좋았을 것이라.",
  47022: "그러니, 만일 그대들이 하나님을 위한 믿음과 순종에 등을 돌린다면 그대들은 -무지의 시대에 그랬던 것처럼- 지상에 불신과 거역 행위 등의 해악을 퍼뜨리고, 그대들의 친척 관계를 끊어버리게 될 것이라.",
  47023: "지상에 해악을 퍼뜨리고 친척 관계를 끊어버리는 자들은 하나님께서 당신의 자비를 박탈하신 자들이라. 하나님께서 그들의 귀를 멀게 하셨기에 그들은 진리를 듣지 못하고 그것을 받아들이지도 아니하며, 그들의 눈을 멀게 하셨기에 그들은 통찰의 시각으로 사물을 바라보지도 못하노라.",
  47024: "꾸란에 등을 돌리는 저들은 꾸란의 의미와 내용을 숙고하지 않는가? 만약 그들이 꾸란을 숙고했더라면 꾸란은 그들에게 좋은 것을 가르쳐주고 나쁜 것을 멀리하도록 했을 것이라. 아니면 그들의 마음이 자물쇠로 굳게 잠겨 있어 교훈이 도달하지 못하고 떠올림도 소용이 없는 것인가?",
  47025: "실로 자신들에게 명백한 증거가 도래하고 선지자의 정직성이 확연히 드러난 후에도 믿음을 저버리고 불신과 위선으로 배교한 자들이 있노라. 그들은 사탄이 그들에게 불신과 위선을 아름답게 포장하여 그 일을 쉽게 한 것이며, 그들에게 헛된 희망의 기한을 늘린 것이라.",
  47026: "그들의 방황은, 하나님께서 당신의 사도에게 내리신 계시를 혐오하는 우상 숭배자들에게 그들이 \"우리는 출전하지 않고 머뭇거리는 등 몇 가지 일로써 곧 그대들을 따르겠소\" 라고 말했기 때문이라. 하나님께서는 그들이 비밀로 하며 숨기는 것을 알고 계시니, 그분께는 그 무엇도 감추어지지 않노라. 하나님께서는 뜻하시는 대로 사도에게 그 비밀의 일부를 알려주실 것이라.",
  47027: "그러니, 죽음의 천사들이 그들을 영혼을 잡아가며, 그들의 얼굴과 볼기짝을 철퇴로 가격할 때 그들의 상태와 그들이 느낄 공포는 어떠하겠는가?",
  47028: "그들이 이러한 징벌을 받는 이유는 그들이 불신, 위선, 하나님과 사도에 반하는 대적 행위 등 하나님의 분노를 초래하는 것을 따르고, 하나님을 믿고 사도를 추종하는 등 하나님께 가까이 다가가는 행위 및 그분의 기쁨을 추구하는 일을 혐오하였기 때문이며, 이에 하나님께서 그들의 행위를 무의미한 것으로 만드셨기 때문이라.",
  47029: "마음속에 의심이 도사린 위선자들은, 하나님께서 결코 그들의 악의를 탄로하지 않으실 것이라 생각한 것인가? 실로 하나님께서는 시련으로써 그들을 시험하시어 신앙에 진실된 자와 거짓된 자를 구분하실 것이며, 그로써 믿는 자가 확연히 드러나고 위선자의 정체가 폭로될 것이라.",
  47030: "만약 하나님께서 의지하셨더라면 실로 그분께서는 그대-사도여! -에게 위선자들을 보여주셨을 것이며, 그리하여 그대는 그들의 표식으로써 정녕 그들을 알아보았을 것이라. 그대는 그들의 어조로 곧 그들을 알아볼 것이라. 하나님께서는 그대들의 행위를 알고 계시니, 그대들의 행위 중 그 무엇도 그분께는 감추어지지 않으며, 그분께서는 그대들의 행위에 기초하여 그대들을 보응하실 것이라.",
  47031: "진실로 하나님께서는 물리적 분투를 요하는 적과의 전쟁으로써 그대들-믿는 자들이여! -을 시험하실 것이라. 이를 통해 하나님께서는 그대들 중에서 당신의 길에서 전쟁에 임하는 자들과 전투 과정에서 꾸준히 인내하는 자들을 드러내실 것이며, 그대들을 시험하시어 그대들 중에서 누가 진실된 자이고 누가 거짓된 자인지를 구분하실 것이라.",
  47032: "실로 하나님과 그분의 사도를 불신하고, 하나님의 종교로 입교하지 않은 채 타인들의 입교를 가로막으며, 무함마드가 선지자임이 명백해진 이후에도 그와 대립각을 세우며 적의를 발산하는 자들이 있노라. 그들은 하나님을 조금도 해칠 수 없으며 오히려 그들은 자기 자신을 해치고 있는 것이라. 하나님께서는 그들의 행위를 무효로 만드실 것이라.",
  47033: "하나님을 믿고 이슬람법을 지키는 자들이여! 하나님과 사도께서 명령하시고 금하신 것을 지킴으로써 하나님을 따르고 사도를 따르라. 그리고 불신과 보여주기식 경배 행위 (리야) 로 그대들의 선행을 무효로 만들지 말라.",
  47034: "실로 하나님을 불신하고 하나님의 종교로 입교하지 않은 채 타인들의 입교를 가로막은 자들, 그 이후에 이러한 죄를 뉘우치지 않고 불신자로 사망한 자들은 하나님께서 그들의 죄를 덮어 주지 않으실 것이라. 오히려 하나님께서는 그들의 죄를 물으시어 그들을 지옥에 영원히 거주토록 하실 것이라.",
  47035: "그러니 그대들-믿는 자들이여! 은 적들과 대치함에 나약해지지 말고, 그대들이 승기를 잡고 있는 상황에서 그들에게 먼저 휴전을 요청하지 말라. 하나님께서는 그대들과 함께하시면서 그대들을 도우실 것이며, 그분께서는 그대들의 행위를 보상하심에 결코 인색하지 않으시노라. 오히려 하나님께서 그대들이 받을 정당한 몫에 더하여 풍성한 보상을 베푸실 것이라.",
  47036: "현세의 삶이란 그저 놀음과 오락일 뿐이라. 따라서 건전한 이성을 지닌 자는 현세를 핑계로 내세를 위한 준비를 소홀히 하지 않노라. 만일 그대들이 하나님과 그분의 사도를 믿고, 하나님께서 명령한 사항을 지키고 금하신 사항을 멀리함으로써 그분을 경외한다면 하나님께서는 그대들에게 풍성한 보상을 주실 것이며, 그대들에게 모든 재산을 바치라 요구하지 않으실 것이라. 그대들이 의무적으로 희사해야 할 것은 자카 하나일 뿐이라.",
  47037: "만일 하나님께서 그들에게 모든 재산을 희사하라 요구하시면서 그대들을 재촉하셨다면 그대들은 하나님의 길에서 내는 희사금에 인색하게 반응했을 것이며, 하나님께서는 이로써 그대들 마음 속에 있는 희사에 대한 부정적 감정을 드러내셨을 것이라. 그러나 하나님께서는 자비를 베푸시어 그대들에게 그러한 희사를 의무 사항으로 두지 않으셨노라.",
  47038: "오! 정녕 그대들은 가진 재산의 일부를 하나님의 길에서 베풀라는 요청을 받은 자들이라. 가진 재산의 전부를 쓰라는 명령이 아님에도 불구하고, 그대들 중 일부는 인색하게 굴며 베풀지 않았으며, 다른 일부는 자기 재산의 일부를 하나님의 길에서 선뜻 희사하였노라. 인색한 자는 단지 자신에게 인색한 것이니, 자신의 영혼이 하나님의 커다란 보상을 받지 못하도록 막았기 때문이라. 하나님께서는 스스로 풍족하시기에 그대들의 희사를 필요로 하지 않으시노라. 반대로 그대들이야말로 하나님이 필요한 가난한 자들이라. 만일 그대들이 이슬람을 떠나 불신으로 되돌아간다면, 하나님께서는 그대들을 파멸시키신 후 그대들 이외의 다른 백성으로 그대들의 자리를 대신하실 것이라. 그 후 이 새로운 백성은 그대들과는 달리 하나님께 순종하는 자들이 될 것이라.",
  48000: "알-파트흐 (승리)\n계시 분류: 메디나\n•    계시 목적    \n선지자와 믿는 자들은 종교를 지키기 위해 진실되게 노력하였고, 이 장은 그러한 그들에게 하나님께서 약속하신 승리를 언급하고 있다.\n•    요약 주해",
  48001: "실로 하나님께서는 후다이비야 조약을 통해 그대-사도여! -에게 명백한 승리를 부여하셨으니",
  48002: "이는 하나님께서 그대-사도여! -가 이 승리 이전에 지은 죄와 그 이후에 지을 죄를 용서하시고, 그대의 종교를 도와주심으로써 그대에게 내려질 은총을 완전히 하시며, 그대를 구부러짐이 없는 올바른 길인 이슬람으로 인도하시기 위함이라.",
  48003: "그리고 하나님께서 그대들의 적에 대항하여 그대에게 강력한 도움을 주시기 위함이니, 그 누구도 그분의 도움에 저항할 수 없노라.",
  48004: "믿는 자들의 마음속에 평온함과 확신을 내리신 분이 하나님이시니, 그들이 기존에 가졌던 믿음에 또 다른 믿음을 더하기 위함이라. (일곱) 하늘과 땅의 군대는 하나님의 소유이며 그분께서는 당신의 종복들 중에서 원하시는 자를 도우시노라. 하나님께서는 종복들에게 유용한 것이 무엇인지 가장 잘 아시는 분이며, 도움을 받을 자를 선택하심에 가장 지혜로우신 분이도다.",
  48005: "하나님께서 당신과 당신의 사도를 믿는 남성들과 믿는 여성들을 궁궐과 나무 아래에 강물이 흐르는 천국으로 들게 하시기 위함이니, 그들은 그곳에서 영원히 거주할 것이라. 그리고 하나님께서 그들을 위해 그들의 악행을 용서해 주시고 그들을 벌하시지 않기 위함이라. 천국의 입성은 그들이 원했던 것으로 그들은 이를 얻었고, 죄를 묻는 것은 그들이 원치 않았던 것으로 그들은 이를 피하였노라. 따라서 이것이야말로 하나님 보시기에 그 무엇과도 비교될 수 없는 위대한 성공이도다.",
  48006: "그리고 하나님께서 남자 위선자들과 여자 위선자들, 남자 우상 숭배자들과 여자 우상 숭배자들을 벌하시기 위함이라. 그들은 하나님께서 당신의 종교를 돕지 않으실 것이며 당신의 말씀을 드높이지 않으실 것이라며 하나님께 사악한 생각을 하는 자들이니 그 사악한 생각이 사악한 재앙이 되어 그들을 덮칠 것이라. 하나님께서 그들의 불신과 사악한 생각으로 노여워하시고, 그들로부터 당신의 자비를 박탈하셨으며, 그들에게 지옥을 준비하시어 그들이 그곳에서 영원히 머물도록 하셨으니 이 얼마나 사악한 귀착지인가!",
  48007: "(일곱) 하늘과 땅의 군대는 하나님의 소유이며 그분께서는 당신의 종복들 중에서 원하시는 자를 도우시노라. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 창조와 운명과 계획에 있어 가장 지혜로우신 분이라.",
  48008: "실로 하나님께서는 그대-선지자여! -를 사도로 보내셨으니, 그대는 심판의 날 이슬람 공동체를 위한 증인이 될 것이라. 또한 그대는 믿는 자들에게 현세에서의 승리와 내세에서의 영원한 기쁨의 소식을 알리는 전달자이며, 불신자들에게 현세에서의 패배 및 굴욕과 내세에서 그들을 기다리고 있는 고통스런 벌의 소식을 전하는 경고자라.",
  48009: "그리하여 그대들이 하나님을 믿고 그분의 사도를 믿으며 그를 공경하고 그의 위엄을 높이며, 그대들이 아침 저녁으로 하나님의 완벽함을 찬양하기 위함이라.",
  48010: "실로 리드완 맹세를 통해 메카의 우상 숭배자들과 맞서 싸우겠다고 그대-사도여! -에게 충성을 맹세한 자들은 하나님께 충성을 맹세하는 것에 다름 아니니, 그들에게 우상 숭배자들과의 전투를 명령하시고 그 전투에 보상을 주시는 분이 바로 하나님이시기 때문이라. 맹세하는 그들의 손 위에 하나님의 손이 있도다. 하나님께서는 그들을 지켜보고 계시며 그분께서는 그 무엇도 놓치지 않으시노라. 그 후 자신이 한 맹세를 깨뜨리고, 하나님의 종교를 돕겠다는 하나님과의 서약을 위반하는 자가 있다면 그 해악은 오직 자기 자신에게 돌아갈 뿐이며, 하나님께서는 그로 인해 어떤 해도 입지 않으시노라. 그러나 이슬람을 돕겠다는 하나님과의 서약을 실천한 자는 그분께서 그에게 천국이라는 위대한 보상을 주실 것이라.",
  48011: "아랍 유목민들 중에는 메카로 떠나던 그대-사도여! -와 동행하지 않고 뒤처져 남은 자들이 있었으니, 그대가 그들을 나무랄 때 그들은 말할 것이라. \"저희가 재산을 관리하고 아이들을 돌보느라 정신이 없어, 당신께서 길을 떠나실 때 함께하지 못했습니다. 그러니 하나님께 저희의 죄를 용서해 달라고 기도해 주십시오\" 그러나 저들은 마음속에 없는 내용을 입으로만 되뇌일 뿐 그들은 죄를 뉘우치지 않았노라. 그대는 그들에게 말하라. \"하나님께서 그대들에게 좋은 것을 원하시거나 그대들에게 나쁜 것을 원하실 때 그 누구도 그대들을 위해 하나님을 저지할 수 없노라. 실로 하나님께서는 그대들의 행위를 상세히 알고 계신 분으로, 그대들이 아무리 숨기려 한들 그대들의 행위는 하나님께 감추어지지 않노라”",
  48012: "\"그렇지 않노라. 그대들이 잔류한 이유는 재산과 아이들을 돌보기 위함이 아니었노라. 그대들은 사도와 그의 교우들이 모두 사망할 것이라 생각하였고 그들의 가족이 있는 메디나로 귀환하지 못할 것이라 생각하였노라. 사탄은 그러한 생각을 그대들 마음 속에 아름다운 것으로 꾸몄고, 그대들은 하나님께서 당신의 사도를 돕지 않으실 것이라는 사악한 생각을 하였노라. 그대들은 몰락하는 무리였으니, 그대들이 하나님에 관해 사악한 생각을 하였고 사도와 함께 하지 않은 채 잔류를 선택했기 때문이라\"",
  48013: "하나님과 그분의 사도를 믿지 않은 자는 불신자로서, 실로 하나님께서는 심판의 날 불신자들에게 타오르는 지옥의 불을 준비하셨고 그들은 그 안에서 고통받을 것이라.",
  48014: "(일곱) 하늘과 땅의 주권은 오직 하나님 한분께 있노라. 하나님께서는 원하시는 종복의 죄를 용서하시어 당신의 은혜로 그를 천국에 들게 하시며, 공정에 의거하여 원하시는 종복을 벌하시노라. 하나님께서는 참회하는 종복의 죄를 용서하시는 분이며 그들에게 자애로우신 분이라.",
  48015: "후다이비야 조약 이후 하나님께서는 카이바르의 전리품을 약속하셨고, 그대들-믿는 자들이여! -이 이 전리품을 취하기 위해 길을 떠날 때, 그대를 따르지 않고 잔류했던 자들은 말할 것이라. \"우리도 그대들을 따라 전리품을 챙길 수 있게 해주시오\" 하나님께서는 후다이비야 조약에 있었던 자들에게만 전리품을 약속하셨고, 그들은 하나님의 이러한 말씀을 바꾸길 원했던 것이라. 그대-사도여! -는 그들에게 말하라. \"그대들은 결코 우리와 함께 전리품을 가지러 갈 수 없노라. 하나님께서는 후다이비야에 있었던 자들에게만 전리품을 약속하셨기 때문이라\" 이에 그들은 말할 것이라. \"아니오. 하나님께서 그렇게 말씀한 것이 아니고, 그대들은 그저 우리를 시기하기 때문에 우리의 전리품 취득을 막는 것이오\" 진실은 잔류한 자들이 생각하는 것과 다르노라. 그들은 하나님의 명령과 금지를 조금 밖에 이해하지 못하며, 그리하여 그들은 하나님을 거역하는 죄를 저지르노라.",
  48016: "그대-사도여! -는 아랍 유목민들 중에서 그대와 메카로 떠나지 않고 뒤처져 있던 자들에게 말하라. \"곧 그대들은 강력한 무력을 지닌 자들과 싸우라는 부름을 받을 것이라. 그대들은 하나님의 길에서 그들과 전투하거나, 혹은 그들이 전투의 과정 없이 스스로 이슬람으로 입교할 것이라. 그리하여 만일 그대들이 전투에 임하라는 하나님의 부름을 따른다면 하나님께서는 그대들에게 훌륭한 보상으로서 천국을 주실 것이라. 그러나 만일 그대들이 이전에 하나님께 순종하지 않고 메카로 떠나길 거부했던 것처럼 이번에도 하나님의 명령에 돌아선다면 그분께서는 그대들에게 고통의 벌을 내리실 것이라\"",
  48017: "하나님의 길에서 수행하는 전투에 참석하지 않고 거주지에 잔류한 시각장애인, 다리가 불편한 자, 병자에게는 죄가 없노라. 하나님과 그분의 사도를 따르는 자는 하나님께서 그들을 천국에 들게 하실 것이니, 그곳의 궁궐과 나무 아래에는 강이 흐르노라. 그러나 하나님과 사도에 순종하지 않고 돌아서는 자는 하나님께서 그에게 고통스런 벌을 내리실 것이라.",
  48018: "진실로 하나님께서는 믿는 자들로 인해 흡족해 하셨으니, 그들이 후다이비야에 있을 때 나무 아래서 그대에게 충성을 맹세 (리드완 맹세) 했을 때라. 그리하여 하나님께서는 그들의 마음속에 있는 신앙과 진실성과 정직함을 아시어 그들의 마음에 평온함을 내리셨노라. 그리고 그에 대한 보상으로 그들에게 가까운 시일에 있을 카이바르의 승리를 주셨으니, 이는 그들이 메카로 들어가지 못한 것에 대한 갈음이었노라.",
  48019: "또한 하나님께서는 그들에게 카이바르 전투에서 발생한 풍부한 전리품으로도 보상하셨노라. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이며, 창조와 운명과 결정에 가장 지혜로우신 분이도다",
  48020: "하나님께서는 그대들-믿는 자들이여! -이 이슬람 팽창 과정에서 취득할 풍족한 전리품을 약속하셨고, 그에 앞서 카이바르 전투에서 발생한 전리품을 그대들에게 선사하셨으며, 그대들이 부재한 사이에 그대들의 가족을 해치려던 유대인들의 계략을 저지시켜 주셨노라. 이는, 전리품이 하나님께서 그대 믿는 자들을 도와주실 것이라는 약속의 징표가 되고, 하나님께서 그대들을 구부러짐이 없는 올곧은 길로 인도하시기 위함이라.",
  48021: "하나님께서는 그대들이 지금 당장은 획득할 능력이 없는 또 다른 전리품도 약속하셨으니, 그분께서는 당신의 지식과 계획으로써 그 약속을 실현시킬 능력을 갖추고 계시노라. 하나님께서는 모든 것이 가능한 분으로, 그 무엇도 그분을 저지할 수 없도다.",
  48022: "설령 하나님과 사도를 불신하는 자들이 그대들-믿는 자들이여! -과 전투를 벌이더라도 실로 그들은 패배하여 도망칠 것이라. 그 후 그들은 자신들을 보호해 줄 어떤 보호자나 그대들과의 전투를 도와줄 어떤 조력자도 찾지 못할 것이라.",
  48023: "믿는 자들이 승리하고 불신자들이 패배함은 시대와 장소를 초월한 진리라. 이것은 부정하는 저들 이전의 공동체에 발견되는 하나님의 섭리로서, 그대-사도여! -는 결코 하나님의 섭리가 변경되는 일을 발견하지 못할 것이라.",
  48024: "약 팔 십 명의 우상 숭배자들이 그대들에게 해를 끼칠 목적으로 후다이비야에 있는 그대들을 급습하였으나 하나님께서는 그대들을 위해 그들을 저지해 주셨노라. 그대들은 그들을 포로로 체포하였음에도 그들을 살해하거나 해악을 끼치지 않았고, 오히려 그들을 해방시켜 주었노라. 실로 하나님께서는 그대들이 행하는 것을 지켜보고 계시는 분이니, 그대들의 행위 중 그 어떤 것도 그분께는 감추어지지 않노라.",
  48025: "하나님과 사도를 불신하고, 그대들이 하람 성원으로 들어가지 못하도록 가로막으며, 순례를 위한 희생 동물인 '하디'를 멈추어 그것이 희생의 장소인 하람 구역으로 이르지 못하게 가로막은 자들이 그들이라. 하나님께서는 그대들에게 메카 입성을 허락하시어, 원하시는 자 (예를 들어 메카의 신앙인들) 를 당신의 자비 속에 들게 하셨을 수도 있으나, 메카에는 그대들이 신앙인임을 알지 못하는 남성들과 믿는 여성들이 있노라. 만약 그대들이 불신자들과의 전쟁 중에 그들을 살해했다면 그대들은 알지도 못한 채 죄와 배상금을 짊어지게 되었을 것이라. 만약 메카에서 믿는 자들과 불신자들이 확연히 구분되었더라면 하나님께서는 당신과 당신의 사도를 불신하는 자들에게 고통스런 벌을 내리셨을 것이라.",
  48026: "하나님과 사도를 불신한 자들이 자신의 마음속에 거만함을 불태웠을 때를 기억하라. 이는 무지 시대의 거만함이며 욕망에 따른 감정으로, 진리의 실현과는 무관한 정서라. 그리하여 그들은 후다이비야 조약이 있었던 그 해에 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 의 메카 출입을 거부하였고, 그러함은 무함마드가 그들의 메카를 지배할까 봐 우려했기 때문이라. 그 후 하나님께서는 친히 당신의 사도와 믿는 자들에게 고요함을 내려 보내셨고, 그로써 그들은 우상 숭배자들의 사악한 행동에 분노로 대응하지 않았노라. 하나님께서는 그들에게 경외심의 말씀인 '라 일라하 일랄라' (하나님 이외에는 경배받을 존재가 없다, 샤하다) 를 심어주셨고 그 내용을 실천할 수 있도록 하셨노라. 실로 그들은 샤하다의 말씀에 관하여 다른 이들보다 더 많은 권리를 지니며 그 내용을 실천할 충분한 자격을 갖춘 자들로서, 하나님께서는 그들의 마음속에 있는 선 (善) 을 잘 알고 계시노라. 하나님께서는 모든 것을 알고 계신 분이시니, 그분께는 그 무엇도 감추어지지 않노라.",
  48027: "하나님의 사도는 길몽을 꾸셨고 그 내용을 교우들에게 알려주었노라. 그리고 하나님께서는 그 꿈을 실현시키 주셨으니, 꿈에서 사도와 그의 교우들은 적으로부터의 위협 없이 안전하게 하람 성원으로 들어가는데, 순례 중임을 드러내며 머리를 삭발하거나 짧게 깎고 있었노라. 그렇게 하나님께서는 그대들-믿는 자들이여! -에게 좋은 것이 무엇인지 알고 계셨으나, 그대들은 그것을 알지 못하고 있었노라. 그리하여 하나님께서는 당장 그 해에 메카로 들어가는 꿈을 실현시켜 주는 대신, 그대들이 후다이비야 조약을 이루고, 그 조약에 참석했던 신앙인들이 얼마 후에 있을 카이바르 전투에서 가까운 승리를 거두도록 하셨노라.",
  48028: "하나님께서는 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 명백한 증거와 진리의 종교인 이슬람을 주시어 그를 당신의 사도로 보내셨고, 그리하여 이슬람이 그 모든 종교 위에 있도록 하셨노라. 이 사실은 하나님께서 증언하시며, 증언자는 하나님만으로 충분하노라.",
  48029: "무함마드는 하나님의 사도라. 무함마드와 함께 있는 교우들 (싸하바) 은 전쟁을 걸어오는 불신자들에게는 엄격하고, 그들 사이에서는 자애로우니 서로를 자상히 대하고 사랑하노라. 그대가 그들을 살펴본다면 그들은 하나님을 위해 허리를 숙여 절하거나 (루쿠으) 엎드리며 절하는 (수주드) 모습을 볼 것이라. 그렇게 그들은 하나님께서 자신들의 죄를 용서해 주시고 풍성한 보상을 베푸시기를, 그리고 그분께서 자신들을 흡족히 여기시기를 희망하는 것이라. 그들의 징표는 부복의 자국을 머금은 그들의 얼굴로서, 그들의 올바른 품행과 얼굴에서 뿜어 나오는 예배의 후광이 그것이라. 이것은 모세가 받은 토라에 있는 그들의 모습이라. 한편 예수가 받은 복음에 있는 그들의 묘사는, 그들이 서로를 돕고 성장해 나감이 마치 저의 싹을 틔운 농작물과 같노라. 그 싹이 강해지고 야문 뒤 줄기가 쭉쭉 뻗어나가니, 농부는 이처럼 활기차게 성장해 나가는 식물의 모습에 흐뭇해 하더라. 그러나 점점 강해지고 견고해지며 번성하는 교우들의 모습에 불신자들은 분노하노라. 하나님께서는 교우들 중에서 당신을 믿고 선행을 실천하는 자들에게 그들의 죄를 용서해 주시고 그 죄로 그들을 질책하지 않으심을 약속하셨고, 그들에게 천국이라는 위대한 보상을 선사할 것임을 약속하셨노라.",
  49000: "알-후주라트 (규방)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 이슬람 공동체가 갖추어야 할 훌륭한 품성에 대해 가르치고 있으며, 올바르지 못한 품성에 대해서는 경고의 메시지를 전하고 있다.\n•    요약 주해",
  49001: "하나님을 믿고 그분의 법률을 따르는 자들이여! 말이나 행동으로써 하나님과 그분의 사도에 앞서 나아가지 말고, 하나님께서 명령하는 것을 지키고 그분께서 금한 것을 멀리함으로써 하나님을 두려워하라. 실로 하나님께서는 종복들이 하는 말을 들으시는 분이시며 그들이 실천하는 행위를 알고 계신 분이시니 그것으로써 그들을 심판하실 것이라.",
  49002: "하나님을 믿고 그분의 법률을 따르는 자들이여! 하나님의 사도에 대한 예의를 지키라: 그와 말을 할 때는 그의 목소리보다 더 높은 목소리로 말하지 말라. 또한, 그대들은 이름으로써 서로를 부르나, 그를 부를 때는 그의 이름이 아닌 선지자나 사도의 명칭으로 부르라. 그대들이 그에 대한 예의를 지키지 않을 경우 그대들이 느끼지 못하는 사이에 그대들의 선행이 무효화 되어 버릴 수도 있는 것이라.",
  49003: "실로 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 앞에서 자신의 목소리를 낮추는 자들이 있더라. 그들은, 하나님께서 그들이 경외심을 가지도록 그들의 마음을 정제하고 깨끗이 해주신 자들이라. 그들이 저지른 죄는 질책받지 않고 용서될 것이며, 그들이 실천한 선행은 심판의 날 천국이라는 위대한 장소로 보답받을 것이라.",
  49004: "실로 그대 - 사도여! - 의 아내들이 거처하던 안방의 뒤쪽에서 그대를 부르던 아랍인들은 대부분이 이성을 쓸 줄 모르더라.",
  49005: "아내들이 거주하던 안방의 뒤쪽에서 그대 - 사도여! - 를 큰 소리로 부르던 저들이 만약, 그대가 방에서 걸어나올 때까지 기다렸다면, 그리하여 그대와 조용한 목소리로 대화하였다면, 그것이야말로 선지자의 명예에 걸맞는 더 적절한 행실이었을 것이라. 하나님께서는 참회하는 종복들과 그들의 무지를 너그러이 용서하시는 분이시며 그들에게 자애로우신 분이라.",
  49006: "하나님을 믿고 그분의 법률을 따르는 자들이여! 품행이 훌륭하지 못한 자가 한 무리에 대한 정보를 알려 왔을 때 그대들은 곧바로 받아들이지 말고 그 정보의 정확성에 대해 한번 더 확인하라. 확인 절차도 없이 주어진 정보에 기초하여 한 무리를 응대할 경우, 추후에 그 정보가 잘못되었음을 알게 되어, 그들에 관한 무지한 행위로 인해 그대들이 후회할 수도 있기 때문이라.",
  49007: "그대들 - 믿는 자들이여! - 중에는 하나님의 계시를 받고 있는 사도가 있음을 알라. 그러니 그대들은 거짓말에 유의하라; 만약 그대들이 거짓말을 한다면 하나님께서는 사도에게 계시를 내리시어 그 사실을 알려 주실 것이라. 사도는 그대들에게 무엇이 좋은 것인지 가장 잘 알고 있노라. 만약 그가 그대들이 제안한 내용의 대부분을 따랐더라면 실로 그대들은 고초를 겪었을 것이며 이것은 사도가 바라지 않던 결과라. 그러나 하나님께서는 그대들이 믿음을 사랑하도록 하시고 그대들 마음속에 믿음을 아름답게 두시어 결국 그대들이 믿는 자들이 되도록 은혜를 베푸셨노라. 또한 하나나님께서는 그대들이 그분에 대한 불신과 거역 행위와 불복 행위를 혐오하도록 하셨노라. 이러한 속성을 지닌 자들이야말로 올바른 길로 들어선 자들이라.",
  49008: "그대들의 마음에 심어진 선(善)에 대한 사랑과 악에 대한 혐오의 감정은 하나님께서 그대들에게 베풀어 주신 그분의 은혜이자 은총이라. 하나님께서는 그분께 감사하는 자가 누군지 알고 계시어 그에게 성공을 주시며, 지혜로우신 분이기에 모든 일을 가장 적합하게 처리하시노라.",
  49009: "믿는 자들 중의 두 무리가 서로 싸우거든 그대들 - 믿는 자들이여! - 은 그들을 중재하여, 하나님의 법률이 그들을 판결토록 하라. 그러나 그들 중 한 무리가 중재를 거부하고 적대적으로 행동한다면 그대들은 그들이 하나님의 판결로 회귀할 때까지 그들과 싸우라. 그리하여 그 무리가 하나님의 판결을 받아들이겠다고 할 때 그대들은 그들 사이를 공평히 중재하고 판결을 내릴 때는 공정을 기하라. 실로 하나님께서는 판결시 공정을 기하는 자들을 사랑하시노라.",
  49010: "신앙인들은 실로 이슬람으로 하나 된 형제들이라. 그러니 그대들 - 신앙인들이여! - 은 다투고 있는 두 형제 사이를 중재하라. 그리고 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금지하신 것을 멀리함으로써 하나님을 경외하라. 그리할 때 그대들은 자비를 받게 될 것이라.",
  49011: "하나님을 믿고 그분의 법률을 따르는 자들이여! 그대들 중의 한 무리가 다른 무리를 천시하지 않도록 하라: 천시받는 자들이 하나님 보시기에 천시하는 자들보다 더 훌륭할 지도 모를 일이며, 중요한 것은 그대들의 판단이 아닌 하나님의 판단이라. 여성들 역시도 다른 여성들을 천시하지 않도록 하라: 천시받는 여성들이 하나님 보시기에 천시하는 여성들보다 더 훌륭할 지도 모를 일이라. 그리고 그대들의 형제들을 흉보지 말라, 그것은 곧 그대들 자신을 흉보는 것과 마찬가지라. 일부 메디나 토박이 거주민들은 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 가 도래하기 전에 서로를 나쁜 별명들로 부르곤 하였지만 이제는 그러지 말라. 그러한 행위를 그만두지 않는 자는 곧 거역하는 자이니, 믿음을 가진 이후에도 일탈 행위를 지속함은 참으로 사악한 속성이라. 이러한 죄스런 행위에 대해 참회하지 않는 자들은 실로 자신을 부당히 대우하는 자들이니, 죄를 저지름으로써 자신들을 파멸로 인도하기 때문이라.",
  49012: "하나님을 믿고 그분의 법률을 따르는 자들이여! 정당한 이유나 충분한 근거 없이 추측하지 말라. 실로 무리한 추측은 죄가 되기도 하노라. 또한 그대들은 믿는 자들의 나쁜 모습을 찾아내기 위해 몰래 감시하지 말고, 당사자가 없는 자리에서 그를 험담하지 말라. 형제에 대한 험담은 마치 죽은 그의 시체를 먹는 것과 같으니, 그 누가 이를 좋아하겠는가? 죽은 자의 살코기 먹기를 혐오하듯이 그대들은 험담을 혐오하라. 그리고 그대들은 하나님께서 명령한 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 두려워하라. 실로 하나님께서는 참회하는 종복을 받아 주시고 그에게 자애로우신 분이라.",
  49013: "사람들이여! 실로 하나님께서는 그대들의 아버지인 아담과 그대들의 어머니인 하와 (이브) 를 통해 그대들을 창조하셨노라. 이처럼 그대들의 출신은 하나이기에, 출신 가문을 내세우며 잘난 체하지 말라. 그 후 하나님께서는 그대들 사이에 다양한 민족과 부족을 두셨으니 이는 서로를 알기 위함이며, 인종을 근거로 으스대기 위함이 아니라. 실로 하나님께 있어 가장 명예로운 자는 그분을 가장 많이 두려워하는 자로서, 오직 경외심만이 구분의 기준이 되노라. 실로 하나님께는 그 무엇도 감추어질 수 없으니, 그분께서는 그대들의 상태를 잘 알고 계신 분이며 그대들 중 누가 뛰어나고 부족한지를 소상히 파악하고 계신 분이라.",
  49014: "유목민들 중의 일부가 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 를 찾아 와서 \"저희는 하나님과 그분의 사도를 믿습니다”라고 말하였도다. 그대 - 사도여! - 는 그들에게 말하라. “그대들은 아직 진정으로 믿은 것이 아니라. 그러니 “순종하였습니다”라고 말하라. 아직 그대들의 마음속에는 진실된 믿음이 자리 잡지 못하였으나, 조만간 그렇게 되기를 바라노라. 그대들 - 유목민들이여! - 이 하나님과 그분의 사도를 따라 믿음을 가지고 선행을 실천하면서 악행을 멀리한다면 하나님께서는 그대들이 받을 보상 그 무엇도 감소시키지 않으실 것이라. 실로 하나님께서는 참회하는 종복들을 너그러이 용서하시는 분이시며 그들에게 자애로우신 분이라”",
  49015: "진정한 신앙인들이란 하나님과 그분의 사도를 믿고, 그 후 믿음에 관한 어떠한 의심도 하지 않으며, 하나님의 길에서 아낌없이 재산과 생명을 바쳐 분투한 자들이라. 이들이야말로 믿음에 있어 진실된 자들이라.",
  49016: "그대 - 사도여! - 는 말하라. “하나님께서는 (일곱) 하늘에 있는 것과 대지에 있는 것을 알고 계신 분인데도, 그대들은 하나님께 그대들이 믿는 종교가 무엇인지를 설명하려는 것인가? 하나님께서는 모든 것을 알고 계신 분이시기에 그분께는 그 무엇도 감추어지지 않노라. 그러니 굳이 그분께 그대들의 종교가 무엇인지 알리려 할 필요는 없노라”",
  49017: "저 유목민들은 자신들이 이슬람을 받아들였음을 그대 - 사도여! - 에게 자랑하더라. 그대는 그들에게 말하라. “그대들이 하나님의 종교로 입교했음을 나에게 자랑하지 말지니, 이슬람의 효용은 그대들 자신에게 돌아가는 것이라. 이슬람으로 입교하였다는 그대들의 주장이 진실된 것이라면, 그대들이 믿음을 가질 수 있었던 이유는 오직 하나님께서 은혜를 베푸시어 그대들을 인도해 주셨기 때문이라”",
  49018: "실로 하나님께서는 (일곱) 하늘과 땅의 보이지 않는 것을 알고 계신 분이기에 그 무엇도 그분께 감추어지는 일이 없노라. 또한 그분께서는 그대들이 행하는 것을 지켜보고 계시는 분이니 그 어떤 행위도 그분께는 감추어지지 않으며, 그분께서는 그대들의 선행과 악행을 빠짐없이 보상하실 것이라.",
  50000: "까프\n계시 분류: 메카\n•    계시 목적    \n이 장은 방심하고 있던 마음을 일깨워, 부활과 보상 및 그에 관한 명백한 증거들을 인지하도록 하고 있다.\n•    요약 주해",
  50001: "(까프.)(이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다) 하나님께서는 심오한 의미와 풍성한 축복이 담긴 명예로운 꾸란을 두고 맹세하시니 그대들은 부활의 날에 다시 깨어나 심판과 보상을 받게 될 것이라.",
  50002: "그들이 거부함은 그대가 거짓말을 한다는 그들의 추측 때문이 아니라, 경고자로서의 사도가 천사가 아닌 인간이라는 사실에 그들은 놀라워하는 것이라. 그들이 놀라 말하였노라. \"우리에게 도래한 사도가 인간이라니 참 신기한 일이라! \"",
  50003: "“우리가 죽으면 흙이 되는데도 다시 부활한단 말인가?! 다 스러진 우리 몸에 다시 삶이 부여된다니 이러한 부활은 말도 안 되는 동떨어진 얘기라”",
  50004: "하나님께서는 대지가 죽은 인간의 시체를 어떻게 분해시키는지 알고 계시며 그 중 어떤 것도 그분께 감추어지지 않노라. 또한 하나님께는 성서가 있으니 그 안에는 인간이 살아가면서, 그리고 죽은 후에 맞이할 모든 운명이 기록되어 있노라.",
  50005: "그러나 사도가 꾸란을 가져왔을 때 저 우상 숭배자들은 꾸란을 부정하면서 그에 관해 일관되지 못하고 혼란스런 입장을 보이더라.",
  50006: "(부활을 부정하는 우상숭배자들의 모습이 언급된 후 여기서부터는 부활을 증명하는 다양한 증거들이 제시되고 있다)  부활을 부인하는 자들은 자신들 위에 떠있는 하늘을 보지 않는가? 하나님께서 어떻게 하늘을 창조하시고, 그 안에 별을 두시어 하늘을 어떻게 갈라짐 없이 아름답게 꾸미셨는지 숙고해 보라. 하늘을 창조하신 하나님이시기에 죽은 자를 부활시키는 일도 그분께는 쉬운 일이라.",
  50007: "하나님께서는 대지를 펼치시어 그 위에 인간이 안전하게 거주하도록 하셨고, 대지에 단단한 산을 심어 두시어 대지가 흔들리지 않도록 하셨으며, 그곳에 모든 종류의 아름다운 목초를 자라나게 하셨노라.",
  50008: "하나님께서 이 모두를 창조하심은 하나님께 순종하며 돌아오는 모든 종복에게 당신의 징표를 보여주시고 상기시켜 주시기 위함이라.",
  50009: "그리고 하나님께서는 하늘에서 축복 가득한 비를 내리시어 그 비로써 정원을 자라나게 하시고, 또한 곡물도 내시니 그대들은 그것을 수확하더라.",
  50010: "또한 하나님께서는 높다랗게 솟은 야자수를 자라나게 하시니, 이 야자수에는 층층이 겹친 꽃밥이 있도다.",
  50011: "하나님께서 자라하게 하시는 이 모든 것들은 인간들의 양식을 위해서라. 그리고 하나님께서는 척박하던 불모의 대지에 비를 적시어 목초를 자라나게 하시니, 그렇게 그분께서는 죽어 있던 자들을 살리어 부활케 하시노라.",
  50012: "그대 - 사도여! - 의 사도직을 부인하는 저들 이전에도 사람들은 사도들을 부정하였으니, 노아 (누흐) 시대의 사람들과 우물의 동료들이 그러하였고 싸무드 부족도 그러하였노라.",
  50013: "아드 부족과 파라오와 롯 (루뜨) 시대의 사람들이 사도들을 부정하였으며",
  50014: "슈아입 시대의 사람들인 밀림의 거주자들과 예맨 왕 툽바의 백성들도 사도들을 부정하였노라. 그들 모두는 하나님께서 보내신 그분의 사도들을 부정하였고 이에 하나님께서는 그들에게 약속하신 징벌을 실현시키셨노라.",
  50015: "하나님께서 무에서 유로 그대를 창조하지 못하시고, 따라서 그대들을 부활시키지도 못하신단 말인가? 그렇지 않노라. 그러나 그들은, 하나님께서 그들을 창조하신 후 또 다른 창조 (부활) 를 하실 것임에 의혹을 품고 있더라.",
  50016: "진실로 인간을 창조하신 분이 하나님이시니 그분께서는 인간의 마음속에 일어나는 의식적, 무의식적 생각 모두를 알고 계시노라. 하나님께서는 당신의 지식으로써 인간에게 가까이 계시니, 목정맥의 혈관보다도 그에게 더 가까이 계시노라.",
  50017: "두 명의 천사가 인간의 행위를 받아서 기록하니, 그 중의 하나는 오른쪽에 앉아 있고 다른 하나는 왼쪽에 앉아 있도다.",
  50018: "인간이 어떤 말을 하든 그 옆에는 그의 말을 감시하는 천사가 있노라.",
  50019: "그 누구도 피해갈 수 없는 죽음의 고통이 찾아왔으니 그것은 그대 - 부주의한 인간이여! - 가 도망치려 애쓰던 것이라.",
  50020: "천사가 두 번째로 나팔을 불 것이며, 실로 이 때는 부활의 날로서 불신자들과 거역자들에게 보내진 경고가 실현될 날이라.",
  50021: "모든 영혼이 천사와 함께 (심판의 장소에) 다다르니, 영혼을 몰아가는 천사와 그의 행위를 증언할 천사와 함께 도착하였노라.",
  50022: "도착한 영혼에게 목소리가 들리니 \"실로 현세에서 너는 욕망과 쾌락에 속아 넘어가 이날에 관해 까맣게 잊고 있었노라. 이제 내가 너에게서 방심의 덮개를 걷어냈으니, 이날의 징벌과 고통을 보지 못하던 너의 시각은 이제 예리해졌도다\"",
  50023: "그와 함께 하며 행위를 기록하던 천사가 (하나님께) 말하였노라. \"이것이 제가 기록한 그의 행위로, 증가나 감소 없이 준비하였습니다\"",
  50024: "하나님께서, 몰아가는 천사와 증언하는 천사에게 말씀하시노라. \"고집을 부리며 진리를 불신하던 자들 모두를 지옥 속으로 내던지라.",
  50025: "그는 내가 의무화한 권리를 저해하고, 내가 지정한 경계를 넘어서며, 나의 약속과 경고에 의심을 품는 자라.",
  50026: "그는 하나님 이외의 다른 신을 두어 하나님과 함께 그 신을 숭배하던 자였으니, 그를 혹독한 벌 속으로 내던지라”",
  50027: "그와 함께하던 사탄이 변명하며 말하였노라. \"저희의 주님이시여! 저는 그를 방황시킨 적이 없습니다. 그러나 그 스스로가 진리를 벗어나 머나먼 방황 속에 빠져든 것입니다\"",
  50028: "하나님께서 말씀하시노라. \"그대들은 나 앞에서 논쟁하지 말라, 쓸모 없는 논쟁일 뿐이라. 나는 현세에서 사도들을 보내어, 나를 불신하고 거역하는 자가 맞이할 결말이 무엇인지 그대들에게 이미 경고한 바 있노라.",
  50029: "나의 말씀은 변하지 않으니 그 무엇으로도 대체되지 않으며 나의 약속은 반드시 실현되노라. 나는 부당히 인간의 선행을 줄여 혹은 악행을 늘려 기록하지 않으며, 있는 그대로의 행위에 기초하여 그에게 보상하노라”",
  50030: "그날 하나님께서 지옥에게 말씀하실 것이니 \"불신자들과 거역자들이 그대에게로 내던져졌고 이제 그대는 그들로 인해 가득 찬 것인가? \" 지옥은 자신의 주님이신 하나님께 \"더 있습니까?\" 라고 답하며 더 많이 채워지길 바라더라.",
  50031: "(하나님께서는 이전 구절을 통해 불신자들을 혹독히 경고하셨고, 지금부터는 그분께서 믿는 자들을 위해 준비한 것들이 무엇인지를 언급하고 계신다. )  하나님께서 명하신 것을 지키고 그분께서 금한 것을 멀리함으로써 하나님을 경외하던 자들에게 천국이 가까오니, 그들이 그 안에 있는 기쁨을 목격할 정도로 천국은 멀지 않은 곳에 놓이게 되노라.",
  50032: "그들에게 목소리가 들리니 \"이것은 하나님께서 그대들을 위해 약속하신 것으로, 자주 참회하면서 하나님께 돌아가는 자들과 그분께서 명령하신 사항을 성실히 지키는 자들 모두를 위한 것이라.",
  50033: "그는 아무도 없는 곳에서도 하나님을 두려워하였고, (심판의 날) 하나님을 뵐 때 많이 참회하면서 깨끗한 마음으로 그분과 만나는 자라.",
  50034: "그대들은 두려움 없이 안전하게 천국으로 들어가라\" 진정 이날은 끝이 없는 영원의 날이라.",
  50035: "그들은 그곳에서 끊이지 않는 기쁨을 누릴 것이라. 그리고 하나님께서는 그보다 더한 기쁨을 가지고 계시니, 눈이 한번도 보지 못하고 귀가 결코 듣지 못한 상상 이상의 기쁨으로서  그 중의 하나는 하나님을 목격하는 기쁨이라.",
  50036: "메카의 우상 숭배자들은 부활을 부정하지만 하나님께서는 그들 이전에 수많은 세대를 멸망시켰노라. 그들은 메카의 우상 숭배자들보다 더 막강한 힘을 가진 자들이었음에도 결국 그들에게 하나님의 벌이 찾아왔고, 그들은 도망칠 곳을 찾아 대지를 헤매었으나 그 어떤 피신처도 발견할 수 없었노라.",
  50037: "실로 이전 공동체의 멸망에 관한 저 이야기 안에는 이성적으로 생각하는 자와 조용히 경청하며 주의를 기울이는 자를 위한 일깨움이 있노라.",
  50038: "진실로 하나님께서는 (일곱) 하늘과 땅과 그 사이에 존재하는 모든 것을 육일 만에 창조하셨으며, 그분께는 -유대인들의 주장과는 달리- 그 어떤 피로도 스치지 않았노라.",
  50039: "그러니 그대 - 사도여! - 는 유대인과 그 이외의 자들이 하는 말에 인내하고, 일출 전에 그리고 일몰 전에 그대 주님을 찬미하며 파즈르 예배와 아쓰르 예배를 드리라.",
  50040: "그리고 밤중에 예배를 드리고, 예배를 드린 후에도 하나님을 찬양하라.",
  50041: "그대 -사도여! - 는 경청하라: 심판의 날, 두 번째 나팔을 불어 심판의 날이 시작되었음을 알리는 천사가 가까운 곳에서 사람들을 부를 것이라.",
  50042: "그날 모든 피조물은 의심의 여지 없이 굉음을 들을 것이니, 진정 이날은 죽은 자들이 부활하여 무덤 밖으로 걸어나올 부활의 날이라. 이날, 그들은 심판을 받을 것이라.",
  50043: "진실로 하나님께서는 살리시고 죽이시는 분으로서, 그분만이 생명을 부여하시고 그분만이 죽음을 지정하시노라. 부활의 날 심판과 보상을 위해 인간이 돌아갈 곳은 오직 하나님 한 분 뿐이라.",
  50044: "그날 대지가 그들을 내버려둔 채 갈라지니 그들이 (무덤에서) 빠른 속도로 걸어 나오더라. 이렇게 인간을 소집함은 실로 하나님께는 쉬운 일이라.",
  50045: "하나님께서는 부정하는 저들이 내뱉는 말을 누구보다 더 잘 알고 계시며, 그대 -사도여! - 는 그들을 강제로 믿게 하는 자가 아니라; 그대는 그저 하나님께서 명령하신 대로 그분의 메시지를 전하는 자일 뿐이라. 그러니 그대는 하나님께서 불신자들과 거역자들에게 내리신 경고를 두려워하는 자들을 꾸란으로써 상기시켜 주라; 오직 두려워하는 자들만이 상기받을 때 교훈을 얻으며 떠올리노라.",
  51000: "앗-다리야트 (흩뜨리는 바람)\n계시 분류: 메카\n•    계시 목적    \n이 장은 피조물의 양식이 하나님으로부터 비롯됨을 알려줌으로써 그들이 그분께 피난처를 구하고 그분께 복종해야 함을 말하고 있다.\n•    요약 주해",
  51001: "하나님께서는 세찬 풍진을 일으키는 바람을 두고 맹세하시고",
  51002: "많은 비를 머금은 구름을 두고 맹세하시며",
  51003: "어려움 없이 한가히 바다를 항해하는 선박을 두고 맹세하시며",
  51004: "하나님의 명령으로 인간의 일을 분배하는 천사를 두고 맹세하시니",
  51005: "진실로 그대들의 주님이신 하나님께서 약속하신 심판과 보상은 의심할 여지 없는 진리이며",
  51006: "진실로 부활의 날, 인간에 대한 심판은 이루어질 것이니 결코 피할 수가 없노라.",
  51007: "하나님께서는 별들이 지나가는 자리를 지닌, 아름답게 창조된 하늘을 두고 맹세하시니",
  51008: "진실로 그대들 - 메카 거주민들이여! - 은 논리 없는 모순된 말에서 헤어나오지 못하고 있노라. 그대들은 어떨 때는 꾸란이 주술이라고 말하다가 또 어떨 때는 시(詩)라고 말하고, 무함마드는 주술사라고 말하면서 또 다른 때는 그가 시인이라고 말하였노라.",
  51009: "하나님께서 보시기에, 꾸란과 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 에 대한 믿음을 저버릴 자는 분명 그렇게 할 것이며, 그는 믿지 아니하고 인도받지도 못할 것이라.",
  51010: "꾸란과 선지자에 관해 거짓말을 일삼는 저들은 저주받았노라.",
  51011: "그들은 깊은 무지의 상태에 빠져, 내세에 대해 무관심하며 부주의한 자들로",
  51012: "\"심판의 날은 언제 도래할 것인가? ”라고 묻지만 정작 그들은 그날을 위해 아무 것도 준비하지 않더라.",
  51013: "하나님께서 그들의 질문에 답하시니 \"그날은 그들이 지옥 불로 고통받을 날이라\"",
  51014: "그날 목소리가 들릴 것이라. “그대들의 고통을 맛 보라. 이것은 그대들이 경고를 받을 때마다 빈정거리며 재촉하던 것이라\"",
  51015: "실로 하나님께서 명령하신 것을 실천하고 그분께서 금하신 것을 멀리함으로써 하나님을 경배하던 자들은 심판의 날 천국에 들어가, 흐르는 샘물을 가까이에 둘 것이라.",
  51016: "그들은 그들의 주님께서 선사해 주시는 보상을 받을 것이니, 실로 그들은 이 보상을 받기 이전에 현세에서 최선을 다하는 자들이었노라.",
  51017: "그들은 잠을 조금만 자면서 밤중에 예배를 드렸고",
  51018: "새벽녘에는 하나님께 죄를 용서해 달라고 기도했으며",
  51019: "가난하여 사람들에게 구걸하는 자와, 가진 양식이 없어도 구걸하지 않는 자를 위해 자신의 재산 일부를 자발적으로 희사하였도다.",
  51020: "그리고 지구상에 존재하는 산, 바다, 강, 나무, 식물, 동물 등에는 창조주이자 조물주이신 하나님의 전능하심을 드러내는 징표가 있으며",
  51021: "그대들 -인간들이여! - 자신에게도 하나님의 징표가 있도다. 그러니 그대들은 통찰하여 교훈을 얻지 않겠는가?",
  51022: "그리고 하늘에는 그대들의 현세와 내세의 양식이 있으며 그대들이 약속받은 좋은 것과 나쁜 것이 있노라.",
  51023: "그러니 하늘과 땅의 주님께 맹세코 부활은 의심할 수 없는 진실이니, 마치 그대들이 말을 함에 의심히지 않는 것처럼 그렇게 그것은 진실이라.",
  51024: "그대 - 사도여! -에게 아브라함 (이브라힘) 을 방문한 천사들의 이야기가 전해졌는가? 아브라함은 그들을 손님으로서 명예롭게 대하였노라.",
  51025: "천사들이 아브라함을 방문하며 \"평안하시오”라고 말하니 이에 아브라함이 \"평안하시오”라고 대답하였고, 그가 속으로 말하였노라. “이들은 우리가 알지 못하는 처음 보는 얼굴들이구나\"",
  51026: "그리하여 그는 그들 몰래 서둘러 자신의 가족에게로 돌아가, 가족에게 있던 살찐 송아지를 가져 왔으니 아브라함은 그 손님들이 인간이라 생각했기 때문이라.",
  51027: "그리하여 그는 손님들에게 송아지 요리를 가까이 밀어주며 친절히 말하였노라. “차려진 음식을 드시지 않겠습니까? \"",
  51028: "그들이 음식을 먹지 않자 그는 두려운 느낌이 들었고, 이를 알아챈 그들은 그를 진정시키며 말하였노라. “두려워 마오. 우리는 하나님께서 보내신 사도라오\". 그 후 그들은 그에게, 장차 깊은 지식을 가지게 될 남자아이가 태어날 것이라 하였으니 그의 이름은 이삭 (이스학, 그에게 평화가 깃들기를) 이라.",
  51029: "아브라함의 아내가 이 기쁜 소식을 듣자 환희의 비명을 지르며 다가왔고, 그녀는 자신의 얼굴을 치면서 놀라워하며 말하였노라. “노파에다 불임인 제가 아이를 가진다니요! \"",
  51030: "천사들이 그녀에게 말하였노라. “우리가 그대에게 알려준 것은 그대의 주님께서 말씀하신 내용이며, 그 누구도 그분께서 하신 말씀을 되돌릴 수 없노라. 실로 하나님께서는 창조와 운명의 지정에 가장 지혜로우신 분이며 피조물이 필요한 것이 무엇인지를 가장 잘 알고 계신 분이라\"",
  51031: "아브라함 (이브라힘) (그에게 평화가 깃들기를) 이 천사들에게 말하였노라. “그대들의 사정은 무엇이고 목적은 무엇입니까? \"",
  51032: "천사들이 그에게 답하며 말하였노라. “실로 하나님께서는 우리를, 추한 죄를 저지르는 무리에게로 보내신 것이오.",
  51033: "우리가 그들에게 찰흙으로 빚어진 단단한 돌멩이를 내려보내기 위함이며",
  51034: "그 돌멩이는 그대 - 아브라함이여! - 주님께서 표시를 새기신 것으로, 불신과 거역 행위로써 하나님의 경계를 크게 벗어난 자들에게 투하될 것이오\"",
  51035: "그리하여 하나님께서는 신앙인들을 선지자 롯 (루뜨. 그에게 평화가 깃들기를) 의 마을에서 빠져나오게 하시어 죄지은 자들이 받을 징벌로부터 그들을 보호해 주셨으니",
  51036: "그 마을에서 롯의 가족을 제외하곤 그 누구도 하나님께 순종하지 않았노라.",
  51037: "하나님께서는 롯의 마을에 그들이 받은 벌의 흔적을 남겨 두시어, 그들에게 덮친 고통의 벌을 두려워하는 자들이 그로부터 교훈을 얻어 그들이 저지른 악행을 반복하지 않도록 함이라.",
  51038: "하나님께서는 모세의 이야기에도 징표를 두셨노라. 그분께서는 명백한 증거와 함께 모세를 파라오에게로 보내셨으니, 고통의 벌을 두려워하는 자들에게 징표가 되도록 하심이라.",
  51039: "이에 파라오는 그의 군대와 함께 진리에 등을 돌렸고, 그는 모세에 대해 \"사람에게 주술을 거는 주술사이거나, 아무 말이나 지껄이는 미친 자\"라고 말하였노라.",
  51040: "이에 하나님께서는 파라오와 그의 군대를 움켜잡은 후 그들을 바다 속에 던져 버리셨으니 이 모두는 파라오가 자신을 신이라 하면서 하나님을 부정했기 때문이라.",
  51041: "하나님께서는 아드 부족의 이야기에도 징표를 두셨노라. 하나님께서는 그들에게 바람을 보내셨으니 그 바람은 비를 동반하지 않으며 나무에 가루받이도 해주지 않는 축복이라곤 찾아볼 수 없는 바람이라.",
  51042: "그 바람이 스쳐 지나간 생명이나 재산은 어김없이 파멸을 맞이하니, 마치 오래되어 낡아 떨어진 것처럼 되어 버렸노라.",
  51043: "하나님께서는 싸무드 부족의 이야기에도 징표를 두셨노라. 그들에게 목소리가 들렸으니 \"그대들은 현세의 삶을 즐겨 보라, 정해진 기간이 오기 전까지라\"",
  51044: "그들은, 하나님을 믿고 그분께 순종하라는 명령에 거만을 떨며 불복하였노라. 이에 하나님께서는 그들이 바라보는 가운데 벼락을 내리시어 그들을 파멸시키셨으니, 그들은 이미 사흘 전에 징벌이 닥칠 것이라는 경고를 받은 바 있노라.",
  51045: "그렇게 그들은 자신에게 다가오는 벌을 저지하지 못했으며, 그들은 그것을 막을 힘도 가지지 못하였노라.",
  51046: "하나님께서는 앞서 언급된 저들 이전에 노아 (누흐) 의 사람들 이야기에도 징표를 두셨노라. 실로 그들은 하나님께 불복하며 그분을 경배하길 거부하였기에 벌을 자초하였노라.",
  51047: "하나님께서는 하늘을 힘으로 세워 아름답게 하셨으며, 그분께서는 하늘의 끝자락을 늘리시는 분이시라.",
  51048: "또한 하나님께서는 인간을 위해 대지를 마치 침대와 같이 부드럽게 펼치셨으니, 그분은 펼치심에 참으로 훌륭한 분이시라.",
  51049: "하나님께서는 모든 것을 쌍으로 창조하심에 남자와 여자, 하늘과 땅, 육지와 바다 등이 그러하노라. 이는 그대들이, 모든 것을 쌍으로 창조하신 하나님에 대해 깊이 생각하고 그분의 전능하심을 떠올리기 위함이라.",
  51050: "그러니 그대들은 하나님께 거역하지 않고 순종함으로써 그분의 징벌을 피하고 그분의 보상을 추구하라. 실로 나 (무함마드) 는 하나님과 관하여 그대들 - 사람들이여! - 에게 명백한 경고를 전달하노라.",
  51051: "그리고 그대들은 하나님 아닌 다른 신을 두어 그것을 숭배하지 말라. 실로 나는 하나님과 관하여 그대들 - 사람들이여! - 에게 명백한 경고를 전달하노라.",
  51052: "메카 주민들이 사도를 부정한 것처럼 그들 이전의 공동체도 부정하였으니, 그들에게 사도가 도래할 때면 그들은 어김없이 '주술사' 혹은 '미친 자'라고 말하였노라.",
  51053: "이전의 불신자들이 이후의 불신자들에게 사도를 부정하라고 권유하는 것인가? 그렇지 않노라. 그들은 경계를 넘어서는 무리라.",
  51054: "그러니 그대 - 사도여! - 는 부정하는 저들에게서 돌아서라. 그럼에도 그대는 책망받지 않을 것이니 그대는 이미 그들에게 메시지를 전달했기 때문이라.",
  51055: "그들에게 돌아선다고 해서 그대가 그들을 상기시켜 주고 교훈을 주는 일을 포기해선 안 되노라. 따라서 그대는 그들을 떠올려 주라. 실로 떠올림은 하나님을 믿는 자들에게 도움이 되기 때문이라.",
  51056: "하나님께서 진과 인간을 창조하심은 그들이 오직 하나님 한 분만을 경배토록 하기 위함이지, 그들이 하나님께 대등한 존재를 두도록 하기 위함이 아니라.",
  51057: "하나님께서 그들로부터 양식을 원하시는 것도 아니며 그들이 그분께 먹을 것을 주길 원하시는 것도 아니라.",
  51058: "실로 하나님 그분이야말로 종복들에게 풍성한 양식을 베푸시는 분이시니, 모든 이는 그분의 양식을 필요로 하노라. 또한 하나님께서는 힘을 가지신 가장 강력하신 분으로서 그 무엇도 감히 그분을 제압할 수 없으니, 진과 인간 모두는 그분의 강력함에 굴복하노라.",
  51059: "실로 그대 - 사도여! - 를 부정함으로써 자신을 부당하게 대우하는 자들은, 이전 시대 그들의 동료들이 받은 벌과 유사한 분량의 벌을 받을 것이라. 그 벌에는 정해진 기한이 있으니, 그들은 그 기한이 오기 전에 하나님께 벌을 재촉하지 않도록 하라.",
  51060: "하나님을 불신하고 사도를 부정한 자들에게는 심판의 날로부터 재앙이 있으니, 이날은 그들에게 내려질 벌이 약속된 날이라.",
  52000: "앗-뚜르 (산)\n계시 분류: 메카\n•    계시 목적    \n이 장은 분명한 근거들로써 불신자들이 제기하는 여러 의혹들을 불식하고 있으며, 이를 통해 그들에게 하나님께 순종할 것을 촉구하고 있다.\n•    요약 주해",
  52001: "하나님께서는 당신께서 모세에게 말씀을 하신 산을 두고 맹세하시고",
  52002: "기록된 책을 두고 맹세하시며",
  52003: "그 계시서들은 펼쳐진 서면 속에 있노라 -",
  52004: "천사들이 하나님을 경배하기 위해 자주 방문하는 하늘의 전당을 두고 맹세하시며",
  52005: "대지의 천장이 되는 높은 하늘을 두고 맹세하시며",
  52006: "물로 채워진 바다를 두고 맹세하시니",
  52007: "진실로 그대 -사도여! - 주님의 벌은 도래할 것이며 불신자들은 결코 이를 피할 수 없노라.",
  52008: "그 누구도 그들을 위해 그 벌을 저지하거나 막아주지 못하노라.",
  52009: "그날 하늘은 크게 움직이며 흔들릴 것이니, 심판의 날이 시작됨을 알리는 것이라.",
  52010: "그날 산들은 움직이면서 제자리를 벗어날 것이라.",
  52011: "하나님께서 불신자들에게 약속하신 벌을 부정하는 자들에게 그날, 파멸과 손실이 있을 것이라.",
  52012: "실로 그들은 부활에 무관심한 채, 거짓에 빠져 노닥이며 즐거워하던 자들이라.",
  52013: "그날 그들은 지옥 불로 난폭하게 밀쳐질 것이라.",
  52014: "그들에게 질책하는 목소리가 들리니 \"이것은 너희에게 도래한 사도가 경고하였던, 그러나 너희가 부정하였던 바로 그 불지옥이라\"",
  52015: "너희가 지금 보는 이 징벌이 주술이란 말인가? 아니면 너희가 제대로 목격하지 못하는 것인가?",
  52016: "지옥 불의 뜨거움을 맛 보며 고통을 느끼라. 그 뜨거움을 참으려 해보라, 아니면 참지 말라. 참든지 참지 말든지 너희에게 (주어지는 고통은) 동일하노라. 너희는 단지 현세에서 너희가 저질렀던 불신과 거역 행위로 벌을 받는 것 뿐이라\"",
  52017: "(하나님께서는 불신하던 자들이 받을 징벌을 언급하셨고, 이제 그분께서는 여기서 진실된 신앙인들이 받을 보상을 언급하고 계신다. )  실로 하나님께서 명령한 것을 지키고 그분께서 금지한 것을 멀리함으로써 하나님을 경외하던 자들은 천국과 끊이지 않는 커다란 기쁨을 누릴 것이라.",
  52018: "그들은 하나님께서 그들에게 베풀어 주신 먹거리와 마실 거리와 배우자에 즐거워하노라. 또한 하나님께서는 그들을 타오르는 불지옥의 벌로부터 구해 주셨으니, 그렇게 그들은 원하는 것을 가지고 원치 않는 것을 멀리함으로써 성공한 자들이 되었노라.",
  52019: "그들에게 목소리가 들릴 것이라. “그대들은 원하는 대로 먹고 마시라. 그대들의 먹거리와 마실 거리에는 그 어떤 해도 없노라. 이는 그대들이 현세에서 실천했던 선행에 대한 보상이라”",
  52020: "그들은 아름답게 꾸며진 침대에 기대어 서로가 서로를 바라보며, 하나님께서는 그들을 아름답고 큼직한 눈을 가진 여성들과 짝지어 주셨노라.",
  52021: "믿는 자들의 아들딸이 믿음을 가져 부모님의 믿음을 따랐다면, 하나님께서는 그들을 부모님과 (천국에서) 함께 할 수 있도록 허락하실 것이라; 아들딸의 선행이 부모님보다 적을지라도 그들이 (천국에서) 함께 머물도록 함으로써 믿는 자들이 기뻐하도록 하기 위함이라. 하나님께서는 그들이 선행으로 받을 보상 그 무엇도 감소시키지 않으시노라. 모든 이는 그의 악행으로 전당이 잡혀 있으니, 그 누구도 자신의 악행을 타인에게 전가시킬 수 없노라.",
  52022: "그리고 하나님께서는 천국의 거주자들에게 그들이 먹고 싶어하는 다양한 종류의 과일과 고기를 푸짐하게 베풀어 주셨노라.",
  52023: "그들은 천국에서 술잔을 돌려 마시나, 현세에서처럼 음주로 인해 허언을 내뱉거나 술에 취한 나머지 죄를 범하는 일이 없노라.",
  52024: "그들을 위해 시중 드는 소년들이 그들 곁을 맴도는데, 그들의 맑고 밝은 피부로 인해 그들은 마치 진주조개 속에 감추어진 진주알과도 같더라.",
  52025: "천국의 거주자들은 현세에서 자신의 처지가 어떠했는지 질문을 주고 받으며 서로가 서로를 바라보더라.",
  52026: "그들이 질문에 답하며 말하노라. “실로 우리는 현세에서 우리 가족과 함께 있으면서 하나님의 벌을 두려워하곤 하였습니다.",
  52027: "그리하여 하나님께서는 우리에게 이슬람으로 인도되는 은혜를 베푸셨고, 견딜 수 없는 고온의 벌로부터 우리를 구해 주셨습니다.",
  52028: "실로 우리는 현세를 살아가면서 지속적으로 하나님을 경배하였으며 그분께 불지옥의 고통으로부터 우리를 보호해 주실 것을 꾸준히 기도하였습니다. 진실로 하나님께서는 종복들과 맺은 약속을 훌륭하고 진실되게 지키시는 분이시며, 그분은 그들에게 가장 자애로우신 분입니다. 우리가 믿음으로 인도되어 천국에 들어가고 지옥을 벗어날 수 있었던 것은 하나님의 훌륭하심과 자애로우심 덕분입니다\"",
  52029: "그러니 그대 - 사도여! - 는 꾸란으로 떠올려 주라. 그대 주님께서 베푸신 믿음과 이성이라는 은총에 의해 그대는 진(Jinn)의 생각에 의지하는 점술가가 아니며 미친 자도 아니라.",
  52030: "부정하는 저들은 \"무함마드는 사도가 아닌 단지 시인에 불과하오. 우리는 그가 어서 죽음을 맞이하여 우리가 편히 쉴 수 있기를 고대하고 있소”라고 말하는 것인가?",
  52031: "그대 - 사도여! - 는 그들에게 말하라. “그대들은 나의 죽음을 기다리라. 나의 사도직을 부정한 그대들이 어떠한 벌을 받을지 나도 기다리고 있노라”",
  52032: "그가 주술사이거나 미친 자라고 그들이 입을 모아 주장하는 이유는 그들의 이성이 그렇게 명하기 때문인가? 그렇지 않노라. 그들은 종교적 법률도 합리적 이성도 따르지 않는, 지켜야 할 경계를 넘어서는 무리이기 때문이라.",
  52033: "그들은 \"무함마드가 꾸란을 만들었다”라고 말하며 그가 받은 계시를 부정하는 것인가? 무함마드는 꾸란을 지어낸 적이 없도다. 그들이 이러한 말을 하는 이유는 그들이 믿음에 대해 거만하였기 때문이라.",
  52034: "무함마드가 꾸란을 지어내었다는 그들의 주장이 사실이라면 그들 자신이 직접 꾸란과 유사한 말씀을 만들어 보도록 하라.",
  52035: "그들이 창조자 없이 저절로 창조된 것인가? 아니면 그들 자신이 칭조자란 말인가? 창조자 없이 피조물은 있을 수 없으며 피조물은 창조하지 못하노라. 그런데도 그들은 왜 자신을 창조한 창조주를 경배하지 않는 것인가?",
  52036: "그들이 (일곱) 하늘과 땅을 창조했단 말인가? 그렇지 않노라. 그들은 하나님께서 그들을 창조하셨음을 믿지 않더라. 만약 그들이 이를 확실히 믿었다면 그들은 유일신 사상을 받아들이고 하나님의 사도를 믿었을 것이라.",
  52037: "그들에게 하나님의 보물 창고가 있어, 원하는 자에게 양식을 제공하고 원하는 자에게 사도직을 부여한단 말인가? 아니면 그들이, 마음대로 통치하고 원하는 대로 행하는 자라도 된단 말인가?",
  52038: "그들에게 사다리가 있어 그것을 타고 하늘로 올라가 하나님의 계시를 엿듣는단 말인가? 그리고 그 계시가 그들이 진리를 따르고 있음을 말하는 것인가? 그렇다면 그들 중의 엿듣는 자가 확실한 근거를 가져오도록 하라: 그가 그들이 진리를 따르고 있음을 말해주는 명백한 근거를 가져오도록 해보라.",
  52039: "하나님께는 그대들이 기피하는 딸이 있고 그대들에게는 그대들이 선호하는 아들이 있단 말인가?",
  52040: "그대 - 사도여! - 가 하나님의 메시지를 전한다는 이유로 그들에게 보수라도 요구한단 말인가? 그럴 경우 그들은 감당할 수 없는 짐을 짊어지게 될 것이라.",
  52041: "그들이 보이지 않는 영역에 대한 지식을 소유하고 있어서 사람들에게 그 지식을 기록해주고, 원하는 내용을 취사선택해서 사람들에게 알려주는 것인가?",
  52042: "부정하는 저들은 그대와 그대의 종교에 계략을 짜려는 것인가? 그대는 하나님께 의탁하라. 계략에 빠진 자는 그대가 아니라, 하나님과 그분의 사도를 불신하는 자들 바로 그들 자신이라.",
  52043: "그들 생각에 하나님 아닌 다른 신이 경배받을 권리를 지니고 있단 말인가? 그들은 감히 하나님께 대등한 존재를 두나 하나님께서는 대등함을 거부하는 완벽한 분이시라!",
  52044: "그들이 만약 하늘에서 떨어지는, 그들을 덮칠 징벌의 조각들을 본다면 그들은 \"저것은 언제나처럼 뭉게구름일 뿐이오\"이라 말하며 교훈을 얻지도 믿음을 가지지도 않을 것이라.",
  52045: "그러니 그대 - 사도여! - 는 고집부리며 논쟁하는 그들을 내버려 두라. 심판의 날이 도래하는 날, 결국 그들은 징벌을 받게 될 것이라.",
  52046: "그날 그들의 계략은 그들에게 그 어떤 보탬도 되지 않을 것이며 실로 그들은 징벌을 모면함에 있어 그 누구로부터의 도움도 받지 못할 것이라.",
  52047: "실로 우상 숭배와 거역 행위로 자신을 부당히 대우한 자들에게는 내세 뿐만이 아니라 현세와 장벽의 세계 (바르자크. 죽음과 심판의 날 사이의 세계) 에서도 벌을 받을 것이라. 그러나 그들 대부분은 이를 알지 못하고 이에 그들은 자신의 불신을 지속하노라.",
  52048: "(하나님께서는 이전 구절들에서 우상 숭배자들이 따르는 것들이 허위임을 알려주셨고, 이제 여기서는 사도에게 명령하여 그들에게 마음을 쓰지 말며 그를 부정하는 그들의 말에 인내하라 말씀하시고 계신다. )  그러니 그대 - 사도여! - 는 그대 주님의 판결과 규정에 인내하라, 실로 그대는 하나님의 배려와 보호 속에 있노라. 그대가 잠에서 깨었을 때는 그대 주님의 완벽한 영광을 드높이라.",
  52049: "그대는 밤중에 하나님을 찬양하면서 예배를 드리고, 아침빛으로 별들이 자취를 감추는 새벽 시간에도 파즈르 예배를 드림으로써 그분을 찬양하라.",
  53000: "안-나즘 (별)\n계시 분류: 메카\n•    계시 목적    \n이 장은 계시의 진실성과 그 원천의 위대함을 드러냄으로써 유일신 사상이 진리이며 다신 사상이 거짓임을 밝히고 있다.\n•    요약 주해",
  53001: "하나님께서는 지는 별을 두고 맹세하시노라:",
  53002: "하나님의 사도 무함마드는 올바른 길에서 벗어나지 않았으며 그릇되지도 않았으니, 그는 올곧은 길로 인도된 자라.",
  53003: "또한 그는 자신의 욕구에 따라 꾸란을 말하는 것이 아니며",
  53004: "이 꾸란은 하나님께서 내리신 계시를 가브리엘 (지브릴) 천사 (그에게 평화가 깃들기를) 가 그에게 전달하는 것이라.",
  53005: "무함마드에게 계시를 가르쳐 준 자는 강력한 힘을 가진 가브리엘 천사로서",
  53006: "훌륭한 모습을 지닌 자로서, 하나님께서 창조하신 모습 그대로 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 나타났노라.",
  53007: "가브리엘 천사는 하늘에 있는 높은 지평선에 있었노라.",
  53008: "그 후 그는 선지자에게 가까이 다가갔고 계속해서 접근하니",
  53009: "그와 선지자와의 거리는 활 두 개의 거리 혹은 그보다 더 가까워졌노라.",
  53010: "그리하여 가브리엘 천사는 하나님께서 계시한 것을 그분의 종복 무함마드에게 계시하였노라.",
  53011: "무함마드의 마음은 자신이 본 것을 부정하지 않노라.",
  53012: "그런데도 그대들 - 우상 숭배자들이여! - 은 그가 승천한 날 하나님께서 그에게 보여준 것들을 의심하며 그와 논쟁하려는 것인가?",
  53013: "진실로 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 는 승천하던 밤, 창조된 모습 그대로의 가브리엘 천사를 한번 더 보았으니",
  53014: "한계의 장소에 있는 시드르 나무 근처에서라. 이 나무는 일곱 번째 하늘에 있는 거대한 나무로서",
  53015: "근처에는 신앙인들의 거주지인 천국이 있으며",
  53016: "하나님의 명령으로 어떤 엄청난 것이 시드르 나무를 감싸고 있는데, 그것이 무엇인지는 오직 하나님만이 아시노라.",
  53017: "무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 의 시각은 보지 말아야 할 다른 곳으로 기울지 않았으며 넘지 말아야 할 경계를 넘어서지도 않았노라.",
  53018: "진실로 무함마드는 승천하던 날 밤, 하나님의 전능함을 드러내는 그분의 위대한 징표를 보았으니, 그는 천국과 지옥과 그 이외의 것들을 보았노라.",
  53019: "그대들 - 우상 숭배자들이여! - 은, 하나님을 제쳐두고 그대들이 숭배하는 우상인 ‘알-라트’와 ‘알-웃자’를 보지 않았는가?",
  53020: "그대들의 또 다른 우상인 ‘마나트’도 보지 않았는가? 말하여 보라. 저것들이 그대들에게 어떠한 효용이나 해악이라도 끼칠 수 있는가?",
  53021: "그대들 - 우상 숭배자들이여! - 이 선호하는 남자는 그대들의 것이고, 그대들이 싫어하는 여자는 하나님의 것이란 말인가?",
  53022: "그대들이 내키는 대로 나눈 이 분배는 부조리한 분배라.",
  53023: "이 우상들은 아무 의미 없는 이름일 뿐이며 저것들은 어떤 신성도 소유하고 있지 않노라. 그대들과 그대들의 조상들은 저것들에게 마음대로 이름을 붙였으나 하나님께서는 그에 관해 어떤 근거도 내리신 적이 없노라. 우상 숭배자들이 따르는 것은 오직 추측일 뿐이며, 그들은 사탄이 자신들 마음 속에 아름답게 꾸민 욕구를 따를 뿐이라. 하나님의 사도를 통해 그들에게 이미 진리가 찾아왔음에도 그들은 올바른 길을 걷지 않더라.",
  53024: "그들은 우상들이 하나님 앞에서 자신들을 중재해 주길 소망하나, 그들이 원하는 대로 다 가진단 말인가?",
  53025: "그렇지 않노라. 그들은 원하는 대로 갖지 못하며, 현세와 내세는 오직 하나님의 것이라. 그분께서는 원하시는 자에게 베푸시고 원하시는 자에게 주지 않고 보류하시노라.",
  53026: "아무리 많은 (일곱) 하늘의 천사들이 (심판의 날) 누군가를 중재하려 한대도 그들의 중재는 결코 도움이 되지 못하노라. 중재는 오직, 원하시는 자에게 하나님께서 중재를 허락하실 때, 그리고 중재받는 자에 관해 하나님께서 흡족하실 때만이 성립하니, 하나님께 대등한 존재를 두던 자는 중재하지 못하며 하나님 이외의 것을 숭배하던 자는 중재받지 못하노라.",
  53027: "내세에서 일어날 부활을 믿지 않는 자들은 실로 천사들에게 여자 이름을 지으니, 이는 천사들이 하나님의 딸들이라는 그들의 미신에 의함이라. 그들이 하나님께 대해 함부로 말하나, 지고하신 하나님께서는 그들의 말과는 무관하시도다.",
  53028: "천사들에게 여성의 이름을 짓는 그들의 행위는 지식에 기반한 것이 아니라. 그들은 오직 짐작하고 넘겨짚을 뿐이니 이러한 추측은 진리에 도달함에 어떠한 도움도 되지 않노라.",
  53029: "그러니 그대 - 사도여! - 는, 하나님을 기억하는 일에는 무관심하면서 현세의 삶에는 모든 관심을 쏟아붓는 자를 내버려 두라. 그는 내세를 믿지 않지 않기에 내세를 위해 아무런 준비도 하지 않는 자라.",
  53030: "천사들에게 여성의 이름을 짓는 우상 숭배자들의 저 말은 그들이 도달한 지식의 한계로서, 그들은 무지한 자들이며 그들에게는 확신이 없노라. 실로 그대 - 사도여! - 의 주님께서는 누가 진리의 길을 벗어나 방황하는지 가장 잘 알고 계시며, 누가 그분께로 향하는 올바른 길을 걷고 있는지 가장 잘 알고 계시노라. 하나님께는 그 무엇도 감추어지지 않노라.",
  53031: "(일곱) 하늘에 있는 것과 대지에 있는 것의 통치와 창조와 일의 결정은 오직 하나님만이 소유하시노라. 그리하여 하나님께서는 현세에서 악행을 저지른 자들에게 그에 걸맞는 벌을 내리시고, 최선을 다했던 믿는 자들에게는 천국으로 보상하시노라.",
  53032: "그들은 커다란 죄와 추악한 거역 행위를 피하는 자들이지만, 스쳐 지나가는 생각 등 사소한 죄는 그들도 피해가지 못하노라. 그러나 그들은 커다란 죄를 저지르지 않았고 많은 선행을 실천하였기에 그들의 작은 죄는 용서받을 것이라. 이처럼 실로 하나님께서는 용서하심에 드넓은 분이시니 그분께서는 참회하는 종복의 죄를 용서하여 주시노라. 하나님께서는 누구보다 더 그대들의 양상을 잘 알고 계신 분이라: 그분께서는 그대들의 아버지인 아담을 흙으로부터 창조하셨고, 어머니 배 속에 태아로 있던 그대들을 여러 단계로 창조하셨노라. 이렇듯 하나님께는 그 무엇도 감추어지지 않노라. 그러니 그대들은 하나님에 대한 경외심을 이유로 자신을 칭찬하지 말라. 하나님께서는 누가 그분을 두려워하는지 가장 잘 알고 계신 분이라.",
  53033: "이슬람을 믿으려 하다가 갑자기 돌아서는 자의 불행한 경우를 그대는 보았는가?",
  53034: "그는 적은 양의 재산을 희사한 후 더 이상을 쓰지 않는 자로서 그러함은 그의 마음 속에 새겨진 인색함 때문이라. 그럼에도 그는 자신이 깨끗하다 생각하며 잘난 체를 하더라.",
  53035: "그에게 보이지 않는 영역의 지식이라도 있어, 그가 미지의 세계를 보고 나서 그에 대해 얘기하는 것인가?",
  53036: "그는 하나님에 대해 말을 지어내는 것인가? 하나님께서 모세에게 계시하신 경전의 내용이 그에게 전해지지 않았기에 그가 이렇게 하나님께 대해 거짓말을 하는 것인가?",
  53037: "하나님의 명령을 빠짐없이 모두 실천한 아브라함 (이브라힘), 그가 받은 경전의 내용도 그에게 알려지지 않은 것인가?",
  53038: "그 내용은 다음과 같노라: 인간은 타인의 죄를 짊어지지 않으며",
  53039: "인간은 오직 자신의 행위에 대해서만 보상을 받을 것이며",
  53040: "그의 행위는 부활의 날 자신의 두 눈으로 직접 보게 될 것이며",
  53041: "그 후 그는 자신의 행위에 대해 남김없는 보상을 받을 것이라.",
  53042: "그리고 인간이 죽은 뒤에 돌아갈 곳은 오직 그대의 주님이신 하나님이며",
  53043: "진실로 하나님께서는 원하시는 자를 기쁘게 하여 웃게 하시고, 또한 원하시는 자를 슬프게 하여 울게 하시노라.",
  53044: "진실로 하나님께서는 현세에서 살아있던 자를 죽음에 들게 하시고, 부활을 통해 죽어있던 자를 살리시며",
  53045: "실로 그분께서는 두 종류의 성을 창조하셨니 남성와 여성이며",
  53046: "자궁 속에 놓인 정액으로부터 그들을 창조하셨노라.",
  53047: "실로 하나님께서는 부활을 위해 죽어 있는 자들을 되살리실 것이라.",
  53048: "실로 하나님께서는 원하시는 자에게 재물을 주시어 그를 부유하게 하시고, 사람들이 축척하는 재산을 주시는 분도 그분이시라.",
  53049: "실로 하나님께서는 일부 우상 숭배자들이 우상으로 섬기던 시리우스의 주님이시라.",
  53050: "실로 하나님께서는 선지자 후드의 사람들인 고대 아드 부족을 멸망시키셨으니 그들이 불신을 고집하였기 때문이라.",
  53051: "또한 하나님께서는 싸무드 부족도 멸망시키셨으니 그들 중 누구도 남겨놓지 않으셨노라.",
  53052: "그분께서는 아드 부족과 싸무드 부족 이전의 노아 (누흐) 시대 사람들도 멸망시키셨노라. 실로 그들은 아드 부족이나 싸무드 부족보다 부당함과 불의함이 더한 자들이라: 노아는 무려 950년을 그들과 머물며 그들에게 유일신 사상을 전하였음에도 그들은 그의 메시지를 한사코 거부하였기 때문이라.",
  53053: "하나님께서는 롯 (루뜨) 이 있었던 마을을 하늘로 들어올리시어 뒤집으신 후 그 마을을 땅 아래로 내리꽂으셨노라.",
  53054: "그 후, 하늘로 올라가 땅으로 곤두박질한 그 마을에는 돌비가 쏟아져 내렸노라.",
  53055: "그러한데도 그대 인간은 하나님의 전능하심을 드러내는 징표로부터 교훈을 얻지 않고 도리어 그분의 징표에 관해 논쟁하려는 것인가?",
  53056: "그대들에게 보내진 이 사도는 이전 사도들이 받은 것과 동일한 메시지를 전하노라.",
  53057: "부활의 날이 가까워졌노라.",
  53058: "하나님을 제외한 그 누구도 부활의 날에 있을 고통을 막아줄 수 없노라.",
  53059: "그런데도 그대들(우상 숭배자들)은 이 꾸란이 하나님으로부터 온 것임에 놀라워하고,",
  53060: "꾸란을 비웃으면서 그 교훈을 듣고도 울지 않고,",
  53061: "꾸란을 외면하며 그것에 관심조차 두지도 않는 것인가?",
  53062: "그렇다면 그대들(믿는 자들)은 하나님 한 분께만 엎드려 절하고 진정으로 그분을 경배하라.",
  54000: "알-까마르 (달)\n계시 분류: 메카\n•    계시 목적    \n이 장은 징표로써 우리를 떠올려 주면서, 동시에 경고의 메시지를 전하고 있다. 또한 이 장은 부정하는 자들의 말로가 무엇인지를 가르쳐 주고 있다. 그러한 이유로 \"진실로 나는 떠올림을 위해 꾸란을 쉽게 하였노라. 그러니, 떠올리는 자 있는가? “라는 구절이 반복되고 있다.\n•    요약 주해",
  54001: "종말의 시간이 가까워졌고, 선지자 시절에 달이 갈라지는 사건이 있었으니 이는 선지자를 위한 구체적인 징표라.",
  54002: "우상 숭배자들이 선지자의 정직성을 드러내는 징표를 볼 때면 그들은 그 징표에 등을 돌리며 말하였노라. “우리가 목격하는 이 징표는 거짓된 주술일 뿐이라\"",
  54003: "그들은 자신의 욕구를 따르며 그들에게 도래한 진리를 부정하였노라. 심판의 날 선행이든 악행이든 모든 일은 그에 걸맞는 보응을 받을 것이라.",
  54004: "실로 그들에게는 파멸을 맞이한 이전 공동체들의 소식이 전해졌으니, 하나님께서는 불신과 부당함으로 말미암아 그 공동체들을 멸망시키셨노라. 그들의 이야기에는 불신과 부당함을 멀리해야 함을 알리는 충분한 교훈이 있노라.",
  54005: "그들의 이야기에는 증거가 되는 감명 깊은 지혜가 담겨 있으나, 하나님과 최후의 날을 믿지 않는 자들에게는 아무 소용이 없더라.",
  54006: "그러니 그들이 올바른 길을 거부할 때 그대 - 사도여! - 는 심판의 날을 기다리며 그들을 놓아두라. 그날은 천사가 나팔을 부는 날로서, 이전에는 없었던 무서운 일을 경험하도록 천사가 사람들을 부를 것이라.",
  54007: "그들의 눈은 모욕으로 가득 찰 것이며, 그들은 무덤에서 빠져 나와 심판의 장소로 이동함에 마치 사방으로 퍼지는 메뚜기 떼처럼 그렇게 재빨리 나아갈 것이라.",
  54008: "그들은, 사람들을 심판의 장소로 부르는 천사로 향해 서둘러 이동할 것이라. 불신자들이 말하니 \"이날은 무섭고 혹독한 날입니다\" 하더라.",
  54009: "(이전 구절에서 하나님께서는 사도 무함마드에게 등을 돌리는 불신자들에게 대해 말씀하셨다. 지금부터는, 사도들을 부정했던 이전 공동체의 소식이 언급되며 이는 사도 무함마드의 마음에 위안이 된다. )  그대 - 사도여! - 를 부정하는 저들 이전에 노아 (누흐) 의 사람들도 하나님의 사도 노아를 부정하였노라. 그들은 노아를 두고 미친 자라고 말하였고, 그를 비방하고 욕하면서 메시지를 전파하지 말 것을 종용하였노라.",
  54010: "이에 노아는 하나님께 기도하였노라. “실로 사람들은 저를 무력으로 저지하면서 제가 전하는 메시지에 응답하지 않고 있습니다. 그러니 당신께서 저를 도와주시어 그들에게 벌을 내려 주십시오\"",
  54011: "그리하여 하나님께서는 연이어 쏟아붓는 비로써 하늘의 문을 여셨으며",
  54012: "대지로부터 여러 샘들을 뽑아내셨고 그로부터 물이 샘솟았노라. 그렇게 하늘로부터 내려오는 물과 대지로부터 솟아오르는 물이 서로 만나니, 하나님께서 이미 운명으로 지정하신 일에 의거함이라. 그리하여 그들 모두는 익사하였으나 하나님께서 구해 주신 자는 예외라.",
  54013: "하나님께서는 나무판자와 못으로 만들어진 방주 위에 노아를 태우심으로써 그와 그와 함께 있던 자들을 익사하지 않도록 구해 주셨노라.",
  54014: "이 방주는 하나님의 배려로 거친 물결에도 안전히 항해하였노라. 사람들은 노아를 불신하며 그가 가져온 하나님의 메시지를 거부하였고, 이에 하나님께서는 노아를 도와주셨노라.",
  54015: "진실로 하나님께서는 그들에게 내려진 벌을 교훈으로 남겨놓았노라. 그러니, 이 교훈을 떠올리는 자 있는가?",
  54016: "부정하는 자들에 대한 하나님의 벌은 어떠하였으며, 그들을 멸망시킨 하나님의 경고 또한 어떠하였는가?",
  54017: "진실로 하나님께서는 교훈을 얻을 수 있도록 꾸란을 쉽게 하였노라. 그러니, 꾸란의 교훈을 떠올리는 자 있는가?",
  54018: "아드 부족은 그들에게 보내진 후드 (그에게 평화가 깃들기를) 를 불신하였노라. 그러니 그대들 - 메카의 거주민들이여! - 은 잘 생각해 보라: 그들에 대한 하나님의 벌은 어떠하였으며, 불신자들에 대한 그분의 경고는 어떠하였는가?",
  54019: "실로 하나님께서는 불길함이 지속되는 날, 그들에게 혹독한 추위의 바람을 보내시어 그들이 지옥에 들어가도록 하셨노라.",
  54020: "그 바람은 땅에 있던 사람들을 하늘로 잡아채어 다시 땅으로 고꾸라뜨리니 그들은 마치 뿌리채 뽑혀 버린 야자수의 몸통과도 같더라.",
  54021: "그러니 그대들 - 메카의 거주민들이여! - 은 잘 생각해 보라: 그들에 대한 하나님의 벌은 어떠하였으며, 불신자들에 대한 그분의 경고는 어떠하였는가?",
  54022: "진실로 하나님께서는 교훈을 얻을 수 있도록 꾸란을 쉽게 하였노라. 그러니, 꾸란의 교훈을 떠올리는 자 있는가?",
  54023: "싸무드 부족은 그들에게 보내진 선지자 쌀리흐 -그에게 평화가 깃들기를- 의 경고를 믿지 않았노라.",
  54024: "그들이 거부하며 말하였노라. “우리와 같은 한낱 인간을 따라야 한단 말인가? 그럼에도 우리가 그를 따른다면 실로 우리는 진리에서 멀어져 방황하면서 고통을 받게 될 것이라\"",
  54025: "우리 모두는 제쳐두고 그에게만 메시지가 내려진단 말인가? 그렇지 않으며 그는 거짓말을 일삼는 거만한 자라.",
  54026: "그들은 심판의 날 거짓말을 일삼는 자가 누구인지 -쌀리흐인지 아니면 그들인지- 알게 될 것이라.",
  54027: "실로 하나님께서는 그들을 위한 시험으로 바위에서 암낙타 한 마리를 뽑아내실 것이라. 그러니 그대 -쌀리흐여! - 는 그들이 낙타에 무슨 짓을 하는지, 그들에게 어떤 일이 일어나는지 관망하면서 그들이 끼치는 해악에 인내하라.",
  54028: "그리고 그대는 그들에게 알리라: 우물물은 그들과 낙타 사이에 분배되어야 하며, 모두는 자신을 위해 정해진 날에만 물을 마실 수 있노라.",
  54029: "이에 그들은 낙타를 죽이기 위해 동료 한 명을 불렀고, 그는 명령받은 대로 칼을 집어든 후 낙타의 다리 힘줄을 끊어 버렸노라.",
  54030: "그러니 그대들 - 메카의 거주민들이여! - 은 잘 생각해 보라: 그들에 대한 하나님의 벌은 어떠하였으며, 불신자들에 대한 그분의 경고는 어떠하였는가?",
  54031: "실로 하나님께서는 그들에게 단 한번의 굉음을 보내시어 그들 모두를 파멸시키셨노라. 이에 그들은 마치, 양우리를 치는 자가 주워 모으는 바스러진 목초처럼 되어 버렸노라.",
  54032: "진실로 하나님께서는 교훈을 얻을 수 있도록 꾸란을 쉽게 하였노라. 그러니, 꾸란의 교훈을 떠올리는 자 있는가?",
  54033: "롯 (루뜨) 의 사람들은 그들에게 보내진 선지자 롯 -그에게 평화가 깃들기를- 의 경고를 믿지 않았노라.",
  54034: "실로 하나님께서는 그들에게 돌비를 내려 보내셨으나, 롯과 함께 하던 신앙인들은 예외라: 그들은 재앙을 피하였으니 벌이 내리기 전 새벽녘에 길을 떠나도록 함으로써 하나님께서는 그들을 구해 주셨노라.",
  54035: "그들이 재앙을 피함은 하나님께서 그들에게 베푸신 은총이라. 하나님께서는 롯에게 보상을 내리신 것처럼 그렇게 은총에 감사하는 자들을 보상하시노라.",
  54036: "진실로 롯은 이미 그들에게 하나님의 강력한 징벌을 경고하였으나 그들은 그가 전달한 경고에 논쟁을 벌이며 부정하였노라.",
  54037: "진실로 그들은 추악한 행위를 저지를 의도로 롯에게 손님을 내달라고 요구하였고 이에 하나님께서는 그들의 시력을 앗아가셨노라. 그러면서 하나님께서는 그들에게 말씀하셨노라. \"그대들은 내가 경고했던 그 벌을 맛 보라\"",
  54038: "진실로 그들의 아침을 연 것은 새벽에 찾아온 무기한의 벌로서, 내세가 찾아올 때까지 지속될 벌이라.",
  54039: "그들에게 목소리가 들리니 \"그대들은 하나님께서 내린 벌을 맛 보라. 이것은 롯이 경고했던 바로 그 벌이라\"",
  54040: "진실로 하나님께서는 교훈을 얻을 수 있도록 꾸란을 쉽게 하였노라. 그러니, 꾸란의 교훈을 떠올리는 자 있는가?",
  54041: "진실로 하나님께서는 모세와 아론을 통해 파라오의 추종자들을 경고하셨노라.",
  54042: "​그들은 하나님께서 보이신 명백한 증거 모두를 부정하였고 이에 그분께서는 그들에게 혹독한 벌을 내리셨으니 그 벌은, 그 누구도 감히 제압할 수 없으며 모든 것이 가능한 하나님께서 내리신 벌이라.",
  54043: "그대들 -메카 거주민들이여! - 과 함께 있는 불신자들이 저들 (노아의 의 백성들, 아드 부족, 싸무드 부족, 롯의 사람들, 파라오와 그의 백성) 보다 더 훌륭하단 말인가? 아니면 그대들은 하나님의 벌에서 면제될 것이라는 약속이 성서에 기록되어 있단 말인가?",
  54044: "메카의 불신자들은 \"우리에게 나쁜 일이 일어나고 분열하길 바라는 자들이 있으나 우리 모두는 그들에게 승리를 거두는 자들이오”라고 말하는 것인가?",
  54045: "저 불신자 무리는 곧 패배를 맞이할 것이며 믿는 자들 앞에서 꽁무니를 빼게 될 것이라. (이 예언은 바드르 전투에서 사실로 실현된 바 있다. )",
  54046: "그러나 그들이 부정해 마지 않는 종말의 날은 그들에게 도래가 약속된 날로서 그날 그들은 벌을 받을 것이라.",
  54047: "실로 불신과 거역으로 악행을 저지르는 자들은 진리를 벗어나 방황하고 있으며 그들은 벌과 고통 속에 빠져 있노라.",
  54048: "그날 그들은 얼굴이 잡힌 채로 불지옥 속으로 끌려갈 것이라. 그 때 목소리가 들리니 \"그대들은 뜨거운 불지옥의 고통을 맛 보라\"",
  54049: "실로 하나님께서 모든 것을 그분의 지식과 의지에 걸맞게, 보존 서책 (알-라우흐 알-마흐푸드) 에 기록된 운명에 의거하여 창조하셨노라.",
  54050: "하나님께서 무언가를 원하실 때는 오직 \"있어라”라는 한 마디의 명령을 내리실 뿐이니, 눈 깜짝할 사이에 그것이 있게 되노라.",
  54051: "실로 하나님께서는 불신을 범하던 그대들과 유사한 이전 공동체를 파멸시키신 바 있노라. 그러니, 이로써 교훈을 얻어 불신을 그만두는 자 있는가?",
  54052: "인간이 행하는 모든 일은 기록 천사가 성서에 기재하니, 그들은 그 무엇도 놓치지 않노라.",
  54053: "그들이 행하는 작은 일이던 큰 일이던 그 모든 것은 행위 기록부와 보존 서책 (알-라우흐 알-마흐푸드) 에 자세히 기록되어 있으며, 그들은 이에 의거하여 보상을 받을 것이라.",
  54054: "실로 하나님께서 명령하신 사항을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하던 자들은 강이 흐르는 천국에서 기쁨을 만끽할 것이라.",
  54055: "그들은 헛된 말이나 죄가 없는 진리의 장소에 앉을 것이니, 모든 것을 소유하시고 그 모든 것이 가능한 하나님 근처에 있을 것이라. 그들이 누리는 영원한 기쁨이란 인간이 상상하는 그 이상이라. ​",
  55000: "알-라흐만 (가장 자비로우신 분)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 현세와 내세에서  내려지는 하나님의  위대한 은총 및 그분께서 베푸시는 자비의 명백한 흔적에 대해 이야기함으로써 인간들에게 믿음을 촉구하고 불신을 경고하고 있다.\n•    요약 주해",
  55001: "드넓은 자비를 지니신, 가장 자비로우신 하나님.",
  55002: "그분께서는 인간에게 꾸란을 가르쳐 주시어, 그들이 쉬이 그것을 암기하고 이해할 수 있도록 하셨노라.",
  55003: "그리고 하나님께서는 인간을 창조하심에 그를 반듯하고 아름다운 모습으로 두셨노라.",
  55004: "또한 그분께서는 인간에게 자신의 생각을 말과 글로써 표현하는 법을 가르쳐 주셨노라.",
  55005: "하나님께서는 해와 달이 완벽한 계산에 의해 움직이도록 하셨고 이를 통해 인간은 연중의 날짜를 파악하고 그 계산법을 익히더라.",
  55006: "덩굴식물과 나무는 하나님을 위해 절하고 그분께 순종하노라.",
  55007: "하나님께서는 하늘을 높이 올리시어 천장으로 하셨으며, 지구에 공정을 두시어 사람들에게 공정을 실천하라 명령하셨노라.",
  55008: "그러함은 그대들 -사람들이여! - 이 무게와 부피를 잴 때 속이지 않고 공정을 기하도록 하기 위해서라.",
  55009: "그대들은 공정한 방식으로 정확히 무게를 재고, 타인에게 무게나 부피를 측정할 때는 실제보다 적게 측정하지 말라.",
  55010: "하나님께서는 대지를 안정되게 두시어 생명체들이 그 위에서 정착할 수 있도록 하셨노라.",
  55011: "거기에는 과일을 맺는 나무가 있고, 꽃밥을 감싸는 큰 덮개를 갖춘 야자수가 있으며​",
  55012: "밀이나 보리처럼 깍지를 지닌 곡물과, 향기로운 냄새를 풍기어 기분을 좋게 하는 꿀풀과 (科) 식물 바질도 있더라.",
  55013: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55014: "하나님께서는 아담 -그에게 평화가 깃들기를- 을 창조하심에 마치 구워진 도자기처럼 하셨으니, 치면 소리가 나는 마른 점토로부터 그를 창조하셨노라.",
  55015: "그리고 그분께서는 진의 조상을 연기 없는 불꽃로부터 창조하셨노라.",
  55016: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55017: "하나님께서는 여름과 겨울에 태양이 뜨는 곳과 지는 곳의 주님이시라.",
  55018: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55019: "하나님께서는 소금의 농도가 짙고 옅은 두 바다를 만나게 하시나,",
  55020: "이 바다 사이에는 장벽이 있어 경계를 넘지 않으면서 서로 섞이지 않노라.",
  55021: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55022: "그 두 바다에서 진주와 산호초가 생성되노라.",
  55023: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55024: "마치 거대한 산처럼 바다에서 항해하는 선박의 움직임은 오직 하나님만이 소유하시노라.",
  55025: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55026: "대지 위에 있는 모든 생명체는 반드시 멸하게 되어 있노라.",
  55027: "그러나 그대 -사도여! - 주님의 얼굴은 장엄함과 베푸심의 속성을 지닌 채 소멸됨 없이 영원히 존재할 것이라.",
  55028: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55029: "(일곱) 하늘에 있는 천사들과 대지에 있는 진과 인간은 하나님께 자신이 필요한 사항을 요청하고, 그분께서는 매일 종복의 삶과 죽음, 양식 등의 일을 결정하시노라.",
  55030: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55031: "그대들 - 인간과 진이여! - 이 현세에서 실천한 행위는 하나님께서는 시간을 내시어 계산하신 후 보응하실 것이니, 악행을 저지른 자는 벌하실 것이며 선행을 실천한 자는 보상하실 것이라.",
  55032: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55033: "하나님께서는 심판의 날 진과 인간을 모은 후 이렇게 말씀하실 것이라. “진과 인간의 무리여. 만약 그대들이 (일곱) 하늘과 땅의 어떤 곳에서라도 탈출구를 찾을 수 있다면 찾아보라. 강력한 힘과 증거가 있을 때만 그렇게 할 수 있으나, 그대들은 결코 그러한 것을 가지지 못하노라\"",
  55034: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55035: "연기가 없는 화염과 화염이 없는 연기가 그대들 -인간과 진이여! - 을 덮칠 것이나 그대들은 그것을 막을 방도가 없노라.",
  55036: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55037: "그때 천사들의 강림으로 하늘이 갈라지니, 그 색깔은 마치 강렬한 붉은 색을 띄는 가죽과도 같더라.",
  55038: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55039: "저 위대한 심판의 날, 인간과 진은 자신이 저지른 죄에 대해 질문받지 않을 것이니, 하나님께서는 그들의 행위 모두를 알고 계시기 때문이라.",
  55040: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55041: "심판의 날 악행을 저지른 자들은 징표로써 구별되는데, 그들이 가진 어두운 얼굴과 파란색 눈이 그것이라. 그들의 몸은 뒤로 휘어져 앞머리와 발등이 서로 만날 것이며 그러한 상태로 그들은 지옥 불에 내던져질 것이라.",
  55042: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55043: "그들에게 질책하는 목소리가 들리니 \"이것은, 악행을 저지른 자들이 현세에서 그 존재를 부정하던 지옥이라\" 이제 그들은 자신의 두 눈으로 지옥을 직접 목격하니 그 존재를 부정하지 못하노라.",
  55044: "그들은 지옥과 고온의 끓는 물 사이를 반복해서 오가며 고통받을 것이라.",
  55045: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55046: "그러나 하나님 앞에 서게 될 심판의 날을 두려워하면서 믿음을 가지고 선행을 실천한 자에게는 두 개의 천국이 있노라.",
  55047: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55048: "이 두 개의 천국은 열매를 맺는, 초록색의 웅장한 나뭇가지들이 있는 곳이라.",
  55049: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55050: "그곳에는 물이 흘러 넘치는 두 개의 샘이 있노라.",
  55051: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55052: "그곳에는 모든 맛있는 과일이 두 종류를 이루고 있노라.",
  55053: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55054: "그들은 침대에 몸을 기댄 채로 있는데 그 이불안은 두꺼운 명주붙이로 이루어져 있노라. 또한 두 천국의 열매와 과일은 가까이 드리워져 있기에, 서 있거나 앉아 있거나 누워 있을 때도 따 먹기가 수월하더라.",
  55055: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55056: "그곳에는 자신의 배우자만을 바라보는 여성들이 있으니, 남편 이전의 어떤 인간이나 진도 그녀들을 스치지 않았노라.",
  55057: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55058: "그녀들은 마치 아름답고도 투명한 루비와 산호초와도 같노라.",
  55059: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55060: "하나님께 순종함에 있어 최선을 다한 자는 하나님께서 그에게 가장 훌륭한 보상을 내리시노라.",
  55061: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55062: "이 두 개의 천국 아래에는 두 개의 또 다른 천국이 있노라.",
  55063: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55064: "이 두 개의 천국은 푸름이 짙은 곳이라.",
  55065: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55066: "그곳에는 두 개의 샘에서 물이 솟아나니, 이 샘솟는 물은 결코 끊이지 않더라.",
  55067: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55068: "그곳에는 풍성한 과일과 커다란 야자와 석류가 있노라.",
  55069: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55070: "그곳에는 성품이 훌륭하고 얼굴이 아름다운 여성들이 있노라.",
  55071: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55072: "그녀들은 아름다운 눈을 가졌으며, 천막에서 보호받으며 가려진 여성들이라.",
  55073: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55074: "남편 이전의 어떤 인간이나 진도 그녀들을 스치지 않았노라.",
  55075: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55076: "그들은 아름다운 침대와 초록색 베겟잇이 덧씌워진 베게에 몸을 기댄 채 있노라.",
  55077: "그럼에도 그대들 -인간과 진이여! - 은 그대들에게 내려진 하나님의 풍성한 은혜 중 그 무엇을 부정하려는 것인가?",
  55078: "장엄함과 베푸심의 속성을 지닌 하나님의 이름에는 축복이 가득하노라.",
  56000: "알-와끼아 (피할 수 없는 날)\n계시 분류: 메카\n•    계시 목적    \n이 장은 심판의 날의 무서움과, 그 날이 반드시 도래할 것임을 이야기하고 있다. 또한 이 장은, 심판의 날에 사람들이 세 종류로 나뉘어지며, 종류에 따라 그들이 받을 보응이 달라짐을 알려주고 있다.\n•    요약 주해",
  56001: "결코 피할 수 없는 심판의 날이 도래하였을 때",
  56002: "현세에서 부정하는 자들이 있을지언정 그날만은 그 누구도 심판의 날을 부정하지 못할 것이라.",
  56003: "그날은 지옥에 들게 함으로써 불신자들을 낮추는 날이며, 천국에 들게 함으로써 믿는 자들을 높이는 날이라.",
  56004: "대지가 격하게 요동치고",
  56005: "산들이 산산히 쪼개져",
  56006: "한 곳에 머물지 못하고 흩어지는 먼지가 될 때",
  56007: "그날 그대들은 세 부류로 나눠지게 될 것이라.",
  56008: "자신의 행위 기록부를 오른쪽으로 받는 우편의 동료들이 있으니 그들의 위치는 참으로 높고 위대하도다.",
  56009: "자신의 행위 기록부를 왼쪽으로 받는 좌편의 동료들이 있으니 그들의 위치는 참으로 낮고 비참하도다.",
  56010: "현세에서 선행으로써 앞서가는 자들은 내세에서 천국으로 들어감에 앞서가는 자들이라.",
  56011: "그들은 하나님께 가까워진 자들로서",
  56012: "기쁨의 천국에서 다양한 기쁨을 만끽하노라.",
  56013: "그들의 다수는 이슬람 공동체 및 이전 공동체 출신의 사람들이며",
  56014: "종말이 가까워진 시대의 사람들은 그들 중의 소수를 차지하노라.",
  56015: "금으로 짜여진 침대 위에서",
  56016: "몸을 기대어 서로의 얼굴을 마주 보니, 등을 돌리는 경우가 없노라.",
  56017: "늙지도 죽지도 않는 어린이들이 시중을 들면서 그들 사이를 왔다 갔다 하는데",
  56018: "컵과 주전자와 끊임없이 흘러내리는 천국의 술로 채워진 잔을 가지고서라.",
  56019: "천국의 술은 현세의 술과는 달라서 마신 후에 두통에 시달리거나 이성이 마비되는 일이 없노라.",
  56020: "영생의 어린이들은 천국의 거주자들이 고른 과일과",
  56021: "그들이 먹고 싶어하는 새고기를 가지고서 그들 주위를 맴도노라.",
  56022: "그리고 그들에게는 아름답고 큼직한 눈을 가진 천국의 여성들이 있으니",
  56023: "마치 조개 속에 숨겨진 진주와도 같더라.",
  56024: "그들이 현세에서 실천하던 선행에 대한 보상이라.",
  56025: "그들은 천국에서 실없는 말을 듣지 않으며 그곳에는 죄가 되는 언행도 없노라.",
  56026: "그들이 듣는 말은 오직, 천사들이 그들에게 보내는 '평안하시오”라는 인사와 그들 사이에 나누는 '평안하시오”라는 인사 뿐이라.",
  56027: "자신의 행위 기록부를 오른쪽으로 받는 우편의 동료들이 있으니 하나님께 있어 그들의 위치는 참으로 위대하도다.",
  56028: "그들은 가시가 제거되어 해 끼침이 없는 시드르 나무 곁에 있을 것이며",
  56029: "바나나가 주렁주렁 열려 있는 나무와",
  56030: "사라지지 않는 그늘과",
  56031: "멈추지 않고 흐르는 물과",
  56032: "셀 수 없이 많은 과일이 그들 곁에 있을 것이라.",
  56033: "그 과일은 계절에 상관없이 끊임없이 공급되며, 원하는 자는 시간에 구애받지 않고 그 과일을 먹을 수 있노라.",
  56034: "그리고 그들 곁에는 높은 침대가 놓일 있을 것이라.",
  56035: "실로 하나님께서는 천국의 여성들을 새롭게 창조하셨노라.",
  56036: "그녀들을 순결한 처녀로 두심에",
  56037: "배우자에게 사랑스러운 동갑내기 여성으로 하셨으니",
  56038: "우편의 동료들을 위해 하나님께서 창조하신 천국의 여성들이라.",
  56039: "그들 중에는 이전 선지자들과 함께 했던 공동체 일원들이 있으며",
  56040: "무함마드와 함께 한 이슬람 공동체 일원들이 있으니 그들은 마지막 신앙 공동체라.",
  56041: "자신의 행위 기록부를 왼쪽으로 받는 좌편의 동료들이 있으니 그들의 위치는 참으로 낮고 비참하도다.",
  56042: "그들은 뜨거운 바람과 고온으로 부글거리는 물에 노출될 것이며",
  56043: "칠흑의 연기가 만드는 그늘에 휩싸일 것이니",
  56044: "서늘하지도 모양새가 훌륭하지도 않더라.",
  56045: "실로 그들은 이같은 벌을 받기 이전에 현세에서 안락을 즐기며 욕망만을 찾던 자들이었으며",
  56046: "그들은 하나님을 불신하면서 우상 숭배를 지속해서 저질렀노라.",
  56047: "그리고 그들은 부활을 부정하면서 \"우리가 죽어서 흙과 뼈다귀가 되었을 때 진실로 우리가 부활한단 말인가? ”라며 비웃음 조로 말하곤 하였노라.",
  56048: "\"우리 이전에 이미 죽은 옛 시대의 조상들도 부활한단 말인가? \"",
  56049: "그대 -사도여! - 는 부활을 부정하는 저들에게 말하라. “진실로 이전 사람들과 이후 사람들 모두는",
  56050: "피해갈 수 없는 부활의 날에 소집되어, 계산받고 심판받을 것이라\"",
  56051: "그 후 실로 부활을 부정하고 올바른 길을 벗어나 방황하는 그대들은 심판의 날에 작꿈 나무의 열매를 먹게 될 것이니 그 열매는 가장 추악하고 더러운 열매라.",
  56052: "그 후 실로 부활을 부정하고 올바른 길을 벗어나 방황하는 그대들은 심판의 날에 작꿈 나무의 열매를 먹게 될 것이니 그 열매는 가장 추악하고 더러운 열매라.",
  56053: "그대들은 그 쓰디쓴 열매로 텅 빈 배를 채울 것이라.",
  56054: "그 후 그대들은 작꿈 열매를 먹고 나서, 뜨거움으로 끓어오르는 물을 마시는데",
  56055: "조갈증에 걸린 낙타가 벌컥거리며 물을 마시듯 그대들도 그렇게 그 뜨거운 물을 마실 것이라.",
  56056: "이전에 언급된 쓰디쓴 음식과 부글거리는 물은 그들이 심판의 날에 손님으로서 받을 대접이라.",
  56057: "하나님께서는 그대들 -부정하는 자들이여! - 을 무 (無)로부터 창조하셨노라. 그러한 하나님이시기에 죽어있는 그대들을 부활시키는 것은 그분께 쉬운 일이라; 그런데도 그대들은 어찌하여 부활을 믿지 않는 것인가?",
  56058: "그대들 -인간들이여! - 은 여성의 자궁에 안착하는 정액에 대해 생각해보라.",
  56059: "정액을 창조하는 자는 그대들인가? 아니면 그것을 창조하는 분은 하나님이신가?",
  56060: "실로 하나님께서는 그대들 사이에 죽음을 운명 지으셨기에 그대들 중 그 누구도 지정한 기한보다 일찍 혹은 늦게 죽음을 맞이할 수 없노라. 또한 그 누구도 감히 하나님을 앞서갈 수 없으니",
  56061: "그대들이 알고 있는 그대들의 창조와 형상을 바꾸시어, 그대들이 알지 못하는 창조와 형상으로 그대들을 새롭게 만드는 것이 하나님께는 불가능한 일이 아니라.",
  56062: "실로 그대들은 하나님께서 그대들을 처음으로 창조하셨음을 잘 알고 있노라. 그러니 그대들은, 그렇게 그대들을 처음으로 창조하신 분께서 죽음 후의 그대들을 다시 부활시키실 수 있음을 깨닫지 않겠는가?",
  56063: "그대들은 논밭에 뿌리는 씨앗에 대해 생각해보라.",
  56064: "씨앗을 자라나게 하는 자는 그대들인가? 아니면 그것을 자라나게 하는 분은 하나님이신가?",
  56065: "하나님께서 의지하셨다면 실로 그분께서는 무르익기 직전의 열매를 메말라 부서지는 조각으로 만들었을 것이며, 그대들은 이같은 재앙에 경악을 금치 못했을 것이라.",
  56066: "그대들이 말할 것이니 \"진실로 우리는 손실로 인해 고통받는 자들이라.",
  56067: "실로 우리는 열매를 얻지 못한 자들이라\"",
  56068: "그대들은 갈증을 느낄 때 마시는 물에 대해 생각해보라.",
  56069: "그대들이 구름으로부터 비를 내렸단 말인가? 아니면 비를 내리는 분은 하나님이신가?",
  56070: "하나님께서 의지하셨다면 물을 소금기 가득한 쓴 맛으로 만들어 마실 수 없도록 하셨을 것이라. 그러나 하나님께서는 자비를 베푸시어 물을 청량한 맛으로 두셨으니, 그대들은 이에 감사하지 않겠는가.",
  56071: "그대들은 효용을 얻기 위해 지피는 불에 대해 생각해보라.",
  56072: "그대들이 나무로부터 불을 얻으니, 그대들이 나무를 만든 것인가? 아니면 그대들을 생각해서 나무를 만든 분은 하나님이신가?",
  56073: "하나님께서는 이 불을 통해 그대들이 내세에 있는 지옥 불을 떠올리도록 하셨고, 장거리를 이동하는 자들이 이 불을 유용하게 사용할 수 있도록 하셨노라.",
  56074: "그러니 그대 - 사도여! - 는 그대 주님의 완벽함을 찬양하라.",
  56075: "실로 하나님께서는 별들이 위치하고 있는 자리를 두고 맹세하시니,",
  56076: "별들의 위치를 두고 하는 이 맹세는 진실로 -그대들이 안다면- 징표와 교훈이 담겨 있는 위대한 맹세라,",
  56077: "그대들 - 인간들이여! - 에게 낭송되는 이것은 많은 효용을 제공하는 명예로운 꾸란으로서",
  56078: "사람들의 시선으로부터 감추어져 있는 보존 서책 (알-라우흐 알-마흐푸드) 에 그 원본이 있으며",
  56079: "죄나 흠이 없도록 정화되어 있는 천사들만이 보존 서책을 만질 수 있노라.",
  56080: "꾸란은, 모든 피조물의 주님이신 하나님께서 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 내리신 성서라.",
  56081: "그대들 - 우상 숭배자들이여! -은 위대한 말씀인 이 꾸란을 부정하며 믿지 않는 것인가?",
  56082: "비가 내렸을 때 그대들은 \"이러이러한 별자리 때문에 비가 왔다”라고 말하였노라; 그대들은 하나님께서 베푸신 양식에 대해 감사하지 않고 오히려 그분의 은총을 부정하는 것인가?",
  56083: "(이전에 부활에 대한 일부 증거가 언급되었다면, 여기서는 하나님께서 창조를 반복하실 수 있음을 언급하고 있다. 인간은 죽음을 물리칠 수 없으나, 하나님께서는 죽음을 지정하시는 분이시다. 그러한 분이시기에 그분께는 생명을 부여하시는 일도 가능한 것이다)  그리하여 정녕 영혼이 목구멍에 이르렀을 때",
  56084: "그대들은 그때, 그대들 앞에서 죽음을 맞이하고 있는 병자를 바라보고 있노라.",
  56085: "하나님께서는 -그분의 지식과 능력과 그분의 천사들로써- 그대들보다 임종하는 자에 더 가까우나 그대들은 그 천사들을 보지 못하노라.",
  56086: "그러니, 정녕 그대들이 -그대들이 주장하는 것처럼- 심판을 위해 부활되지 않을 것이라면,",
  56087: "그대들이 진실을 말하는 자들이라면, 임종하는 자의 몸에서 빠져나오는 영혼을 그의 몸으로 다시 되돌려보라; 그대들은 그렇게 할 수 없을 것이라.",
  56088: "그러니 만약 임종하는 자가 선행을 위해 경쟁하던 자들 중의 하나라면",
  56089: "그가 가질 것은 피곤함이 없는 휴식과, 훌륭한 양식과 자비와, 원하는 모든 것을 즐길 수 있는 천국이라.",
  56090: "만약 임종하는 자가 우편의 동료들 중의 하나라면",
  56091: "그대는 그에 관해 걱정하지 말라: 그에게는 평화와 안녕이 있을 것이라.",
  56092: "만약 임종하는 자가 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 가 가져온 메시지를 부정하고, 올곧은 길을 벗어나 방황하던 자들 중의 하나라면",
  56093: "그가 받을 후한 대접은 뜨거움으로 끓어오르는 고온의 물이며",
  56094: "그의 피부는 타오르는 불지옥의 뜨거움으로 타버릴 것이라.",
  56095: "진실로 하나님께서 그대 -사도여! - 에게 전달한 이 말씀은 의심의 여지가 없는 확고한 진리라.",
  56096: "그러니 그대는 그대 주님의 완벽함을 찬양하고 그 어떤 결함도 없는 그분의 신성함을 떠올리라.",
  57000: "알-하디드 (철)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 이슬람 전파 및 분투를 위해 필요한 강한 신앙심과 물리적 강인함을 다루고 있다. 또한 이 장에는 영혼의 성장을 방해하는 장애물들을 제거할 수 있는 내용들이 담겨 있다. 그러한 이유로 이 장에서는 최선과 신앙에 관한 언급이 재강조되고 있다.\n•    요약 주해",
  57001: "(일곱) 하늘과 땅에 있는 피조물들이 하나님의 위엄을 드높이고 그분의 무결하심을 찬미하도다. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 운명의 결정에 있어 가장 지혜로우신 분이라.",
  57002: "(일곱) 하늘과 땅의 주권은 하나님 한 분께만 있으며, 그분께서는 원하시는 자에게 생명을 불어넣으시고 원하시는 자에게 죽음을 부여하시노라. 하나님께는 모든 것이 가능하기에 그분께 불가능한 일이란 없노라.",
  57003: "하나님 이전에는 그 무엇도 없었으며 그분 이후에 존재하는 것도 없노라. 또한 그분 위에는 그 무엇도 없으며 그분보다 가까운 존재도 없노라. 하나님께서는 모든 것을 알고 계신 분이기에 그분께서는 그 무엇도 놓치지 않으시노라.",
  57004: "하나님께서는 눈 깜짝할 사이에 모든 것을 창조하실 수 있는 분이시나, 그분께서는 일요일에 시작하여 금요일까지, 하늘과 땅을 육일 만에 창조하셨노라. 그 후 하나님께서는 당신의 존엄에 걸맞는 방식으로 권좌 위로 오르셨노라. 그분께서는 비나 씨앗과 같이 대지로 들어가는 것과, 식물과 광물 등 대지로부터 나오는 것과, 비나 계시처럼 하늘에서 내려오는 것과, 천사나 인간의 영혼과 행위 등 하늘 위로 올라가는 것을 알고 계시노라. 하나님께서는 그대들 - 인간들이여! - 이 어디에 있든 당신의 지식으로써 그대들과 함께 계시니, 그분께는 그 무엇도 감추어지지 않노라. 그리고 하나님께서는 그대들이 행하는 것을 지켜보고 계시는 분이기에 그대들의 어떤 행위도 그분께는 감추어지지 않으며, 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  57005: "(일곱) 하늘과 땅의 주권은 하나님 한 분께만 있으며 모든 일은 하나님 한 분께로 돌아가게 될 것이니, 그분께서는 심판의 날 창조물의 행위를 공정한 대가로써 보응하실 것이라.",
  57006: "하나님께서는 밤을 낮으로 들어가게 하시어 어둠이 찾아오게 하시고 사람들이 수면을 취할 수 있게 하시며, 낮을 밤으로 들어가게 하시어 빛이 찾아오게 하시고 사람들이 일을 시작할 수 있도록 하시노라. 실로 하나님께서는 인간들의 가슴 속에 있는 것을 알고 계시는 분이니 그 어떤 것도 그분께는 감추어지지 않노라.",
  57007: "그대들은 하나님과 그분의 사도를 믿고, 하나님께서 그대들에게 물려주신 재산을 이슬람법을 준수하며 쓰도록 하라. 그대들 중에 하나님을 믿고 그분의 길에서 희사금을 낸 자들은 천국이라는 커다란 보상을 얻게 될 것이라.",
  57008: "사도가 그대들을 하나님으로 초대하면서 그분을 믿으라 하는데도 무엇이 그대들로 하여금 하나님을 믿지 않도록 하는 것인가? 그대들이 믿는 자들이라면 하나님께서는 그대들의 아버지 (아담) 의 등에서 그대들 모두를 끄집어 내셨고, 그 때 그분께서는 그대들로부터 “저희는 하나님을 믿겠습니다”라는 신성한 약속을 받아내신 적이 있노라.",
  57009: "그대들을 불신과 무지의 암흑에서 믿음와 지식의 광명으로 꺼내기 위해 당신의 종복 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 분명한 징표를 내리시는 분이 하나님이시라. 실로 그대들을 인도하고 기쁜 소식을 전하는 사도를 보내주신 하나님께서는 그대들에게 인자하시고 자애로우신 분이라.",
  57010: "(일곱) 하늘과 땅의 유산은 하나님의 소유인데도 무엇이 그대들로 하여금 하나님의 길에서 희사하지 않도록 하는 것인가? 그대들 - 믿는 자들이여! - 은 단계가 동일하지 않노라: 메카 무혈 입성 이전에 하나님의 기쁨을 위해 자신의 재산을 희사하고 이슬람을 위해 불신자들과의 전투에 참전한 자는 메카 입성 이후에 자신의 재산을 희사하고 불신자들에 대항하여 싸운 자들과 같지 않노라. 메카 입성 이전에 희사하고 하나님의 길에서 참전한 자들은 메카 입성 이후에 희사하고 참전한 자들보다 하나님 보시기에 더 위대한 지위를 가지며 더 높은 단계에 있노라. 그러나 하나님께서는 그들 모두에게 천국을 약속하셨노라. 하나님께서는 그대들의 행위를 상세히 알고 계신 분이니 그대들의 모든 행위를 알고 계시며 그대들의 행위를 빠짐없이 보상하실 것이라.",
  57011: "하나님을 위해 흔쾌히 자신의 재산을 내놓는 자가 누구인가? 하나님께서는 그가 희사한 재산에 대한 보상을 증가시켜 주실 것이며 심판의 날 그에게는 천국이라는 풍성한 보상이 있을 것이라.",
  57012: "그날 그대는 믿는 남성들과 믿는 여성들을 볼 것이니 그들의 앞쪽과 오른쪽에서 빛이 뿜어져 나올 것이라. 목소리가 들리니 “오늘 그대들에게 기쁜 소식이 있노라. 궁궐 같은 저택들 아래에 강물이 흐르는 천국이 그대들의 소유이며 그대들은 그곳에서 영원히 거주할 것이라” 정녕 이러한 보상이야말로 그 무엇과도 비교되지 않는 위대한 성공이라.",
  57013: "(하나님께서는 그 날에 있을 믿는 자들의 모습을 언급하셨고, 여기서부터는 위선자들의 모습을 언급하고 계신다)  그날 남성 위선자들과 여성 위선자들은 믿는 자들에게 말할 것이라. “다리를 건널 때 꼭 필요하니 우리가 그대들의 빛을 빌려 쓸 수 있게 우리를 조금만 기다려 달라” 이에 그들을 비웃는 목소리가 들리더라. “그대들은 뒤로 돌아가라. 거기에 빛이 있다면 거기서 빛을 한번 찾아 보라” 그리하여 그들 사이에는 장벽이 쳐 지니 그 장벽에는 문이 있더라. 문 안쪽의 믿는 자들 근처에는 자비가 있고 문 바깥쪽의 위선자들 근처에는 벌이 있노라.",
  57014: "위선자들이 믿는 자들을 부르니 “우리가 이슬람을 믿으며 그대들과 함께 있지 않았던가? ” 믿는 자들이 대답할 것이라. “그러하오. 그대들은 우리와 함께 있었소. 그러나 그대들은 위선으로써 그대들 자신을 파괴하였고, 믿는 자들이 패배하여 그대들이 (내면의) 불신을 선포할 수 있길만을 간절히 기다렸으며, 하나님께서 믿는 자들을 도울 것인지를 의심하면서 죽음 후의 부활이 과연 있기나 한 것인지 의심하였소. 그리고 그대들은 죽음이 올 때까지 계속해서 헛된 희망을 품었고, 사탄은 하나님께 관해 그대들을 농간하였소”",
  57015: "(하나님께서 말씀하실 것이라. ) “그러니 오늘 너희 - 위선자들이여! - 가 하나님의 벌을 모면하기 위해 몸값을 바친대도 너희의 몸값은 수락되지 않으며, 공개적으로 하나님을 불신하던 자들의 몸값 역시도 수락되지 않노라. 너희와 불신자의 거주지는 불지옥이니 그곳이 너희에게 더 마땅한 장소라. 얼마나 비참한 귀착지인가”",
  57016: "하나님과 그분의 사도를 믿는 자들은 하나님을 떠올림으로써, 그리고 꾸란에 계시된 약속과 경고의 말씀을 읽음으로써 마음의 평안을 찾아야 할 것이라. 이전에 토라를 받았던 유대인들과 복음을 받았던 기독교인들은 그들 이후에 새로운 선지자가 도래하기까지 기나긴 시간이 흘렀고 그동안 그들의 마음은 모질어졌노라. 그들 대부분은 하나님께 대한 순종을 거부하는 자들이었으니, 믿는 자들은 그들처럼 되지 말아야 할 것이라.",
  57017: "그대들은 하나님께서 척박한 대지에 목초를 자라나게 하시어 그곳에 생명을 불어넣으심을 알라. 실로 하나님께서는 그대들 - 인간들이여! - 을 위해 당신의 전능하심과 유일하심을 가리키는 명백한 증거를 보여 주셨으니 이는 그대들이 그러한 증거를 충분히 이해하기 위함이라; 죽어 있던 대지를 살리는 분이 하나님이시라면, 죽어 있던 그대들을 부활시키고 굳어 있던 그대들의 마음을 부드럽게 하는 일도 그분께는 가능하노라.",
  57018: "자신이 가진 재산의 일부로써 흔쾌히 자선을 베풀면서도 그것으로써 은근히 자랑하거나 타인에게 해를 끼치지 않는 남성들과 여성들은 그들의 보상이 배가될 것이니, 그들은 최소 열 배에서 칠백 배까지 혹은 그보다 더 많은 축복을 받을 것이라. 그리고 그들에게는 천국이라는 풍성한 보상이 있을 것이라.",
  57019: "하나님을 믿고 하나님의 사도들을 구분 없이 모두 믿는 자, 이들이야말로 진실된 신앙인이라. 하나님께 가까운 곳에 있는 순교자들에게는 그들을 위해 준비된 보상이 있으며 심판의 날 그들의 앞쪽과 오른쪽에서 빛이 발산할 것이라. 그러나 하나님과 그분의 사도들을 불신하며 하나님의 징표를 부정하는 자들은 작열하는 불지옥의 거주자들로서 그곳에서 영원히 거주하니 결코 그곳으로부터 빠져나가지 못할 것이라.",
  57020: "현세의 삶이란 한낱 육체의 놀음과 마음의 유희와 외모의 치장일 뿐이며, 그대들은 이 현세의 삶에서 서로에게 소유한 것을 과시하며 더 많은 재물과 자식을 갖기 위해 경쟁을 일삼더라. 현세의 삶은 마치 비와도 같아서 농부들은 비를 맞은 후 자라나는 작물을 보고 기뻐하지만 이내 작물은 시들어 말라버리노라. 그리하여 그대는 푸르던 작물이 누렇게 변하는 것을 보며 그 후 하나님께서는 그것을 메말라 부서지는 조각으로 만드시노라. 내세에는 불신자와 위선자에게 내려질 혹독한 벌이 있으며 믿는 자를 위해 준비된 하나님의 용서와 기쁨이 있노라. 현세의 삶이란 한낱 사그러질 유희에 불과하기에, 현세의 일시적 향락을 위해 내세의 영원한 기쁨을 놓치는 자는 속임을 당해 손실을 보는 자들이라.",
  57021: "그대들 - 인간들이여! - 은 참회 등 하나님께 가까이 다가가는 선행을 실천함에 서로 경쟁하라. 그로써 그대들은 하나님의 용서를 받을 것이며 천국에 들어가게 될 것이라. 천국의 너비는 하늘과 땅의 너비이며 그곳은 하나님께서 당신과 당신의 사도들을 믿는 자들을 위해 준비하신 곳이라. 이같은 보상은 하나님의 은혜로서 그분의 종복 중에 원하시는 자에게 주시노라. 하나님께서는 믿는 자들에게 내려진 위대한 은혜의 소유자시라.",
  57022: "사람들이 겪는 가뭄 등 대지에서의 시련과 그들의 생명과 관련한 모든 시련은, 하나님께서 그러한 시련을 발생시키기 이전에 이미 보존 서책에 기록되어 있었노라. 이것은 실로 하나님께는 손쉬운 일이라.",
  57023: "그리하여 그대들 - 인간들이여! - 이 받지 못한 것에 슬퍼하지 아니하고 하나님께서 그대들에게 주신 것에 실없이 기뻐하지 않기 위해서라. 하나님께 받은 것으로써 사람들에게 거만을 떨면서 잘난 체하는 자가 있다면 하나님께서는 그러한 자를 사랑하지 않으시노라.",
  57024: "그들은 손실자이니, 의무적으로 써야 할 재산에 인색해 하면서 사람들에게 자신들처럼 인색하기를 권하기 때문이라. 만약 하나님께 순종하지 않고 돌아서는 자가 있다면 그는 하나님께 해를 끼치지 못하며 해를 입는 자는 오히려 자기 자신일 뿐이라. 실로 하나님 그분께서는 스스로 풍족하신 분이기에 사람들의 순종을 필요로 하지 않으시며, 그분께서는 어떠한 상황에서도 영광을 받으시는 분이라.",
  57025: "실로 하나님께서는 그분의 사도들을 분명한 증거와 함께 보내셨으며 그들과 함께 성서와 저울을 내리시어 사람들이 공정함을 실천할 수 있도록 하셨노라. 그리고 하나님께서는 철을 내려 보내셨으니 그 안에는 무기를 제조하는 등의 강력한 힘과, 제조와 가공 등 사람들을 위한 유용함이 있노라. 그렇게 철을 내리신 것은 하나님께서, 종복들 중 보이지 않게 당신과 당신의 사도들을 돕는 자가 누구인지 사람들에게 드러내시기 위함이라. 실로 하나님께서는 그 누구도 감히 제압할 수 없는 가장 강하시고 존엄하신 분이라.",
  57026: "실로 하나님께서는 노아 (누흐) 와 아브라함 (이브라힘) (그들에게 평화가 깃들기를) 을 사도로 보내셨으며, 그들의 후손에게 선지자직과 계시서를 주셨노라. 그들의 후손들 중에는 올바른 길로 인도된 자가 있으나, 그들 대부분은 하나님께 순종하지 않고 거역하는 자들이라.",
  57027: "그 후 하나님께서는 여러 사도들을 뒤이어 보내셨고, 그들은 각자의 공동체에 순차적으로 보내졌노라. 하나님께서는 그들의 뒤를 이어 마리아 (마르얌) 의 아들 예수를 보내시면서 그에게 복음을 주셨고, 그분께서는 예수의 사도직을 믿고 그를 따르던 자들의 마음 속에 인자함과 자비심을 두셨으니 그들은 서로가 서로를 사랑하면서 자애를 베풀더라. 그러나 그들은 종교를 과장하기 시작했고, 하나님께서 허락하신 결혼과 여러 즐거움을 멀리하기 시작하였노라. 정작 하나님께서는 그러한 것을 명하신 적이 없으나 그들 스스로가 자신의 종교에 새로운 것을 만들어 내었노라. 실로 하나님께서 그들에게 명하신 것이란 오직 당신의 기쁨을 추구하는 것이었으나 그들은 그러한 하나님의 명령을 실천하지 않았노라. 그리하여 하나님께서는 그들 중에 있던 일부 믿는 자들에게 합당한 보상을 주었으나 그들 대부분은 하나님에 대한 순종을 거부하며 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 가져온 메시지를 부정하는 자들이라.",
  57028: "하나님을 믿고 그분의 법률을 지키는 자들이여! 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 두려워하고 그분의 사도를 믿으라. 그리하면 하나님께서는 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에 대한 그대들의 믿음과 이전 사도들에 대한 그대들의 믿음을 보시어 그대들에게 두 배의 보상을 주실 것이라. 그리고 하나님께서는 그대들에게 현세의 삶에서 길잡이가 될 광명을 주실 것이니 그대들은 심판의 날 그 빛으로써 무사히 다리 (씨라뜨) 를 건널 것이라. 또한 그렇게 할 때 하나님께서는 그대들을 용서해 주실 것이니 그대들의 죄를 가려 주시고 그 죄에 관하여 그대들을 질책하지 않으실 것이라. 하나님께서는 종복들을 너그러이 용서하시는 분이며 그들에게 자애로우신 분이라.",
  57029: "하나님께서는 그대들 - 믿는 자들이여! - 에게 당신께서 준비해 주신 풍성한 보상에 대해 설명해 주셨고, 이는 이전에 성서를 받은 유대인과 기독교인이 다음의 사실을 알 수 있도록 하기 위함이라; 그들은 하나님의 은혜에 관하여 아무런 권한이 없기에 자신들이 원하는 자에게 그 은혜를 주거나 막을 수 없으며, 하나님의 은혜는 당신의 손에 달려 있으므로 당신께서 원하시는 종복에게 그 은혜를 선사하시는 것이라. 이렇듯 하나님께서는 위대한 은혜의 소유자로서 당신께서 원하는 종복에게 은혜를 특정하시노라.",
  58000: "알-무자딜라 (논쟁하는 여성)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 하나님의 완전하고도 포괄적인 지식을 드러냄으로써, 그분께서 우리를 지켜보고 계심을 상기시키고 그분의 명령을 거역함이 얼마나 엄중한 일인지 경고하고 있다.\n•    요약 주해",
  58001: "실로 하나님께서는 한 여성 (카울라 빈트 싸을라바) 의 말씀을 들으셨노라. 그녀는 그대 - 사도여! - 에게 찾아가 자신의 남편 (아우스 이븐 앗-싸미트) 에 관하여 판결을 구하니, 그녀의 남편이 자신과 부부 관계를 갖지 않겠다고 맹세했기 때문이라. 그녀는 남편의 행동에 관하여 하나님께 호소하였고, 하나님께서는 그대 둘의 대화 내용 모두를 듣고 계시노라. 실로 하나님께서는 인간의 말 한마디도 빠짐없이 들으시며 그들의 일거수 일투족을 지켜보고 계신 분이라.",
  58002: "자신의 아내에게 \"당신은 나에게 있어 내 어머니의 뒷등과도 같소\" (디하르) 라고 말하는 자들이 있으니 그들은 이 말로써 진정 거짓말을 한 것이라. 그들의 아내는 그들의 어머니가 아니며 그들의 어머니란 오직 그들을 낳아 준 여성일 뿐이라. 그들의 말은 따라서 비난 받아 마땅한 거짓된 말이라. 진실로 하나님께서는 관용을 베푸시고 너그러이 용서하시는 분이니 그들을 위해 속죄의 규정을 제정하심으로써 그들이 죄에서 벗어날 수 있도록 하셨노라.",
  58003: "아내가 어머니의 등과 같다고 거짓된 말을 한 자가 다시 부부 관계를 가지려 할 때는 반드시 성관계 이전에 한 명의 노비를 해방해야 하노라. 이 명령을 통하여 그대들은 더 이상 이러한 거짓 선언을 하지 않을 것이라. 하나님께서는 그대들이 행하는 일에 밝으신 분이니 그대들의 어떤 행위도 그분께 감추어지지 않노라.",
  58004: "그대들 중에 해방할 노비를 가지지 못한 자는 아내와의 성관계를 가지기 전에 두 달 연속으로 단식을 실시해야 하노라. 두 달 연속으로 단식을 할 능력이 없는 자는 육십 명의 불우한 자들에게 음식을 제공해야 하노라. 하나님께서 제정하신 이 규범은 그대들이 그분께서 내린 명령을 지키도록 하기 위함이라. 또한 이 규범은 인간이 넘어서는 안 될 하나님의 경계를 알려 주기 위함이라. 하나님의 규범과 그분의 경계를 부정하는 자들은 고통스런 벌을 받게 될 것이라.",
  58005: "실로 하나님과 그분의 사도를 적으로 대하는 자들은 그들 이전의 공동체들이 그랬던 것처럼 굴욕과 수모를 겪을 것이라. 이미 하나님께서는 분명한 징표를 내렸노라. 하나님과 그분의 징표와 사도를 불신하는 자들에게는 치욕의 벌이 있을 것이라.",
  58006: "그날 하나님께서는 한 명도 남겨놓지 않고 모두를 부활시키시어 현세에서 그들이 행했던 악행을 알려 주실 것이라. 하나님께서는 그들의 행위 모두를 기재하셨으나 정작 그들은 자신의 행위를 잊었더라. 그들은 작은 것이든 큰 것이든 그들의 모든 행위가 기록부에 적혀 있음을 발견할 것이라. 하나님께서는 모든 것을 지켜 보시는 분이니 그들의 어떤 행위도 숨겨질 수 없노라.",
  58007: "하나님께서 (일곱) 하늘에 있는 것과 대지에 있는 것을 알고 계심을 그대 - 사도여! - 는 알지 못하는가. 그분께는 그 무엇도 감추어지지 않노라. 세 명이 모여 비밀스런 대화를 나눌 때마다 하나님께서는 그들의 네 번째시니 그분의 지식으로써 함께하심이라. 다섯 명이 모여 비밀스런 대화를 나눌 때마다 하나님께서는 그들의 여섯째시니 그분의 지식으로써 함께하심이라. 모인 자들의 숫자가 그보다 더 적든 더 많든, 그들이 어디에 있든지 간에 하나님께서는 당신의 지식으로써 항상 그들과 함께 하시노라. 그 후 부활의 날 하나님께서는 그들에게 자신들이 행했던 것을 알려 주실 것이라. 실로 하나님께서는 모든 것을 알고 계신 분이니 그분께는 그 무엇도 감추어지지 않노라.",
  58008: "그대 - 사도여! - 는 유대인들을 보지 않았던가: 그들은 믿는 자들을 볼 때마다 비밀스럽게 대화하였고 하나님께서는 이에 그들의 비밀 대화를 금지하셨으나 그 후에도 그들은 비밀 대화를 반복하였노라. 그들은 그들만의 비밀 대화를 가지며 믿는 자들을 험담하는 죄를 범하고 그들에 대한 적의를 드러내면서 하나님의 사도가 내린 명령에 불복하였노라. 그들은 그대 - 사도여! - 를 만날 때면 하나님께서 그대에게 인사하지 않는 방식으로 그대에게 인사하니 \"그대에게 독이 깃들기를\" (앗-싸무 알라이크) 이라고 말하며 그대의 죽음을 기도하였노라. 그들은 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 를 부정하면서, \"하나님은 왜 우리가 하는 말을 벌하지 않는 것인가? 그가 정녕 선지자였다면 하나님은 진작 우리를 벌하였을 것이라”라고 말하였노라. 그들의 말에 대한 징벌은 지옥으로 충분하도다. 그들은 타오르는 지옥 불로 고통 받을 것이니 그들이 귀착할 장소는 얼마나 사악한 곳인가.",
  58009: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 유대인처럼 죄와 적의와 사도에 대한 거역으로 가득한 비밀 대화를 나누지 말고, 하나님을 거역하지 않으며 그분께 복종하는 비밀 대화를 가지라. 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 두려워하라. 심판의 날 그대들은 그분께로 소집될 것이니 그분께서 그대들의 행위를 심판하신 후 그대들에게 보상과 징벌을 내리실 것이라.",
  58010: "죄와 적의와 사도에 대한 거역으로 가득한 비밀 대화는 사탄이 자신을 따르는 자들을 유혹하고 속삭임으로써 비롯되는 것이라. 그렇게 사탄은 믿는 자들을 슬프게 하려 하니, 믿는 자들은 그들의 이러한 비밀 대화가 자신들을 해하기 위한 책략이라 느낄 것이기 때문이라. 그러나 하나님의 의지와 원하심이 없는 이상 사탄은 결코 믿는 자들을 해치지 못할 것이라. 그러니 믿는 자들은 그 모든 일에 있어 오직 하나님 한 분께만 의탁하도록 하라.",
  58011: "(이전에서 하나님께서는 말할 때의 예절에 대해 언급하셨고, 이제 그분께서는 모임에서의 예절에 관해 말씀하고 계신다. )  하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 앉은 자리에서 자리를 넓혀 달라고 요청 받는다면 그대들은 자리를 넓혀 주라. 그러면 하나님께서 그대들을 위해 현세와 내세에서의 삶을 넓혀 주실 것이라. 어떤 모임에서 중요한 사람이 도착하였고 그의 앉을 자리를 위해 일어나 달라고 요청 받는다면 그대들은 일어나 주라. 그러면 하나님께서 그대들 중에 믿는 자들과 지식을 부여 받은 자들의 위치를 크게 높여 주실 것이라. 하나님께서는 그대들의 행위를 상세히 알고 계신 분이니 그대들의 어떤 행위도 그분께 감추어지지 않으며, 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  58012: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 그대들이 사도와 사적인 대화를 가지고자 할 때는 대화를 하기 이전에 희사금을 베풀라. 이렇게 희사금을 베푸는 것이 그대들에게 더 좋은 것이며 더 깨끗한 것이니, 하나님에 대한 복종으로써 마음이 정화되기 때문이라. 만약 그대들이 희사할 재산을 구하지 못했다면 희사 없이 대화를 진행해도 무방하노라. 실로 하나님께서는 종복의 죄를 너그러이 용서하시는 분이며, 감당할 수 없는 의무는 부과하지 않으시는 자애로우신 분이라.",
  58013: "하나님의 사도와 사적인 대화를 할 때마다 희사금을 베풀면 그대들이 가난해지지 않을까 걱정하는 것인가? 그리하여 그대들이 하나님께서 명령하신 것을 행하지 않았다면 그분께서는 희사금 납부를 의무로 두지 않으심으로써 그대들을 용서하여 주셨노라. 그러니 그대들은 성실히 예배를 드리고 그대들의 재산에서 의무 희사금을 내며 하나님과 그분의 사도를 따르라. 하나님께서는 그대들이 행하는 일에 밝으신 분이니 그대들의 어떤 행위도 그분께 감추어지지 않으며 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  58014: "그대 - 사도여! - 는 위선자들을 보지 않았던가? 그들은, 불신과 불복종으로 하나님의 노여움을 산 유대인들을 절친한 친구로 삼았노라. 저 위선자들은 믿는 자들의 일원도 유대인들의 일원도 아니면서 두 무리 사이를 배회하였노라. 그들이 그대들에게 말하기를 자신들은 무슬림이며, 유대인들에게 무슬림에 관한 정보를 흘린 적이 없다고 맹세하나 실로 그들은 거짓말을 하는 것이라.",
  58015: "하나님께서는 그들을 위해 내세에서 혹독한 벌을 준비하셨으니 그들은 불지옥의 가장 낮은 곳에서 거주하게 될 것이라. 실로 그들이 현세에서 저지르던 불신 행위는 얼마나 추악한 것인가.",
  58016: "그들은 무슬림임을 맹세함으로써 자신의 생명과 재산 유지를 도모하고, 내면의 불신을 숨긴 채 겉으로는 무슬림 행세를 하더라. 그렇게 그들은 무슬림들을 속임으로써 사람들이 하나님의 길로 들어섬을 가로막으니 그들은 치욕의 벌을 받게 될 것이라.",
  58017: "그들의 재산도 그들의 자손도 하나님 앞에서 그들에게 그 어떤 도움도 되지 못할 것이라. 저들은 불지옥의 거주자들이니 실로 그들은 그 안에서 영원히 머물며 끊임없는 고통을 받을 것이라.",
  58018: "그날 하나님께서는 그 어떤 누구도 남김없이 모두를 부활시키시어 그들을 심판하실 것이라. 이 때 그들은 하나님께 맹세하며 말하기를 그들은 불신과 위선을 따른 적이 없으며 하나님께서 기뻐하시는 선행을 실천하는 신앙인이었다고 하였노라. 그들이 마치 현세에서 그대들에게 자신들이 무슬림이라 맹세했던 것처럼 그렇게 하나님께 맹세하면서, 이러한 맹세가 그들에게 유용함을 가져다 주거나 해악을 막아줄 것이라 생각하였노라. 현세에서도 그리고 내세에서도 줄곧 거짓 맹세만을 해대는 그들이야말로 진정한 거짓말쟁이들이라.",
  58019: "사탄이 그들을 덮치니, 속삭이는 말로 그들을 망각케 하여 그들이 하나님을 떠올리지 못하도록 하였노라. 그리하여 그들이 하는 행동이란 하나님을 기쁘게 하는 선행이 아니라 하나님의 분노를 유발하는 악행 뿐이라. 저들은 사탄의 동맹군이자 추종자들이라. 진실로 사탄의 동맹군과 추종자들, 그들이야말로 현세와 내세에서의 손실자들이니, 그들은 올바른 길을 버리고 방황의 길로 들어섰으며 천국이 아닌 지옥을 선택했기 때문이라.",
  58020: "실로 하나님과 그분의 사도를 적으로 대하는 자들은 불신을 저질렀던 이전 공동체들과 함께 할 것이니 그들은 하나님께서 현세와 내세에서 커다란 굴욕을 맛 보게 할 자들이라.",
  58021: "하나님께서는 그분의 완전한 지식으로써 운명을 기록하셨으니 “진실로 나와 나의 사도들은 논리와 힘으로써 적들에 대해 정녕코 승리를 거둘 것이라” 하셨노라. 실로 하나님께서는 그분의 사도들을 도우심에 강하신 분이며 그들의 적을 응징하심에 존엄하신 분이라.",
  58022: "하나님과 부활의 날을 믿는 사람들이 하나님과 그분의 사도를 대적하는 자들을 사랑으로 대하고 보호자로 삼는 경우를 그대 - 사도여! - 는 발견하지 못할 것이라. 하나님과 그분의 사도를 대적하는 자들이 믿는 자들의 아버지이거나 자식이거나 형제이거나 가까운 친척일지라도 그러할 것이라. (이는, 신앙을 가진 자는 하나님과 그분의 사도의 적을 사랑할 수 없기 때문이고, 신앙이라는 연결 고리는 그 어떤 연결 고리보다 지고하기 때문이며, 신앙과 다른 요소가 충돌할 때는 신앙이 우선시 되기 때문이다. ) 이러한 신앙인들은 하나님께서 그들의 마음속에 흔들리지 않는 믿음을 심어주신 자들이며, 하나님께서 명백한 증거와 광명으로써 그들을 강하게 해주신 자들이라. 그리고 하나님께서는 그들을 영원의 천국에 들게 하실 것이니, 천국의 나무들 아래에는 강이 흐르노라. 그들은 천국에서 영원히 머물면서 끊이지 않는 기쁨을 만끽할 것이라. 하나님께서 그들에 흡족하시니 그분께서는 결코 그들에게 분노하시지 않으시며, 그들도 하나님께 기뻐하니 그들은 그분께서 주신 영원한 즐거움과 그분을 두 눈으로 볼 수 있는 완전한 기쁨을 누리노라. 이들은 하나님의 명령과 금지를 철저히 준수하는 그분의 동맹군이라. 진실로 하나님의 동맹군 그들이야말로 성공한 자들이니, 그들은 현세와 내세에서 그들이 원하던 좋은 것을 얻고 그들이 두려워하던 나쁜 것으로부터 벗어날 것이라.",
  59000: "알-하슈르 (추방)\n계시 분류: 메디나\n•    계시 목적    \n하나님께서는 유대인과 위선자들을 능욕하시고 분열시키셨으며, 반대로 신앙인들은 단결시키셨다. 이 장은 이러한 하나님의 무한한 능력과 그분의 존엄하심을 드러내고 있다.\n•    요약 주해",
  59001: "(일곱) 하늘과 땅에 있는 피조물들이 하나님의 위엄을 드높이고 그분의 무결하심을 찬미하도다. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이라.",
  59002: "하나님을 불신하고 그분의 사도 무함마드를 부정하는 ‘안-나디르’ 부족을 그들의 거주지인 메디나에서 나오게 하신 분이 하나님이시니, 메디나에서 샴 지역으로의 첫 번째 추방이라. (그들은 토라를 계시받은 유대인들로서, 그들이 무슬림들과의 조약을 위반하고 우상 숭배자들과 밀약을 맺었기 때문이다. 그리하여 하나님께서는 그들을 시리아 주변의 샴 지역으로 추방하셨다. ) 그들이 가진 무력과 병력이 막강하였기에 그대들 -믿는 자들이여! - 은 그들이 자신의 거주지에서 쫓겨나리라고는 상상조차 하지 못하였노라. 그들은 자신들이 지은 높은 요새가 하나님의 징벌로부터 자신들을 막아 줄 것이라 생각하였으나 하나님의 징벌은 그들이 예상치 못한 곳에서 그들에게로 도래하였노라. 하나님께서는 당신의 사도에게 그들과 전투하여 그들을 거주지에서 추방하라 명령하셨도다. 그리고 하나님께서는 그들의 마음속에 공포를 불어넣으셨노라. 그들은 집 내부에 있는 것을 자신들의 손으로 직접 파괴함으로써 무슬림들이 그것을 사용하지 못하게 하였고, 무슬림들은 그들의 집 외부를 파괴하였노라. 그러니 시각을 지닌 자들이여, 이로써 교훈을 얻으라: 저들은 자신들이 저지른 불신으로 인해 징벌을 받았으니 그들처럼 되지 말라. 그들처럼 불신할 때 그대들도 그들이 받은 징벌을 받을 것이라.",
  59003: "하나님께서 그들에게 추방을 운명짓지 않으셨다면 실로 그분께서는 현세에서 -그들의 형제인 '알-꾸라이다' 부족에게 하셨던 것처럼- 그들에게 전쟁터에서의 전사와 생포의 벌을 내리셨을 것이라. 그리고 내세에서 그들은 불지옥의 벌을 받으며 그곳에서 영원히 머물 것이라.",
  59004: "그러함은 그들이 불신으로써 그리고 조약의 위반으로써 하나님과 그분의 사도에게 대적하였기 때문이라. 하나님께 대적하는 자가 있다면 실로 하나님께서는 응징함에 엄하신 분이니 그는 곧 하나님의 응징을 맛볼 것이라.",
  59005: "그대들 -믿는 자들이여! - 이 ‘안-나디르’ 부족과의 전쟁에서 하나님의 적들을 자극하기 위해 야자수를 벤 것이나, 그대들이 효용을 얻기 위해 줄기가 성한 채로 야자수를 남겨둔 것은 하나님의 허락에 의한 것이며, 그들의 주장처럼 지상에 해악을 퍼뜨리기 위함이 아니라. 그리고 이는 하나님께서, 조약을 위반하고 배반을 선택하여 그분을 거역한 유대인들에게 치욕을 주시기 위함이라.",
  59006: "‘안-나디르’ 부족이 도망치며 남긴 재산은 하나님께서 그분의 사도에게 선사하신 공물 (空物) 전리품으로서, 그대들은 이 전리품을 획득하기 위해 말이나 낙타를 타고 전장으로 돌진한 적이 없으며 그 어떠한 수고도 들인 적이 없노라. 그러나 하나님께서는 그분의 사도들에게 그분께서 원하시는 자를 상대로 통치권을 부여하시니, 하나님께서는 그분의 사도가 ‘안-나디르’ 부족이 거주하던 곳을 무혈 입성케 하시어 사도가 그 지역을 통치하도록 하셨노라. 하나님께서는 모든 것이 가능한 분이시니 그분께 불가능한 일이란 있을 수 없노라.",
  59007: "유대인 마을 거주민들이 남기고 간 재산은, 하나님의 사도가 전투 없이 획득하도록 허락하신 하나님의 전리품으로서, 하나님께서 원하시는 자에게 선사하는 것이라. 이 공물 (空物) 전리품은 사도가 가지며, 사도의 친척인 하쉼 가문과 알-뭇딸립 가문도 이 전리품을 분배 받으니 그들은 사도의 친척이라는 이유로 평소에 의무 희사금 (자카) 을 받지 못하기에 이 전리품은 그에 대한 보상이라. 그리고 고아들과 불우한 자들과 가진 것이 다 떨어진 나그네도 이 전리품을 분배 받노라. 이는, 공물 전리품이 부유한 자들의 전유물이 되어 가난한 자들에게는 혜택이 돌아가지 않음을 방지하기 위함이라. 사도가 그대들 -믿는 자들이여! - 에게 나누어 준 공물 전리품은 받아들이고, 그가 그대들에게 주지 않은 것은 단념하라. 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금지하신 것을 멀리함으로써 하나님을 두려워하라. 하나님께서는 응징함에 엄하신 분이니 그대들은 그분의 벌을 유의하라.",
  59008: "공물 전리품의 일부는, 하나님의 길에서 메카에서 메디나로 이주한 가난한 무슬림들에게도 분배되니, 그들은 하나님께서 주시는 현세에서의 양식과 내세에서 얻게 될 그분의 기쁨을 추구하던 중 재산과 자식들을 놓아두고 자신들의 거주지로부터 추방당한 자들이라. 그들은 하나님을 돕고, 하나님의 길에서 분투하면서 하나님의 사도를 도우니 이들은 실로 흔들리지 않는 굳은 신앙을 지닌 자들이라.",
  59009: "(이전 구절에서 하나님께서는 메카 이주민을 칭찬하셨다. 이제 여기서 그분께서는 메디나 정착민을 칭찬하고 계신다. )  그리고 ‘안싸르’ (메디나 정착민) 는 ‘무하지룬’ (메카 이주민) 이전에 메디나에 정착하고 있던 자들로 하나님과 그분의 사도를 믿기로 결정하였으니, 그들은 메디나로 이주해온 메카 이주민들을 사랑하더라. 메카 이주민은 하나님의 길에서 공물 전리품을 받았으나 메디나 정착민은 그러한 것을 받지 못하였고, 그럼에도 메디나 정착민들은 그들이 받은 것에 관하여 시기나 질투의 감정을 느끼지 않았노라. 그리고 메디나 정착민은 자신들의 절실한 필요에도 불구하고 메카 이주민에게 현세에서 필요한 여러 것들을 양보하였노라. 재물에 집착하는 자신의 인색함을 벗어나 하나님의 길에서 재산을 희사하는 자가 있다면 그들은 결국 그들이 원하던 좋은 것을 얻고 그들이 두려워하던 나쁜 것으로부터 벗어날 것이니, 그들이야말로 진정으로 성공한 자들이라.",
  59010: "그리고 그들 이후에 온 자들은 그들의 모범을 따르며 이렇게 말하더라. “저희의 주님이시여! 저희를 용서하여 주시고, 하나님과 그분의 사도에 대한 신앙심으로써 저희를 앞서간 저희의 형제들을 용서하여 주십시오. 그리고 저희의 마음속에 믿는 자들에 대한 미움이나 앙심의 감정을 두지 말아 주십시오. 저희의 주님이시여! 실로 당신은 종복들에게 인자하시고 그들에게 자애로우신 분입니다”",
  59011: "내면의 불신을 숨기면서 겉으로는 믿는 척 하는 자들을 그대는 보지 않았던가? 그들은 불신으로써 서로 형제가 된 유대인에게 말하였노라. “그대들의 거주지에 머물러 있으시오. 우리는 그대들을 배신하지 않을 것이며 적들에게 그대들을 내주지 않을 것이오. 만약 무슬림들이 그대들을 추방한다면 우리는 그대들과 함께 메디나를 나감으로써 그대들을 지원할 것이며, 우리는 그대들과 함께 메디나로 나가려는 우리를 막는 그 누구도 결코 따르지 않을 것이오. 그리고 누군가가 그대들에게 전투를 걸어온다면 우리는 진실로 그대들을 도울 것이오” 실로 하나님께서는 저 위선자들이 거짓을 말하는 자들임을 증언하시노라: 유대인이 추방되면 그들도 함께 나갈 것이라는 말과, 전투가 시작되면 그들도 함께 싸울 것이라는 말은 모두 거짓이라.",
  59012: "무슬림들이 유대인들을 추방한다 하더라도 위선자들은 유대인들과 함께 나가지 않을 것이며, 누군가가 유대인들을 공격해 온다 하더라도 위선자들은 유대인들을 돕지 않을 것이라. 만약 위선자들이 유대인들을 돕기 위해 무슬림들과 싸울지라도 결국 위선자들은 뒷꽁무니를 빼며 도망할 것이라. 그리하여 위선자들은 그 누구로부터도 도움을 받지 못할 것이며 하나님께서는 그들에게 굴욕을 맛 보게 할 것이라.",
  59013: "실로 그대들 -믿는 자들이여! - 은 위선자와 유대인에게 있어 하나님보다 더 무서운 존재라. 그렇게 그들이 그대들을 심히 두려워하면서도 하나님은 적게 두려워하는 이유는 그들이 이해하지도 알지도 못하는 무리이기 때문이라: 만약 그들이 제대로 이해했더라면 하나님이야말로 가장 두려워해야 할 존재라는 것을 알았을 것이니, 그대들이 그들을 제압하도록 허락한 분은 다름 아닌 하나님이시라.",
  59014: "그들이 요새로써 사방이 보호된 마을 안에 있거나 장벽이 뒤에 있어 더 이상 물러날 수 없는 곳에 있지 않는 이상, 그들이 일치 단결하여 그대들과 싸우는 일은 없을 것이라. 그들 내부의 적의로 인하여 그들은 심각한 알력을 겪고 있도다. 그대는 그들이 결집하여 한 목소리를 낸다고 생각하나 그들의 마음은 뿔뿔이 흩어져 있도다. 그들 사이의 분열과 적의는 그들이 이성을 쓸 줄 모르는 무리이기 때문이니, 만약 진리를 알았더라면 그들은 하나의 진리를 따르면서 의견을 달리하지 않았을 것이라.",
  59015: "저 유대인들은 불신과 징벌에 있어 그들 바로 이전에 있었던 메카의 우상 숭배자들과 비슷하니 그들은 자신들이 저지른 불신의 참담한 결말을 맛보았노라; 우상 숭배자들은 ‘바드르’ 전투를 통해 전사와 생포의 벌을 받았도다. 그리고 내세에서 그들은 고통스런 벌을 받을 것이라.",
  59016: "유대인들이 위선자의 말에 귀기울이는 것은 마치 사탄이 인간에게 불신을 속삭이는 것과 같도다: 인간이 사탄의 유혹에 넘어가 불신하였을 때 사탄이 그에게 말하니 “실로 나는 당신의 불신으로부터 결백하오. 실로 나는 만유의 주님이신 하나님이 두렵소” 하였노라.",
  59017: "그리하여 추종받던 사탄과 추종하던 인간은 심판의 날 불지옥에서 영원히 머물 것이니 그것이 사탄과 그를 따르던 자들의 최후라. 그리고 이는 하나님의 경계를 벗어난 부당한 자들에 대한 징벌이라.",
  59018: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 그분을 두려워하라. 그리고 모든 이는 심판의 날 하나님 앞에서 제시할 선행이 무엇인지 유념하도록 하라. 그대들은 하나님을 경외하라. 실로 하나님께서는 그대들이 행하는 일에 밝으신 분이니 그분께는 그대들의 어떤 행위도 감추어지지 않으며 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  59019: "하나님께서 명령하신 것을 어기고 그분께서 금지하신 것을 범함으로써 하나님을 망각한 자들이 있으니 그대들은 그들처럼 되지 말라. 그에 대한 벌로써 하나님께서는 그들이 자기 자신을 망각케 하셨고, 이로 인해 그들은 하나님의 분노와 징벌로부터 자신을 지켜줄 선행을 실천하지 않았노라. 하나님을 잊어 버린 저들은 실로 하나님께 복종하지 않는 거역자들이라.",
  59020: "불지옥의 거주지와 천국의 거주자는 동일하지 않으니 현세에서 그들의 행위가 다른 것처럼 내세에서 그들이 받을 보응이 다르노라. 천국의 거주자들이야말로 성공한 자들이라. 그들은 그들이 원하던 좋은 것을 얻고 그들이 두려워하던 나쁜 것으로부터 벗어났노라.",
  59021: "만약 하나님께서 이 꾸란을 산 위에 내리셨다면 그대 -무함마드여! - 는 그 거대한 산이 하나님에 대한 엄청난 두려움으로 인해 곤두박질치고 산산히 쪼개짐을 보았을 것이라: 이는 꾸란이 가진 위대한 교훈과 엄중한 경고의 메시지 때문이라. 이는 하나님께서 인간들을 위해 드는 예로서 그들이 이성을 사용하여 꾸란의 교훈을 숙고하기 위함이라.",
  59022: "그분은 하나님으로서 하나님 이외에는 그 누구도 경배받을 권리가 없노라. 하나님께서는 보이지 않는 것과 보이는 것을 알고 계시는 분으로서 그분께는 그 무엇도 감추어지지 않노라. 하나님께서는 현세와 내세에서 가장 자비로우시고 가장 자애로우신 분으로서 그분의 자비는 모든 것을 아우르노라.",
  59023: "그분은 하나님으로서 하나님 이외에는 그 누구도 경배받을 권리가 없노라. 하나님께서는 제왕이시며, 그 어떤 부족함도 없으신 성스러우신 분이며, 그 어떤 결점도 없으신 완벽하신 분이며, 사도들에게 명백한 징표를 주심으로써 그들의 사도직을 확증하시는 분이며, 인간의 모든 행위를 지켜보시는 분이며, 그 누구도 감히 제압할 수 없는 가장 존엄하신 분이며, 당신의 위엄으로써 존재하는 모든 것을 위압하시는 분이며, 홀로 위대하신 분이라. 우상 숭배자들은 우상을 섬김으로써 감히 하나님께 대등한 존재를 두나 하나님께서는 대등함을 거부하는 완벽한 분이시라!",
  59024: "그분은 하나님으로서 존재하는 모든 것을 창조하신 분이며, 창조를 시작하시는 분이며, 원하시는 대로 피조물에 형상을 부여하시는 분이라. 하나님께는 당신의 지고하신 속성을 드러내는 가장 훌륭한 이름들이 있노라. (일곱) 하늘과 땅에 있는 것들이 하나님의 무결하심을 찬미하니, 그분께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이라.",
  60000: "알-뭄타하나 (시험받는 여성)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 믿는 자들에게 하나님의 종교인 이슬람 이외의 것에 마음이 끌리지 말 것을 강조하고 있다.\n•    요약 주해",
  60001: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 그대들이 하나님의 길에서 그분의 기쁨을 바라며 출전하였다면 하나님의 적과 그대들의 적을 교우로 두지 말라. 그들은 하나님의 사도가 그대들에게 가져온 진리의 종교를 이미 불신하였노라. 그럼에도 불구하고 그대들은 그들에게 사랑의 감정을 내보인단 말인가. 그대들이 그대들의 주님이신 하나님을 믿는다는 이유만으로 그들은 그대들과의 친척 관계도 무시한 채 하나님의 사도와 그대들을 메카에서 추방하였노라. 그대들은 그들에 대한 사랑을 이유로 그들에게 무슬림들의 비밀 정보를 발설하나 하나님께서는 그대들이 숨기는 것과 내보이는 것을 알고 계시니 그분께는 그 무엇도 감추어지지 않노라. 그대들 중에 불신자들에게 대한 사랑의 감정으로 무슬림을 배반하는 자 있다면 실로 그는 길의 한복판을 벗어나 길을 잃고 방황한 것이라.",
  60002: "그들이 그대들보다 우위에 있을 때면 그들은 마음속에 감추고 있던 그대들에 대한 적의를 드러낼 것이니 그대들을 해치기 위해 사악한 손길을 뻗치고, 그들의 혀를 놀리며 그대들을 욕하고 비방할 것이라. 또한 그들은 자신들이 불신한 것처럼 그대들도 하나님과 그분의 사도를 불신하길 갈망할 것이라.",
  60003: "그대들이 그대들의 불신자 친척들과 자식들을 보호자로 삼는대도 그들은 그대들에게 어떠한 효용도 주지 못할 것이니 심판의 날 하나님께서는 그대들 사이를 분리시키실 것이라: 그대들 중 천국의 거주자들은 천국으로 들어가고 지옥의 거주자들은 지옥으로 들어갈 것이며 그대들 서로가 서로에게 어떤 도움도 주지 못할 것이라. 하나님께서는 그대들이 행하는 것을 보고 계시는 분이니, 그 어떤 것도 그분께는 감추어지지 않으며 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  60004: "아브라함 (이브라힘) (그에게 평화가 깃들기를) 과 그와 함께 있었던 자들에게는 그대들 -믿는 자들이여! - 을 위한 훌륭한 모범이 있노라; 불신하는 마을 사람들에게 그들은 말하였노라. “실로 우리는 그대들과 그대들이 숭배하는 하나님 이외의 우상들로부터 결백하오. 우리는 그대들이 따르는 종교를 불신하며 우리와 그대들 사이에는 적의와 증오가 드러났으니 그대들이 하나님 한 분만을 믿고 그분께 어떠한 대등한 존재도 두지 않을 때까지오”. 그렇기에 그대들은 그들과 유사한 양상을 보이는 메카 사람들로부터 결백해야 하노라. 그러나 아브라함 (그에게 평화가 깃들기를) 이 그의 아버지에게 한 말, 즉 “진실로 저는 당신을 위해 하나님께 용서를 빌어 줄 것입니다” 는 예외로서, 그대들은 이 말을 모범으로 삼지 말라. 이 말은 아버지의 불신이 확실해지기 전에 아브라함의 입에서 나온 말로서, 믿는 자들은 우상 숭배자들을 위해 용서를 빌어서는 안 되노라. 아브라함이 말하였노라. “저는 하나님의 벌로부터 아버지 당신을 구해줄 어떤 힘도 없습니다. 저희의 주님이신 하나님이시여! 저희는 당신께 저희의 모든 일을 의탁하였고, 당신께 참회하며 돌아왔으며, 심판의 날에 귀착할 곳은 당신 한 분이십니다”.",
  60005: "“저희의 주님이시여! 불신자들이 저희 위에 군림한 후 ‘너희가 진리를 따른다면 왜 우리가 너희를 압도한 것인가? ”라고 말함으로써 저희가 불신자들에 대한 시험이 되지 않도록 해주십시오. 그리고 저희의 죄를 용서하여 주십시오. 저희의 주님이시여! 실로 당신께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분입니다”.",
  60006: "그들에게서 발견되는 훌륭한 모범은 오직 하나님과 최후의 날을 염원하는 자들을 위한 것이라. 이러한 모범을 놓아두고 등을 돌리는 자가 있다면 실로 하나님께서는 인간의 복종을 필요치 아니하시는 스스로 풍족하신 분이며, 언제 어디서든지 가장 영광되신 분이라.",
  60007: "하나님께서 그대들 -믿는 자들이여! - 이 적의를 보였던 불신자들을 이슬람으로 인도하신 후 그대들과 그들 사이에 사랑과 형제애를 불어넣으실지도 모르는 일이라. 하나님께서는 능력을 가지신 분이며 그분께서는 불신자들의 마음을 신앙으로 인도하실 능력을 지니셨노라. 그리고 하나님께서는 참회하는 종복들을 너그러이 용서하시는 분이며 그들에게 자애로우신 분이라.",
  60008: "하나님께서는, 이슬람을 받아들였다는 이유로 그대들과 싸운 적이 없으면서 그대들을 거주지에서 추방하지 않은 자들을 그대들이 좋게 대하고, 그들에게 공정을 기하며 그들이 가진 권리를 실현시켜 주는 일을 금하지 않으시노라 (아부 바크르의 딸 아스마는 어머니가 불신자였다. 아스마는 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 자신과 어머니와의 관계에 대해 질문하였고 사도께서는 아스마에게 어머니와의 관계를 지속하라고 명령하셨다. ). 실로 하나님께서는, 자신과 자신의 가족과 그 이외의 자들을 공정으로 대하는 자들을 사랑하시노라.",
  60009: "하나님께서 그대들에게 금한 것은 단지, 믿었다는 이유만으로 그대들과 싸웠고 거주지로부터 그대들을 추방하였으며 그대들의 추방을 도왔던 자들을 교우로 두는 것이라. 그대들 중에 그들을 교우로 두는 자가 있다면 실로 그들은 자신을 부당히 대우한 자들이니 하나님의 명령을 어김으로써 자신을 파멸로 내몰았기 때문이라.",
  60010: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 믿는 여성들이 불신의 장소를 떠나 믿음의 장소로 그대들에게 이주하여 왔다면 그녀들의 믿음을 시험하라. 하나님께서는 그녀들의 믿음을 가장 잘 알고 계시니 그녀들의 마음속에 있는 그 무엇도 그분께는 감추어지지 않노라. 시험을 통하여 그녀들의 믿음이 확인되었다면 그대들은 그녀들을 불신자 남편들에게로 돌려보내지 말라. 믿는 여성이 불신자 남성과 결혼하는 것은 허락되지 않으며 불신자 남성이 믿는 여성과 결혼하는 것도 허락되지 않노라. 그대들은 불신자 남편들이 그녀들에게 주었던 지참금 액수만큼을 그들에게 되돌려 주라. 지정 기간이 끝난 그녀들과 결혼하는 것은 그대들 -믿는 자들이여! - 에게 죄가 되지 않으나 그대들은 그녀들에게 지참금을 주어야 하노라. 아내가 불신자이거나 배교하였다면 그녀의 불신으로 인해 혼인 관계가 무효가 되었으니 무슬림 남편은 불신자 아내를 붙잡지 말라. 배교자 아내에게 주었던 그대들의 지참금은 불신자들에게 그 보상을 요구하고, 이슬람으로 입교한 아내에게 주었던 불신자들의 지참금은 불신자들이 믿는 자들에게 그 보상을 요구하도록 하라. 이것 -지참금의 상호 요구- 은 하나님의 판결로서 그분께서는 원하시는 대로 그대들 사이를 판결하시노라. 하나님께서는 인간이 처한 상황과 행위 모두를 알고 계신 분으로서 그 무엇도 그분께 감추어지지 않으며, 하나님께서는 그분의 종복들에게 법률을 제정하심에 가장 지혜로우신 분이라.",
  60011: "만약 그대들의 아내 중 일부가 배교하여 불신자들에게로 떠나버렸다면, 그리하여 그대들이 불신자들에게 그녀들의 지참금을 요구하였으나 그들이 거부했다면, 그대들은 이미 그들로부터 전리품을 획득한 바 있도다. 그러니 배우자가 떠난 그들에게 그대들 전리품의 일부를 내줄 것이니 그들이 배우자들에게 쓴 지참금 액수 만큼이라. 그리고 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 그대들이 믿는 하나님을 두려워하라.",
  60012: "선지자여! 메카 무혈 입성시에 있었던 일처럼, 만약 믿는 여성들이 그대에게 이주하여 와서 그대에게 맹세하길 하나님께 그 어떤 대등한 존재도 두지 않고 그분 한 분만을 경배할 것이며, 도둑질하지 않고, 불법 성관계를 범하지 않고, 무지의 시대에 있었던 관습을 거부하여 자신의 자식들을 살해하지 않고, 불법 성관계로 생긴 자식을 남편의 자식이라 거짓말하지 않으며, 이슬람 이전의 관습 중 그대가 금지하는 악행은 더 이상 저지르지 않겠다고 한다면 그대는 그녀들의 맹세를 받아들이고 그녀들을 위해 하나님께 용서를 빌어 주라. 하나님께서는 참회하는 종복들을 너그러이 용서하시는 분이며 그들에게 자애로우신 분이라.",
  60013: "(이 장은 하나님의 적을 교우로 삼지 말라는 명령으로 첫 구절을 시작하였고 동일한 내용으로써 마지막 구절을 끝내고 있다. 그렇게 하여 명령된 사항이 다시 한번 강조되는 것이다. )  하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 내세를 믿지 않아 하나님의 노여움을 산 무리를 교우로 두지 말라. 그들은 마치, 죽어서 무덤에 묻힌 자가 다시 살아 돌아오지 못함을 확신하는 것처럼 그렇게 내세가 존재하지 않으리라 확신하노라.",
  61000: "앗-쌋프 (대열)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 믿는 자들에게 하나님의 종교를 돕고 그분의 길에서 분투해야 함을 독려하고 있다.\n•    요약 주해",
  61001: "(일곱) 하늘과 땅에 있는 피조물들이 하나님의 위엄을 드높이고 그분의 무결하심을 찬미하도다. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 운명의 결정과 법의 제정에 있어 가장 지혜로우신 분이라.",
  61002: "하나님을 믿는 자들이여! 왜 그대들은 실제로 행하지 않은 일을 하였다고 말하는가? 그대들 중의 누구는 ‘나는 칼을 들고 전투에 임하였고 주먹으로 싸웠소’ 라고 말하나 그는 그러한 적이 없노라.",
  61003: "그대들이 행하지 않는 일을 말함은 하나님께 있어 커다른 증오를 유발하는 일이라. 그러니 믿는 자는 언제나 하나님께 정직해야 하며 그의 말은 그의 행위와 항상 일치해야 하노라.",
  61004: "실로 하나님께서는 그분의 기쁨을 바라며 그분의 길에서 대열을 지어 전투에 참전하는 믿는 자들을 사랑하시니 그들은 마치 견고하고 빈틈없이 지어진 건축물과도 같더라.",
  61005: "(하나님께서는 그분의 길에서 일치단결하며 분투하는 신앙인들을 칭찬하셨고, 이제 다음 구절들에서는 모세와 예수 시절에 사도를 거역했던 자들에 대해 언급하고 계신다. 무슬림들에게 사도를 거역하지 말라는 간접적인 메시지를 주고 계신 것이다. )  그대 - 사도여! - 는 모세가 그 당시 사람들에게 했던 말을 떠올리라. “나의 사람들이여! 내가 그대들에게 보내진 하나님의 사도라는 것을 잘 알면서도 왜 그대들은 나의 명령을 거역함으로써 나에게 해를 끼치는가? ” 그렇게 그들은 자신들에게 도래한 진리를 벗어나 엇나갔으며 이에 하나님께서는 그들의 마음을 진리로부터 멀어지게 하셨노라. 하나님에 대한 복종을 거부하는 사람들에 관하여 하나님께서는 그들을 진리로 인도하지 않으시노라.",
  61006: "그대 - 사도여! - 는 마리아 (마르얌) 의 아들 예수가 했던 말을 떠올리라. “이스라엘의 자손들이여! 나는 특별한 존재가 아니라 그대들에게 보내진 하나님의 사도로서 나 이전에 있었던 토라를 확증하노라. 그리고 나는 기쁜 소식을 전하니 나 이후에 ‘아흐마드’라는 이름의 사도가 올 것이라” 그러나 예수가 분명한 증거를 가지고 그들에게 도래했을 때 그들은 “이것은 속임수 강한 주술일 뿐이니 우리는 이것을 따르지 않겠소”라고 말하였노라.",
  61007: "하나님만을 경배하는 유일신 사상인 이슬람을 믿으라 권유 받으면서도, 하나님께 대등한 존재를 두고 그것을 숭배하여 하나님에 관해 거짓을 지어내는 자들이 있으니 그들보다 더 부당한 자들이란 있을 수 없노라. 하나님께서는 우상 숭배와 거역 행위로써 자신을 부당히 대우하는 자들을 인도하지 않으시니 그들은 올바른 길로 인도되지 못하노라.",
  61008: "징표를 부정하는 저들은 진리를 흐리게 하는 말로써 하나님의 광명을 끄려 하나, 하나님께서는 당신의 광명을 완전히 하시니 그분의 종교가 전세계에 드러나고 그분의 말씀이 드높여지더라. 불신자들이 싫어한대도 하나님께서는 그렇게 하시노라.",
  61009: "올바른 길의 종교이자 선 (善) 의 종교, 그리고 지식과 실천의 종교인 이슬람과 함께 사도 무함마드를 보내시어 그 모든 종교 위에 이슬람을 높이 두신 분이 하나님이시라. 우상 숭배자들은 지구상에 이슬람이 번성함을 싫어하나 하나님께서는 그렇게 하시노라.",
  61010: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 고통스런 벌로부터 그대들을 구해줄 훌륭한 거래 행위가 있으니, 하나님께서 그대들에게 그것이 무엇인지 안내해 주려 하시노라.",
  61011: "이득을 제공하는 이 거래 행위란, 그대들이 하나님과 그분의 사도를 믿고, 하나님의 기쁨을 바라며 그대들의 재산과 생명을 바쳐 그분의 길에서 분투하는 것이라. 그대들이 알고 있다면 이러한 행위가 그대들에게 더 좋은 것이니 그대들은 서둘러 이를 실천하라.",
  61012: "이 거래의 결과로서 하나님께서는 그대들의 죄를 용서하여 주실 것이며, 그대들을 천국에 들게 할 것이니 그곳에는 궁궐 같은 저택과 수목이 있어 그 아래에는 강물이 흐르노라. 또한 그분께서는 그대들을 영원한 거주가 보장되는 천국, 그 안에 마련되어 있는 안락한 거주지에 들게 하실 것이라. 이것이야말로 그 어떤 성공과도 비교되지 않는 가장 위대한 성공이라.",
  61013: "이 거래의 또 다른 결과는 그대들이 사랑하는 현세의 것들이라: 그대들의 적을 패배케 할 하나님의 도움과 그대들에게 주어질 가까운 승리 (메카 무혈 입성) 가 그것이라. 그대 -선지자여! - 는 믿는 자들에게 현세에서의 도움과 내세에서의 천국이라는 기쁜 소식을 전하라.",
  61014: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 하나님을 위해 돕는 자들이 되어라. 예수가 자신의 제자들 (하와리윤) 에게 “하나님을 위해서 나를 도와줄 자들은 누구인가? ”라고 말했을 때 제자들이 망설임 없이 “우리들이야말로 하나님을 위해 돕는 자들입니다”라고 말했던 것처럼 그렇게 그대들은 하나님을 위해 돕는 자들이 되어라. 그리하여 이스라엘 자손들 중의 한 무리는 예수를 믿었고 다른 한 무리는 그를 불신하였노라. 이에 하나님께서는 믿는 자들을 불신자들에 대항하여 도와주었으니 믿는 자들은 그들의 적을 압도하는 자들이 되었노라.",
  62000: "알-주무아 (금요일)\n계시 분류: 메디나\n•    계시 목적    \n이 장은, 하나님께서 당신의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 를 보내심으로써 이슬람 공동체에 은혜를 베푸셨으며, 방황하고 있던 그들을 인도하여 주셨음을 밝히고 있다. 또한 이 장은 우리가 하나님께 복종해야 함을 알리면서, 유대인들을 닮아가지 말 것을 경고하고 있다.\n•    요약 주해",
  62001: "(일곱) 하늘과 땅에 있는 피조물들이 하나님의 위엄을 드높이고 그분의 무결하심을 찬미하도다. 하나님께서는 주권을 소유하신 유일의 제왕이시고, 그 어떤 결점도 없으신 분이며, 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이라.",
  62002: "쓰지도 읽지도 못하는 아랍인들에게 그들 출신의 사도를 보내신 분이 하나님이시라. 그리하여 사도가 그들에게 하나님으로부터 계시받은 징표를 낭송하고, 불신과 저속한 품성으로부터 그들을 정화하며, 그들에게 꾸란과 순나 (선지자의 모범) 를 가르치더라. 진실로 그들은 이슬람 이전에 우상을 숭배하고 서로를 살해하며 친척 관계를 단절하는 등 진리와 멀어진 채 크게 방황하고 있었노라.",
  62003: "사도가 보내짐은 그 이후에 올 아랍인 출신과 비아랍인 출신의 다른 이들을 위함이라. 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이라.",
  62004: "하나님께서 아랍인과 비아랍인을 위하여 사도를 보내신 것은 당신의 은혜로 말미암은 것으로, 하나님께서는 원하시는 자에게 당신의 은혜를 주시노라. 하나님께서는 위대한 은혜의 소유자로서, 모든 인류를 위해 이슬람 공동체에 사도를 보내신 것도 그분의 위대한 은혜 중의 하나라.",
  62005: "(하나님께서는 사도를 보내시고 꾸란을 내리신 그분의 은총을 언급하신 후, 모세 (그에게 평화가 깃들기를) 를 따르는 일부 무리들이 토라를 실천하지 않음을 언급하시면서 이슬람 공동체가 그들을 따르지 말 것을 경고하고 계신다. )  토라의 가르침을 따르라는 명령에도 불구하고 토라를 실천하지 않는 자들은 마치 커다란 책을 나르는 당나귀와 같으니 자신이 무엇을 지고 있는지 알지 못하노라. 하나님의 징표를 부인하는 무리의 예란 얼마나 추한 것인가. 하나님께서는 부당한 무리를 진리로 인도하지 않으시노라.",
  62006: "그대 - 사도여! - 는 말하라. “왜곡으로 얼룩진 유대교를 버리지 않고 고수하는 자들이여! 만약 그대들이 타인을 제외한 오직 그대들만이 하나님의 동료라는 허황된 믿음을 가졌다면, 그리고 그대들의 이 주장이 진실이라면, 죽음을 소망해 보라. 그렇게 할 때 그대들은 그대들만이 가질 수 있는 (내세의) 명예를 가질 것이 아닌가\"",
  62007: "그들은 결코 죽음을 소망하지 않을 것이며 오히려 현세에서 영원히 머물고 싶어하니 이는, 그들이 불신과 거역과 부당 행위를 저지르며 토라를 왜곡하고 변경했기 때문이라. 하나님께서는 모든 부당한 자들을 알고 계시니 그들의 어떤 행위도 그분께는 감추어지지 않으며 그분께서는 그들의 행위를 심판하실 것이라.",
  62008: "그대 -선지자여! - 는 저 유대인들에게 말하라. “실로 그대들은 죽음으로부터 도망치려 하나, 결국 그대들은 필연적으로 죽음을 맞이하게 될 것이라. 그런 후 그대들은 심판의 날 하나님께로 돌아가게 될 것이니, 그분께서는 보이지 않는 것과 보이는 것 모두를 알고 계시는 분이며 그 어떤 것도 그분께는 감추어지지 않노라. 그리고 하나님께서는 그대들이 현세에서 행하던 것을 알려주실 것이며 그로써 그대들의 행위를 심판하실 것이라”",
  62009: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 금요일에 이맘이 설교대로 올라가고 아단 (예배를 위한 부름) 이 울렸다면 그대들은 어서 마스지드로 이동하여 설교를 경청하고 합동 예배를 드리라. 그리고 이 시간의 상거래는 잠시 그만둠으로써 상거래가 경배 행위를 방해치 않도록 하라. 금요일 아단이 울릴 때 상거래를 그만두고 마스지드로 이동함은 - 그대들이 알고 있다면 - 실로 그것이 그대들을 위해 더 좋은 것이라. 그러니 그대들은 하나님의 명령을 따르라.",
  62010: "그리하여 예배가 종료되었다면 그대들은 허락된 양식을 구하고 필요한 것을 얻기 위해 대지로 흩어지되 허락된 이윤을 구함에 있어 하나님의 은혜를 간구하라. 그리고 현세의 양식을 구하면서도 하나님을 많이 떠올리라. 그러할 때 그대들은 원하는 좋은 것을 얻고 그대들이 두려워하는 나쁜 것으로부터 벗어날 것이라.",
  62011: "그들이 장사하는 무리들이나 오락 거리를 보았을 때 그들은 있던 곳에서 일어나 밖으로 나갔고 그대 - 사도여! - 를 설교대에 선 채로 내버려 두었노라. 그대 - 사도여! - 는 말하라. “선행에 관하여 하나님께서 주실 보상이 그대들이 구경 나갔던 오락 거리나 장사보다 더 좋은 것이라. 하나님께서는 양식을 베푸는 자들 중에서 으뜸이신 분이라”",
  63000: "알-무나피꾼 (위선자들)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 위선자들이 누구인지 그들의 겉모습을 드러내면서 이슬람과 무슬림에 대한 그들의 자세를 밝히고 있다. 이는 무슬림들이 그들을 구분하고 유의하기 위함이다.\n•    요약 주해",
  63001: "내면의 불신을 숨기고 겉으로만 이슬람을 내보이는 위선자들은 그대 - 사도여! - 와 함께 하는 모임에 참석하여 “우리는 실로 그대가 하나님의 사도임을 증언합니다”라고 말하나 하나님께서는 실로 그대가 그분의 사도임을 알고 계시며 하나님께서는 실로 위선자들이 마음속에 없는 거짓을 말하고 있음을 증언하시노라.",
  63002: "그들은 자신의 거짓 신앙에 맹세를 걸어 그것을 방패 삼아 자신에게 있을 불이익을 모면하였노라. 그리고 이슬람에 관해 의심을 부추기고 거짓 정보를 퍼뜨려 사람들이 하나님의 길로 들어섬을 가로막으니 실로 그들의 위선과 거짓 신앙이란 얼마나 추악한 것인가.",
  63003: "그러함은, 위선적인 믿음으로 인해 그들의 마음속에 진정한 신앙이 자리잡지 않았기 때문이며, 그 후 그들은 남몰래 하나님을 불신하였기 때문이라. 그렇게 그들이 저지른 불신으로 말미암아 그들의 마음은 믿음을 받아들일 수 없게 봉해져 버렸으니 그들은 유용한 것과 올바른 것이 무엇인지 이해하지 못하더라.",
  63004: "그대가 그들을 볼 때면 풍요로움으로 잘 갖추어진 그들의 외관이 마음에 들 것이며, 그들이 말을 할 때면 그대는 그들의 능숙한 달변을 경청하게 될 것이라. 그들은 그대 - 사도여! - 와 함께 하는 모임에 앉아 있으나 아무것도 이해하지 못하는 자들이니 그들은 마치 벽에 맞대어진 나무둥치처럼 허울만 근사할 뿐 깨닫지를 못하노라. 행여 누군가가 소리 높여 외치면 겁쟁이인 그들은 그 외침이 자신들을 향한 것이라 생각하더라. 그들은 진정한 적이니 그대 - 사도여! - 는 그들이 비밀을 누설하거나 음모를 꾸밀 수 있음에 유의하라. 하나님께서 그들을 저주하시노라. 명백하고 확실한 증거가 있음에도 그들은 어떻게 믿음을 거부하고 돌아선단 말인가?",
  63005: "누군가가 “그대들 (위선자들) 의 잘못을 해명하기 위해 하나님의 사도에게로 가시오. 그러면 그대들이 저지른 죄에 대해 사도가 하나님께 용서를 빌어 줄 것이오”라고 말할 때면 그들은 비웃으면서 머리를 내돌릴 것이라. 그리고 그대는 그들이 진리 앞에 거만해 하며 그들이 받은 명령을 실천하지 않고 돌아서는 것을 볼 것이라.",
  63006: "그대 - 사도여! - 가 그들을 위해 용서를 빌어 주든 빌어 주지 않든 마찬가지라. 하나님께서는 그들의 죄를 용서해 주지 않으실 것이라. 실로 하나님께서는 당신께 복종하지 않고 죄를 지으며 거역하는 무리를 인도하지 않으시노라.",
  63007: "“하나님의 사도와 함께 있는 가난한 자들과 유목민들이 사도로부터 떨어져 나갈 때까지 그대들 재산을 그들에게 희사하지 마시오”라고 말하는 자들이 그들이라. (일곱) 하늘의 보물 창고와 대지의 보물 창고는 오직 하나님 한 분만이 소유하고 계시며 그렇게 그분께서는 원하시는 자에게 양식을 베푸시노라. 그러나 위선자들은 하나님으로부터 모든 양식이 비롯됨을 알지 못하노라.",
  63008: "위선자들의 우두머리인 압둘라 이븐 우바이가 말하였노라. “만일 우리가 메디나로 귀환한다면 맹세컨대 그들보다 더 명예로운 우리 -나와 나를 따르는 자들- 가 우리보다 더 허약한 자들 -무함마드와 그의 교우들-을 쫓아낼 것이라”. 명예는 오직 하나님의 소유이자 하나님의 사도의 것이며 믿는 자들의 것이라. 그러나 위선자들은 이 사실을 알지 못하더라.",
  63009: "(이전 구절에서 하나님께서는 위선자들이 얼마나 인색하며, 그들이 하나님의 길을 막기 위해 어떻게 기꺼이 비용을 지불하는지를 언급하셨다. 이제 하나님께서는 믿는 자들에게 저들의 속성을 경고하시면서 당신의 길에서 베풀 것을 명령하신다. )  하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 그대들의 재산과 그대들의 자식들이 예배와 기타 의무 사항을 수행함에 방해가 되지 않도록 하라. 그렇게 하는 자가 있다면 실로 그들은 심판의 날 자기 자신과 가족들을 잃는 손실자들이 될 것이라.",
  63010: "그대들 중 누군가에게 죽음이 찾아 오기 전에 그대들은 하나님께서 베풀어 주신 양식으로 희사하라. 그렇게 하지 않을 때 그는 죽음이 찾아 온 순간 그의 주님께 이렇게 말하게 될 것이라. “저의 주님이시여! 저를 가까운 기한까지만 늦추어 주신다면 저는 진실로 하나님의 길에서 제 재산을 희사할 것이며 선행을 실천하는 하나님의 선량한 종복이 될 것입니다”",
  63011: "그러나 지고하신 하나님께서는 영혼의 기한이 도래하고 목숨이 다하였을 때 결코 그 영혼의 죽음을 늦추시는 법이 없노라. 하나님께서는 그대들의 행위를 상세히 알고 계신 분이니 그대들의 그 어떤 행위도 그분께는 감추어지지 않으며 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  64000: "앗-타가분 (득실)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 부활의 날 불신자들이 겪는 손실에 대해 언급함으로써 불신의 위험성에 대해 경고하고 있다.\n•    요약 주해",
  64001: "(일곱) 하늘과 땅에 있는 피조물들이 하나님의 위엄을 드높이고 그분의 무결하심을 찬미하도다. 오직 하나님께만 주권이 있으니 그분만이 왕이시며, 모든 찬미는 하나님의 것이라. 그리고 하나님께서는 모든 것이 가능한 분이시니 그 무엇도 감히 그분의 의지에 대항할 수 없노라.",
  64002: "그대들 -인간들이여! - 을 창조하신 분이 하나님이시라. 그리하여 그대들 중에는 불신자로서 불지옥에 거주할 자가 있으며, 또한 그대들 중에는 믿는 자로서 천국에 거주할 자가 있노라. 하나님께서는 그대들이 행하는 것을 지켜보고 계시는 분이니, 그분께는 그대들의 어떤 행위도 감추어지지 않으며 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  64003: "하나님께서는 (일곱) 하늘과 땅을 진리에 걸맞게 창조하셨으니 장난으로 그것을 창조한 것이 아니라. 그리고 하나님께서는 그대들 -인간들이여! - 에게 형상을 부여하심에 그대들의 모습을 아름답게 하셨노라. 이것은 하나님께서 베푸신 은혜로서 만약 원하셨다면 그대들의 모습을 추하게 하셨을 것이라. 심판의 날 귀착할 곳은 하나님 한 분이시니 그분께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  64004: "하나님께서는 (일곱) 하늘에 있는 것과 대지에 있는 것을 알고 계시며 그대들이 숨기는 행위와 드러내는 행위 모두를 알고 계시노라. 그리고 하나님께서는 심중에 있는 좋은 것과 나쁜 것을 다 알고 계시는 분이니 그분께는 그 무엇도 감추어지지 않노라.",
  64005: "이전에 있었던 불신자 공동체의 소식이 그대들 -우상 숭배자들이여! - 에게 전해지지 않았는가? 노아 (누흐) 와 아드와 싸무드 시절의 사람들은 그들의 불신으로 말미암아 현세에서 참담한 결말을 맛보았노라. 그리고 그들은 내세에서 고통스런 벌을 받을 것이라. 그대들은 이미 그들의 소식을 알고 있으니, 그들의 전례를 통해 교훈을 얻으라. 그들이 받았던 벌이 그대들에게 닥치기 전에 그대들은 서둘러 하나님께 참회하라.",
  64006: "그들에게 닥친 벌은, 사도들이 그들에게 분명한 증거를 제시하였음에도 그들은 거만해 하며 “한낱 인간이 우리를 진리로 인도한다 말인가? ”라고 말하였기 때문이며, 불신하면서 믿음에 등을 돌렸기 때문이라. 그들은 하나님을 조금도 해하지 못하니 그분은 그들의 믿음이나 복종 따위를 필요로 하지 아니하시노라. 하나님께서는 인간이 필요 없으신 풍족한 분이시며, 말씀과 행위가 영광으로 가득 찬 분이시라.",
  64007: "불신하는 자들은 하나님께서 죽어 있는 자신들을 부활시키지 않을 것이라는 헛된 확신을 가지더라. 그대 - 사도여! - 는 말하라. “그렇지 않노라. 나의 주님께 맹세코, 진실로 그대들은 심판의 날에 부활할 것이며 그런 후 하나님께서는 그대들이 현세에서 행하던 일을 그대들에게 알려주실 것이라. 그리고 이러한 부활은 하나님께 쉬운 일이라; 태초에 창조를 시작하신 분이 하나님이시기에, 그분께서는 심판과 보응을 위해 죽어 있는 그대들을 되살릴 수 있음이라”",
  64008: "그러니 그대들 -사람들이여! - 은 하나님과 그분의 사도을 믿고 하나님께서 그분의 사도에게 내리신 꾸란을 믿으라. 하나님께서는 그대들이 행하는 일에 밝으신 분이니 그대들의 그 어떤 행위도 그분께는 감추어지지 않으며 하나님께서는 그대들의 행위를 빠짐없이 보상하실 것이라.",
  64009: "그대 - 사도여! - 는 기억하라: 그날 하나님께서는 부활의 날을 위해 그대들을 모으시어 그대들의 행위를 보상하실 것이니 그날은 불신자들의 손실이 드러나는 날이라: 지옥의 거주자들에게 마련되어 있던 천국의 장소가 믿는 자들의 것이 되고, 천국의 거주자들에게 마련되어 있던 지옥의 장소는 불신자들이 대신 들어가게 될 것이라. 하나님을 믿고 선행을 실천하는 자가 있다면 하나님께서는 그의 악행을 용서해 주실 것이며 그를 천국에 들게 하실 것이라. 그곳은 궁궐 같은 저택들 아래에 강물이 흐르는 곳으로서 그들은 거기서 영원히 거주하며 끊임없는 즐거움을 만끽할 것이라. 그들이 천국에서 가지게 될 기쁨은 그 어떤 성공과도 비교되지 않는 가장 위대한 성공이라.",
  64010: "그러나 하나님을 불신하며 그분께서 사도에게 내려 주신 그분의 징표를 부인하는 자, 저들은 불지옥의 거주자들로서 그곳에서 영원히 거주할 것이라. 얼마나 비참한 귀착지인가.",
  64011: "생명이나 재산이나 자식 등에 일어난 그 모든 시련은 하나님께서 지정하신 운명에 의한 것이라. 하나님의 운명을 믿는 자가 있다면 하나님께서는 그의 마음을 인도하실 것이니 그는 하나님의 결정을 받아들이며 그분의 정명에 대해 만족할 것이라. 하나님께서는 그 모든 것을 알고 계심에 그 어떤 것도 그분께는 감추어지지 않노라.",
  64012: "그대들은 하나님을 따르고 사도를 따르라. 만약 하나님의 사도가 가져온 메시지에 대해 그대들이 돌아선다면 손해를 입을 자는 오히려 그대들이며 사도에게는 전혀 해가 되지 않노라: 하나님의 사도의 임무는 오직 명백하게 메시지를 전달하는 것 뿐이며 사도는 이미 자신의 임무를 완수하였기 때문이라.",
  64013: "하나님 이외에는 그 누구도 경배받을 권리가 없노라. 믿는 자들은 그 모든 일에 있어 오직 하나님 한 분께만 의탁하도록 하라.",
  64014: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 그대들의 배우자들과 자손들을 이유로, 하나님을 기억하고 그분의 길에서 분투하는 일을 그만둔다면 실로 그들은 그대들의 적과 다름 없을 것이라. 그러니 그대들은 그들로부터 영향을 받지 않도록 유의하라. 만약 그대들이 그들의 오류에 대해 관용과 아량을 베풀고 용서하여 준다면 실로 하나님께서는 그대들의 죄를 용서하고 그대들에게 자비를 베풀어 주실 것이라. 용서해 준 만큼 그대들도 용서를 받는 것이라.",
  64015: "그대들의 재산과 자식들은 시험일 뿐이라: 그대들은 그들을 이유로 금지된 방식으로 양식을 구하기도 하며 그들을 이유로 하나님을 위한 경배 행위를 포기하기도 하노라. 그러나 위대한 보상은 하나님 그분께 있으니 자식이나 재산이 아닌 하나님을 최우선으로 두는 자들은 천국이라는 보상을 받게 될 것이라.",
  64016: "그러니 그대들은 능력이 허락하는 최대한으로 하나님께서 명령한 것을 지키고 그분께서 금지한 것을 멀리하여 그분을 두려워하라. 그리고 하나님과 당신의 사도께서 하신 말씀을 듣고 따르며 하나님께서 그대들에게 베풀어 주신 재산으로써 좋은 곳에 희사하라. 하나님의 허락으로 마음의 각박함으로부터 벗어난 자, 이들이야말로 성공한 자들로서 그들은 원하던 좋은 것을 얻고 그들이 두려워하던 나쁜 것으로부터 벗어날 것이라.",
  64017: "그대들이 하나님의 길에서 재산을 희사한다면 그것은 마치 하나님께 돌려받지 않을 빚을 내주는 것과 같노라. 하나님께서는 그대들을 위하여 그 보상을 최소한 열 배에서 많게는 칠백 배까지 혹은 그보다 더 크게 증가시켜 주실 것이라. 또한 하나님께서는 그대들의 죄를 용서하여 주실 것이니 하나님께서는 작은 선행도 크게 보상하시는 분이며 징벌을 서두르지 않으시는 분이라.",
  64018: "하나님께서는 보이지 않는 것과 보이는 것 모두를 알고 계시는 분이며 그 어떤 것도 그분께는 감추어지지 않노라. 또한 하나님께서는 누구도 감히 제압할 수 없는 가장 존엄하신 분이자, 피조물의 창조와 법의 제정과 운명의 결정에 있어 가장 지혜로우신 분이라.",
  65000: "앗-딸라끄 (이혼)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 이혼의 엄중함과 그 경계에 대해 다루고 있으며, 하나님에 대한 경외심 및 그분의 경계를 벗어나는 일이 어떠한 결과를 초래하는지 설명하고 있다.\n•    요약 주해",
  65001: "선지자여! 그대나 그대를 따르는 이슬람 공동체의 무슬림이 자신의 아내와 이혼하고자 할 때는 지정 기간 (알-잇다) 을 고려하여 이혼을 실시하라: 두 생리 기간 사이에 부부 관계를 가지지 않았을 때만 이혼이 가능하도다. 그리고 이혼 후에는 지정 기간을 잘 계산하라: 이혼을 취소하고 싶을 때는 정해진 지정 기간 (세번의 생리) 내에서만 취소가 가능하기 때문이라. 그대들은 하나님께서 명령하신 것을 지키고 그분께서 금지하신 것을 멀리함으로써 그대들의 주님을 두려워하라. 그대들은 지정 기간이 끝나지 않는 한 이혼이 선언된 아내들을 집에서 쫓아낼 수 없으며 아내들 스스로도 거주하던 집에서 나가서는 안 되지만, 그녀들이 불법 성관계 (지나) 등 그 추악함이 명백한 일을 저지른 경우는 예외라. 이것은 하나님께서 종복들을 위해 지정하신 그분의 경계라. 하나님의 경계를 넘는 자는 진실로 자신을 부당히 다룬 것이니, 그는 주님을 거역함으로써 자신을 파멸에 노출시켰기 때문이라. 그대-이혼을 선언한 자여! -는 미래의 일을 알지 못하니, 하나님께서 남편의 이혼 선언 후 그의 심경에 변화를 일으켜, 결국 남편이 자신의 아내에게로 되돌아 갈지도 모를 일이라.",
  65002: "그대들이 다시 훌륭한 결혼 생활을 희망한다면 지정 기간이 종료되기 전에 아내와 재결합하라. 그렇지 않다면 지정 기간이 종료된 후에 합당한 방식으로 그녀들과 헤어짐으로써 그녀들이 자신의 미래를 계획할 수 있도록 하고 그대들은 그녀들의 권리인 위자료를 지급하라. 이렇게 그대들이 재결합이나 결별을 원할 경우에는 두 명의 공정한 무슬림을 증인으로 세워 이후에 있을 논쟁을 미연에 방지하라. 증언하는 자들은 증언을 실시함에 그것이 하나님의 기쁨을 위한 증언이 되어야 하노라. 이러한 규정을 통하여 하나님과 부활의 날을 믿는 자는 가르침을 얻을 것이니 그들이야말로 가르침으로부터 배우는 자들이기 때문이라. 하나님께서 명령하신 것을 지키고 그분께서 금한 것을 멀리함으로써 하나님을 두려워하는 자가 있다면 그분께서는 그가 겪고 있는 어려움에 관하여 출구를 마련해 주실 것이라.",
  65003: "그리고 하나님께서는 그가 생각하지도 못한 곳에서, 예상하지도 못한 방법으로 그에게 양식을 베푸실 것이라. 자신의 모든 일을 하나님께 의탁하는 자, 그는 하나님 한 분만으로 충분하도다. 실로 하나님께서는 원하시는 대로 실행하시는 분이니 그분께서는 그 무엇도 놓치지 않으시며 그 누구도 그분을 막지 못하노라. 실로 하나님께서는 모든 것에 알맞은 양을 두셨기에 일정량에 도달한 후에 어려움은 사라질 것이며, 평이함도 일정량에 도달한 후에는 사라질 것이라; 인간이 어려움이나 평이함만을 지속해서 경험하는 일은 없노라.",
  65004: "이혼이 선언된 여성들 중 나이가 많아 생리를 단념한 여성이 있다면, 그리하여 그대들이 어떻게 지정 기간을 계산해야 할지 모르겠다면, 그녀의 지정 기간은 삼개월이라. 나이가 어려 생리를 하지 않는 여성도 마찬가지로서 이혼 후 그녀의 지정 기간은 삼개월이라. 임신한 여성은 만약 이혼이 선언되었거나 남편이 사별했을 경우 출산할 때까지가 그녀가 기다려야 할 기간이라. 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 두려워하는 자가 있다면 그분께서는 그의 일을 쉽게 해주실 것이며 그가 겪는 어려움을 완화시켜 주실 것이라.",
  65005: "이혼과 재결합, 지정 기간 등은 하나님께서 그대들 -믿는 자들이여! - 을 위해 내리신 그분의 규정이라. 하나님께서 명령한 것을 지키고 그분께서 금하신 것을 멀리함으로써 하나님을 두려워하는 자가 있다면 그분께서는 그가 저지른 악행을 용서해 주실 것이며 그에게 위대한 보상을 내리실 것이니 그것은 끊이지 않는 즐거움이 있는 천국으로의 입성이라.",
  65006: "(하나님께서 이혼과 재결합에 관한 규정을 언급하였고, 이제 여기서 그분께서는 경제적 부양과 거주지 마련에 관해 말씀하고 계신다. )  가진 역량껏 그대들 -남편들이여! - 이 거주하고 있는 곳에서 그녀들이 머물게 하라: 하나님께서는 거주지와 관련하여 그대들이 가진 것 이외의 것을 짐 지우지 않으시노라. 그대들은 경제적 부양과 거주지 마련에 있어 그녀들에게 해를 끼쳐 그녀들을 압박하지 말라. 만약 이혼이 선언된 여성들이 임신한 상태라면 출산할 때까지 그녀들을 부양하라. 출산 후 그녀들이 그대들을 배려하여 그대들의 자식에게 젖을 물렸다면 그대들은 그녀들에게 수유에 대한 보상을 지불하되 보상 금액에 관하여는 합당한 방식으로 서로 간에 합의하라. 만약 아내가 원하는 금액을 남편이 거부하거나 남편이 주는 금액에 아내가 동의하지 않는다면 아이의 아버지는 아이를 수유해 줄 다른 유모를 찾도록 하라.",
  65007: "재산이 풍족한 자는 그의 풍족함으로써 이혼이 선언된 아내와 자식을 부양하고, 한정된 양식만을 가진 자는 하나님께서 그에게 주신 것으로써 부양토록 하라. 하나님께서는 영혼에게 오직 주신 만큼만 짐 지우시니 인간은 받은 것 이상 혹은 가진 능력 이상의 것을 의무 사항으로 요구 받지 않노라. 하나님께서는 그가 겪는 어려움을 쉬움으로 바꾸어 주실 것이라.",
  65008: "(하나님께서는 여러 명령을 언급하신 후 그러한 그분의 명령을 어기는 것이 얼마나 엄중한 결과를 초래할 것인지를 경고하고 계신다. )  얼마나 많은 마을이 그들 주님과 그분의 사도들의 명령에 불복하였는가. 이에 하나님께서는 그들의 악행을 심판하심에 가혹히 심판하셨고 현세와 내세에서 그들을 벌하심에 매섭게 벌하셨도다.",
  65009: "그리하여 그들은 자신이 저지른 악행의 참담한 결말을 맛보았으며 그들이 맞이한 최후는 현세와 내세에서의 비참한 손실이었도다.",
  65010: "하나님께서는 그들을 위해 가혹한 벌을 준비하셨노라. 그러니 하나님과 그분의 사도를 믿는 슬기를 지닌 자들이여, 하나님께서 명령하신 것을 지키고 그분께서 금지하신 것을 멀리함으로써 하나님을 경외하라. 그리할 때 그대들은 그대들 이전의 자들이 겪어야만 했던 징벌을 피할 수 있을 것이라. 실로 하나님께서는 그대들에게, 악행은 참담한 결말을 초래하며 선행은 훌륭한 보상을 가져올 것이라는 메시지를 내리셨노라.",
  65011: "그 메시지는 사도를 통하여 그대들에게 하나님의 분명한 징표로 낭송되노라. 그리함은 사도가, 하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들을 방황의 어둠에서 인도의 빛으로 꺼내기 위함이라. 하나님을 믿고 선행을 실천하는 자가 있다면 하나님께서는 그를 천국에 들게 하실 것이니 그곳은 궁궐 같은 저택과 울창한 수목 아래에 강물이 흐르는 곳이며 그들은 그곳에서 영원히 거주할 것이라. 실로 하나님께서는 천국의 거주자를 위해 양식을 훌륭히 하셨으니 그는 천국에 들어가 끊이지 않는 기쁨을 누릴 것이라.",
  65012: "일곱 개의 하늘을 창조하시고 지구도 그처럼 일곱 개의 층으로 창조하신 분이 하나님이시라. 하나님의 명령이 하늘과 지구 사이에 내려오니, 그대들이 하나님에 대해 알도록 하기 위함이라; 하나님께서는 모든 것이 가능한 분이시기에 그분께 불가능한 일이란 있을 수 없으며, 하나님께서는 모든 것을 지식으로 아우르고 계시기에 하늘과 지구의 그 무엇도 그분께는 감추어지지 않노라.",
  66000: "앗-타흐림 (금지)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 선지자 가정에 교훈을 줌으로써 그들이 무슬림 가정과 이슬람 공동체에 모범이 되도록 하고 있다.\n•    요약 주해",
  66001: "사도여! 하나님께서는 그대가 몸종 마리아와 함께하는 것을 허락하셨는데도 어찌하여 그대는 그것을 금하려 하는가? 질투하는 그대 아내들의 기쁨을 얻으려는 것인가? 하나님께서는 그대를 너그러이 용서하시는 자애로우신 분이라.",
  66002: "하나님께서는 이미 그대들을 위해 맹세의 해약법을 지정하셨도다: 그것은, 맹세한 내용보다 더 좋은 것을 원하거나 맹세한 내용을 어겼을 때 그대들이 속죄 의식 (알-캇파라) 을 실시하는 것이라. 하나님께서는 그대들을 도와주시는 분이라. 그리고 하나님께서는 그대들의 모든 상황을 숙지하고 계시기에 무엇이 그대들에게 적합한지를 알고 계신 분이며 그분께서는 법률과 운명의 제정에 있어 가장 지혜로우신 분이라.",
  66003: "기억하라: 선지자가 아내 하프싸에게 비밀 -마리아와 더 이상 함께하지 않겠다는 결심 등- 을 알려 주었고 그녀는 그 비밀을 아이샤에게 전하였노라. 이에 하나님께서는 선지자에게 그녀의 비밀 누설 행위를 알려 주셨노라. 선지자는 발설된 비밀의 일부를 하프싸 앞에서 언급하였고 나머지에 관하여는 침묵하였도다. 이에 하프싸가 묻길 “누가 당신께 이것을 알려 주었습니까? ” 선지자가 말하였노라. “모든 것을 알고 계시고 숨겨진 것도 알고 계시는 분께서 나에게 알려 주셨노라”.",
  66004: "그대들 (하프싸와 아이샤) 이 하나님께 참회하는 것은 당연한 일이라; 그대들의 마음은 이미 하나님의 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 가 기피하는 것으로 기울었으니, 그가 마리아를 멀리하며 금욕하길 바랐노라. 만약 그대들이 선지자에 대항하여 서로 간에 협력하는 일을 계속한다면 하나님 그분이야말로 그의 가호자이시며 가브리엘 (지브릴) 천사와 선량한 신앙인들도 그를 사랑하며 도와줄 것이라. 뿐만 아니라 천사들도 그에게 해를 끼치는 자들에 대항하여 그에게 도움을 줄 것이라.",
  66005: "만약 선지자가 그대들과 이혼한다면 그의 주님께서는 그를 위해 그대들보다 더 훌륭한 배우자들 - 하나님의 명령에 순종하는 여성들, 하나님과 그분의 사도를 믿는 여성들, 하나님께 부단히 복종하는 여성들, 자신의 죄를 참회하는 여성들, 주님을 경배하는 여성들, 단식하는 여성들, 남편을 잃은 기혼 여성들과 아직 결혼하지 않은 여성들 - 로 대체시켜 주실 지도 모를 일이라.",
  66006: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 불지옥로부터 그대들 자신과 가족들을 구하라. 그곳은 인간과 돌을 땔감으로 하여 타오르는 곳이라. 불지옥 위에는 천사들이 있으니 그곳의 거주자들을 모질고 혹독하게 대하노라. 그들은 하나님의 명령에 거역하지 않으며, 그들은 명령받은 사항을 지체 없이 수행하노라.",
  66007: "부활의 날 불신자들에게 목소리가 들릴 것이라. “하나님을 불신하던 자들이여! 너희가 저지르던 불신과 불복종에 관해 오늘 변명을 대지 말라. 너희의 변명은 통하지 않을 것이라. 현세에서 하나님을 불신하고 사도를 부인한 것에 대해 오늘 너희는 응당한 벌을 받는 것이라”",
  66008: "하나님을 믿고 그분께서 제정하신 법률을 따르는 자들이여! 그대들이 저지른 죄에 대하여 하나님께 진실로 참회하라. 그러면 그대들 주님께서 그대들을 위해 그대들의 악행을 없애 주시고, 심판의 날 그대들을 천국에 들게 할 것이니 그곳에는 궁궐 같은 저택이 있어 그 아래에는 강물이 흐르노라. 그날 하나님께서는 선지자와 그와 함께 믿었던 자들에게 불지옥으로 들어가는 치욕을 면제해 주실 것이라. 심판의 다리 를 건너기 위해 서 있는 믿는 자들 앞편과 오른편에는 빛이 펼쳐질 것이며 그들은 말할 것이라. “위선자들은 그들의 빛이 꺼진 나머지 심판의 다리를 건너지 못하였습니다. 저희의 주님이시여! 저희에게는 빛을 완전히 하시어 저희가 무사히 천국에 들어갈 수 있도록 해주십시오. 그리고 저희의 죄를 용서하여 주십시오. 실로 당신께서는 모든 것이 가능한 분이시기에 저희의 빛을 완전히 해 주십시오. 저희의 죄를 용서하는 일은 당신께 쉬운 일입니다”",
  66009: "선지자여! 불신자들을 상대로 (전시에) 무력으로 분투하고 위선자들을 상대로 (평시에) 말로써 분투하며 그들에게 엄격하라. 그들이 돌아가게 될 거주지는 지옥이니 그들이 귀착할 장소는 얼마나 사악한 곳인가.",
  66010: "하나님께서는 무슬림들과 그들의 친인척들에게 말씀하시면서, 하나님의 선지자 노아 (누흐) 와 롯 (루뜨) 의 아내를 예로 드시어 불신자들의 모습이 어떠할지를 그들에게 알려 주시노라. 두 여성은 하나님의 선량했던 두 종복의 아내였으나 남편의 종교를 배신한 채 불신자로서의 삶을 살았노라. 그렇기에 하나님의 사도인 노아와 롯은 하나님의 징벌에 관하여 자신들의 아내를 조금도 도와주지 못하노라. 그리고 두 아내에게 목소리가 들리니 “그대들은 지옥으로 들어갈 자들과 함께 불지옥으로 들어가라” 하더라. (이 구절은, 선지자들 혹은 선량한 자들과 친인척 관계에 있는 자라 할지라도 그들이 저지른 악행에 대한 대가는 반드시 치러야 함을 알려주고 있다. )",
  66011: "하나님께서는 파라오의 아내를 예로 드시어, 하나님을 믿고 그분만을 경배하며 그분의 법률을 지키면서, 불신자들과의 교류에도 불구하고 자신의 믿음을 굳게 지키는 신앙인들의 모습이 어떠한지 알려 주시노라. 그녀는 가장 사악한 불신자인 파라오의 아내였으나 하나님을 믿고 있었으니 그녀가 말하였노라. “저의 주님이시여! 천국에서 저를 위해 당신께 가까운 곳에 집을 지어 주십시오. 그리고 파라오의 폭정과 시험과 그가 저지르는 악행로부터 저를 구해 주시고 파라오의 부당함과 방황을 따르는 무리로부터, 그리고 그들이 받을 징벌로부터 저를 구해 주십시오”",
  66012: "하나님께서는 이므란의 딸 마리아 (마르얌) 를 예로 드시어, 하나님과 그분의 사도를 믿는 자들의 모습이 어떠한지 알려 주시노라. 마리아는 순결을 지키며 불법 성관계를 멀리하였기에 하나님께서는 가브리엘 (지브릴) 천사에게 명령하여 그 안에 숨을 불라고 하셨노라. 이에 그녀는 하나님의 전능하심으로 인해 아버지가 없는 예수를 잉태하였도다. 그녀는 하나님의 법률과 그분의 사도들이 계시 받은 성서들을 믿었으며, 또한 그녀는 하나님께서 명령하신 것을 실천하고 그분께서 금하신 것을 멀리함으로써 하나님께 부단히 복종하는 자들 중의 하나였노라.",
  67000: "알-물크 (주권)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님의 주권과 능력의 완벽함을 드러냄으로써 그분에 대한 경외심을 불어넣고 그분의 벌에 대한 경각심을 일깨우고 있다.\n•    요약 주해",
  67001: "축복 가득하신 하나님, 그분의 손에 모든 주권이 달려 있도다. 하나님께서는 모든 것이 가능한 분이시니 그분께 불가능한 일이란 있을 수 없노라.",
  67002: "하나님께서 죽음을 창조하시고 삶을 창조하셨으니 누가 더 훌륭한 행위를 하는지 그분께서 그대들 -인간들이여! - 을 시험하시기 위함이라. 그분께서는 그 누구도 감히 제압할 수 없는 가장 존엄하신 분이며, 용서를 구하는 자의 죄를 용서하시는 가장 너그러우신 분이라.",
  67003: "하나님께서는 일곱 개의 하늘을 창조하셨으니 하늘 위에 또 다른 하늘을 층으로 두시어 서로간의 간섭이 없도록 하셨노라. 그대는 하나님께서 창조하신 것에서 그 어떤 엉성함도 발견하지 못하노라. 그러니 그대는 눈을 되돌려 다시 살펴보라; 그대는 거기서 그 어떤 균열도 발견할 수 없을 것이며 그대가 보는 것은 오직 훌륭하고 완전한 창조물일 뿐이라.",
  67004: "그 후 계속해서 눈을 되돌려 보라: 하늘의 창조에서 허점이나 결함을 발견하지 못한 채 약해진 눈은 이제 침침해지어 제대로 볼 수조차 없을 것이라.",
  67005: "진실로 하나님께서는 빛나는 별들로써 지구에서 가장 가까운 하늘을 아름답게 꾸미셨으며 그 별들을 별똥별로 두시어 그것이 (하늘의 정보를) 몰래 엿듣는 사탄들을 격퇴하고 그들을 태워 버리도록 하셨노라. 그리고 내세에서 하나님께서는 사탄들에게 타오르는 화염을 준비하셨노라.",
  67006: "자신의 주님을 불신하는 자들에게는 부활의 날 불타오르는 지옥의 벌이 있노라. 그들이 돌아가게 될 지옥이란 얼마나 비참한 귀착지인가.",
  67007: "그들이 지옥 안으로 팽개쳐질 때 그들은 흉측하고 혹독한 지옥의 소리를 들으니, 지옥은 마치 가마솥의 물이 끓는 것처럼 그렇게 끓어오르더라.",
  67008: "지옥은 그 안으로 들어오는 자들에 대한 노여움으로 인해 산산이 조각나기 직전이라. 그 안에 한 무리의 불신자들이 내던져질 때마다 지옥을 관리하는 천사들이 그들에게 질책하며 물을 것이라. “너희가 현세에 있을 때 사도가 도래하여 하나님의 징벌을 두려워하라 경고하지 않았던가? ”",
  67009: "불신자들이 대답하였노라. “그렇습니다. 진작 저희들에게 하나님의 징벌을 경고하는 사도가 도래하였으나 저희들은 그를 부정하였고 ‘하나님은 그 어떤 것도 계시하지 않았소. 사도를 자처하는 그대들은 커다란 방황을 하는 것 뿐이오’라고 말하였습니다”",
  67010: "불신자들이 말하였노라. “저희들이 진작 제대로 들었거나 진리와 허위를 구분하기 위해 이성을 썼더라면 불지옥의 거주자들과 함께 있지 않았을 것입니다. 만약 그렇게 했더라면 저희들은 사도들을 믿고 그들이 가져온 것을 인정하여 결국 천국의 거주자들이 되었을 것입니다”",
  67011: "그리하여 그들은 자신의 불신과 부정을 인정하니 불지옥의 거주자들이여, 멀리 떨어지라.",
  67012: "(하나님께서는 불신자들의 모습과 그들이 받게 될 징벌을 언급하셨고, 이제 여기서는 신앙인들의 모습과 그들이 받을 보상에 대해 언급하고 계신다. )  사람들과 떨어져 홀로 있을 때도 하나님을 두려워하는 자들은 그들의 죄가 용서받게 될 것이며 그들은 천국이라는 커다란 보상을 얻게 될 것이라.",
  67013: "그대들 -인간들이여! - 이 비밀스레 말하거나 드러내 놓고 말한대도 하나님께서는 다 알고 계시노라. 실로 그분께서는 인간들의 가슴 속에 있는 것을 알고 계시는 분이니 그 어떤 것도 그분께는 감추어지지 않노라.",
  67014: "창조라는 위대한 비밀을 알고 계신 분, 하나님. 그분께서 존재하는 피조물 모두를 창조하셨는데 어찌 그분께서 그대들이 숨기는 하찮은 비밀을 알지 못한단 말인가? 그분께서는 인간들에게 가장 자상하신 분이며, 그들의 일을 소상히 알고 계신 분이기에 그분께는 그 어떤 일도 감추어지지 않노라.",
  67015: "그대들이 쉽게 거주할 수 있도록 대지를 순응토록 하신 분이 하나님이시라. 그러니 그대들은 대지의 여러 곳으로 이동하여 하나님께서 그 안에 준비해 두신 양식을 구해 먹어라. 그대들은 곧 그분께로 부활하여 심판과 보응에 직면하게 될 것이라.",
  67016: "그대들의 거주를 위하여 대지는 평탄해지고 순해졌으나 하늘에 계신 하나님께서는 -‘까룬’에게 벌을 내리셨던 것처럼 (제28장 81절) - 그대들과 대지를 한꺼번에 꺼뜨려 버리실 수 있음이라. 그럼에도 그대들은 그분으로부터 안전해 한단 말인가? 보라, 고요했던 대지가 이제는 요동치고 있노라.",
  67017: "하늘에 계신 하나님께서 -롯 (루뜨) 의 사람들에게 벌을 내리셨던 것처럼 (제11장 82절) - 그대들 위로 돌비를 보내실 수 있음이라. 그럼에도 그대들은 그분으로부터 안전해 한단 말인가? 그분의 징벌과 경고를 두 눈으로 목격할 때 그대들은 그것이 진정 무엇이었는지 알 것이나 벌을 목도할 때는 이미 늦은 것이라.",
  67018: "진실로 저들 우상 숭배자 이전의 공동체들도 (하나님의 징표를) 부인하였고 그들의 계속된 불신과 부정으로 하나님께서는 그들에게 징벌을 내리셨노라. 그러니 그들에 대한 나의 힐책이 어떠하였는지 보라. 그것은 혹독한 질책이었노라.",
  67019: "(하나님의 징표를) 부인하는 저들은 그들 위에서 날개를 펼치고 접는 새를 보지 않았던가? 새가 땅으로 떨어지지 않도록 붙잡아 주시는 분은 오직 하나님 뿐이라. 실로 그분께서는 모든 것을 보시는 분이니 그분께는 그 어떤 것도 감추어지지 않노라.",
  67020: "하나님께서 그대들 -불신자들이여! - 을 벌하고자 하실 때 그분의 벌로부터 그대들을 구해 줄 군대란 존재하지 않노라. 불신자들은 오직 사탄의 속임수에 넘어간 것일 뿐이라.",
  67021: "하나님께서 그분의 양식을 끊어 버리실 때 그대들에게 양식을 제공해 줄 자란 존재하지 않노라. 실로 불신자들은 거만함을 고집하며 진리에 대한 거부감을 버리지 않더라.",
  67022: "그러니 (지옥에서) 엎어진 채 자신의 얼굴을 바닥에 대고 걷는 자 -하나님께 대등한 존재를 두는 우상 숭배자- 가 더 인도받은 자인가 아니면 올곧은 길 위를 반듯하게 걷는 신앙인이 더 인도받은 자인가?",
  67023: "그대 - 사도여! - 는 저 우상 숭배자들에게 말하라. “그대들을 창조하시고 그대들을 위해 들을 수 있는 청각과 볼 수 있는 시각과 이해할 수 있는 마음을 두신 분이 하나님이시라. 그분께서 베풀어주신 이러한 은혜에도 그대들은 감사함이 참으로 적도다”",
  67024: "그대 - 사도여! - 는 (하나님의 징표를) 부정하는 우상 숭배자들에게 말하라. “그대들을 창조하여 대지에 퍼뜨린 분은 하나님이며 그대들의 우상이 아니라. 그것들은 그 무엇도 창조하지 못하노라. 그리고 부활의 날 그대들은 하나님께로 소집되어 심판과 보응이 이루어질 것이며, 우상은 그대들을 소집하지도 심판하지도 못하노라. 그러니 하나님 한 분만을 두려워하고 그분만을 경배하라”",
  67025: "부활을 부정하는 자들이 부활은 불가능한 일이라며 말하였노라. “무함마드 당신과 그대의 교우들은 우리에게 장담하면서 그날이 올 것이라 주장하는데 도대체 그날은 언제쯤 오는 것이오? ”",
  67026: "그대 - 사도여! - 는 말하라. “종말의 시간에 대한 지식은 오직 하나님께만 있으니, 그것이 언제인지는 오직 그분만이 아실 뿐이라. 나는 오직 경고자로서 그대들에게 분명한 경고의 말을 전할 뿐이라”",
  67027: "그리하여 심판의 날, 약속이 다가오니 그들은 두 눈으로 징벌을 목격하게 될 것이며 불신자들의 얼굴은 어두워질 것이라. 그리고 그들에게 목소리가 들릴 것이라. “이것이야말로 너희가 현세에서 재촉하던 그 약속의 실현이라”",
  67028: "그대 - 사도여! - 는 저 우상 숭배자들에게 반문하며 말하라. “나에게 알려 주어 보라: 하나님께서 나를 그리고 나와 함께 있는 믿는 자들을 죽음으로 거두어 간다 하더라도, 고통스러운 벌로부터 불신자들을 구해 줄 자는 누구란 말인가? 그 누구도 그들을 구해 줄 수 없노라”",
  67029: "그대 - 사도여! - 는 저 우상 숭배자들에게 말하라. “그대들이 홀로 경배해야 할 분은 가장 자비로우신 분이신 하나님이시라. 우리는 그분을 믿으며 그분 한 분께만 우리 일의 향방을 맡기노라. 그러니 그대들은 누가 명백한 방황 속에 있는지, 그리고 누가 올곧은 길을 걷고 있는지 곧 알게 될 것이라”",
  67030: "그대 - 사도여! - 는 저 우상 숭배자들에게 말하라. “나에게 알려 주어 보라: 만약 그대들이 마시는 물이 땅 속으로 스며들어 간다면 그대들은 그 어떤 물도 구할 수 없을 것이라. 이 때 그대들에게 줄기차게 흐르는 물을 가져다 줄 자가 하나님 이외에 또 있단 말인가? ”",
  68000: "알-깔람 (펜)\n계시 분류: 메카\n•    계시 목적    \n하나님께서는 이 장을 통해 선지자를 조롱하는 우상 숭배자들에 대응하여 선지자의 지식과 성품을 드러내고 계신다.\n•    요약 주해",
  68001: "(눈.)(이와 같은 단절 문자에 관하여는 야신 장 첫 번째 구절에서 이미 논의된 바 있다). 하나님께서 펜을 두고 맹세하시며, 펜으로써 사람들이 기록하는 것을 두고 맹세하시니",
  68002: "그대 - 사도여! - 는 하나님께서 베푸신 사도직을 받은 자로서 미친 자가 아니며 우상 숭배자들이 말하는 광기와는 무관하노라.",
  68003: "그대는 사람들에게 메시지를 전달하는 임무를 짊어지었기에 진실로 그대가 받을 보상은 끊이지 않는 것으로서, 그것은 그 어떤 인간도 그대에게 주지 못하는 하나님으로부터의 보상이라.",
  68004: "그리고 진실로 그대는 고결한 품성을 지녔으니, 그대는 꾸란이 명령하고 있는 훌륭한 품성을 가장 완벽히 실천하였도다.",
  68005: "그러니 그대는 볼 것이며 부정하는 저들도 볼 것이라.",
  68006: "진리가 밝혀지는 순간 그대들 중 광기 들린 자가 누구인지 드러날 것이라.",
  68007: "실로 그대 - 사도여! - 의 주님께서는 누가 그분의 길을 벗어나 방황하는지 알고 계시며 그분께서는 누가 올바른 길을 걷는 자들인지 가장 잘 알고 계신 분이라. 그리하여 그분께서는, 그들이 하나님의 길에서 벗어나 방황하고 있으며 그대는 올바른 길을 걷고 있음을 알고 계시노라.",
  68008: "그러니 그대 - 사도여! - 는 그대가 가져온 진리를 부정하는 자들을 따르지 말라.",
  68009: "그들은 그대가 종교를 포기한 채 그들을 마냥 유화롭게 대하고 그에 따라 그들도 그대를 유화롭게 대하길 갈망하더라.",
  68010: "그대는, 말끝마다 거짓으로 맹세하는 비천한 자들 중 그 어떤 누구도 따르지 말라.",
  68011: "그는 사람들의 험담을 일삼고, 친했던 자들을 고자질과 흉보기로 갈라 놓는 자라.",
  68012: "그는 지속적으로 선을 막고, 사람들의 재산과 명예와 생명을 침해하며 수많은 죄를 저지르는 자라.",
  68013: "뿐만 아니라 그는 모질고 혹독하며, 사람들 사이에 출신 가문이 명확하지 않은 자라.",
  68014: "그는 재물과 자손을 소유했다는 이유로 하나님과 그분의 사도에 대한 믿음에 거만해 하였노라.",
  68015: "그에게 하나님의 징표가 낭송될 때면 그는 “이것은 옛날 사람들의 설화일 뿐이라”라고 말하였노라.",
  68016: "하나님께서는 그의 코 위에 지워지지 않는 흉칙한 표시를 새기실 것이라.",
  68017: "실로 하나님께서는 저 (메카의) 우상 숭배자들을 가뭄과 기아로 시험하였으니 마치 정원의 소유자들을 시험한 것과 같노라. 정원의 주인들이 맹세하였노라. “우리는 정녕코 이른 새벽에 정원의 열매를 거두어 갈 것이니, 그렇게 하면 가난한 자 누구도 우리의 열매에 손을 대지 못할 것이라”",
  68018: "그러나 그들은 맹세를 하면서 ‘하나님께서 원하신다면’ (인샤알라) 라고 말하여 예외가 발생할 수 있음을 언급하지 않았노라.",
  68019: "그리하여 하나님께서는 정원에 불을 내리시어 그것을 태워버리셨으나 정원의 주인들은 잠들어 있었기에 정원에 대해 손을 쓸 수가 없었노라.",
  68020: "그리하여 정원은 칠흑 같은 밤처럼 새까맣게 변했노라.",
  68021: "그렇게 그들은 이른 새벽에 서로가 서로를 부르더라.",
  68022: "그들은 서로를 부르며 말하였노라. “가난한 자들이 오기 전에 정원의 열매를 거두고 싶다면 그대들은 아침 일찍 경작지로 떠나야 하오”",
  68023: "그리하여 그들은 낮은 목소리로 서로에게 이야기하면서 서둘러 출발하였노라.",
  68024: "그들이 서로 얘기하더라. “오늘만큼은 어떤 불우한 자도 그대들의 정원에 들어와선 안 되오”",
  68025: "그들은 가난한 자들이 열매를 먹지 못하게 하겠다는 굳은 결심을 하며 아침 일찍 떠났노라.",
  68026: "그리하여 그들이 타버린 정원을 보았을 때 말하였노라. “진실로 우리는 길을 잘못 든 것이라”",
  68027: "“그렇지 않노라. 우리는 불우한 자들이 열매를 먹지 못하도록 저지하려 했고 그로 인해 우리가 열매를 따지 못하도록 제지된 것이라”",
  68028: "그들 중의 가장 훌륭한 자가 말하였노라. “가난한 자들이 열매를 먹지 못하도록 그대들이 그들을 막겠다 다짐했을 때 내가 그대들에게 하나님을 찬양하고 그분께 용서를 구하라고 말하지 않았는가? ”",
  68029: "그들은 말하였노라. “저희의 주님은 완벽하신 분이며, 가난한 자들이 열매를 먹지 못하게 막으려 한 저희는 실로 부당한 자들이었습니다”",
  68030: "그들은 서로가 서로를 바라보며 원망의 말을 주고 받았노라.",
  68031: "그들이 후회하며 말하였노라. “우리는 몰락하였습니다! 가난한 자들의 권리를 막은 우리는 실로 경계를 넘어선 자들이었습니다”",
  68032: "“우리의 주님께서 우리의 이전 정원을 더 좋은 것으로 대체하여 주시길 바랍니다. 실로 우리는 우리의 주님께로만 소망하고 그분께 용서를 구하면서 좋을 것을 주십사 기도할 뿐입니다”",
  68033: "하나님께서는 양식을 금하는 이러한 벌로써 그분을 거역하는 자를 벌하시노라. 그러나 그들이 알고 있다면 내세의 벌은 그 혹독함과 지속함이 현세의 벌보다 훨씬 더 크노라.",
  68034: "하나님의 명령을 지키고 그분께서 금지한 것을 멀리함으로써 하나님을 경외하는 자들은 실로 그들 주님께 가까운 곳에서 기쁨의 천국을 가질 것이니 그들은 그곳에서 영원히 기뻐할 것이라.",
  68035: "그런데도 하나님께서 - 메카의 우상 숭배자들이 주장하는 것처럼 - 무슬림들과 불신자들에게 동일한 보상을 내리신단 말인가?",
  68036: "그대들 - 우상 숭배자들이여! - 에게 무슨 일이 일어난 것인가? 도대체 어떻게 판단하길래 그대들은 이러한 불공정한 판결을 내리는 것인가?",
  68037: "아니면, 순종하는 자들와 거역하는 자들을 동일하게 둔 판결에 관하여 그대들이 읽는 책이라도 있단 말인가?",
  68038: "실로 그대들은 내세에서 고르는 대로 다 가질 것이라는 말이 그 책에 있는 것인가?",
  68039: "아니면 하나님께서 책임져 주실 확실한 맹세를 그대들이 가지고 있어 그 맹세에 의해 그대들은 판결하는 대로 다 가진단 말인가?",
  68040: "그대 - 사도여! - 는 저러한 말을 하는 그들에게 그들 중의 누가 그것을 보증할 것인지 물어보라.",
  68041: "아니면 그들에게는 하나님과 대등한 존재들이 있어 그것들이, 믿는 자들과 우상 숭배자에게 동일한 보상을 준단 말인가? 그렇다면, 그들의 주장이 사실이라면 그들이 말하는 대등한 존재들을 가져와 보도록 하라.",
  68042: "심판의 날 공포가 전개되고 하나님께서는 당신의 정강이를 노출하실 것이며 사람들은 부복할 것을 명령받을 것이라. 이에 믿는 자는 엎드려 절하지만 불신자와 위선자는 그렇게 하지 못하노라.",
  68043: "그들의 눈은 모욕으로 가득 찰 것이며 후회와 굴욕이 그들을 덮칠 것이라. 그들은 이전에, 심판의 날의 공포가 없는 안전한 현세에서 하나님께 엎드려 절하라 요구받은 적이 있노라.",
  68044: "그러니 그대 - 사도여! - 는 그대에게 계시된 이 꾸란을 부정하는 자를 하나님께 놓아 두라. 하나님께서는 그들이 서서히 징벌을 맛보도록 할 것이니, 그들은 그것이 자신들에 대한 책략이자 단계적 징벌임을 알지 못하노라.",
  68045: "하나님께서는 그들에게 시간을 연장하시어 그들이 더 많은 죄를 짓도록 할 것이라. 실로 불신하고 부정하는 자들에 대한 하나님의 계략은 강력하니, 하나님께서는 그들에 관한 그 무엇도 놓치지 않으시며 그들은 하나님의 징벌로부터 조금도 벗어나지 못할 것이라.",
  68046: "만약 그대 - 사도여! - 가 이슬람을 전한다는 이유로 그들에게 보수를 요구할 경우 그들은 엄청난 채무를 짊어지게 될 것이니, 그들은 이를 이유로 그대에게 등을 돌리는 것인가? 사실은 그렇지 아니하니, 그대는 그들에게 어떠한 것도 요구하지 않노라. 그런데도 그들은 왜 그대를 따르지 않는가?",
  68047: "아니면 보이지 않는 영역에 대한 지식을 그들이 소유하고 있어 거기서 유리한 근거들을 끄집어 낸 후 그것으로써 그대와 논쟁을 벌이는 것인가?",
  68048: "그러니 그대 - 사도여! - 는 그대 주님께서 그들을 보류하심에 인내하고, 물고기의 동료인 선지자 요나처럼 사람들의 불신을 원망하지 말라: 요나는 바다의 어둠에서, 그리고 물고기 배 속의 어둠에서 시름에 잠긴 채 하나님을 불렀노라.",
  68049: "하나님의 자비가 아니었다면 실로 그는 비난받으며 물고기 배 속에서 벌판으로 내던져졌을 것이라.",
  68050: "그리하여 그의 주님은 그를 선택하시어 선량한 종복들 중의 하나로 두셨노라.",
  68051: "하나님과 그분의 사도를 불신하는 자들은 그대에게 계시된 꾸란을 들을 때마다 그대를 노려보니 그들의 무서운 눈이 그대를 넘어뜨리기 직전이라. 그들은 욕망을 따르고 진리에 등을 돌리면서 “자신이 사도라고 주장하는 그는 진실로 미친 자라” 고 말하더라.",
  68052: "그러나 그대에게 계시된 이 꾸란은 다름 아닌 인간과 진을 위한 교훈과 일깨움의 메시지라.",
  69000: "알-학까 (기필코 찾아올 날)\n계시 분류: 메카\n•    계시 목적    \n이 장은 부활의 날이 반드시 올 것임을 말하면서 꾸란의 진실성을 강조하고 있다. 또한 이 장은 믿는 자들에게는 기쁨이 있을 것임을 약속하고, 불신자들에게는 슬픔이 있을 것임을 경고하고 있다.\n•    요약 주해",
  69001: "하나님께서는 필연적으로 찾아올 부활의 날을 언급하고 계신다.",
  69002: "그 후 그분께서는 다음 질문을 통해 그날의 위대함을 재확인하고 계신다: 기필코 찾아올 날이란 무엇인가?",
  69003: "그 누가 그대에게 기필코 찾아올 날이 무엇인지를 알려줄 것인가?",
  69004: "쌀리흐 시대의 백성이었던 싸무드 부족과 후드 시대의 백성이었던 아드 부족은 인류에게 닥칠 대재앙의 날 (심판의 날) 을 부정하였노라.",
  69005: "하나님께서는 극한의 고통을 유발하는 무서운 굉음으로써 싸무드 부족을 멸망시키셨노라.",
  69006: "아드 부족은 하나님께서 그들을 파멸시켰으니 엄청난 추위를 동반한 맹렬한 바람이 그들을 엎쳤노라.",
  69007: "하나님께서 바람을 굴종시키심에 그 바람은 일곱 밤과 여덟 낮 동안 쉬지 않고 그들을 파괴하였노라. 그리하여 그대는 사람들이 자신의 집 안에서 고꾸라져 죽어 있음을 보니 그들의 주검은 마치 쓰러져 버린 야자수의 썩은 몸통과도 같더라.",
  69008: "그러니 그대는, 징벌이 덮친 후 그들에게 어떠한 영혼도 남아 있지 않음을 볼 것이라.",
  69009: "(그들 이후에) 파라오와 그 이전의 공동체와 뒤집혀진 마을의 주민들 (롯 (루뜨) 의 백성들) 이 도래하였고, 그들은 우상 숭배와 거역 행위 등의 죄를 저질렀노라.",
  69010: "그렇게 그들은 그들에게 도래한 사도에 불복하고 그를 부정하였으니 하나님께서는 그들에게 파멸 그 이상의 벌을 내리셨노라.",
  69011: "실로 하나님께서는 물이 (홍수로 인해) 그 경계를 넘어섰을 때 그대들을 방주에 태우셨으니, 그 방주는 노아 (누흐) (그에게 평화가 깃들기를) 가 하나님의 명령을 받아 지은 것이라.",
  69012: "그리하여 하나님께서 방주와 그에 관한 이야기를 사람들을 위한 교훈으로 두시어, 불신하는 자들은 멸망하며 믿는 자들은 번성한다는 사실을 떠올릴 수 있도록 하고, 깨어있는 귀가 그것을 듣고 기억하기 위함이라.",
  69013: "이제 나팔을 부는 임무를 맡은 천사가 나팔에 숨을 불어넣으니 두 번째 나팔 소리라.",
  69014: "대지와 산들이 위로 들어올려져 한꺼번에 산산조각이 나더라.",
  69015: "이 모든 것이 일어나는 그날은 심판의 날이 도래하는 날이라.",
  69016: "천사들이 하늘로부터 하강함에 그것이 갈라지니, 단단하고 야물던 하늘은 그렇게 흐물흐물해졌노라.",
  69017: "천사들은 하늘의 여러 끝자락 위에 있을 것이며, 위대한 이날 여덟 명의 천사들이 그대 주님의 권자를 떠받칠 것이라.",
  69018: "그날 그대들 - 사람들이여! - 은 하나님 앞에 놓여지게 될 것이니 그분께서는 그대들의 어떠한 내밀한 행위도 놓치지 않으시고 다 들여다 보실 것이라.",
  69019: "행위 기록부를 자신의 오른쪽에서 받은 자는 기뻐하며 말할 것이니 “내 행위가 담겨진 이 기록부를 읽어들 보시오” 하더라.",
  69020: "“실로 나는 현세에서, 언젠가 내가 죽음에서 부활하여 보상과 징벌을 맞닥뜨릴 것임을 확신하고 있었소”",
  69021: "그리하여 그는 끊이지 않는 기쁨으로 인해 만족스런 삶을 누리더라.",
  69022: "그 위치와 지위가 높은 천국에서의 삶이라.",
  69023: "천국의 과실은 가까이 드리워져 있어 손쉽게 먹을 수 있노라.",
  69024: "그들을 융숭히 대접하기 위한 목소리가 들리니 “그대들은 즐거이 먹고 마시라, 지난 날 현세에서 그대들이 실천한 선행에 대한 대가라” 하더라.",
  69025: "행위 기록부를 자신의 왼쪽에서 받은 자는 크게 후회하며 말할 것이니 “내가 아예 내 기록부를 받지 않았더라면 좋았을 텐데! 나의 기록부에는 악행이 있으니 내가 그로 말미암아 벌을 받을 것이라”",
  69026: "“내가 차라리 나의 계산 결과를 몰랐더라면 좋았을 텐데! ”",
  69027: "“내가 죽고 나서 아예 다시 부활하지 않았더라면 좋았을 텐데! ”",
  69028: "“내 재산도 하나님의 벌을 경감시킴에 나에게 어떠한 도움이 되지 않는구나”",
  69029: "“내가 강력하다고 생각했던 (불신의) 근거들도 이제는 내게서 다 사라져 버렸구나”",
  69030: "목소리가 들릴 것이라. “그대들 - 천사들이여! - 은 그를 잡은 후 그의 손으로써 그의 목덜미를 감으라”",
  69031: "“그런 후 그를 작열하는 불지옥에 집어 넣어 그 뜨거움을 맛 보게 하라”",
  69032: "“그런 후 길이가 칠십 척인 사슬 속으로 그를 던져 넣으라”",
  69033: "실로 이전에 그는 가장 위엄하신 하나님을 믿지 않았으며",
  69034: "불우한 자들에게 음식을 주자고 사람들에게 권유하지 않았노라.",
  69035: "그렇기에 심판의 날 그의 벌을 막아줄 절친한 친구는 없노라.",
  69036: "지옥의 거주자들의 육체에서 흘러나오는 진물 이외에는 그에게 먹을 것이 없노라.",
  69037: "그것을 먹는 자는 오직 죄를 지으며 불복했던 자들 뿐이라.",
  69038: "그러니 하나님께서는 그대들이 보는 것을 두고 맹세하시고",
  69039: "그대들이 보지 못하는 것을 두고 맹세하시니",
  69040: "진실로 꾸란은 하나님의 말씀으로서 그분의 명예로운 사도가 그것을 사람들에게 낭송하노라.",
  69041: "이 꾸란은 시인의 말이 아니라; 꾸란은 시의 운율을 따르지 않노라. 그대들이 믿는 것은 조금일 뿐이더라.",
  69042: "또한 꾸란은 점술가의 말도 아니라; 점술가의 말과 꾸란은 서로 구분되노라. 그대들이 깊이 생각하는 것은 조금일 뿐이더라.",
  69043: "그러나 그것은 모든 피조물의 주님이신 하나님으로부터 내려온 것이라.",
  69044: "만약 무함마드가 하나님께서 말씀하지 않은 것으로써 일부 말들을 지어냈다면",
  69045: "하나님께서는 그를 강력히 움켜잡아 응징했을 것이라.",
  69046: "그런 후 실로 하나님께서 그의 대동맥을 절단했을 것이라.",
  69047: "그럼에도 그대들 중 어떤 누구도 하나님을 가로막지 못할 것이라. 그렇기에 그가 그대들을 상대로 하나님에 관하여 말을 지어낸다는 것은 불가능한 일이라.",
  69048: "실로 꾸란은 교훈으로서, 하나님께서 명령하신 것을 지키고 그분께서 금하신 것을 멀리함으로써 주님을 경외하는 자들에게 교훈이 되노라.",
  69049: "진실로 하나님께서는 그대들 중에 꾸란울 부정하는 자들이 있음을 알고 계시노라.",
  69050: "진실로 꾸란을 부정하는 행위는 심판의 날 커다란 후회가 될 것이라.",
  69051: "진실로 꾸란은 확실한 진리로서, 그것이 하나님으로부터 온 것임에 어떠한 의심의 여지도 없노라.",
  69052: "그러니 그대 - 사도여! - 는 그대 주님의 완벽함을 찬양하고 가장 위엄하신 그대 주님의 이름을 떠올리라.",
  70000: "알-마아리즈 (승천의 길)\n계시 분류: 메카\n•    계시 목적    \n이 장은 불신자들이 받을 징벌과 심판의 날을 믿는 자들이 누릴 내세의 안락함을 강조하고 있다.\n•    요약 주해",
  70001: "우상 숭배자 출신의 한 남성이 자신과 그의 사람들에게 벌이 내려지길 기도하였도다. 그는 벌이란 존재하지 않는 것이라며 비아냥거렸으나 심판의 날 그 벌은 어김없이 닥쳐올 것이라.",
  70002: "그 벌은 하나님을 불신하는 자들을 위한 것으로서, 어떤 누구도 그 벌을 막을 수 없노라.",
  70003: "그 벌은 은혜와 은총의 소유자이신, 지고하시고 드높으신 하나님께서 내리시는 것이라.",
  70004: "부활의 날 천사들과 가브리엘 (지브릴) 천사는 하나님께로 올라가니 유구한 그날의 길이는 오만년이라.",
  70005: "그러니 그대 - 사도여! - 는 역정이나 불평 없이 인내하라.",
  70006: "실로 그들은 이 벌이 결코 일어나지 않을 것이라 생각하지만",
  70007: "하나님께서는 그 벌을 곧 일어날 것으로 보시노라.",
  70008: "그날 하늘은 끓는 쇳물처럼 될 것이라.",
  70009: "그리고 산들은 가벼운 양털처럼 될 것이라.",
  70010: "또한 절친한 친구는 다른 절친한 친구의 안부를 묻지 않을 것이니, 모두는 오직 자신의 안위만을 신경 쓸 뿐이라.",
  70011: "모든 이는 자신의 피붙이를 목격하지만 서로가 서로의 안부를 묻지 못하니 심판의 날에 펼쳐지는 무서움 때문이라. 지옥에 들어가게 될 자는 자신의 자손을 바쳐서라도 지옥의 징벌로부터 벗어나길 애원하노라.",
  70012: "자신의 아내와 형제를 바칠 수만 있다면",
  70013: "어려울 때 자신과 함께 있어 주던 가까운 친척을 바칠 수만 있다면",
  70014: "지구상에 있는 인간과 진 (Jinn) 등 모두를 바칠 수만 있다면, 그리하여 그들의 몸값으로 자신이 불지옥의 고통으로부터 해방될 수만 있다면 하고 애원하노라.",
  70015: "그것은 악행을 저지른 자의 헛된 바람일 뿐이라. 내세에서의 지옥은 타오르는 화염이라.",
  70016: "지옥의 거주자들은 불지옥의 뜨거움으로 인해 머리 껍질이 녹아 내릴 것이라.",
  70017: "지옥은 (현세에서) 진리에 대해 등을 돌리며 믿지도 실천하지도 않던 자를 부르노라.",
  70018: "지옥이 부르는 그 자는, 돈을 모으면서도 하나님의 길에서 자신의 재산을 쓰지 않던 자라.",
  70019: "실로 인간은 욕심 많게 창조되었노라.",
  70020: "그에게 병환이나 가난 등의 재앙이 닥치면 오래 참지를 못하고",
  70021: "그에게 풍년이나 재물 등 좋은 것이 생기면 하나님의 길에서 재산을 쓰지 않고 몹시 박하게 구노라.",
  70022: "그러나 예배 드리는 자들은 예외니 저러한 나쁜 습성을 가지고 있지 않노라.",
  70023: "그들은 실로 그들의 예배에 있어 근면한 자들로서, 바쁘다는 핑계로 예배를 놓치지 않으며 지정된 예배 시간에 예배를 드리는 자들이라.",
  70024: "그리고 그들의 재산에 정해진 몫이 있는 자들이니",
  70025: "그 몫은 가난하여 구걸하는 자와, 가진 양식이 없어도 구걸하지 않는 자를 위한 것이라.",
  70026: "그리고 그들은 모든 이가 행한 대로 보상 받을 부활의 날을 믿으며",
  70027: "선행을 실천하면서도 그들 주님께서 그들에게 내리실지도 모를 벌에 대해 두려워하는 자들이라.",
  70028: "실로 그들 주님의 벌이란 이성을 지닌 자라면 그 누구도 안전해 할 수 없는 것이라.",
  70029: "그리고 그들은 실로 자신의 순결을 보호하면서 추악한 행위를 멀리하는 자들이라.",
  70030: "그러나 그들의 배우자나 그들이 소유한 노비에 관하여 그들이 부부 관계를 가지더라도 책망받지 않노라.",
  70031: "그런데도 배우자나 노비 이외의 것으로 욕망을 해결하려는 자들이 있다면 저들은 실로 하나님께서 지정하신 경계를 넘은 자들이라.",
  70032: "그리고 그들은 실로 위탁받은 물건이나 전해 들은 비밀 등을 보존하고 사람들과 맺은 계약을 지키면서, 수탁한 물건에 대해 신의를 저버리거나 체결한 계약을 위반하지 않는 자들이라.",
  70033: "그리고 그들은 증언을 섬에 실로 굳건하여, 증언의 대상에 대한 친분이나 적의가 그들의 증언에 영향을 끼치지 않노라.",
  70034: "그리고 그들은 실로 그들의 예배를 꾸준히 지키니, 정해진 예배 시간을 준수하고 예배 전의 세정과 예배 중의 고요함을 지키면서 다른 일을 핑계로 예배를 빠뜨리지 않노라.",
  70035: "그들은 천국에서 영원한 기쁨을 누리며 거주할 것이며, 거기서 그들은 하나님의 고귀한 얼굴을 보게 될 것이라.",
  70036: "우상 숭배자들이 그대 - 사도여! - 근처에서 서둘러 그대를 부정하니 이는 어찌 된 일인가?",
  70037: "그들은 그대의 오른쪽과 왼쪽에서 군집을 이루더라.",
  70038: "불신을 버리지 않으면서도 그들 모두는 천국에 들어가길 희망하니, 하나님의 허락으로 천국에 입성하여 그곳에서 기쁨을 누리길 원하더라.",
  70039: "그들이 희망하는 것과 현실은 엄연히 다르노라. 실로 하나님께서 그들을 창조하심에, 그들이 잘 알고 있는 보잘것없는 정액으로부터 그들을 창조하셨노라. 그렇게 그들은 허약한 자들이니 그들 자신에게 효용도 해악도 제대로 통제할 수 없노라. 그럼에도 어떻게 그들은 거만해한단 말인가?",
  70040: "해와 달과 모든 별들이 뜨고 지는 장소를 소유하신 하나님, 그분께서 당신 자신을 걸고 맹세하시니 실로 하나님께서는 능력을 가지신 분이라;",
  70041: "하나님께서는 그들을 파멸시킨 후 그분께 순종하는 자들로써 그들을 대체하실 능력을 가지신 분이며, 그들을 파멸시키고 대체함에 그 누구도 그분을 막을 수 없노라.",
  70042: "그러니 그대 - 사도여! - 는 그들을 놓아두라; 그들은 허위와 방황의 말들을 내뱉으며 현세의 삶을 즐기다가 결국에는 꾸란을 통해 약속받은 심판의 날을 직면하게 될 것이라.",
  70043: "그날 그들은 마치 어떤 표식을 두고 경쟁하여 달리는 것처럼 그렇게 묘지에서 재빨리 빠져 나올 것이라.",
  70044: "그들의 눈은 모욕으로 가득 찰 것이며 후회와 굴욕이 그들을 덮칠 것이라. 저 날은 그들이 약속받던 날로 그들은 현세에서 심판의 날에 대해 신경조차 쓰지 않았노라.",
  71000: "누흐 (노아)\n계시 분류: 메카\n•    계시 목적    \n이 장은 노아 (누흐) 의 이야기를 통해 이슬람을 알리는 사람들이 갖추어야 할 인내심과 그들의 분투에 대해 교훈을 주고 있다. 또한 이 이야기로써 믿는 자들의 신앙은 증진되고 믿음을 부정하는 자들은 경고의 메시지를 받게 된다.\n•    요약 주해",
  71001: "실로 하나님께서는 노아 (누흐) 를 사도로 선택하시어 그의 백성들에게 보냈으니, 그가 그들을 이슬람으로 초대하고 그들이 저지르고 있는 우상 숭배로 인해 받을 고통스러운 벌을 경고하도록 하셨노라.",
  71002: "그가 사람들에게 말하였노라. “나의 사람들이여. 실로 나는 그대들을 위한 명백한 경고자니, 그대들이 하나님께 참회하지 않는다면 그대들에게 벌이 내리고 말 것이라.",
  71003: "내가 그대들에게 분명히 경고하건대 그대들은 하나님 한 분만을 경배하고 그분께 어떠한 대등한 존재도 두지 말라. 그리고 그분께서 명령하신 사항을 실천하고 그분께서 금하신 것을 멀리함으로써 그분을 경외하라. 그리고 그대들은 내가 내리는 명령을 따르라.",
  71004: "그대들이 그렇게 했을 때 하나님의 권리와 관련한 그대들의 죄가 용서될 것이며 하나님께서 그대들의 수명을 연장시켜 주실 것이니 그분만이 아시는 지정된 기간까지라. 실로 죽음이 도래했을 때는 결코 늦추어지는 법이 없노라. 그대들이 이를 제대로 알았더라면 그대들은 서둘러 하나님을 믿고 그대들이 저지르던 우상 숭배와 방황에 대해 서둘러 참회했을 것이라”",
  71005: "노아 (누흐) 가 말하였노라. “저의 주님이시여! 실로 저는 사람들에게 당신을 믿고 당신만을 경배하라고 밤낮으로 이야기했습니다.",
  71006: "그러나 저의 부름은 오직 그들의 반감만을 증가시켰을 뿐이며 그들은 신앙으로부터 멀어지기만 했습니다.",
  71007: "당신을 경배하고 당신께서 지정하신 경계를 지키고 당신과 당신의 사도를 따르라고, 그리하여 당신의 용서를 받으라고 제가 그들을 부를 때마다 그들은 손가락을 귀에 대고선 제 말을 듣지 않으려 했으며 자신의 옷으로 얼굴을 덮어 싸며 저를 보지 않으려 했습니다. 그리고 그들은 우상 숭배를 계속하면서 제가 초대하는 신앙에 대해 거만을 떨며 거부하였습니다.",
  71008: "그 후 실로 저는 - 주님이시여! - 그들을 큰 소리로 불렀습니다.",
  71009: "그 후 실로 저는 목소리 높여 그들을 믿음으로 초대하였고, 낮은 소리로 비밀스레 그들에게 말을 걸기도 하였습니다. 그렇게 저는 다양한 방식으로 그들을 불렀습니다.",
  71010: "그리하여 제가 그들에게 말하였습니다. ‘그대들은 참회로써 그대들 주님에게 용서를 구하라. 실로 하나님께서는 참회하는 종복을 너그러이 용서하시는 분이도다.",
  71011: "그대들이 내가 말한 대로 할 때 하나님께서는 그대들에게 필요한 만큼의 풍성한 비를 내려주실 것이며 그리하여 그대들에게는 가뭄이 들지 않을 것이라.",
  71012: "그리고 하나님께서는 그대들에게 많은 재산과 자손을 주실 것이고 그대들을 위해 과실이 풍부한 정원을 두실 것이며 그대들을 위해 강을 두실 것이니 그로부터 그대들이 물을 마시고 농작물과 가축에 물을 댈 것이라.",
  71013: "사람들이여! 그대들은 하나님의 위엄하심을 두려워하지 않고 그분을 거역함에 개의치 않으니 이 어찌 된 일인가?",
  71014: "실로 하나님께서는 정액에서 응혈로 그리고 작은 살점으로 그대들을 창조하셨노라.",
  71015: "하나님께서 어떻게 일곱 개의 하늘을 겹겹이 창조하셨는지 그대들은 알지 못하는가?",
  71016: "그리고 그분께서는 일곱 개의 하늘 중 가장 낮은 현세의 하늘에 달을 두심에 지구의 거주자를 위해 빛으로 두셨으며 그분께서는 태양이 빛을 내뿜도록 하셨노라.",
  71017: "하나님께서는 그대들을 흙으로부터 만드셨으니 그대들의 아버지인 아담을 흙으로부터 창조하셨노라. 그 후 그대들은 흙에서 곡물을 자라게 하여 그것을 먹어 영양분을 얻으며,",
  71018: "그 후 하나님께서는 그대들이 죽어서 흙으로 되돌아가게 하시고 그 후 부활을 위해 흙으로부터 그대들을 다시 꺼내실 것이라.",
  71019: "하나님께서는 그대들이 쉽게 거주할 수 있도록 대지를 넓고 매끈하게 두셨노라.",
  71020: "그대들이 그 안에서 넓은 길을 드나들며 허락된 양식을 구할 수 있도록 함이라’”",
  71021: "노아 (누흐) 가 말하였노라. “저의 주님이시여! 실로 그들은 저에게 불복하였으며 그들은, 자신의 재산과 자식으로써 오직 자신에게 손실만을 증가시키는 자를 따랐습니다.",
  71022: "그리고 그들 중의 우두머리들은 저와 사람들 사이를 이간질하며 매우 커다란 책략을 꾸몄습니다.",
  71023: "그리고 그들은 그들의 추종자들에게 말했습니다. ‘그대들은 우상 숭배를 절대 그만두지 말며, 그대들의 우상인 ‘왓드’와 ‘수와으’와 ‘야구쓰’와 ‘야우끄’와 ‘나스르’ 숭배를 절대 그만두지 말라’",
  71024: "실로 그들은 이 우상들로 많은 사람들을 방황시켰습니다. 당신 - 주님이시여! - 께 기도컨대, 불신과 거역을 지속함으로써 자기 자신을 부당히 대우하는 자들에게는 오직 방황만을 증가시켜 주십시오”",
  71025: "그들은 자신이 저지른 죄로 인해 홍수로 익사하였고 죽음 후에는 불 속으로 곧바로 들어가게 되었으니 그들은 홍수와 불로부터 자신들을 구해줄, 하나님 이외의 어떤 조력자도 찾지 못하였노라.",
  71026: "하나님께서 노아 (누흐) 에게 알려주시면서, 지금껏 믿은 자들 이외에는 더 이상 누구도 믿지 않을 것이라 하셨을 때 노아는 말하였노라. \"저의 주님이시여! 불신자들 중에서 생명이 붙어있는 단 한 명의 인간일지라도 그를 지구상에 남겨두지 마십시오.",
  71027: "실로 당신 -저희의 주님이시여! - 께서 그들을 남겨두신다면 그들은 당신을 믿는 종복들을 방황케 할 것이며, 당신께 순종하지 않는 사악한 자, 당신의 은총에 감사하지 않는 불신자만이 그들의 자식으로 태어날 것입니다.",
  71028: "저의 주님이시여! 저의 죄를 용서하여 주시고 저의 부모님과, 믿는 자로서 저의 집에 들어왔던 자와, 믿는 남성들과 믿는 여성들을 용서하여 주십시오. 그리고 불신과 거역으로 자기 자신을 부당히 대우하는 자들에게는 오직 파멸과 손실만을 더해 주십시오\"",
  72000: "알-진 (Jinn)\n계시 분류: 메카\n•    계시 목적    \n이 장은 진의 믿음을 통해 꾸란이 하나님으로부터 내려진 계시임을, 그리고 우상 숭배자들의 미신은 허위임을 밝히고 있다.\n•    요약 주해",
  72001: "그대 - 사도여! - 는 그대를 따르는 공동체에 말하라. “하나님께서 나에게 계시를 내려주시어 알려주시길, 한 무리의 진이 '바뜬 나클라' 지역에서 낭송하던 나의 꾸란 소리를 들었고, 그들은 자신의 마을로 돌아가 다른 진들에게 이렇게 말하였노라. “실로 우리는 그 의미과 음율이 놀랄 정도로 아름다운 낭송을 들었습니다.",
  72002: "우리가 들은 이 말씀은 올바른 믿음과 말과 행동이 무엇인지를 제시하기에 우리는 그것을 믿었습니다. 그리고 우리는 이 말씀을 계시한 우리 주님께 어떤 대등한 존재도 두지 않을 것입니다.",
  72003: "실로 우리 주님께서 소유하신 존엄은 지고한 것이며, 우상 숭배지들의 말과는 달리 그분께서는 아내도 자식도 가지지 않으셨습니다.",
  72004: "실로 이블리스는 하나님에 관하여 궤언을 하며 그분에게 아내와 자식이 있다는 주장을 하곤 하였습니다.",
  72005: "인간과 진의 우상 숭배자들이 “하나님께서는 아내와 자식을 가지고 계시다”라고 말할 때 실로 우리는 그들이 하나님에 관하여 결코 거짓말을 하지 않을 것이라 생각하여 그들을 따라 믿었습니다.",
  72006: "실로 무지의 시대에 인간 남성들은 무서운 장소에서 하룻밤을 보낼 때면 진 남성들에게 보호를 요청하곤 하였고 그들은 이렇게 말하였습니다: ‘저는 이 골짜기에 사는 진의 우두머리에게 그 졸개들의 사악함으로부터 보호를 구합니다’ 그렇게 하여 진 남성들에 대한 인간 남성들의 공포심은 더욱 커졌습니다.",
  72007: "그리고 실로 인간은, 그대들 - 진이여! - 이 생각한 것처럼 하나님께서 그 누구도 결코 부활시키지 않을 것이며 심판도 보응도 없을 것이라 생각하였습니다.",
  72008: "실로 우리가 하늘의 소식을 엿들으려 하였으나 하늘은 천사들로 가득차 있었고 그들은 강력한 파수꾼이 되어 우리의 엿들음을 막았습니다. 하늘은 또한 타오르는 불로 가득차 있었는데 그것은 소식을 엿들으려 가까이 다가가는 자들에게로 날아갔습니다.",
  72009: "실로 예전에 우리는 천사들끼리 교환하는 정보를 엿듣기 위해 하늘에 앉아있곤 하였고 그렇게 습득한 정보는 지구상의 무당에게 알려주곤 하였습니다. 그러나 지금은 상황이 바뀌었습니다. 우리들 중 누군가가 엿들으려는 시도를 할 때마다 그는 타오르는 불에 봉착하는데, 그 불은 그를 위해 준비된 것으로서 가까이 다가가면 그것이 그에게 날아들어 그를 태워버리는 것입니다.",
  72010: "실로 우리는 파수꾼의 존재 이유를 알지 못합니다; 그것으로 지구에 있는 자들에게 나쁜 것이 의도된 것인지 아니면 하나님께서 그들에게 좋은 것을 원하시는 것인지 우리는 모릅니다. 그렇게 우리에게 하늘의 소식은 끊겨버렸습니다.",
  72011: "실로 우리 진들 중에는 하나님을 두려워하는 선한 자들이 있는 반면 하나님을 불신하며 거역하는 자들도 있습니다. 우리는 종류가 다양하고 욕구가 천차만별이었습니다.",
  72012: "실로 하나님께서 우리에게 무엇을 원하실 때 우리는 그분을 결코 피해갈 수 없으며, 우리가 도망하려 한대도 모든 것을 에워싸시는 그분을 결코 피해갈 수 없음을 확신하였습니다.",
  72013: "실로 우리는 가장 올바른 길로 안내하는 꾸란의 말씀을 들었을 때 그것을 믿었습니다. 자신의 주님을 믿는 자가 있다면 그는 보상에 관하여 정당한 몫보다 적게 받을 걱정도, 죄에 관하여 부당히 벌을 더해 받을 걱정도 하지 않을 것입니다.",
  72014: "실로 우리의 일부는 하나님께 순종하며 그분의 명령을 따르는 무슬림들이며, 또 다른 일부는 올곧은 길로부터 벗어난 부당한 자들입니다. 하나님께 복종하며 선행을 실천하는 자, 그들은 올바른 길을 추구한 자들입니다.",
  72015: "올바른 길로부터 벗어난 부당한 자들에 관해서는 그들은 지옥을 위한 장작더미가 될 것이며 지옥의 불은 그들과 인간들을 땔감으로 하여 타오를 것입니다\"",
  72016: "(한 무리의 진이 꾸란을 경청한 사건이 선지자에게 계시된 것처럼 다음의 말씀도 그에게 계시되었다. ) 만약 진과 인간이 이슬람의 길을 따르며 그 가르침을 굳건히 실천하였다면 하나님께서는 그들이 풍성한 물을 마시도록 하고 그들에게 다양한 은총을 내리셨을 것이라.",
  72017: "그리하여 하나님께서는 그분의 은총에 관해 그들이 감사하는지 아니면 부정하는지를 시험하시노라. 꾸란과 그 안의 교훈에 등돌리는 자, 그의 주님께서는 그를 감당할 수 없는 고단한 벌 속에 들게 하실 것이라.",
  72018: "실로 성원은 다름 아닌 지고하신 하나님을 위한 것이니 그대들은 성원 안에서 하나님과 더불어 다른 것에 기도하지 말라. 만약 그렇게 한다면 그대들은 교회에서 기도하는 기독교인들처럼 될 것이라.",
  72019: "실로 하나님의 종복 무함마드가 '바뜬 나클라' 지역에 서서 그의 주님께 기도할 때 진들은 그의 꾸란 낭송을 듣기 위해 서로를 올라타며 그에게 밀착하여 있었노라.",
  72020: "그대 - 사도여! - 는 우상 숭배자들에게 말하라. “나는 오직 나의 주님 한 분께만 기도할 뿐이며, 하나님을 경배함에 그 어떤 대등한 존재도 두지 않노라”",
  72021: "그대는 그들에게 말하라. “실로 나는 하나님께서 그대들에게 운명 지으신 해악을 물리칠 수 없으며, 하나님께서 금지하신 유용함을 내가 가져올 수도 없노라”",
  72022: "그대는 그대들에게 말하라. “내가 만약 하나님을 거역한다면 그 누구도 그분으로부터 나를 구원해주지 못하며 나는 결코 그분 이외의 피난처를 찾지 못할 것이라.",
  72023: "그러나 내가 통제할 수 있는 것은 나에게 내려진 하나님의 명령을 전달하는 것과 사도로서 그분의 메시지를 그대들에게 알리는 일이라. 하나님과 그의 사도를 거역하는 자가 있다면 실로 그의 종착지는 불지옥으로서 그는 그곳에 들어가 영원히 빠져나오지 못할 것이라.",
  72024: "불신자들은 불신을 지속할 것이니 그들이 현세에서 약속받던 징벌을 두 눈으로 목격할 심판의 날까지라. 그때 그들은 누가 더 허약한 조력자를 가지는지 알게 될 것이며 누가 더 소수의 도움을 받을지 알게 될 것이라”",
  72025: "그대 - 사도여! - 는 부활을 부정하는 저 우상 숭배자들에게 말하라. “그대들이 약속받은 징벌이 가까운지 아니면 나의 주님께서 그것에 그분만이 아시는 기한을 두셨는지 나는 알지 못하노라.",
  72026: "하나님께서는 보이지 않는 모든 것을 아시는 분이니 그 무엇도 그분께는 숨겨지지 않노라. 그리하여 그분께서는 그 누구에게도 그분의 보이지 않는 영역을 보여주지 않으시며 그 지식은 오직 그분만이 알고 계시노라.",
  72027: "그러나 하나님께서 흡족해 하시는 사도는 예외로서 실로 그분께서는 사도에게 원하시는 대로 미지의 것을 보여주시며 사도의 전방과 후방에 수호 천사들을 보내시어 사도 이외의 존재가 그것을 볼 수 없도록 하시노라.",
  72028: "이는, 하나님께서 이전의 사도들에게 그분의 메시지를 전달하라 명령하셨고 이에 그들은 하나님의 배려로써 그들 주님의 메시지를 제대로 전달하였음을 사도가 알도록 하기 위해서라. 하나님께서는 당신의 지식으로써 천사들과 사도들이 가진 것을 아우르시며 모든 것의 숫자를 헤아리고 계시기에 그분께는 그 무엇도 감추어지지 않노라”",
  73000: "알-뭇잠밀 (옷을 두른 자)\n계시 분류: 메카\n•    계시 목적    \n이 장에는 이슬람을 알리는 자들이 현세의 혹독한 시련에 직면했을 때 영혼의 양식으로 삼을 말씀들이 언급되어 있다. 이를 통해 이 장은 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 를 더욱 굳건히 하는 동시에 그를 부정하는 자들에 대해 경고하고 있다.\n•    요약 주해",
  73001: "옷으로 자신을 감싼 자여! (선지자여! )",
  73002: "그대는 얼마간의 시간을 제외한 밤중 내내 일어나 예배를 드리라.",
  73003: "원한다면 밤의 절반을 예배로 지새우거나 아니면 그보다 조금 적은 시간인 삼분의 일을 예배하거나",
  73004: "거기에 더하여 밤시간의 삼분의 이를 예배하라. 그대가 꾸란을 읽을 때는 천천히 읽어서 꾸란의 의미를 명확히 전달하라.",
  73005: "실로 하나님께서는 그대 - 사도여! - 에게 꾸란을 내릴 것이라. 그것은 무거운 말씀으로 그 안에는 의무 사항과 지켜야 할 경계와 규정과 예절 등이 포함되어 있기 때문이라.",
  73006: "진실로 밤 시간은, 낭송이 마음으로 전달됨에 가장 훌륭한 시간이며 올바른 말 (예배) 을 하기에 더욱 적합한 때라.",
  73007: "실로 낮에는 그대가 일상의 일로 바쁜 나머지 꾸란 낭송을 미뤄야 하니 그대는 밤중 예배를 드리라.",
  73008: "그대는 다양한 방식으로 하나님을 떠올리고, 진정으로 그분만을 경배함으로써 오직 그분께 열중하라.",
  73009: "동쪽과 서쪽의 주님이신 하나님 이외에는 그 누구도 경배받을 권리가 없으니 그대는 모든 일을 그분께 의탁하고 맡기라.",
  73010: "그대는 그들이 뱉어내는 조롱과 모욕의 말에 인내하고 그들을 멀리하되 해를 끼치지 말라.",
  73011: "그리고 그대는, 현세의 안락을 즐기며 진리를 부정하는 자들을 신경쓰지 말며 나에게 그들을 놓아두라. 그리고 그들의 수명이 다할 때까지 그들을 기다려 주라.",
  73012: "실로 하나님께는 내세의 무거운 족쇄와 작열하는 불이 있으며",
  73013: "그분께는 또한 목에 걸려 넘어가지 않는 음식과 그에 더하여 고통스런 벌이 있노라.",
  73014: "(하나님을) 부정하는 자들이 고통받을 그날에 대지와 산들은 크게 흔들릴 것이며, 산들은 그날의 엄청난 두려움으로 인해 곧 무너져내릴 모래 언덕처럼 될 것이라.",
  73015: "실로 하나님께서는 그대들에게, 심판의 날 그대들의 행위를 증언할 사도를 보냈으니 이는 마치 그분께서 파라오에게 사도 모세를 보낸 것과 유사하노라.",
  73016: "그러나 파라오는 자신의 주님께서 보내신 사도를 거역하였고 이에 하나님께서는 그를 혹독히 응징하셨으니 현세에서 익사한 후 그는 내세에서 불지옥의 화염으로 고통받을 것이라. 따라서 그대들은 그대들에게 보내진 사도를 거역하지 말라, 그렇지 않으면 그대들에게 그와 유사한 벌이 내려질지도 모를 일이라.",
  73017: "그런데도 만약 그대들이 하나님을 불신하고 그분의 사도를 부정한다면 그대들은, 극심한 공포와 오랜 기간으로 어린이들의 머리카락이 하얗게 되어 버리는 심판의 날로부터 어떻게 자신을 보호할 수 있겠는가?",
  73018: "하늘은 그날에 대한 두려움으로 갈라 터질 것이라. 하나님의 약속은 반드시 실행되니라.",
  73019: "실로, 심판의 날이 얼마나 두려운 날인지를 알려주는 교훈 가득한 이 구절들은 떠올림으로서, 믿는 자들은 이를 통해 가르침을 얻노라. 그러니 주님에게로 향하는 길을 원하는 자는 그 길을 걷도록 하라.",
  73020: "실로 그대 - 사도여! - 의 주님께서는 그대가 어떨 때는 밤의 삼분의 이를 예배 드리고, 어떨 때는 밤의 절반을, 또 어떨 때는 삼분의 일을 예배 드림을 알고 계시며 그대와 함께 하는 믿는 자들의 일부도 그대와 함께 예배 드림을 알고 계시노라. 하나님께서는 밤과 낮을 조절하시며 그 시간을 셈하시노라. 하나님께서는 그대들이 밤을 새울 수 없으며, 명령받은 대로 밤의 대부분을 예배드리는 것이 그대들에게 매우 힘든 일임을 알고 계셨기에 그분께서는 그대들의 참회를 받아 주셨노라. 그러니 그대들은 쉽다고 생각하는 양만큼 밤중에 일어나 예배 드리라. 하나님께서는 그대들 - 믿는 자들이여! - 중에 병으로 고생하는 환자들이 있을 것이고, 다른 이들은 하나님의 양식을 구하러 먼 길을 떠날 것이며, 다른 이들은 하나님의 기쁨을 위해, 하나님의 말씀을 드높이기 위해 불신자들과의 전투에 참전할 것임을 알고 계셨노라. 그들 모두에게는 밤중 예배가 매우 힘든 일이 될 것이니 그대들은 쉽다고 생각하는 양만큼 밤중에 일어나 예배 드리라. 그리고 그대들은 꾸준히 의무 예배를 드리고, 그대들 재산에서 (일정 비율의) 의무 희사금을 내며, 하나님의 길에서 (자발적으로) 재산을 희사하라. 그대들 자신들을 위해 내놓는 그 어떤 재산도 그대들은 그것에 더 훌륭하고 더 위대한 보상이 있음을 발견할 것이라. 그대들은 하나님께 용서를 구하라. 실로 하나님께서는 참회하는 종복들을 너그러이 용서하시는 분이며 그들에게 자애로우신 분이라.",
  74000: "알-뭇닷씨르 (담요를 덮은 자)\n계시 분류: 메카\n•    계시 목적    \n이 장은 이슬람으로 사람들을 초대해야 함을 명령하면서 그 초대를 거부하는 자들을 경고하고 있다.\n•    요약 주해",
  74001: "외투를 덮은 자여! (선지자여! )",
  74002: "일어나서 하나님의 벌에 대해 경고하라.",
  74003: "그리고 그대 주님의 위대함을 드높이고",
  74004: "그대의 영혼은 죄로부터 정화하고, 그대의 옷은 오물로부터 깨끗이 하며",
  74005: "우상 숭배는 멀리하라.",
  74006: "그리고 그대가 선행을 많이 실천했음을 그대 주님께 자랑하지 말며",
  74007: "그대가 겪는 고충은 하나님을 위해 인내하라.",
  74008: "그리하여 두 번째 나팔이 불릴 때",
  74009: "실로 그날은 혹독한 날이라.",
  74010: "하나님과 그분의 사도를 불신하는 자들에게는 쉽지 않은 날이라.",
  74011: "하나님께서 재산이나 자식도 없이 어머니 배 속에서 홀몸으로 창조하신 자 (알-왈리드 이븐 알-무기라) 가 있으니, 그대 - 사도여! - 는 그를 하나님께 놓아두라.",
  74012: "하나님께서는 그에게 풍족한 재산을 주셨고",
  74013: "그와 언제나 함께 하는 자손들을 두셨으니 그들은 아버지와 함께 모임에 참석하면서, 재산이 많기에 여행을 떠날지라도 헤어지지 않더라.",
  74014: "그리고 하나님께서는 그를 위해 안락한 삶과 풍성한 양식과 많은 자식을 주셨노라.",
  74015: "그 후에도 그는, 하나님을 불신하면서도 그분께서 그에게 더 주시기를 희망하더라.",
  74016: "사실은 그가 생각하는 것과는 다르노라. 실로 그는 하나님의 사도에게 계시된 그분의 징표에 대해 고집을 부리며 부정하였노라.",
  74017: "하나님께서는 그에게 감당할 수 없는 고된 벌을 부과할 것이라.",
  74018: "하나님께서 은총을 베풀어 주신 이 불신자는 꾸란을 부정하기 위해 생각을 하면서 마음속에서 이것 저것을 재더라.",
  74019: "그러니 그가 재는 방법에 저주와 벌이 있노라.",
  74020: "다시 한번, 그가 재는 방법에 저주와 벌이 있노라.",
  74021: "그 후 그는 꾸란의 말씀에 대해 다시 한번 생각해 보았고",
  74022: "그 후 그는 꾸란을 비방할 수 있는 것을 찾지 못해 얼굴을 찌푸리고 찡그렸노라.",
  74023: "그 후 그는 믿음에 등을 돌리고, 거만해 하면서 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 를 따르기를 거부하였노라.",
  74024: "그리하여 그가 말하였노라. “무함마드가 가져온 이것은 하나님의 말씀이 아니라. 이것은 그저 다른 이들로부터 전해져 내려오는 주술일 뿐이오\"",
  74025: "\"이것은 하나님의 말씀이 아닌 그저 인간의 말에 불과하오\"",
  74026: "하나님께서는 이 불신자를 지옥의 한 층에 들게 할 것이니 그곳의 이름은 '사까르' 이며 그는 그곳의 뜨거움에 고통받을 것이라.",
  74027: "그 누가 그대 - 무함마드여! - 에게 '사까르' 가 무엇인지를 알려줄 것인가?",
  74028: "불지옥은 그 안에 있는 어떤 자도 남겨두거나 내버려 두지 않고 고통을 주노라. 고통을 받은 자는 상처가 회복된 후 또다시 고통을 받으니 그렇게 영원히 반복되더라.",
  74029: "불지옥은 또한 피부를 심하게 태우고 검게 그슬리노라.",
  74030: "불지옥을 지키는 임무를 맡은 천사는 열아홉이라.",
  74031: "하나님께서는 불지옥의 문지기들 모두를 천사로 두심에 인간 그 누구도 그들을 제압할 수 없노라. 또한 하나님께서는 천사들의 숫자를 하나님을 불신하는 자들에 대한 시험으로 두셨으니 그들이 하는 말로써 그들의 벌은 배가되더라. 그것을 통해 토라를 받은 유대인들과 복음을 받은 기독교인들은 꾸란에 계시된 내용에 대해 확신을 가지고, 믿는 자들은 성서의 사람들이 동의하는 내용을 통해 기존의 믿음이 증가되며, 이로써 유대인들과 기독교인들과 신앙인들이 의심하지 않기 위함이라. 그러나 믿음에 대해 머뭇거리는 자들과 불신자들은 '이 이상한 숫자로써 하나님이 원하는 것은 무엇인가? ”라고 말하더라. 천사들의 숫자를 부정하는 자들을 방황시키고 그 숫자를 믿는 자들을 인도하시는 것처럼 하나님께서는 그렇게 원하시는 자를 방황시키시고 원하시는 자를 인도하시노라. 오직 하나님만이 당신의 군대가 얼마나 많은지 그 정확한 숫자를 알고 계시노라. 불지옥은 다름 아닌 인간을 위한 떠올림으로서 그를 통해 인간은 지고하신 하나님의 위대함을 알게 되노라.",
  74032: "우상 숭배자들은 자신들의 동료들로써 불지옥의 문지기들을 쫓아낼 수 있을 것이라 생각하나, 그렇지 않노라. 하나님께서는 달을 두고 맹세하시니",
  74033: "자취를 감추는 밤을 두고 그분께서 맹세하시니",
  74034: "밝아오는 아침을 두고 그분께서 맹세하시니",
  74035: "진실로 불지옥은 엄청난 시련이자",
  74036: "인간을 위한 엄중한 경고로서",
  74037: "그대들 - 인간들이여! - 중에서 하나님에 대한 믿음과 선행으로 앞으로 나아가고자 하는 자 혹은 불신과 거역으로 뒤로 물러서고자 하는 자를 위한 것이라.",
  74038: "모든 영혼은 그의 행위로 전당이 잡혀 있노라; 그는 악행으로 말미암아 파멸되거나 선행으로 인해 파멸로부터 보호되노라.",
  74039: "그러나 신앙인들은 예외로 그들은 자신들의 죄로 인해 힐책받지 않노라. 이는 하나님께서 그들의 선행을 보시어 눈감아 주신 것이라.",
  74040: "그들은 심판의 날 천국에서 서로가 서로에게 물으니",
  74041: "거역 행위로써 자신을 파멸로 몰로 간 불신자들에 관해서라.",
  74042: "그들이 그들에게 말하노라. \"그대들이 불지옥에 들어가 있는 이유는 무엇인가? \"",
  74043: "불신자들이 그들에게 대답하며 말하노라. “우리는 현세에서 의무 예배를 드리는 자들이 아니었고\"",
  74044: "\"하나님으로부터 받은 것으로 가난한 자들에게 음식을 제공하지도 않았습니다\"",
  74045: "\"우리는 허위를 일삼는 자들과 항상 자리를 함께 하고, 방황하는 자들과 얘기를 나누면서\"",
  74046: "\"심판의 날을 부정하였습니다\"",
  74047: "\"우리에게 죽음이 찾아올 때까지 계속해서 그러하였기에 우리의 참회는 이제 받아들여지지 않고 있는 것입니다\"",
  74048: "그러니 심판의 날, 천사들과 선지자들과 선량한 자들 등 중재하는 자들의 중재도 그들에게 도움이 되지 않으니, 중재가 받아들여지는 조건은 중재 받는 자들에 대한 (하나님의) 만족이기 때문이라.",
  74049: "우상 숭배자들은 어떠한 연유로 꾸란에 등을 돌리는 것인가?",
  74050: "그들이 꾸란으로부터 등을 돌림은 마치 무서워 달음박질하는 당나귀들과 같도다.",
  74051: "그 당나귀들은 사자를 보고선 줄행랑치는 당나귀들이라.",
  74052: "실로 저 우상 숭배자들 모두가 바라길 자기의 머리맡에 책자가 펼쳐져 무함마드가 하나님의 사도임을 알려주길 바라더라. 이는 이슬람의 증거가 부족하거나 논거가 허약해서가 아니라 그들이 아집과 오만을 부리기 때문이라.",
  74053: "진실은 그렇지 않노라. 그들이 방황을 지속함은 그들이 내세의 벌을 믿지 않기 때문이라. 그렇게 그들은 불신을 고집하더라.",
  74054: "보라, 실로 이 꾸란은 교훈이자 깨우침이니",
  74055: "꾸란을 읽음으로써 교훈을 원하는 자는 그것으로 교훈을 얻을 것이라.",
  74056: "오직 하나님께서 원하시는 자만이 교훈을 얻을 것이라. 사람들은 응당 하나님의 명령을 지키고 금지 사항을 멀리함으로써 그분을 두려워해야 하며, 하나님께서는 사람들이 참회할 때 용서해주시는 분이라.",
  75000: "알-끼야마 (부활)\n계시 분류: 메카\n•    계시 목적    \n이 장은 인간을 창조하고 또한 부활시킬 능력을 가지신 분이 하나님임을 드러내고 있다.\n•    요약 주해",
  75001: "부활의 날을 두고 하나님께서 맹세하시니 그날은 인간이 만유의 주님 앞에 서게 되는 날이라.",
  75002: "그리고 심히 자책하는 영혼을 두고 하나님께서 맹세하시니 그 영혼은 선행을 더 많이 실천하지 않았음에, 또한 악행을 저질렀음에 크게 후회하는 영혼이라. 하나님께서는 이 둘을 두고 맹세하시니 그분께서는 인간을 부활시키어 그들을 심판하시고 보응하실 것이라.",
  75003: "죽음 후에 있을 부활을 위해 하나님께서 인간의 뼈를 모으실 텐데도 정녕 인간은 이를 부정한단 말인가?",
  75004: "그렇지 않노라. 하나님께서는 죽어있는 인간의 손가락을 이전의 모습 그대로 되살릴 수 있노라.",
  75005: "그러나 부활을 부정하는 인간들은 망설이지 않고 끊임없이 사악함을 저지르고 싶어하노라.",
  75006: "부활의 날을 납득할 수 없다며 그가 물으니 \"도대체 그날은 언제란 말인가? \" 하더라.",
  75007: "자신이 부정하던 것을 목격한 나머지 혼비백산하여 눈이 정신을 잃을 때,",
  75008: "달이 그 빛을 잃어 버리며",
  75009: "해와 달이 겹칠 때",
  75010: "악행을 저지르던 인간은 그날 말할 것이라. “어디로 도망쳐야 하는가? \"",
  75011: "그날 도망은 성립하지 않으며 악인은 피난할 곳도 몸을 숨길 곳도 없노라.",
  75012: "그날은 사람들이 그대 - 사도여! - 의 주님에게로 귀착하여 심판과 보응을 받을 것이라.",
  75013: "인간은 그날 자신이 한 행위와 하지 않은 행위에 대해 소식을 듣게 될 것이라.",
  75014: "실로 인간은 자기가 저질렀던 악행에 대해 자신의 신체가 불리한 증언을 할 것이라.",
  75015: "그는 악행을 저지른 적이 없다는 억지 변명을 늘어놓지만 아무 소용이 없노라.",
  75016: "그대 - 사도여! - 는 꾸란이 떠나갈까 봐 그대의 혀를 급히 움직여 서두르지만 그러지 말라.",
  75017: "실로 그대가 꾸란을 암기하여 마음속에 보존하고 그대의 혀로써 꾸란을 낭송하는 일은 하나님께서 책임지실 것이라.",
  75018: "그러니 하나님께서 보내시는 가브리엘 (지브릴) 천사가 꾸란을 읽으면 그대는 조용히 하고 그 낭송을 경청하라.",
  75019: "그 후 그대에게 꾸란의 의미를 알려주는 일은 하나님께서 책임지실 것이라.",
  75020: "그대들은 부활이 불가능하다 말하지만 그렇지 않노라. 창조를 시작하신 분께서 죽은 자를 살리는 일이 가능함은 그대들도 잘 알고 있노라. 이렇게 그대들에게 부활을 떠올려 줌은 그대들이, 곧 스러질 현세의 삶을 사랑하기 때문이라.",
  75021: "그러면서 그대들은 내세의 삶을 내버려 두나, 내세의 훌륭한 삶에 도달하기 위해서는 하나님께서 명령하신 것을 따르고 그분께서 금지하신 것은 멀리해야 하노라.",
  75022: "믿음을 가진 자들은 그날 얼굴이 포근히 빛날 것이며",
  75023: "그들의 주님이신 하나님을 바라보며 기뻐할 것이라.",
  75024: "불신한 자들은 그날 얼굴을 찌푸릴 것이니",
  75025: "자신들에게 엄청난 벌과 고통이 닥칠 것이라 확신하노라.",
  75026: "우상 숭배자들은 자기가 죽은 후에 벌받지 않을 것이라 생각하지만 그렇지 않노라. 그들 중 누군가의 영혼이 쇄골에 도달하고 (죽음에 이르고)",
  75027: "사람들이 서로에게 \"이 병든 자를 위해 누가 주문을 외워 그를 치유해 줄 것인가? ”라고 말하고",
  75028: "자기의 영혼이 뽑혀져 나가고 이것이 죽음으로 인한 현세와의 이별이라 인간이 확신하고",
  75029: "현세의 마지막 순간의 괴로움과 내세의 첫 순간의 괴로움이 모일 때",
  75030: "이 모든 것이 실현될 때 죽은 자는 (천사들에게) 몰리어 그대 주님께로 이동할 것이라.",
  75031: "그러나 이 불신자는 사도가 가져온 메시지를 믿지 않았으며 하나님을 위해 예배를 드리지도 않았노라.",
  75032: "오히려 그는 사도가 가져온 메시지를 부인하며 등을 돌렸노라.",
  75033: "그 후 이 불신자는 팔자걸음으로 거드름을 피우며 자기 가족을 향해 걸어갔노라.",
  75034: "그리하여 하나님께서는 불신자에게 경고하시니 머지않아 하나님의 벌이 곧 그에게 닥칠 것이라.",
  75035: "(하나님께서는 강조를 위해 문장을 반복하셨다. ) 머지않아 하나님의 벌이 곧 그에게 닥칠 것이라.",
  75036: "인간은, 하나님께서 자기에게 의무를 부과하지 않으시고 그대로 내버려 두실 것이라 생각하는가?",
  75037: "인간은 한때 자궁 속에 쏟아진 한 방울의 정액이지 않았던가?",
  75038: "그러한 상태 후에 그는 덩어리진 핏방울이었으며 그 후 하나님께서는 그를 균형잡힌 모습으로 만드셨노라.",
  75039: "그 후 하나님께서는 그로부터 남성과 여성이라는 두 개의 성을 두셨노라.",
  75040: "한 방울의 정액, 그리고 응혈에서 인간을 창조하신 하나님께서 보상과 징벌을 위해 죽은 자들을 살리실 수 없단 말인가? 그렇지 않노라, 그분은 그렇게 하실 수 있노라.",
  76000: "알-인산 (인간)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 인간의 근원을 언급하고, 인간 창조에 내재된 지혜와 인간이 도달하게 될 현세와 내세의 종착지를 설명하면서, 천국에서 누리게 될 기쁨을 묘사하고 있다. 이렇게 이 장은 믿는 자들의 마음을 굳건히 하고 불신자들을 이슬람의 신앙으로 초대하고 있다.\n•    요약 주해",
  76001: "오랜 기간 동안 인간은 존재하지 않았고 그때는 어떤 누구도 인간을 언급하지 않았노라.",
  76002: "실로 하나님께서는 정자와 난자의 배합으로써 인간을 창조하셨고, 인간에게 의무를 부과하여 그를 시험하시니, 그에게 청각과 시각을 주심은 그가 의무를 실천하기 함이라.",
  76003: "실로 하나님께서는 그분의 사도를 통해 인도의 길을 설명해 주셨고 이를 통해 방황의 길도 명백해졌노라. 그리하여 인간은 올곧은 길을 걸음으로써 하나님을 믿고 그분께 감사하거나 그 올곧은 길을 벗어나 하나님을 불신하고 그분의 징표를 부인하더라.",
  76004: "(하나님께서는 두 종류의 인간, 즉 인도의 길을 걷는 자와 방황하는 자에 관해 말씀하신 후 여기서는 그 두 종류에 대한 보상과 벌이 무엇인지 밝히고 계신다)  실로 하나님께서는, 그분과 그분의 사도를 부정하는 불신자들을 불지옥에 가둘 사슬과 그들을 옥죌 멍에와 그들을 태울 화염을 준비해 두셨노라.",
  76005: "실로 심판의 날 하나님께 순종하던 믿는 자들은 가득 찬 술잔을 마시는데 그 안에는 장뇌가 섞여 그 향기가 상쾌하노라.",
  76006: "이 음료는 하나님께 순종하던 자들을 위해 준비된 것으로서, 가까이에 있으면서도 풍성하여 결코 마르지 않는 샘터에서 나온 것이라. 하나님의 종복들은 그 샘물을 마시니 그들은 원하는 곳에서 그 샘물을 마음대로 솟아나게 하더라.",
  76007: "천국에서 즐거이 음료를 마시는 그들은 현세에서 자신들이 맹세한 말을 준수하였고, 사악함이 급속도로 퍼질 부활의 날을 두려워하였노라.",
  76008: "그리고 그들은 자신이 필요로 하고 좋아하는 음식을 가난한 자와 고아와 포로에게 내주었노라.",
  76009: "그들이 속으로 말하기를 ‘우리가 그대들에게 음식을 제공하는 것은 오직 하나님의 얼굴을 보기 위해서이며, 그대들로부터 보상이나 칭찬을 바라는 것이 아니라.",
  76010: "실로 우리는, 사악한 자들이 혹독함으로 얼굴을 찌푸릴 심판의 날에 우리의 주님이신 하나님을 두려워하노라’ 하더라.",
  76011: "그리하여 하나님께서는 당신의 은혜로써 그들을 그날의 사악함으로부터 구해 주셨고 그들의 명예를 드높이셨으니 그들의 얼굴에는 포근한 빛을, 그들의 마음에는 즐거움을 주셨노라.",
  76012: "그리고 그들은 선행을 실천하고 운명에 인내하며 악행을 삼갔기에 하나님께서는 그들의 인내에 대한 보상으로 기쁨의 천국과 부드러운 비단옷을 선사하셨노라.",
  76013: "천국에서 그들은 아름답게 꾸며진 침대 위에서 편히 누워 쉴 것이며, 그들은 따가운 햇빛이나 혹한에도 노출되지 않으니 더위나 추위 없는 그곳에서 그들은 선선한 그늘을 즐길 것이라.",
  76014: "천국의 그늘은 그들을 가까이서 감싸며, 그곳의 열매는 따기가 매우 수월하니 앉은 자와 서 있는 자와 누워 있는 자도 쉽게 따서 먹을 수 있노라.",
  76015: "하인들이 은으로 만들어진 그릇을 가지고 그들 주위를 돌고, 그들이 음료를 마시고 싶어할 때는 투명한 색깔의 컵을 갖다 주니",
  76016: "그 색이 너무도 투명하여 마치 유리와 같으나 실제로 그것은 은으로 만들어진 컵이라. 이 컵은 천국의 거주자들이 원하는 만큼 적당한 양으로 조절하니 그들에게 지나치지도 부족하지도 않더라.",
  76017: "명예로운 저들은 술잔에 담긴 술을 마시는데 그 술잔 안에는 생강이 섞여 있으며",
  76018: "천국의 샘을 마시니 그 샘터의 이름은 '살사빌' 이라.",
  76019: "영원의 젊음을 얻은 어린이들이 천국에서 그들 사이를 돌 것이니 그대가 저 어린이들을 보았을 때는 그들을 흩뿌린 진주알로 생각할 것이라; 여기저기로 흩어져 있는 수많은 그들은 얼굴에서 포근한 빛이 뿜어나오고 피부색 역시 아름답기 때문이라.",
  76020: "정녕 천국에서 그대가 발견할 것은 형용할 수 없는 안락함과 그 어떤 왕도 근접하지 못한 위대한 주권이라.",
  76021: "그들은 부드러운 비단으로 만들어진 녹색의 비단 옷과 두꺼운 명주붙이를 걸칠 것이며 은으로 만들어진 팔찌를 차게 될 것이라. 그리고 하나님께서는 그들을 위해 부드럽게 목을 넘어가는 음료를 주실 것이라.",
  76022: "그리고 목소리가 들릴 것이니 이는 그들의 명예를 드높이기 위함이라. “실로 내가 그대들에게 선사한 이 은총은 그대들이 실천한 선행에 대한 보상으로서 하나님께서 그대들의 행위를 받아 주신 것이라\"",
  76023: "진실로 하나님께서는 그대 - 사도여! - 에게 꾸란을 단계적으로 계시하셨으니 한번에 다 계시하신 것이 아니라.",
  76024: "그러니 그대는 하나님의 운명과 법률에 인내하고, 죄짓는 자가 권유하는 악행이나 불신하는 자가 권유하는 불신에 응하지 말라.",
  76025: "그리고 이른 낮 시간에는 파즈르 예배로써, 늦은 낮 시간에는 두흐르와 아쓰르 예배로써 그대 주님을 떠올리며",
  76026: "밤 시간에는 마그립 예배와 이샤 예배로써 하나님을 떠올리고 그 이후에는 타핫주드 예배(한밤중 예배)를 드리라.",
  76027: "실로 저 우상 숭배자들은 현세를 사랑하고 그에 모든 신경을 쏟으나, 정작 혹독한 심판이 있을 엄중한 부활의 날은 뒤로 내버려 두더라.",
  76028: "실로 하나님께서는 그들을 창조하셨고 그들의 뼈와 근육 등을 강하게 하셨노라. 만약 하나님께서 그들을 파멸시킨 후 그들과 유사한 자들로써 그들을 대체하길 원하셨다면 정녕 그렇게 하셨을 것이라.",
  76029: "실로 이 장은 인간을 상기시키고 그에게 교훈을 주고 있노라. 그러니 주님의 기쁨을 위한 길을 걷고 싶다면 그렇게 하도록 하라.",
  76030: "그대들이 하나님의 기쁨을 위한 길을 걷고자 함은 오직 하나님께서 그렇게 원하셨기 때문이니, 그 모든 일은 그분께 달려 있노라. 실로 하나님께서는 인간에게 유용한 것과 그렇지 않은 것이 무엇인지 가장 잘 아시는 분이며, 인간의 창조와 운명과 법률 제정에 있어 가장 지혜로우신 분이도다.",
  76031: "하나님께서는 종복들 중에서 원하시는 자를 당신의 자비 속에 들게 하시어 그들이 신앙을 가지고 선행을 실천하도록 하시노라. 그리고 그분께서는 불신과 거역 행위으로써 자신을 부당히 다루는 자들을 위해 내세에서 불지옥이라는 고통의 벌을 준비하셨노라.",
  77000: "알-무르살라트 (몰아치는 바람)\n계시 분류: 메카\n•    계시 목적    \n이 장은 부활을 부정하는 자들에게 다양한 증거로써 그들의 주장이 거짓임을 밝히면서 그들에게 경고의 목소리를 내고 있다.\n•    요약 주해",
  77001: "하나님께서는 말갈기처럼 연이어 몰아치는 바람을 두고 맹세하시고",
  77002: "맹렬하고 거센 바람을 두고 맹세하시고",
  77003: "비를 퍼뜨리는 바람을 두고 맹세하시며",
  77004: "옳고 그름의 기준을 전달하는 천사들을 두고 맹세하시고",
  77005: "계시를 전하는 천사들을 두고 맹세하시니",
  77006: "천사들이 전하는 이 계시는 사람들이 더 이상 변명할 수 없도록 하는 하나님의 메시지이며 그들에게 하나님의 벌을 떠올리게 하는 경고의 말씀이기도 하노라.",
  77007: "진실로 그대들이 약속받은 부활과 심판과 보응은 닥쳐오고 말 것이라.",
  77008: "그러니 별들이 그 빛을 잃고",
  77009: "하늘이 하강하는 천사들로 갈라지고",
  77010: "산이 뽑혀 나가 산산조각이 되고",
  77011: "사도들이 정해진 그 시간에 모이게 될 때",
  77012: "이 위대한 날, 자신의 공동체에 대한 증인이 되기 위해 사도들은 기다림을 받은 것이라.",
  77013: "이날은 사람들이 분리되는 날로서, 진리를 따르던 자와 허위를 좆던 자가 구분되고 행복해질 자와 불행해질 자가 구분될 것이라.",
  77014: "그 누가 그대 - 사도여! - 에게 분리의 날이 무엇인지를 알려줄 것인가?",
  77015: "그날, 하나님의 사도가 가져온 것을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77016: "하나님께서는 당신을 불신하고 사도를 부정한 이전 공동체를 멸하지 않으셨던가?",
  77017: "그 후 하나님께서는 진리를 부정하는 후대의 사람들이 그들을 뒤따르도록 하여, 이전 사람들이 멸망한 것처럼 그들도 멸망케 하시노라.",
  77018: "하나님께서 이전의 공동체를 멸하신 것처럼, 그분께서는 무함마드가 가져온 메시지를 부정하는 자들을 멸하실 것이라.",
  77019: "그날, 악행을 저지르면서도 벌받지 않을 것이라 생각하던 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77020: "하나님께서 그대들 - 인간들이여! - 을 소량의 비천한 액체, 즉 정액으로부터 창조하지 않으셨던가?",
  77021: "그 후 하나님께서는 그 정액을 견고한 장소, 즉 여성의 자궁에 두었으니",
  77022: "임신이라는 정해진 기간까지라.",
  77023: "그렇게 하나님께서는 태아의 모습과 피부색 등을 조절하였으니 그분께서는 얼마나 훌륭히 조절하시는 분인가.",
  77024: "그날, 하나님의 능력을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77025: "하나님께서는 대지가 인간을 담아가도록 하지 않으셨던가?",
  77026: "그리하여 인간은 대지 위에 집을 짓고 살아가며, 죽은 자들은 대지에 묻히더라.",
  77027: "그리고 하나님께서는 대지에 견고하고 높은 산을 두시어 대지가 흔들리지 않도록 하셨고, 그대들 - 인간들이여! - 에게 시원하고 달콤한 물을 제공하셨노라. 이 모든 것이 가능한 하나님이시기에 그분께서는 그대들을 부활시킬 능력도 지니고 계신 것이라.",
  77028: "그날, 하나님께서 베풀어주신 은총을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77029: "사도가 가져온 메시지를 부정하던 자들에게 목소리가 들릴 것이라. “그대들이 부정하던 징벌을 맛보기 위해 길을 떠나라”",
  77030: "“불지옥의 연기가 만든 세 개의 어둠으로 이동하라”",
  77031: "그 어둠에는 시원한 그늘이 없으며 그대들을 위해 지옥의 불길도 막아주지 않노라.",
  77032: "실로 지옥은 여러 불꽃을 내뱉는데 불꽃 하나의 크기는 마치 높이 솟은 성 (城) 과도 같으니",
  77033: "지옥이 내뿜는 불꽃은 그 색깔과 크기에 있어 마치 검은 색 낙타와도 같더라.",
  77034: "그날, 하나님의 징벌을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77035: "이날은 그들이 어떤 말도 하지 못하는 날이며",
  77036: "그들은 주님께 자기의 불신에 대해 변명하고자 하나 그러한 기회는 주어지지 않을 것이라.",
  77037: "이날의 소식을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77038: "이날은 피조물들이 분리되는 날로서 하나님께서 그대들과 이전 공동체 일원들을 한 곳에 불러 모으실 것이라.",
  77039: "그러니 그대들이 하나님의 징벌로부터 빠져나갈 계략이 있다면 하나님께 그 계략을 꾸며 보라.",
  77040: "분리의 날을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77041: "하나님께서 명령하신 것을 따르고 그분께서 금하신 것을 멀리함으로써 하나님을 경외하던 자들은 천국의 나무 밑에서 시원하고 널찍한 그늘을 즐길 것이라. 그리고 달콤하고 신선한 샘물이 항상 그들 곁에 있을 것이며",
  77042: "그들이 먹기를 바라는 과일도 그들 곁에 있을 것이라.",
  77043: "그들에게 목소리가 들릴 것이라. “그대들은 맛있는 음식을 먹고, 부드럽게 넘어가는 음료를 마시라. 그대들이 현세에서 실천했던 선행에 대한 대가라”",
  77044: "그대들이 받는 이 같은 보상으로써 하나님께서는 최선을 다하는 자들의 선행을 보상하시노라.",
  77045: "그날, 경외하는 자들을 위해 하나님께서 준비하신 것을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77046: "진리를 부정하는 자들이 경고를 받노라. “현세에 머무르는 얼마 동안, 먹고 마시며 즐겨 보라. 실로 그대들은 하나님을 불신하고 그분의 사도를 부정하는 악행을 저지르고 있도다”",
  77047: "심판의 날에 있을 보상을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77048: "사람들은 진리를 부정하는 저들에게 “하나님을 위해 예배하시오”라고 말했지만 그들은 예배를 하지 않았노라.",
  77049: "그날, 하나님의 사도가 가져온 것을 부정하는 자들에게 파멸과 징벌과 손실이 있을 것이라.",
  77050: "그들은 하나님으로부터 계시된 이 꾸란을 믿지 않으니, 그렇다면 그들은 도대체 어떤 말씀을 믿는단 말인가?",
  78000: "안-나바 (소식)\n계시 분류: 메카\n•    계시 목적    \n이 장은 근거와 논증을 통해 부활과 보상이 진실임을 확증하고 있다.\n•    요약 주해",
  78001: "하나님께서 그분의 사도를 보내셨음에도 저 우상 숭배자들은 무엇에 관해 서로에게 질문하는 것인가?",
  78002: "저들은 위대한 소식에 관해 서로에게 묻고 있으니, 그 위대한 소식은 사도에게 계시된 꾸란으로서, 이 꾸란은 부활에 관하여 알려 주고 있노라.",
  78003: "저들은 이 꾸란에 관해 서로 다른 견해를 가지고 있으니, 그들은 꾸란을 주문, 시, 점술, 옛날 사람들의 설화 등으로 묘사하더라.",
  78004: "그들의 추측은 사실이 아니라. 꾸란을 부정하는 저들은 그 엄중한 결과가 무엇인지 곧 알게 될 것이라.",
  78005: "다시 한번 그들은 확인하게 될 것이라.",
  78006: "하나님께서 대지를 침상으로 만드시어 사람들이 그 위에서 살 수 있도록 하시지 않았던가?",
  78007: "또한 하나님께서는 대지 위에 말뚝의 역할을 하는 산을 두시어 그것으로써 대지가 흔들리지 않도록 하셨노라.",
  78008: "하나님께서는 그대들 - 인간들이여! - 을 두 종류로 창조하셨으니 남성과 여성이라.",
  78009: "그리고 그분께서는 그대들의 잠을 활동이 단절되는 시간으로 두시어 그대들이 휴식을 취할 수 있게 하셨노라.",
  78010: "옷이 부끄러운 부분을 가리듯 하나님께서는 밤의 그늘이 그대들을 덮어 주도록 하셨으며",
  78011: "낮을 양식을 구하는 시간으로 두셨노라.",
  78012: "그리고 하나님께서는 그대들 위에 일곱 개의 강하고 견고한 하늘을 지으셨으며",
  78013: "태양이 횃불처럼 뜨겁고 밟은 불을 발산하도록 하셨노라.",
  78014: "그리고 하나님께서는 비구름에서 장대비를 내리셨으니",
  78015: "그것으로써 그분께서는 다양한 종류의 곡물과 들풀을 내시고",
  78016: "울창한 나무들로 이루어진 정원도 내시노라.",
  78017: "(이전 구절에서 하나님께서는 여러 은총을 언급하시면서 그러한 은총을 가능케 하는 그분의 능력을 드러내 보이셨다. 하나님께서는 여기서부터 부활과 심판을 언급하시는데, 은총을 창조하신 하나님이시기에 그분께는 죽어있는 자를 부활시키고 그들을 심판하는 일 역시도 가능하기 때문이다. )  실로 피조물들이 분리되는 부활의 날은 정해진 시간에 시작될 것이며, 그 시간은 변하지 않노라.",
  78018: "그날 천사가 두 번째 나팔을 불 때 그대들 - 사람들이여! - 은 떼를 지어 올 것이며",
  78019: "하늘은 열리어 그 사이에 균열이 생기니 하늘이 마치 열린 문들처럼 되고",
  78020: "산들은 움직여 흩어진 먼지처럼 되니 그 모습이 마치 신기루처럼 될 것이라.",
  78021: "실로 지옥은 매복하여 지켜보고 있으니",
  78022: "경계를 넘어선 자들이 돌아가게 될 곳이라.",
  78023: "지옥에서 그들은 끝없는 시간을 머물 것이며",
  78024: "그들은 지옥에서 뜨거움을 식혀줄 시원한 바람도, 즐거이 마실 어떤 음료도 맛보지 못할 것이니",
  78025: "그들이 맛볼 것은 오직 부글거리는 물과 지옥의 거주자들에게서 흘러나오는 고름 뿐이라.",
  78026: "이는 그들이 저질렀던 불신과 방황에 상응하는 징벌이라.",
  78027: "현세에서 그들은 내세에 있을 하나님의 심판을 개의치 않았으니, 그들은 부활을 믿지 않았기 때문이라. 만약 그들이 부활을 두려워했다면 하나님을 믿고 선행을 실천했을 것이라.",
  78028: "또한 그들은 사도에게 계시된 하나님의 징표를 거짓으로 치부하였노라.",
  78029: "하나님께서는 그들이 행한 모든 것을 상세히 기재하셨으니 그들의 악행은 기록부에 기술되어 있노라.",
  78030: "그러니 너희 - 경계를 넘어선 자들이여! - 는 이 영원한 고통을 맛 보라. 하나님께서는 너희에게 고통 위에 고통을 더하실 것이라.",
  78031: "실로, 하나님께서 명령하신 것을 지키고 그분께서 금한 것을 멀리함으로써 하나님을 두려워하는 자들은 천국이라는 성공의 장소에 들어갈 것이니 그들은 그곳에서 원하는 것을 가질 것이라.",
  78032: "정원과 포도,",
  78033: "봉긋한 가슴을 지닌 자기 또래의 여성,",
  78034: "그득한 술잔이 그들의 것이며",
  78035: "그들은 천국에서 실없는 말을 듣지 않고, 거짓말도 듣지 않으며 서로가 서로에게 거짓말을 하는 일도 없을 것이라.",
  78036: "이 모든 것은 하나님께서 그들에서 너그러이 베풀어 주신 보상의 결과로서",
  78037: "(일곱) 하늘과 땅 그리고 그 사이에 존재하는 것의 주님이시자, 현세와 내세에서 가장 자비로우신 분이신 하나님으로부터의 축복이라. (일곱) 하늘과 땅의 그 어떤 누구도 하나님께 감히 질문하지 못할 것이나, 그분의 허락이 있을 때는 예외라.",
  78038: "가브리엘과 천사들이 줄지어 서는 그날, 그 누구도 타인을 중재하기 위한 말을 하지 못할 것이나, 가장 자비로우신 그분께서 허락하시는 경우는 예외로서 그는 오직 진실만을 말할 것이라.",
  78039: "이날이야말로 반드시 일어나게 될 날이라. 그러니 그날에 있을 하나님의 벌을 피하길 원하는 자는 그분께서 흡족해 하실 선행을 실천함으로써 그분께로 향하는 길을 잡으라.",
  78040: "실로 하나님께서는 그대들 - 인간들이여! - 에게 얼마 후에 다가올 징벌에 대해 경고하셨노라. 그날 인간은 자신이 현세에서 행했던 일을 목격할 것이며, 불신자는 - “흙이 되어라”라는 명령을 받는 동물을 보고선 - 자신에게 덮친 고통으로부터 벗어나고자 “내가 차라리 흙이었더라면! ” 이라고 소원할 것이라.",
  79000: "안-나지아트 (끄집어내는 천사)\n계시 분류: 메카\n•    계시 목적    \n이 장은 부활과 심판을 부정하는 자들에게 죽음과 부활, 소집 및 심판에 대한 강력한 증거를 제시하고 있다.\n•    요약 주해",
  79001: "하나님께서는 불신자들의 영혼을 거칠게 끄집어내는 천사들을 두고 맹세하시고",
  79002: "믿는 자들의 영혼을 부드럽게 추출하는 천사들을 두고 맹세하시고",
  79003: "하나님의 명령을 받아 하늘에서 지구로 유영하는 천사들을 두고 맹세하시며",
  79004: "하나님의 명령을 먼저 실행하기 위해 서로 경쟁하는 천사들을 두고 맹세하시고",
  79005: "하나님의 명령으로써 일을 결정짓는 천사들 - 예를 들어, 인간의 행위에 관한 임무를 맡은 천사들 - 을 두고 맹세하시니, 하나님께서는 심판과 보응을 위해 인간을 부활시키실 것이라.",
  79006: "그날 첫 번째 나팔이 불리어 대지는 요동치고",
  79007: "두 번째 나팔이 이 나팔을 뒤따를 것이라.",
  79008: "그날 불신자와 거역자의 마음은 두려움으로 가득 차고",
  79009: "그들의 시선에는 굴복의 흔적이 드러날 것이라.",
  79010: "그들은 이전에 말하였노라. “우리가 죽은 후에 다시 되살아난단 말인가? ”",
  79011: "“다 썩어버린 뼛조각이 된 우리가 다시 되살아난단 말인가? ”",
  79012: "그들은 말하였노라. “그렇게 우리가 되돌아간다면 그것은 우리에게 손실이 될 것이며 우리는 결국 속은 자들이 될 것이라”",
  79013: "부활은 단순한 일이니, 하나님의 명령을 받은 천사가 나팔을 불어 생기는 굉음으로 시작되노라.",
  79014: "보라, 땅 밑에서 죽어있던 자들이 이제 지면 위에서 살아있노라.",
  79015: "그대 - 사도여! - 에게 모세와 그의 주님인 하나님과 그의 적인 파라오에 관한 이야기가 전해졌는가?",
  79016: "모세의 주님께서 거룩한 골짜기인 ‘뚜와’ 에서 그를 불렀노라.",
  79017: "하나님께서 말씀하셨노라. “그대 모세는 파라오에게로 가라. 실로 그는 부당함과 거만함의 극치에 달했노라”",
  79018: "“그리고 파라오에게 말하라. ‘그대는 불신과 거역으로부터 정화되길 원하는가? ’”",
  79019: "“‘그대를 창조하시고 은혜를 베푸신 하나님께로 내가 그대를 인도하려 하노라. 그리하여 (그대가 인도된다면) 그대는 하나님을 두려워하게 되고 선행을 실천하며 그분의 분노를 사는 일을 피하게 될 것이라’“",
  79020: "그 후 모세 (그에게 평화가 깃들기를) 는 파라오에게 자신의 사도직을 증명하는 엄청난 징표들을 보여주었으니, 그것은 빛을 발산하는 손과 뱀으로 변하는 지팡이라.",
  79021: "그럼에도 파라오는 징표를 부정하며 모세의 명령을 거역하였노라.",
  79022: "그 후 그는 모세가 가져온 메시지에 등을 돌리고, 하나님을 거역하고 진리를 부정함에 모든 힘을 쏟았으니",
  79023: "모세를 위압할 목적으로 사람들을 불러 모아",
  79024: "그들에게 말하였노라. “나는 그대들의 지고한 주님으로서 가장 지고한 존재이니 그대들은 나 이외에 그 누구도 따르지 말라”",
  79025: "그리하여 하나님께서는 그에게 징벌을 내리셨으니 현세에서 그는 바닷물에 익사하는 벌을 받았고, 내세에서는 지옥에 들어가 가장 혹독한 벌을 받게 될 것이라.",
  79026: "진실로, 하나님께서 파라오에게 내리신 현세와 내세의 벌에는 하나님을 경외하는 자를 위한 교훈이 있으며, 오직 하나님을 경외하는 자들만이 교훈을 통해 효용을 얻노라.",
  79027: "부활을 부정하는 자들이여! 인간을 창조하는 것이 더 어려운 일인가, 아니면 하늘을 창조하는 것이 더 어려운 일인가? 하나님께서 하늘을 창조하셨노라.",
  79028: "그분께서는 하늘의 천정을 높이 올리셨고 그 후 하늘을 고르게 하셨으니, 그 안에는 흐트러짐이나 균열도 없더라.",
  79029: "또한 하나님께서는 태양이 질 때 밤을 어둡게 하셨고 태양이 뜨는 아침에는 밝은 빛을 내셨노라.",
  79030: "그분께서는 하늘의 창조 후에 땅을 넓게 펼치시어 그 안에 많은 효용을 비축해 두셨고",
  79031: "흐르는 샘물과 동물이 뜯어먹을 들풀을 내셨으며",
  79032: "산은 흔들리지 않도록 땅에 고정시키셨으니",
  79033: "이 모든 것은 그대들 - 인간들이여! - 과 그대들이 소유한 가축의 편의를 위해서라. 이 모두를 창조하신 하나님이시기에 그분께서 새로운 창조를 시작하심은 어려운 일이 아니라.",
  79034: "그리하여 두 번째 나팔이 불리고 그 두려움이 모든 것을 덮치는 심판의 날이 도래하였을 때",
  79035: "그날 인간은 자신이 행한 선행과 악행을 떠올릴 것이라.",
  79036: "지옥이 등장하여 시각을 가진 모두가 그 모습을 볼 때",
  79037: "경계를 넘어서 방황하면서",
  79038: "영원한 내세의 삶은 버려둔 채 짧은 현세의 삶만을 좇던 자는",
  79039: "실로 작열하는 불지옥만이 그가 거주할 유일한 장소가 될 것이라.",
  79040: "그러나 (심판의 날) 하나님 앞에 서는 일을 두려워하고, 그분께서 금한 것을 범하지 않도록 자신의 욕망을 통제하던 자는 다름 아닌 천국에서 영원히 거주하게 될 것이라.",
  79041: "그러나 (심판의 날) 하나님 앞에 서는 일을 두려워하고, 그분께서 금한 것을 범하지 않도록 자신의 욕망을 통제하던 자는 다름 아닌 천국에서 영원히 거주하게 될 것이라.",
  79042: "부활을 부정하는 자들이 그대 - 사도여! - 에게 묻더라. “종말의 시간은 도대체 언제 시작하는 것인가? ”",
  79043: "그대는 종말의 시간이 언제 개시되는지에 관한 지식이 없으며, 그 시간은 그대에게 중요한 것이 아니라. 그대의 임무는 종말의 시간을 어떻게 준비해야 하는지에 관한 것이기 때문이라.",
  79044: "종말의 시간이 언제인지는 오직 하나님만이 알고 계시노라.",
  79045: "그대는 오직 종말의 시간을 두려워하는 자들을 위한 경고자일 뿐이니, 그들이야말로 그대의 경고를 통해 진정 효용을 얻는 자들이라.",
  79046: "그들이 종말의 시간을 두 눈으로 직접 목격하는 날, 그들은 마치 현세에서 오후 무렵이나 아침의 한나절만을 머물렀다 생각할 것이라.",
  80000: "아바사 (얼굴을 찌푸리다)\n계시 분류: 메카\n•    계시 목적    \n이 장은 꾸란이 전하는 메시지의 실체와, 꾸란의 메시지를 통해 효용을 얻는 자의 명예 및 그 메시지에 등돌리는 자의 비천함 등을 알리고 있다.\n•    요약 주해",
  80001: "하나님의 사도 (그에게 하나님의 자비와 평화가 깃들기를) 가 인상을 찌푸리며 돌아섰으니",
  80002: "시각장애인인 ‘압둘라 이븐 움무 마크툼’ 이 조언을 구하기 위해 그를 찾아왔기 때문으로, 당시 하나님의 사도는 우상 숭배자들의 지도자들을 이슬람으로 인도하기 위해 그들과 진지하게 이야기를 나누고 있었노라.",
  80003: "무엇이 그대 - 사도여! - 에게 알려줄 것인가? ‘압둘라’가 죄를 용서받아 정화될 수도 있으며",
  80004: "그가 그대의 말을 들어 교훈을 얻을 수도 있는 것이라.",
  80005: "자신이 가진 재산만으로 충분하며 그대가 가져온 믿음의 메시지는 필요 없다고 생각하는 자에 관하여는",
  80006: "그대가 그를 바라보며 상대해 주었으나,",
  80007: "그가 죄를 용서받기 위해 하나님께 참회하지 않을지라도 그대에게는 아무 책임이 없노라.",
  80008: "반면 선을 찾기 위해 매진하며 그대에게 찾아온 자에 관해서는",
  80009: "그가 주님을 두려워하면서 그대를 찾아왔음에도 불구하고",
  80010: "그대는 우상 숭배자들의 지도자들에게만 집중한 나머지 그를 소홀히 하였노라.",
  80011: "진실은 그렇지 않노라. 실로 그것 (꾸란 구절들) 은 받아들일 준비가 된 자를 위한 교훈이자 상기의 메시지라.",
  80012: "그렇기에 하나님을 떠올리길 원하는 자는 그분을 떠올릴 것이며 꾸란을 통하여 교훈을 얻을 것이라.",
  80013: "이 꾸란은 천사들이 가지고 있는 명예로운 경전에 보관되어 있노라.",
  80014: "그 경전은 높은 곳에 올려져 있는, 때묻지 않은 고결한 경전으로서",
  80015: "사도의 임무를 맡은 천사들의 손에 있으니",
  80016: "그들은 하나님께 있어 명예로운 자들이며 많은 경배 행위와 선행을 실천하는 자들이라.",
  80017: "불신하는 인간에게는 저주가 있으니, 얼마나 극심히도 하나님을 불신하던가!",
  80018: "하나님께서 무엇으로부터 그를 창조하셨기에 그가 그토록 지상에서 거만해 하며 불신을 저지르는 것인가?",
  80019: "하나님께서는 그를 소량의 정액으로부터 창조하셨고 그 후 단계적으로 그의 창조 과정을 조절하셨노라.",
  80020: "단계적 창조를 끝내신 후 하나님께서는 그가 어머니 배 속에서 빠져나오는 길을 쉽게 해주셨고",
  80021: "그 후 그가 일정 기간 동안 삶을 산 뒤에 죽음을 맞이하게 하셨고, 심판의 날이 올 때까지 그를 무덤 속에 머물게 하셨으며",
  80022: "그 후 하나님께서 의지하실 때 그를 부활시켜 심판을 받도록 하실 것이라.",
  80023: "이 불신자는 자신이 행해야 할 주님의 권리를 다 실천했다 생각하지만, 그렇지 않노라. 그는 지금껏 하나님께서 명령하신 의무 사항을 지키지 않았노라.",
  80024: "그러니 하나님을 불신하는 인간은 그가 먹는 음식을 보도록 하라; 이 음식은 어디서 나온 것인가?",
  80025: "그 음식의 원천은 하늘에서 내린 비로서, 줄기차게 쏟아지는 빗방울은 하나님께서 내리시는 것이라.",
  80026: "하나님께서는 그런 후 대지를 갈라내시어 그로부터 새싹이 나오도록 하셨고",
  80027: "밭에서 밀과 옥수수 등이 자라나도록 하셨으며",
  80028: "포도와 가축의 여물로 쓰일 부드러운 풀과",
  80029: "올리브와 야자를 그곳에 자라나게 하셨고",
  80030: "나무들로 무성한 정원과",
  80031: "과일과 가축들이 뜯어먹을 목초도 자라나게 하셨으니",
  80032: "이 모든 것은 그대들의 편의를 위함이며 그대들의 가축을 위함이라.",
  80033: "그리하여 고막이 터질 듯한 엄청난 나팔 소리가 들려올 때",
  80034: "그날 인간은 자신의 형제를 놓아둔 채 도주하고",
  80035: "어머니와 아버지,",
  80036: "아내와 자손들을 내버려둔 채 도주할 것이라.",
  80037: "모든 이는 그날에 찾아올 엄청난 근심으로 타인에 신경 쓸 여유가 없더라.",
  80038: "그날 행복한 자들의 얼굴은 밝게 빛나고",
  80039: "웃으면서 기뻐할 것이니 하나님께서 그들을 위해 준비해주신 당신의 자비 때문이라.",
  80040: "그날 불행한 자들의 얼굴들은 먼지로 뒤덮히고",
  80041: "시커먼 그늘에 휩싸일 것이니",
  80042: "저들은 실로 불신과 사악함을 한 몸에 모은 자들이라.",
  81000: "앗-타크위르 (말아 덮음)\n계시 분류: 메카\n•    계시 목적    \n이 장은 온전하던 자연계가 으스러지게 되는 부활의 날을 묘사하고 있다.\n•    요약 주해",
  81001: "태양이 말려 올라가 그 빛을 잃을 때",
  81002: "별들이 그 빛을 잃고 줄줄이 떨어질 때",
  81003: "산들이 제자리에서 뽑혀 움직일 때",
  81004: "새끼를 밴 지 십 개월이 된 값진 암낙타가 그 주인에 의해 버려질 때",
  81005: "사나운 짐승들이 인간과 함께 한 곳에 모이게 될 때",
  81006: "바다가 타올라 불구덩이로 변할 때",
  81007: "비슷한 영혼들이 한데 모여, 사악한 영혼들이 서로 모이고 선한 영혼들이 서로 모일 때",
  81008: "산 채로 매장되었던 여자아이가 하나님으로부터 질문을 받을 때",
  81009: "“어떤 죄를 저질렀기에 네가 죽임을 당한 것인가? ”",
  81010: "행위 기록부가 펼쳐져 모든 이가 자신의 기록부를 읽을 때",
  81011: "양가죽이 벗겨지듯 하늘의 가리개가 벗겨질 때",
  81012: "지옥이 활활 타오를 때",
  81013: "천국이 믿는 자들에게 가까이 놓일 때",
  81014: "언급된 사건들이 일어나는 그날, 모든 영혼은 자신이 내놓은 행위가 무엇인지 알게 될 것이라.",
  81015: "그리하여, 저녁 이전에 그 모습이 감추어진 별들을 두고 하나님께서 맹세컨대,",
  81016: "그리고 궤도를 따라 유영하다가, 아침이 되면 마치 사슴이 자신의 거처에 몸을 숨기듯 그렇게 사라지는 별들과",
  81017: "어둠이 들어오고 나가는 밤과",
  81018: "빛을 발산해 낼 때의 아침을 두고 하나님께서 맹세하시니",
  81019: "무함마드 (그에게 하나님의 자비와 평화가 깃들기를) 에게 내려진 꾸란은 실로 하나님의 말씀으로서, 진실의 천사인 가브리엘 (그에게 평화가 깃들기를) 이 그분의 말씀을 전하는 것이라.",
  81020: "가브리엘 (지브릴) 천사는 강력한 힘을 소유하고 있으며, 권좌의 주님이신 하나님으로부터 가까운 곳에서 커다란 지위를 누리고 있노라.",
  81021: "하늘에 있는 천사들도 그를 따르며, 계시를 전달함에 있어 그는 전적으로 신뢰받는 자라.",
  81022: "그대들 (메카의 우상 숭배자들) 은 무함마드와 함께 어울려 왔기에 그의 건전한 사고력과 높은 정직성을 잘 알고 있노라; 그럼에도 그대들은 그가 미친 자라며 억지를 부리고 있노라.",
  81023: "진실로 그대들의 동료 무함마드는 선명한 지평선 부근의 하늘에서, 창조된 모습 그대로 있던 가브리엘 (지브릴) 천사를 보았노라.",
  81024: "그대들의 동료는, 전달을 명령받은 지식을 아까워하며 그대들에게 알려주지 않거나 점술가들처럼 보수를 받는 일이 없으며",
  81025: "이 꾸란은 하나님의 자비를 박탈 당한 사탄의 말도 아니라.",
  81026: "이러한 명백한 증거에도 불구하고 그대들은 꾸란이 하나님의 계시임을 부정하니, 그대들은 대체 어떤 길을 걷고 있는 것인가?",
  81027: "꾸란은 다름 아닌 인간과 진을 위한 교훈과 일깨움의 메시지니",
  81028: "그대들 중에서 진리의 길을 굳건히 걸어가고자 하는 이를 위한 것이라.",
  81029: "그대들이 진리의 길을 걷고자 함은 오직 하나님께서 그렇게 원하셨기 때문이니, 그분께서는 모든 피조물의 주님이시라.",
  82000: "알-인피따르 (파열)\n계시 분류: 메카\n•    계시 목적    \n이 장은 피조물들의 균형이 깨어지고 그 상태와 움직임이 변하게 되는 부활의 날의 양상을 묘사하고 있다.\n•    요약 주해",
  82001: "하늘을 뚫고 내려오는 천사들로 인해 하늘이 갈라 터질 때",
  82002: "행성들이 궤도를 이탈하여 떨어져 나갈 때",
  82003: "바다가 넘쳐 대양의 물이 서로 뒤섞일 때",
  82004: "무덤들이 뒤집어엎혀 그 속에 있던 죽은 자들이 걸어 나올 때",
  82005: "그때 모든 영혼은 자신이 한 행위와 하지 않은 행위가 무엇인지 알게 될 것이라.",
  82006: "주님을 불신하는 인간이여! 하나님께서는 그대에게 은혜를 베푸시어 징벌을 서두르지 않으시는데도, 그대는 주님의 명령을 어기고만 있으니 어떤 연유로 그러한 것인가?",
  82007: "하나님께서는 존재하지 않았던 그대를 생겨나게 하셨고 그대 신체의 각 부분을 알맞게 조절하신 후 균형을 잡아주셨으니",
  82008: "원하시는 모습으로 그대를 창조하셨노라. 이는 그대에게 베푸신 하나님의 축복으로, 그대의 모습은 당나귀나 개 등의 형상이 아니라.",
  82009: "진실은, 기만당한 그대들이 생각하는 것과는 다르노라. 그대들은 심판의 날을 부정하면서 그날을 준비하지도 않고 있노라.",
  82010: "진실로 그대들 위에는 그대들의 행위를 빠짐없이 기록하는 천사들이 있노라.",
  82011: "그 천사들은 하나님 앞에서 명예로운 자들이며 그대들의 행위를 적어 내려가는 서기들로서",
  82012: "그대들이 무엇을 하는지 알고 있기에 그대들의 행위를 기재하고 있노라.",
  82013: "하나님을 따르면서 많은 선행을 실천하던 자들은 심판의 날에 실로 영원한 안락을 누릴 것이라.",
  82014: "그러나 사악한 자들은 진실로 지옥에서 불타오르게 될 것이라.",
  82015: "그들은 심판의 날 지옥에 들어가 그곳의 뜨거움으로 고통받을 것이니",
  82016: "그곳에서 머물며 결코 벗어나지를 못하노라.",
  82017: "그 누가 그대 - 사도여! - 에게 심판의 날이 무엇인지를 알려줄 것인가?",
  82018: "다시 한번, 그 누가 그대에게 심판의 날이 무엇인지를 알려줄 것인가?",
  82019: "그날은 인간이 타인을 위해 어떠한 효용도 제공할 수가 없으며, 그날 모든 일의 권한은 하나님께 있노라.",
  83000: "알-무땃피핀 (적게 주는 자들)\n계시 분류: 메카\n•    계시 목적    \n이 장은 내세에서 개개인의 평가 및 지위가 달라질 것임을 말하고 있으며 이를 통해, 거짓말하면서 적게 주는 자들을 경고하고 정직하면서 후하게 주는 자들에게 희망을 주고 있다.\n•    요약 주해",
  83001: "적게 주는 자들에게 파멸과 손실이 있을 것이라.",
  83002: "그들은 사람들이 자신들 물건의 부피를 측정할 때는 그들에게 감소 없이 확실히 부피를 재라고 요구하나",
  83003: "정작 그들이 타인 물건의 부피를 재거나 무게를 달 때면 일부러 그 양을 적게 측정하노라 (선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 께서 메디나로 이주하였을 때 메디나 주민들은 이러한 관습에 젖어 있었다).",
  83004: "비난받을 이러한 행위를 저지르는 저들은 어찌하여 자신들이 하나님께로 부활될 것임을 확신하지 않는단 말인가?",
  83005: "시험과 두려움으로 가득찬 위대한 날, 그날에 있을 심판과 보상을 위해 그들은 부활할 것이니",
  83006: "그날 인간은 심판받기 위해 모든 피조물의 주님이신 하나님 앞에 설 것이라.",
  83007: "그들은 죽음 이후에 부활이란 없을 것이라 생각하나 그렇지 않노라. 사악한 불신자들과 위선자들의 행위 기록부는 진실로 지구의 가장 낮은 곳인 ‘싯진’에 있노라.",
  83008: "그 누가 그대 - 사도여! - 에게 ‘싯진’이 무엇인지를 알려줄 것인가?",
  83009: "실로 그들의 기록부는 그 정보가 소멸되지 않도록 기입되어 있으니, 증가하거나 감소하지 않노라.",
  83010: "그날, 부정하는 자들에게 파멸과 손실이 있을 것이니",
  83011: "그들은 심판의 날을 부정하는 자들로서, 그날은 하나님께서 인간이 현세에서 저지른 행위를 심판하시는 날이라.",
  83012: "하나님께서 지정하신 경계를 넘어서며 수많은 죄를 짓는 자는 어김없이 그날을 부정하노라.",
  83013: "사도에게 계시된 하나님의 징표가 낭송될 때면 그는 “이것은 옛날 사람들의 설화일 뿐이며 하나님으로부터 온 것이 아니라”라고 말하더라.",
  83014: "진실을 부정하는 그들의 추측은 사실이 아니라. 그들이 저지르던 죄악이 그들의 마음을 덮어버렸기에 그들이 진실을 보지 못하는 것일 뿐이라.",
  83015: "진실로 그들은 심판의 날 장막으로 가로막히어 그들의 주님인 하나님을 보지 못할 것이라.",
  83016: "그 후 실로 그들은 작열하는 불지옥에 들어가 그 뜨거움으로 고통받을 것이라.",
  83017: "그 후 심판의 날 그들에게 힐책하는 목소리가 들릴 것이니 “너희가 맛 보고 있는, 사도가 경고했던 이 벌은 너희가 현세에서 거짓말이라 치부하던 바로 그 벌이라” 하더라.",
  83018: "그들은 심판도 보상도 없을 것이라 생각하니, 진실은 그렇지 않노라. 하나님께 순종하던 자들의 행위 기록부는 진실로 ‘일리윤’에 있노라.",
  83019: "그 누가 그대 - 사도여! - 에게 ‘일리윤’이 무엇인지를 알려줄 것인가?",
  83020: "실로 그들의 기록부는 그 정보가 소멸되지 않도록 기입되어 있으니, 증가하거나 감소하지 않노라.",
  83021: "하나님께 가까운 곳에 있는 하늘의 천사들이 그 행위 기록부를 가지고 올 것이라.",
  83022: "하나님을 따르면서 많은 선행을 실천하던 자들은 심판의 날에 실로 영원한 안락을 누릴 것이니",
  83023: "그들은 아름답게 꾸며진 침대 위에서 주님을 바라볼 것이며, 그들을 기쁘게 하는 것들을 바라보며 즐거워할 것이라.",
  83024: "그대가 그들을 본다면 그들이 누리는 안락함으로 인해 그들의 얼굴에서 아름다움과 기쁨을 발견할 것이라.",
  83025: "시중드는 자들이 그들에게 마실 거리를 바치니, 꼭지가 밀봉된 술로서",
  83026: "그 달콤한 향기는 사향으로, 마지막 한 방울까지 그 향기가 지속되노라. 경쟁하는 자들은 이러한 풍성한 보상을 위해 경쟁해야 할 것이며, 하나님의 기쁨을 얻는 선행을 실천하고 그분의 분노를 사는 악행을 멀리하는 경쟁을 해야 할 것이라.",
  83027: "밀봉된 술에는 ‘타스님’ 이라는 샘터에서 흘러나오는 샘물이 섞여 있으니",
  83028: "그것은 천국의 가장 높은 곳에 있는 샘터로, 하나님께 가까워진 자들은 그 샘물을 직접 마시며, 그 이외의 믿는 자들은 그 샘물이 섞여 있는 음료를 마시노라.",
  83029: "불신으로써 악행을 저지르던 자들은 이전에 믿는 자들을 조롱하며 비웃곤 하였노라.",
  83030: "그들은 믿는 자들을 지나칠 때마다 서로에게 눈짓을 하며 그들을 놀렸고",
  83031: "자기 가족에게 되돌아갈 때면 자신들의 불신에 기뻐하고 그들의 믿음을 조롱하였으며",
  83032: "믿는 자들을 볼 때면 “조상들의 종교를 버리다니 진실로 저들은 진리로부터 벗어난 방황하는 자들이라”라고 말하였노라.",
  83033: "그러나 하나님께서는 불신자들을 믿는 자들에 대한 감시자로 보내신 적이 없기에 저들은 그런 말을 할 자격이 없노라.",
  83034: "그리하여 심판의 날에는 하나님을 믿는 자들이 불신자들을 비웃을 것이니, 불신자들이 현세에서 그들을 비웃던 것처럼 그렇게 비웃을 것이며",
  83035: "아름답게 꾸며진 침대 위에 누워, 하나님께서 그들을 위해 준비해 주신 영원한 기쁨을 보면서 즐거워할 것이라.",
  83036: "불신자들이 치욕의 벌을 맛봄은 그들이 현세에서 저지른 악행에 대한 징벌이라.",
  84000: "알-인쉬까끄 (갈라짐)\n계시 분류: 메카\n•    계시 목적    \n이 장은 만물이 주님의 명령에 복종하게 되는 심판의 날을 묘사함으로써, 사람들에게 고집스런 논쟁을 그만두고 하나님께 순종할 것을 촉구하고 있다.\n•    요약 주해",
  84001: "하강하는 천사들로 인해 하늘이 갈라지고",
  84002: "그 하늘이 하나님께 순종하며 그분의 말씀을 경청할 때 -마땅히 그래야 하노라-",
  84003: "마치 무두질된 동물 가죽처럼 하나님께서 땅을 평평하게 만드시고",
  84004: "땅 안에 있던 보물과 죽은 자들이 내던져져 땅이 횅하게 되며",
  84005: "그 땅이 하나님께 순종하며 그분의 말씀을 경청할 때 -마땅히 그래야 하노라-",
  84006: "인간이여! 실로 그대는 선행과 악행을 한 후에 심판의 날 하나님을 만나뵐 운명이니, 그분께서 그대의 행위를 심판하실 것이라.",
  84007: "(이전 구절에서 인간의 행위에 관한 일반적 언급이 있었다면, 여기서는 심판의 날 행위에 대한 보상이 어떻게 이루어지는지에 관해 세부적인 설명이 제시된다. )  그러니, 자신의 행위 기록부를 오른손으로 받은 자는",
  84008: "하나님께서 그를 심판하심에 쉬운 심판을 하실 것이니, 그가 저지른 행위를 제시하시지만 그에 관해 질책하시지는 않으실 것이라.",
  84009: "그리고 그는 즐거워하면서 자신의 가족에게로 되돌아갈 것이라.",
  84010: "그러나 자신의 행위 기록부를 등 뒤의 왼편으로 받은 자는",
  84011: "자신의 파멸을 기도할 것이며",
  84012: "불지옥에 들어가 그곳의 뜨거움으로 고통받을 것이라.",
  84013: "그는 현세에서 자기 가족과 함께 있으면서 자신이 저지르던 불신과 악행에 만족하였노라.",
  84014: "실로 그는 죽음 후에 또 다른 삶으로 되돌아가는 일은 없을 것이라 생각하였으나",
  84015: "그렇지 않노라, 하나님께서는 애초에 그를 창조하셨던 것처럼 분명 그를 되살리실 것이라. 실로 그의 주님께서는 그의 상태를 지켜보고 계시는 분으로서 그 무엇도 그분께는 감추어지지 않으며 그의 행위를 충분히 보상하실 것이라.",
  84016: "하나님께서는 해 질 녘의 지평선에 떠오르는 붉은 노을을 두고 맹세하시고",
  84017: "밤과 그 안에 모이는 것을 두고 맹세하시며",
  84018: "가득 차올라 보름달이 된 달을 두고 맹세하시니",
  84019: "진실로 그대들 - 인간들이여! - 은 정액 방울에서 응혈, 작은 살점이 되고 그 이후에 삶과 죽음, 부활이라는 다양한 단계를 거치게 될 것이라.",
  84020: "그럼에도 저 불신자들은 하나님과 최후의 날을 믿지 않으니 어찌 된 일인가?",
  84021: "그들에게 꾸란이 낭송될 때도 그들은 자신들의 주님을 위해 엎드려 절하지 않더라.",
  84022: "실로 불신하는 자들은 그들의 사도가 가져온 진리를 부정하지만",
  84023: "하나님께서는 그들이 마음속에 무엇을 쌓아 놓고 있는지 낱낱이 알고 계시니, 그들의 행위 중 어떤 것도 그분께 감추어지는 일이 없도다.",
  84024: "그러니 그대 - 사도여! - 는 그들에게 고통스런 벌이 그들을 기다리고 있음을 알리라.",
  84025: "그러나 하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들은 천국이라는 끊이지 않는 보상을 받을 것이라.",
  85000: "알-부루즈 (별자리)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님의 강력한 힘과 완전한 아우르심을 드러내고 있다. 또한 믿는 자들에게 시련이 닥치길 바라는 자들에 관하여 하나님께서 그들을 혹독히 벌하실 것임을 경고하고 있다.\n•    요약 주해",
  85001: "하나님께서는 해와 달 등의 경로가 되는 별자리를 지닌 하늘을 두고 맹세하시고",
  85002: "모든 피조물을 모을 것이라 약속하신 부활의 날을 두고 맹세하시며",
  85003: "증언하는 모든 것, 예를 들어 공동체에 대해 증언하는 선지자와 증언받는 모든 것, 예를 들어 선지자의 증언을 받는 공동체를 두고 맹세하시니",
  85004: "깊고 넓은 구렁을 파던 자들에게 저주가 있노라.",
  85005: "그들은 그 구렁에 불을 지피어 그 안에 믿는 자들을 내던졌노라.",
  85006: "보라. 그들은 불타는 구렁 근처에 앉아서",
  85007: "믿는 자들이 받는 고통스런 고문을 지켜보고 있었노라.",
  85008: "저 불신자들이 믿는 자들을 혐오한 이유는 단 하나로서, 그들이 가장 존엄하시고 가장 영광되신 하나님을 믿었기 때문이라.",
  85009: "하나님께서는 (일곱) 하늘의 주권과 대지의 주권을 소유하시고 계시노라. 하나님께서는 모든 것을 면밀히 지켜보고 계시니 인간의 일 그 어떤 것도 그분께는 감추어지지 않노라.",
  85010: "실로 믿는 남성들과 믿는 여성들을 불로써 고문하여 그들이 유일하신 하나님을 믿지 못하도록 하고, 그 후에도 자신의 죄를 하나님께 참회하지 않는 자들은 심판의 날 지옥의 벌을 받을 것이니, 타오르는 불이 그들을 태워버릴 것이라. 이는 그들이 믿는 자들을 불태운 것에 대한 징벌이라.",
  85011: "하나님을 믿고 그분의 사도를 따르며 선행을 실천하는 자들은 천국이 그들의 것이니, 그곳에는 궁궐 같은 저택과 수목이 있어 그 아래에는 강물이 흐르노라. 하나님께서 그들을 위해 마련해 주신 이 같은 보상이야말로 그 어떤 성공과도 비교되지 않는 가장 위대한 성공이라.",
  85012: "그대 - 사도여! - 의 주님께서 부당한 자들을 제압하실 때 -지금 당장은 그들을 유예하고 계시지언정- 그분의 제압은 진실로 강력한 것이라.",
  85013: "진실로 하나님께서는 창조하심과 벌하심을 시작하신 후 그것을 반복하시노라.",
  85014: "그리고 하나님께서는 참회하는 종복의 죄를 너그러이 용서하시는 분이시고, 그분을 경외하는 신앙인들을 많이 사랑하시는 분이시며",
  85015: "영예로운 권자의 소유자이자",
  85016: "원하시는 자를 용서하시고 원하시는 자를 벌하시는 분이시니, 그 누구도 감히 그분을 강제할 수 없노라.",
  85017: "진리에 대적하기 위해 집결했던 무리들의 이야기가 그대 - 사도여! - 에게 전해지지 않았던가?",
  85018: "파라오와, 선지자 쌀리흐에 대적한 싸무드 부족의 이야기라.",
  85019: "불신하는 자들은, 불신으로 인해 파멸한 이전 공동체들의 소식을 접하지 못하여 불신하는 것이 아니라. 그들이 지속해서 사도를 부정하는 이유는 그들이 자신들의 욕망만을 따르기 때문이라.",
  85020: "하나님께서는 그들의 일거수 일투족을 아우르시는 분으로서 그 무엇도 놓치지 않으시니 그것으로써 그들을 심판하실 것이라.",
  85021: "부정하는 자들은 그것이 한낱 시 (詩) 에 불과하다 말하지만, 실로 그것은 명예로 충만한 꾸란으로서",
  85022: "왜곡이나 변경이 없는 보존 서책 (알-라우흐 알-마흐푸드) 안에 간직되어 있노라.",
  86000: "앗-따리끄 (저녁 별)\n계시 분류: 메카\n•    계시 목적    \n이 장은 모든 것을 지켜보시며 감시하시는 하나님의 전능함을 드러내고 있다.\n•    요약 주해",
  86001: "하나님께서는 하늘을 두고 맹세하시고, 밤중에 모습을 드러내는 별을 두고 맹세하시니",
  86002: "그 누가 그대 - 사도여! - 에게 이 커다란 별이 무엇인지를 알려줄 것인가?",
  86003: "그것은 빛을 내뿜어 하늘을 관통하는 별이라.",
  86004: "하나님께서는 모든 이에게 그의 행위를 감시하는 천사를 두셨고, 부활의 날 천사의 기록을 통해 인간의 행위를 심판하실 것이라.",
  86005: "그러니 인간은 하나님께서 자신을 무엇으로부터 창조하셨는지 깊게 생각해 보아 그분의 전능하심과 자신의 미약함을 깨달을 수 있도록 하라.",
  86006: "하나님께서는, 분출하여 자궁에 놓인 정액으로부터 그를 창조하셨으며",
  86007: "이 정액은 척추와 가슴뼈 사이에서 나오는 액체라.",
  86008: "보잘것없는 액체에서 그를 창조하신 하나님께서는 심판을 위해 죽어 있던 그를 되살릴 수 있는 분이시라.",
  86009: "그날은 마음속에 감추어져 있던 의향과 신념이 만천하에 드러나게 되며, 그렇게 선량한 자가 사악한 자로부터 구분될 것이라.",
  86010: "그날 인간에게는 하나님의 징벌을 막을 그 어떤 힘도 없을 것이며, 그를 도와줄 그 어떤 조력자도 발견하지 못할 것이라.",
  86011: "하나님께서는 내렸다가 멈추기를 반복하는 비의 근원인 하늘을 두고 맹세하시고",
  86012: "새싹과 열매와 나무가 움트는 대지를 두고 맹세하시니",
  86013: "진실로 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 계시된 이 꾸란은 진리와 허위, 참과 거짓을 판가름하는 말씀으로서",
  86014: "장난으로 건네는 실없는 말이 아닌, 참되고도 진정한 말씀이라.",
  86015: "실로 사도가 가져온 메시지를 부정하는 저들은 수많은 계략을 꾸미면서 그의 초대를 거부하며 부정하지만",
  86016: "하나님 역시도 계략을 꾸미시어 진리의 종교를 드러내시고 거짓을 멸하시노라.",
  86017: "그러니 그대 - 사도여! - 는 불신자들을 늦추어 주라. 그들이 받을 징벌을 재촉하지 말고 당분간 기다려 주라.",
  87000: "알-아을라 (가장 지고하신)\n계시 분류: 메카\n•    계시 목적    \n이 장은 가장 지고하신 하나님께서 인간에게 베푸신 은혜를 상기시키면서, 내세에 마음을 두되 현세에 집착하지 말 것을 강조하고 있다.\n•    요약 주해",
  87001: "모든 피조물 위에 계시는 그대 주님의 완벽함을 찬양하면서 그분의 이름을 떠올리라.",
  87002: "하나님께서는 인간을 반듯하게 창조하시고 그의 균형을 잡아주셨으며",
  87003: "피조물의 종류와 속성을 지정하셨고 각자에게 적합한 것이 무엇인지를 가르쳐 주셨노라.",
  87004: "그리고 하나님께서는 그대들의 가축이 먹을 들풀을 자라게 하신 후",
  87005: "그 신선하고 푸르던 들풀을 메마른 흑갈색의 건초로 만드신 분이라.",
  87006: "하나님께서 그대- 사도여! -의 가슴 속에 꾸란을 두시어 그대가 꾸란을 읽도록 하실 것이라. 그러니 그대는 꾸란을 잊을까 두려워 할 필요가 없으며, 가브리엘 (지브릴) 천사가 꾸란 낭송을 끝내기 전에 서둘러 꾸란을 읽지 말도록 하라.",
  87007: "그러나 하나님의 지혜로써 그대가 망각하도록 그분께서 원하시는 것은 제외라. 실로 하나님께서는 드러내는 것과 숨기는 것 모두를 아시는 분으로서, 그분께는 그 무엇도 감추어지지 않노라.",
  87008: "하나님께서는 그대가 그분을 기쁘게 하는 선행을 쉽사리 할 수 있도록 배려하여 그대가 천국으로 들어가도록 할 것이라.",
  87009: "사람들이 교훈을 받아들일 준비가 되어 있을 때 그대는 계시 받은 꾸란으로써 그들을 일깨워 주라.",
  87010: "하나님을 두려워하는 자라면 그대의 일깨움으로부터 교훈을 얻을 것이라.",
  87011: "그러나 불신자는 교훈을 멀리하며 피하려 할 것이니 그는 지옥에 들어가게 될 불행한 자이기 때문이라.",
  87012: "그는 내세에서 불지옥에 들어가 극한의 뜨거움으로 영원히 고통받을 것이라.",
  87013: "그렇게 그는 지옥 불에서 영원히 거주할 것이니, 죽지 않기에 그는 고통으로부터 잠시도 쉴 수가 없으며, 편안한 삶이 없기에 그는 그곳에서 살아있는 것도 아니라.",
  87014: "진정 성공한 자는 우상 숭배와 죄로부터 정화된 자이며",
  87015: "이슬람이 지정한 방식으로 하나님을 떠올리고, 정해진 절차에 따라 예배를 드린 자라.",
  87016: "그렇지 않노라. 그대들은 내세의 삶을 제쳐두고 현세의 삶을 더 많이 사랑하지만, 그 두 삶 사이에는 커다란 차이가 있노라.",
  87017: "실로 내세는 현세의 즐거움과 향락보다 더 좋으며 더 오래 남아 있으니, 내세의 즐거움은 결코 멈추지 않는 것이기 때문이라.",
  87018: "진실로 하나님께서 말씀하신 이 명령들과 소식들은 꾸란 이전에 계시되었던 경전들에도 있었으니",
  87019: "그 경전들은 아브라함 (이브라힘) 과 모세 (그들에게 평화가 깃들기를) 가 계시 받은 경전들이라.",
  88000: "알-가쉬야 (온몸을 뒤덮는 공포의 날)\n계시 분류: 메카\n•    계시 목적    \n이 장은 징벌과 보상에 관한 하나님의 절대적 능력에 관하여 그 증거들을 제시하고 있으며, 이를 통해 독자의 영혼이 두려움과 희망으로 가득 차길 주문하고 있다.\n•    요약 주해",
  88001: "인간을 두려움으로 에워쌀 심판의 날에 관한 이야기가 그대 - 사도여! - 에게 전해졌는가?",
  88002: "심판의 날에 인간들은 불행한 자와 행복한 자로 나뉠 것이니, 불행한 자들의 얼굴은 모멸을 받을 것이라.",
  88003: "그들은 사슬과 멍에로 끌려 가니 괴롭고 힘든 노동으로 지쳐 있노라.",
  88004: "그들은 작열하는 지옥 불로 들어가 그 뜨거움으로 고통받을 것이며",
  88005: "펄펄 끓는 샘물을 들이마시게 될 것이라.",
  88006: "그들이 가진 먹거리는 오직 말라버린 '쉬브리끄' (오노니스) 밖에 없으니, 더럽고 냄새 나는 그 안에는 독이 서려 있노라.",
  88007: "그것에는 자양분이 없으며 아무리 먹어도 배고픔이 사라지지 않노라.",
  88008: "반면 그날 행복한 자들의 얼굴은 안락함과 기쁨으로 빛날 것이니 그들이 누리게 될 은총 때문이라.",
  88009: "그들은 현세에서 선행을 실천하였고, 그 선행에 대한 축적되고 배가된 보상으로 인해 그들은 매우 흡족할 것이라.",
  88010: "그들은 지고하고 명예로운 천국에 거주하며",
  88011: "금지된 말은 물론이며 허황된 말도 듣지 않을 것이라.",
  88012: "천국에는 흐르는 샘물이 있어 그들이 원하는 대로 퍼올려 마시노라.",
  88013: "또한 천국에는 높은 침대들과",
  88014: "마실 준비가 되어 있는 술잔들과",
  88015: "흐트럼 없이 잘 정리된 베개들과",
  88016: "여기저기에 펼쳐진 부드러운 융단들이 있노라.",
  88017: "(하나님께서는 내세에서 행복한 자와 불행한 자의 상태가 어떻게 다른지를 언급하셨다. 이제 그분께서는 불신자들에게 창조자의 전능하심과 피조물의 아름다움을 살펴볼 것을 명하고 계신다. 그렇게 하여 그들이 믿음을 가질 때 그들은 결국 천국에 들어가는 행복한 자들이 될 것이다. )  하나님께서 어떻게 낙타를 창조하시고 어떻게 인간이 그 낙타를 부릴 수 있도록 하셨는지 그들은 숙고하지 않겠는가?",
  88018: "하나님께서 하늘을 마치 천장처럼 높게 두시어 어떻게 그들 위로 떨어지지 않도록 하셨는지,",
  88019: "그분께서 산을 세우시어 어떻게 그것으로 땅을 고정시키고 흔들리지 않도록 하셨는지,",
  88020: "그리고 대지를 고르게 두시어 어떻게 사람들이 그 위에서 안정적으로 살 수 있도록 하셨는지 그들은 숙고하지 않겠는가?",
  88021: "(하나님께서는 그들에게 그분의 전능하심을 알려주는 피조물들을 살펴보라 하셨고, 이제 그분께서는 사도를 향하여 말씀을 전하고 계신다. )  그러니 그대 - 사도여! - 는 저들에게 교훈을 주고 그들이 하나님의 징벌을 두려워하도록 하라. 그대의 역할은 사람들을 상기시켜 주는 일 뿐이며, 그들을 믿음으로 인도하는 일은 오직 하나님의 손에 달려 있노라.",
  88022: "그러니 그대는 그들에게 횡포를 부리며 믿음을 강요하는 자가 아니라.",
  88023: "그러나 믿음에 등을 돌리며 하나님과 그분의 사도를 불신하는 자는",
  88024: "심판의 날 하나님께서 그에게 가장 커다란 벌을 내리실 것이니, 그는 지옥에 들어가 그곳에서 영원히 거주할 것이라.",
  88025: "실로 죽음 이후 그들이 돌아갈 곳은 오직 하나님 한 분 뿐이며",
  88026: "실로 그들의 행위를 심판하실 분은 그대도, 다른 누구도 아닌 오직 하나님 한 분이시라.",
  89000: "알-파즈르 (새벽빛)\n계시 분류: 메카\n•    계시 목적    \n이 장은 우주와 인간 역사에 내재한 하나님의 위대하심과 전능하심을 드러내고, 기만하는 자들의 결말이 무엇인지를 보여주고 있다.\n•    요약 주해",
  89001: "하나님께서는 새벽빛을 두고 맹세하시고",
  89002: "둘 힛자 (이슬람력 12월) 첫 번째 십 일 밤을 두고 맹세하시며",
  89003: "짝수인 것과 홀수인 것을 두고 맹세하시고",
  89004: "밤이 머무른 후 사라질 때를 두고 맹세하시니 (그대들은 그대들의 행위에 상응하는 보상을 받을 것이라. )",
  89005: "언급된 저 모든 것 안에는 이성을 갖춘 자를 위한 맹세가 있노라.",
  89006: "선지자 후드와 함께 있었던 아드 부족이 그들에게 보내진 선지자를 부정했을 때 하나님께서 그들을 어떻게 하셨는지 그대 - 사도여! - 는 알지 못하는가?",
  89007: "아드 부족은 우람한 체격의 아람을 선조로 두고 있으며",
  89008: "하나님께서는 일찍이 지구상에서 그들과 유사한 존재를 창조하신 적이 없노라.",
  89009: "그리고 선지자 쌀리흐와 함께 있었던 싸무드 부족을 하나님께서 어떻게 하셨는지 그대는 알지 못하는가? 그들은 산 골짜기에 있는 돌을 조각하여 집을 만들던 자들이라.",
  89010: "또한 그대는 하나님께서 파라오를 어떻게 하셨는지 알지 못하는가? 그에게는 말뚝이 있어 그것으로써 사람들을 고문하였노라.",
  89011: "저들 모두는 각자의 나라에서 부당함의 극치에 도달한 채",
  89012: "불신과 거역 행위를 퍼뜨렸노라.",
  89013: "그리하여 하나님께서는 그들에게 가혹한 벌을 내리시어 그들을 멸하셨노라.",
  89014: "진실로 그대 - 사도여! - 의 주님께서는 선행을 행하는 자를 천국에 들게 하시고 악행을 행하는 자를 지옥에 들게 하시기 위해 인간의 행위를 면밀히 관찰하고 계시노라.",
  89015: "(이전 공동체가 누리던 번영에도 불구하고 그들은 결국 멸망하였다. 이제 하나님께서는 여기서, 그들이 즐기던 향락이 그들에 대한 그분의 만족을 뜻하는 것이 아님을 말씀하시고 계신다. )  (불신하는) 인간의 천박한 본성은, 하나님께서 그를 시험하시어 그에게 재산과 자식과 명성을 주실 때면 그것이 하나님께서 그에게 선사하신 명예로 착각하는 것이라. 그는 이 때 “저의 주님께서 저에게 걸맞는 명예를 주셨습니다”라고 말하더라.",
  89016: "그러나 하나님께서 그를 시험하시어 그에게 양식을 제한하실 때면 그것을 하나님께서 내리신 치욕으로 생각하면서 “저의 주님께서 저에게 치욕을 주셨습니다”라고 말하더라.",
  89017: "인간은, 그가 누리는 부유함이 자신에 대한 하나님의 만족이며 그가 겪는 가난함은 자신에 대한 하나님의 불만족이라 생각하나, 인간이 가진 이런 생각은 결코 사실이 아니라. 그럼에도 그대들은 하나님으로부터 받은 양식을 고아에게 베풀지 않으며",
  89018: "먹을 것이 없는 불우한 자들에게 음식을 주자고 서로가 서로에게 권유하지도 않노라.",
  89019: "그리고 그대들은 허약한 여성과 고아에게 남겨진 유산을 허락 없이 송두리째 갈취하고",
  89020: "재물을 너무도 사랑하여 하나님의 길에서 자신의 재산을 쓰려 하지 않노라.",
  89021: "그대들의 이러한 행위는 타당하지 않노라. 그대들은 땅이 심하게 요동치고 지진으로 갈라질 때를 기억하라.",
  89022: "그대 - 사도여! - 의 주님께서 그분의 종복들을 구분 짓기 위해 오시고, 천사가 여러 줄을 이루어 정렬하여 다가올 때",
  89023: "이날에 지옥이 대령되니 그것에는 칠만개의 고삐가 있어, 하나의 고삐마다 칠만명의 천사가 모여들어 그 고삐로 지옥을 끌어 올 것이라. 인간은 이날 하나님에 관한 자신의 소홀함을 깨닫지만 이 같은 그의 깨달음은 소용이 없노라. 이날은 선행을 실천하기 위한 날이 아니라 현세의 행위를 심판 받기 위한 날이기 때문이라.",
  89024: "그가 크게 후회하며 말하노라. “내세에서의 삶을 위해 내가 선행을 베풀었다면 좋았을 텐데! ”",
  89025: "그날 어느 누구도 하나님의 벌과 같은 벌을 내리지 못하니, 그분의 벌은 가장 혹독하면서도 가장 오래 남는 벌이라.",
  89026: "또한 그 누구도 하나님의 사슬과 같은 사슬로써 지옥에 있는 불신자들을 묶지 못하노라.",
  89027: "(이전에 하나님께서는 불신자들이 받을 징벌에 대해 언급하셨고, 이제 그분께서는 여기서 믿는 자들이 받을 보상에 대해 언급하고 계신다. )  믿는 자들의 영혼은, 죽음이 도래하였을 때와 심판의 날이 찾아왔을 때 다음과 같은 목소리를 들을 것이라. “믿음과 선행으로 평온함을 찾는 영혼이여! ”",
  89028: "“그대의 주님이신 하나님께로 돌아가라; 그대는 그대가 받을 풍성한 축복에 기뻐할 것이며, 하나님께서도 그대가 실천한 선행으로 흡족하실 것이라”",
  89029: "“그리하여 그대는 나(하나님)의 선량한 종복들에게로 들어가라”",
  89030: "“그들을 위해 내(하나님) 가 준비한 천국으로 그들과 함께 들어오라”",
  90000: "알-발라드 (도시)\n계시 분류: 메카\n•    계시 목적    \n이 장은 현세와 내세에서의 인간의 양상을 밝히고 있다: 인간은 내세에서 불신에 따른 고단함과 고통을 겪거나, 믿음에 따른 자비와 영광을 얻을 것이다.\n•    요약 주해",
  90001: "하나님께서는 성스러운 도시 메카를 두고 맹세하시니",
  90002: "-이 도시에서 그대-사도여!-가 취했던 전시 상황에서의 여러 행위들은 허락된 것이었노라-",
  90003: "그리고 하나님께서는 아이를 출산하는 부모와 그로부터 혈연을 이루는 자식을 두고 맹세하시니",
  90004: "실로 하나님께서는 인간을 창조하심에 그가 현세의 삶 속에서 피곤함과 고단함을 느끼도록 하셨노라.",
  90005: "하나님께서 그렇게 인간을 창조하셨음에도, 인간은 죄를 저질렀을 때 그 누구도 자신을 통제하거나 벌하지 않을 것이라 생각하는 것인가?",
  90006: "그가 말하노라. “나는 축적된 많은 재산을 소비하였도다”",
  90007: "많은 돈을 썼다며 뻐기는 이 자는 하나님께서 그를 보지 않는다고 생각하는 것인가? 어디서 그 재산을 구했는지, 어떤 곳에 그 재산을 썼는지 하나님께서 그의 재산에 관해 심판하지 않으실 것이라 생각하는 것인가?",
  90008: "하나님께서 그의 시각을 위해 두 눈과",
  90009: "혀와 말할 수 있는 두 입술을 주시지 않았던가?",
  90010: "또한 하나님께서는 그에게 진리의 길과 허위의 길을 가리켜 주셨노라.",
  90011: "그럼에도 그는 천국으로 들어가기 위해 건너야만 하는 험한 길을 헤쳐나가지 않았노라.",
  90012: "그 누가 그대 -사도여! - 에게 천국으로 들기 위해 건너야만 하는 험한 길이 무엇인지를 알려줄 것인가?",
  90013: "그것은 남자 노비나 여자 노비를 해방시켜 주거나",
  90014: "먹을 것이 부족한 배고픈 날에 사람들에게 먹을 것을 베풀고",
  90015: "친척 관계에 있는 고아 아이나",
  90016: "아무 것도 가진 것이 없는 불우한 자에게 먹을 것을 베푸는 것이라.",
  90017: "만약 그가 이러한 선행들을 실천한 후에 하나님을 믿는 무슬림이 되었다면, 그리하여 하나님을 위한 경배 행위에 인내할 것을 서로에게 권유하고 사람들 사이에 자비로울 것을 권유하는 자가 되었다면, 그의 믿음 뿐만 아니라 그가 실천했던 이슬람 이전의 선행 모두도 받아들여졌을 것이라.",
  90018: "이렇게 선행을 실천한 후에 이슬람으로 입교한 자들은 (심판의 날) 자신의 행위 기록부를 오른쪽으로 받을 것이라.",
  90019: "그러나 하나님께서 사도에게 내리신 징표를 불신하는 자들은 실로 자신의 행위 기록부를 왼쪽으로 받을 것이라.",
  90020: "그들 위에는 굳게 닫히어 빠져 나갈 수 없는 지옥 불이 있으니 그 안에서 그들은 고통받을 것이라.",
  91000: "앗-샴스 (해)\n계시 분류: 메카\n•    계시 목적    \n이 장은 인간의 영혼을 정화하고 거역 행위를 방지하기 위해, 하나님의 징표와 인간과 자연에게 내려진 그분의 은총을 드러내는 데 집중하고 있다.\n•    요약 주해",
  91001: "하나님께서는 태양과, 동쪽에서 태양이 떠오르는 시간을 두고 맹세하시고",
  91002: "달이 자신의 빛으로 일몰 후에 남아 있는 태양빛을 이어갈 때를 두고 맹세하시며",
  91003: "낮이 자신의 빛으로 대지 위에 있는 것들을 드러낼 때를 두고 맹세하시고",
  91004: "밤이 대지를 뒤덮어 어둠이 짙어올 때를 두고 맹세하시노라.",
  91005: "그리고 하나님께서는 하늘과, 그것의 완벽한 짜임새를 두고 맹세하시고",
  91006: "지구와, 그 위에서 사람들이 거주할 수 있도록 평평하게 만들어진 대지를 두고 맹세하시며",
  91007: "영혼을 지닌 인간과, 그를 균형 있게 창조하신 분을 두고 맹세하시니",
  91008: "그 후 하나님께서는 무엇이 사악한 것이고 무엇이 경건한 것인지 알 수 있도록 인간에게 영감을 불어 넣으셨노라 -",
  91009: "선을 추구하고 악을 멀리함으로써 자신의 영혼을 정화한 자는 진정 성공한 것이며",
  91010: "자신의 영혼을 숨겨 가면서 거역 행위와 죄악을 저지른 자는 진정 실패한 것이라.",
  91011: "(하나님께서는, 자신의 영혼을 은폐하면서 죄를 저지르는 자가 실패한 것이라 선언하셨고, 이제 여기서는 이들의 예시로서 싸무드 부족을 언급하고 계신다. )  싸무드 부족은 거역 행위와 죄악을 저지름에 극한의 경계에 도달하였고, 그렇게 그들은 그들에게 보내진 선지자 쌀리흐를 부정하였노라.",
  91012: "그들은 자신들 중 가장 사악한 자를 지정하여 파견하니",
  91013: "하나님의 사도인 쌀리흐가 그들에게 \"하나님의 암낙타에 해를 끼치지 말고 정해진 날에 낙타가 물을 마실 수 있도록 하라”라고 말하였으나",
  91014: "그들은 사도의 명령을 거역하였고 그들 중 가장 사악한 자가 낙타를 죽여버렸으니, 그들은 그의 악행에 만족함으로써 그가 저지른 범죄에 동참하였노라. 그리하여 하나님께서는 그들이 저지른 죄에 대한 벌로서 그들에게 엄청난 굉음을 내리셨고 이 벌은 구분 없이 그들 모두를 파멸시켰노라.",
  91015: "이렇게 그들의 멸망을 초래한 벌을 내리심에 하나님께서는 전혀 개의치 않으시노라.",
  92000: "알-라일 (밤)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님의 징표와 인간과 그들의 행위의 다양성을 언급함으로써 믿는 자들과 불신자들간에 존재하는 차이점을 드러내고 있다.\n•    요약 주해",
  92001: "밤이 자신의 어둠으로 하늘과 땅 사이를 뒤덮을 때를 두고 하나님께서 맹세하시고",
  92002: "선명하게 드러난 낮을 두고 맹세하시며",
  92003: "남자와 여자를 양성으로 창조하신 하나님을 두고 맹세하시니",
  92004: "진실로 그대들 - 인간들이여! - 의 행위는 그 종류가 천차만별이라; 그 중에는 그대들을 천국으로 인도하는 선행이 있으며, 그대들을 지옥으로 인도하는 악행이 있노라.",
  92005: "자카를 내고 경제적 부양을 하는 등 그에게 의무가 되는 지출을 성실히 이행하고, 하나님께서 금지하신 것을 멀리하며,",
  92006: "자신이 쓴 재산은 하나님께서 더 훌륭한 것으로 대체해 주실 것을 확신하는 자",
  92007: "하나님께서는 그가 선행을 실천하고 하나님의 길에서 재산을 쓰는 일을 쉽게 해주실 것이라.",
  92008: "그러나 재산을 써야 할 곳에 인색하며, 부유한 자신은 하나님이 필요치 않다 생각하면서 그분께 은총을 구하지도 않으며,",
  92009: "하나님께서 그가 쓴 재산을 대체해 주지도, 그것에 대해 보상을 베풀지도 않으실 것이라 생각하는 자",
  92010: "하나님께서는 그의 악행을 쉽게 하시고 그가 선행을 실천하는 일을 어렵게 하실 것이라.",
  92011: "그가 인색하게 굴며 쓰지 않던 그 재산은, 죽은 후 지옥으로 떨어질 때 그에게 아무런 도움이 되지 못하노라.",
  92012: "하나님께서 필연코 하실 일은 진리의 길과 거짓의 길이 무엇인지 알려주는 것이며",
  92013: "내세와 현세는 다름 아닌 하나님의 소유이기에 그분께서는 원하시는 대로 두 세상을 다스리시노라.",
  92014: "그렇기에 하나님께서는 그대들 - 인간들이여! - 에게 당신을 거역하는 자들이 맛 보게 될 타오르는 불지옥을 경고하셨노라.",
  92015: "지옥 불에 고통받을 자는 오직 불신자들 뿐이니 그들은 가장 불행한 자들로서",
  92016: "사도가 가져온 메시지를 부정하고 하나님의 명령에 등을 돌린 자들이라.",
  92017: "그러나 가장 높은 경외심을 지녔던 아부 바크르는 그 불지옥으로부터 멀리 떨어져 있게 될 것이니",
  92018: "그는 죄를 용서받기 위해 자신의 재산을 훌륭한 곳에 쓰던 자라.",
  92019: "그가 희사하는 재산은 자신에게 은혜를 베풀어 준 누군가를 보상하기 위한 것이 아니며",
  92020: "그가 자신의 재산으로 바라는 것은 오직, 피조물 위의 가장 높은 곳에 계신 하나님의 얼굴을 뵙는 일 뿐이라.",
  92021: "그는 하나님께서 주시는 풍성한 보상에 정녕 기뻐하게 될 것이라.",
  93000: "앗-두하 (아침빛)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님께서 선지자에게 주신 계시의 은총을 언급함으로써 선지자를 위안하면서, 믿는 자들에게는 감사함의 중요성을 상기시키고 있다.\n•    요약 주해",
  93001: "하나님께서는 이른 아침 시간을 두고 맹세하시고",
  93002: "어둠이 찾아와 사람들의 움직임이 잦아드는 밤을 두고 맹세하시니",
  93003: "그대- 사도여! -에게 계시가 멈추었다는 이유로 우상 숭배자들은 추측하며 말하나, 하나님께서는 그들의 말처럼 그대를 버리신 것이 아니며, 그대를 싫어하시는 것도 아니라.",
  93004: "실로 그대에겐 끊이지 않는 영원한 기쁨이 있는 내세가 현세보다 더 훌륭한 거주지이며",
  93005: "하나님께서 정녕코 (내세에서) 그대와 그대의 이슬람 공동체에 풍성한 보상을 베푸실 것이니 그대와 그대의 공동체는 만족할 것이라.",
  93006: "하나님께서는 그대가 고아임을 아시고, 그대의 할아버지인 압둘 뭇딸립과 삼촌인 아부 딸립을 그대의 보호자로 두시어 그대에게 거처를 제공해 주셨노라.",
  93007: "그리고 하나님께서는 성서와 믿음이 무엇인지를 모르는 그대를 가르쳐 주셨고",
  93008: "그대가 가난함을 아시고는 부족함을 채워 주셨노라.",
  93009: "그러니 그대는 고아를 가혹하게 대하거나 모멸하지 말고",
  93010: "필요로 인해 구걸하는 자는 질책하지 말며",
  93011: "하나님께서 그대에게 주신 은총에는 감사하며 그 은총에 관해 이야기를 나누라.",
  94000: "앗-샤르흐 (열어넓힘)\n계시 분류: 메카\n•    계시 목적    \n이 장에서 하나님께서는 선지자의 근심과 고충을 덜어주신 당신의 은총에 대해 말씀하시면서, 선지자가 그에 상응하여 해야 할 일이 무엇인지 언급하고 계신다.\n•    요약 주해",
  94001: "하나님께서는 그대의 가슴을 넓게 열어주셨기에 그대는 계시 받기를 열망하게 되었노라.",
  94002: "하나님께서는 이전에 있었던 그대의 죄를 용서해 주셨으며, 무지의 시대에 그대가 짊어졌던 짐을 내려 주셨으니",
  94003: "등골을 짓누르며 그대를 힘들게 하던 짐이라.",
  94004: "그리고 하나님께서는 그대를 위하여 그대의 명예를 높여 주셨으니, 아단 등에서 그대의 이름이 언급되도록 하셨노라.",
  94005: "그러니 실로 어렵고 빠듯한 시간이 지나면 쉽고 넉넉한 시간이 올 것이라.",
  94006: "실로 어렵고 빠듯한 시간이 지나면 쉽고 넉넉한 시간이 올 것이라. 이 사실을 알았으니 그대는 사람들의 괴롭힘을 두려워 말며, 포기하지 않고 계속해서 그들을 이슬람으로 초대하라.",
  94007: "그러니 해야 할 일을 마치고 여유가 생겼을 때 그대는 주님을 위해 열심히 경배 행위에 임하며",
  94008: "그대의 소망과 목표를 하나님 한 분께로만 향하게 하라.",
  95000: "앗-틴 (무화과)\n계시 분류: 메카\n•    계시 목적    \n이 장은 인간의 가치를 언급하고 있다. 계시가 내려진 지역에 대한 맹세로 시작하는 이 장은, 인간은 이슬람을 통하여 비로소 명예로워지며 이슬람을 등질 때는 미천한 존재로 전락함을 밝히고 있다.\n•    요약 주해",
  95001: "하나님께서는 무화과와 무화과가 자라는 지역, 올리브와 올리브가 자라는 지역을 두고 맹세하시니 그곳은 예수 (그에게 평화가 깃들기를) 가 보내진 팔레스타인 지역이라.",
  95002: "또한 하나님께서는 당신께서 모세 (그에게 평화가 깃들기를) 를 부르셨던 시나이 산을 두고 맹세하시며",
  95003: "들어가면 누구든지 안전함을 보장받는 신성한 도시이자, 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 가 사도직을 받은 도시인 메카를 두고 맹세하시니",
  95004: "진실로 하나님께서는 인간을 가장 준수하고 훌륭한 모습의 피조물로 두셨노라.",
  95005: "그 후 하나님께서는 그를 나이가 들게 하시어 그의 육체를 허약하게 만드셨고, 창조 본성을 거부하고 불신을 선택한 인간에 대해서는 그를 불지옥에 들게 하셨노라.",
  95006: "그러나 하나님을 믿고 선행을 실천하는 자들은, 현세에서 나이가 들어 육체가 허약해질지언정, 내세에서 천국이라는 끊이지 않는 보상을 받을 것이니, 그들은 창조 본성을 지켰기 때문이라.",
  95007: "그대-인간이여!-는 하나님의 무한한 능력을 드러내는 여러 징표들을 보았음에도 무엇으로 인해 그대는 심판의 날을 부정하는 것인가?",
  95008: "부활의 날을 심판의 날로 두신 하나님께서는 가장 지혜로우시고 가장 공정하신 판결자가 아니시던가? 하나님께서는 선행을 실천하던 자를 선으로 보상하고 악행을 저지르던 자를 악으로 징벌하시니, 이러한 보응 과정 없이 인간을 그대로 내버려 두는 것은 하나님께 합당치 않은 일이라.",
  96000: "알-알라끄 (매달린 것)\n계시 분류: 메카\n•    계시 목적    \n이 장은 인간이 받은 지식과 계시의 축복을 언급하고 있다. 인간은 지식과 계시를 통해 하나님께 더욱 가까워지고 순종하게 되며 그렇지 않을 때는 반대의 경우에 노출된다.\n•    요약 주해",
  96001: "모든 피조물을 창조하시는 그대- 사도여! - 주님의 이름으로, 그대에게 내려지는 하나님의 계시를 읽어라.",
  96002: "하나님께서는 정액에서 만들어진 고체의 핏덩어리로부터 인간을 창조하셨도다.",
  96003: "그대 - 사도여! - 는 하나님께서 내리시는 계시를 읽어라. 그대의 주님이신 하나님께서는 그 누구와도 비교될 수 없는 관대함을 가지신 분으로서 널리 그리고 훌륭히 베푸시노라.",
  96004: "하나님께서는 펜으로 쓰는 글자와 필기법을 가르쳐 주셨으니",
  96005: "인간이 이전에는 알지 못했던 것을 가르쳐 주셨노라.",
  96006: "실로 아부 자흘과 같은 사악한 인간은 하나님께서 지정하신 경계를 넘어섰도다.",
  96007: "자신은 명예와 부를 가졌으니 하나님을 필요로 하지 않는다고 생각하기 때문이라.",
  96008: "실로 그대 - 인간이여! - 는 심판의 날 하나님께로 돌아가게 될 것이며 그분께서는 그 모두를 정당히 보상하실 것이라.",
  96009: "아부 자흘이 제지하니 그의 행위는 참으로 놀랍도다.",
  96010: "그는 카으바 근처에서 예배하는 하나님의 종복 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 를 제지하였노라.",
  96011: "제지를 당한 그는 하나님으로부터 받은 지식을 통해 올바른 길을 걷고 있었으며",
  96012: "사람들에게, 하나님을 두려워하면서 그분의 명령을 따르고 그분께서 금지하신 것을 멀리하라 명하고 있었노라. 이러한 그인데 무슨 연유로 그가 제지를 당해야 하는 것인가?!",
  96013: "무함마드를 제지하던 아부 자흘은 사도가 가져온 메시지를 부정하고 등을 돌리니, 그는 하나님을 두려워하지 않는 것인가?",
  96014: "예배 드리는 종복을 제지한 그는, 모든 것을 소상히 알고 계신 하나님께서 그를 지켜 보고 계심을 알지 못하는가?",
  96015: "실제는 그가 추측하는 것과 다르노라. 실로 그가 하나님의 종복에게 해를 끼치려는 시도와, 그를 거짓말쟁이로 몰고 가는 일을 그만두지 않는다면 하나님께서는 정녕 그의 머리채를 잡아끌어 지옥 불로 내던지실 것이라.",
  96016: "끌려가는 머리채를 달고 있는 이 자의 말은 거짓되고, 행동은 죄악으로 물들어 있노라.",
  96017: "그러니 그는 지옥으로 끌려갈 때 자신의 패거리를 불러, 불지옥의 고통으로부터 그를 구해 달라고 요청해 보라.",
  96018: "그러면 하나님께서는 지옥을 파수하는 모질고 거친 천사들을 부르실 것이니, 그들은 하나님의 명령을 거역하지 않노라. 그러니 그는 이 두 무리들 중 어느 누가 더 힘세고 강한 능력을 갖추었는지 살펴보도록 하라.",
  96019: "아부 자흘은 무함마드에게 해악을 끼칠 수 있을 것이라 생각하나 실상은 그렇지 않노라. 그대 무함마드는 그의 명령이나 금지를 따르지 말며, 하나님을 위해 엎드려 절하라. 그러한 경배 행위로써 그대는 하나님께 더욱 가까이 이르게 될 것이라.",
  97000: "알-까드르 (운명)\n계시 분류: 메카\n•    계시 목적    \n이 장은 운명의 밤의 위대함과 그날 밤에 내려진 계시에 대해 이야기하고 있다.\n•    요약 주해",
  97001: "실로 하나님께서는 운명의 밤에 가장 낮은 현세의 하늘로 꾸란을 내리셨고, 라마단 달을 맞이하여 운명의 밤에 사도 (하나님께서 그에게 자비와 평화를 베푸시길) 에게 꾸란을 계시하기 시작하셨노라.",
  97002: "그대 - 사도여! - 는 운명의 밤이 지닌 훌륭함과 그 축복이 무엇인지 알고 있는가?",
  97003: "운명의 밤은 그 위대함이 이루 말할 수 없으니, 그날 밤에 믿음으로써 보상을 바라며 예배를 드리는 자가 있다면 이 밤은 천 개월보다 더 좋으니라.",
  97004: "그날 밤 천사들과 가브리엘 (지브릴) 천사는 그들의 주님이신 하나님의 허락으로 하강하는데, 그 해에 있을 인간의 탄생과 죽음 등 하나님께서 운명으로 결정하신 모든 사안들을 가지고 하강하노라.",
  97005: "이 축복 받은 밤은 그 시작부터 새벽빛이 뜨는 마지막까지 좋은 것들로 가득차 있노라.",
  98000: "알-바이이나 (분명한 증거)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 사도 무함마드 (하나님께서 그에게 자비와 평화를 베푸시길) 께서 받은 메시지의 명확함과 완전함에 대해 이야기하고 있다.\n•    요약 주해",
  98001: "불신하는 기독교인들과 유대교인들, 그리고 우상 숭배자들은 이견 없이 모두가 불신에 합의하고 있었으나, 그들에게 명백한 증거와 논리가 도래한 후에는 분열하면서 서로 다른 의견을 보였노라.",
  98002: "그 명백한 증거와 논리는 하나님께서 보낸 그분의 사도로서, 그는 정화된 자들만이 만질 수 있는 꾸란을 낭송하노라.",
  98003: "그 경전 안에는 정확한 역사적 기록과 공정한 판결이 있어 사람들이 그것으로써 올바른 길을 향할 수 있게 되노라.",
  98004: "토라를 받은 유대인들과 복음을 받은 기독교인들은 자신들의 성서에 예언된 사도의 도래를 믿고 있었으나, 정작 하나님께서 그 사도를 보내셨을 때 그들은 서로 다른 의견을 보였으니, 일부는 이슬람으로 입교하였으나 다른 일부는 사도의 진실성을 알면서도 불신을 지속하였노라.",
  98005: "유대교인들과 기독교인들이 꾸란에서 명령받은 내용은 그들의 성서가 이전에 그들에게 명령한 것들로서, 진정으로 하나님 한 분만을 경배하고 다신 사상을 배척하며 성실히 예배를 드리고 의무 희사금을 내라는 명령이었노라. 그들이 명령받은 이것이야말로 구부러짐이 없는 올곧은 종교라.",
  98006: "실로 불신하는 유대인들과 기독교인들, 그리고 우상 숭배자들은 심판의 날 지옥에서 영원히 머물 것이라. 저들은 실로 가장 사악한 피조물로서 하나님을 불신하고 그분의 사도를 부정하였기 때문이라.",
  98007: "하나님을 믿고 선행을 실천하는 자들은 진실로 가장 훌륭한 피조물이라.",
  98008: "그들이 받을 보상은 하나님께 가까운 곳에 있는 천국이니, 그곳에는 궁궐 같은 저택들 아래에 강물이 흐르며 그들은 그곳에서 영원히 거주할 것이라. 하나님께서는 그들의 믿음과 선행에 흡족하시고, 그들도 그분으로부터 받은 자비에 크게 기뻐하노라. 이와 같은 자비는 하나님을 두려워던 자를 위한 것이니, 그들은 하나님께서 명령한 것을 지키고 그분께서 금지하신 것은 멀리했기 때문이라.",
  99000: "앗-잘잘라 (요동침)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 심판의 날에 관해 방심하고 있던 자들을 일깨우고 있다.\n•    요약 주해",
  99001: "심판의 날 땅이 심하게 요동치고",
  99002: "땅이 자신이 품고 있던 죽은 자들을 방출해 내며",
  99003: "사람들이 당황하여 “땅이 이렇게 뒤틀리고 흔들리니 도대체 땅에게 무슨 일이 생긴 것인가? ”라고 말할 때",
  99004: "이 위대한 날 땅은, 사람들이 땅 위에서 행했던 선행과 악행에 대해 소식을 전할 것이니",
  99005: "하나님께서 땅에게 소식을 가르쳐 주시고 명령하셨기 때문이라.",
  99006: "땅이 요동치는 이 위대한 날 인간들은 심판이 이루어지는 장소로부터 각자 앞으로 나아가, 현세에서 자신들이 행했던 일들을 목격하게 될 것이니",
  99007: "조그만 개미만큼의 무게라도 선행을 실천한 자는 자신 앞에 펼쳐진 선행을 보게 될 것이며",
  99008: "조그만 개미만큼의 무게라도 악행을 저지른 자는 자신 앞에 펼쳐진 악행을 보게 될 것이라.",
  100000: "알-아디야트 (질주하는 말)\n계시 분류: 메카\n•    계시 목적    \n이 장은 현세에 집착하는 인간을 묘사하고 그가 맞이하게 될 결말을 언급함으로써 그가 자신이 걷고 있는 잘못된 길을 바로잡기를 촉구하고 있다.\n•    요약 주해",
  100001: "하나님께서는 거친 숨을 몰아쉬며 질주하는 말을 두고 맹세하시고",
  100002: "발굽과 돌이 부딪혀 부싯불을 일으키는 말을 두고 맹세하시며",
  100003: "새벽녘에 적들을 향해 돌진하는 말을 두고 맹세하시니",
  100004: "그때 말은 돌진하고 먼지를 일으키며",
  100005: "기수와 함께 적진의 한가운데로 돌격하노라 -",
  100006: "진실로 인간은 하나님께서 원하시는 좋은 것들을 실천하지 않노라.",
  100007: "진실로 그는 자신이 좋은 일을 하지 않음을 증언하니, 그 사실은 너무도 명백하여 차마 부정할 수 없기 때문이라.",
  100008: "또한 진실로 그는 재산에 대한 사랑이 극심한 나머지 타인을 인색하게 대하노라.",
  100009: "하나님께서 무덤에 있던 죽은 자들을 끄집어내시어 심판을 진행하실 터인데도, 현세에 기만당하고 있는 그는 (부활이 없을 것이란) 자신의 생각이 착각에 불과함을 알지 못하노라.",
  100010: "인간의 마음속에 있던 의도와 믿음 등이 밖으로 드러날 때",
  100011: "진실로 그들의 주님이신 하나님께서는 이날 그들의 모든 사정에 밝으시니, 그들의 그 무엇도 그분께는 감추어지지 않으며 그분께서는 그들 모두를 충분히 보응하실 것이라.",
  101000: "알-까리아 (대재앙의 날)\n계시 분류: 메카\n•    계시 목적    \n이 장은 공포로 뒤덮힐 심판의 날의 양상에 대해 언급함으로써 그날에 대해 주의할 것을 촉구하고 있다.\n•    요약 주해",
  101001: "공포스런 현상들로 사람들이 두려움으로 떨게 될 종말의 시간.",
  101002: "두려움으로 떨게 될 종말의 시간은 무엇인가?",
  101003: "그 누가 그대 - 사도여! - 에게 두려움으로 떨게 될 종말의 시간이 무엇인지를 알려줄 것인가? 그 시간은 바로 심판의 날이라.",
  101004: "그날 사람들은 두려움에 떨면서 마치 사방으로 흩어지는 불나방들처럼 도망칠 것이며",
  101005: "산들은 마치 풀어 헤쳐진 가벼운 양털처럼 움직일 것이라.",
  101006: "그러니 선행이 악행보다 많아 자신의 행위 저울이 선행으로 기운다면",
  101007: "그는 천국에서 행복한 삶을 누릴 것이라.",
  101008: "그러나 악행이 선행보다 많아 자신의 행위 저울이 악행으로 기운다면",
  101009: "심판의 날 그가 거주하게 될 곳은 지옥이라.",
  101010: "그 누가 그대 - 사도여! - 에게 이 지옥이 무엇인지를 알려줄 것인가?",
  101011: "그곳은 극한의 뜨거움으로 타오르는 불구덩이라.",
  102000: "앗-타카쑤르 (더 많이 갖기 위한 경쟁)\n계시 분류: 메카\n•    계시 목적    \n이 장은 현세에 몰두하고 있는 자들에게 죽음과 심판을 상기시켜 주고 있다.\n•    요약 주해",
  102001: "그대들 - 인간들이여! -은 재산과 자식을 뽐내기 위한 경쟁에만 몰두한 나머지 하나님께 순종해야 함은 잊었도다.",
  102002: "죽어서 무덤에 들어갈 때까지 그대들은 그렇게 경쟁하노라.",
  102003: "그러한 경쟁으로 인해 하나님께 순종해야 함을 잊는 일은 합당치 않으며, 이러한 망각에 대한 결과가 무엇인지 그대들은 곧 알게 될 것이라.",
  102004: "다시 한번, 그대들은 그 결과가 무엇인지 곧 알게 될 것이라.",
  102005: "그대들이 하나님께로 부활할 것이며 그분께서 그대들의 행위를 심판하실 것임을 확신하고 있었더라면 그대들은 재산과 자식에 몰두한 채 내세를 잊지 않았을 것이라.",
  102006: "진실로 그대들은 심판의 날 뜨겁게 타오르는 불을 목격할 것이라.",
  102007: "다시 한번, 진실로 그대들은 한치의 의심도 없이 확실하게 그 불을 목격할 것이라.",
  102008: "그런 후, 진실로 하나님께서는 이날, 그대들이 현세에서 누렸던 건강과 재산 등의 은총에 관하여 그대들에게 질문하실 것이라.",
  103000: "알-아쓰르 (시간)\n계시 분류: 메카\n•    계시 목적    \n이 장은 현세의 진정한 이익과 손실이 무엇인지 밝히면서 인간이 사용하는 시간의 중요성에 대해 주의를 환기하고 있다.\n•    요약 주해",
  103001: "하나님께서는 낮 시간을 두고 맹세하시니",
  103002: "진실로 인간은 부족하며 파멸에 직면할 존재라.",
  103003: "그러나 하나님을 믿고 그분의 사도를 따르면서 선행을 실천하고, 서로에게 진리를 권유하며 진리를 따름에 인내할 것을 권유하는 자들은 현세와 내세의 삶에서 그러한 손실을 면할 것이라.",
  104000: "알-후마자 (험담하는 자)\n계시 분류: 메카\n•    계시 목적    \n이 장은 이슬람에 대해 거만해 하며 무슬림을 조롱하는 자들을 경고하고 있다.\n•    요약 주해",
  104001: "사람들 간에 험담을 일삼고 조롱하는 자에게 혹독한 벌이 있을 것이라.",
  104002: "그에게는 재산을 벌어 얼마나 모았는지 확인하는 것이 매우 중요한 일이며",
  104003: "그는 자신이 모은 재산으로 현세에서 죽지 않고 영원히 살 수 있을 것이라 생각하노라.",
  104004: "진실은, 이 무지한 자가 생각하는 것과는 다르노라. 그는 지옥으로 내던져질 것이니, 그곳은 들어오는 모든 것들을 부숴버리는 참혹한 장소라.",
  104005: "그 누가 그대 - 사도여! - 에게 모든 것을 부숴버리는 곳이 무엇인지를 알려줄 것인가?",
  104006: "그곳은 불타오르는 하나님의 지옥으로서",
  104007: "그 불은 인간의 몸을 뚫고 들어가 가슴을 파고드노라.",
  104008: "실로 지옥 불은 고통 받는 자들 위에 굳게 닫혀 있으며",
  104009: "길게 뻗친 기둥들에 감싸져 있어 지옥의 거주자들은 그곳을 결코 빠져 나가지 못하노라.",
  105000: "알-필 (코끼리)\n계시 분류: 메카\n•    계시 목적    \n이 장은 하나님께서 카으바 성전을 보호하신 사건을 언급함으로써 그분의 위대한 능력과 드넓은 은총을 상기시키고 있다.\n•    요약 주해",
  105001: "그대 -사도여! - 는 카으바를 부수려 한 아브라하와 그 무리들을 하나님께서 어떻게 하셨는지 알지 못하는가?",
  105002: "하나님께서는 카으바를 파괴하려던 그들의 계획을 물거품으로 만드셨고, 그들의 바람과는 달리 사람들이 변함없이 카으바를 방문하였기에, 그들은 그 어떤 목적도 이루지 못하였노라.",
  105003: "하나님께서는 그들 위로 무리지어 차례로 날아드는 새들을 보내셨으니",
  105004: "새들이 그들에게 찰흙으로 만들어진 돌멩이를 투석하였노라.",
  105005: "그리하여 하나님께서는 그들을 마치, 가축들이 먹고 나서 밟아 버린 농작물의 잎사귀와 같은 것으로 만드셨노라.",
  106000: "꾸라이쉬 (꾸라이쉬 부족)\n계시 분류: 메카\n•    계시 목적    \n이 장은 꾸라이쉬 부족에 내려진 은총을 상기시키면서 그들이 그 은총에 상응하는 행위를 해야 함을 말하고 있다.\n•    요약 주해",
  106001: "하나님께서는 꾸라이쉬 부족이 주기적으로 교역할 수 있도록 해주셨으니",
  106002: "겨울에는 예맨 지역으로, 여름에는 샴 지역으로 그들이 대상 무역을 할 수 있도록 배려하셨노라.",
  106003: "그러니 꾸라이쉬 부족은, 이 성스러운 건축물의 주님이시자 그들의 여행길을 쉽게 해 주신 하나님 한 분만을 경배하도록 하고 그분께 어떤 대등한 존재도 두지 않도록 하라.",
  106004: "이는, 기아에 시달리던 꾸라이쉬 부족에게 풍성한 양식을 제공하신 분이 하나님이시기 때문이라. 또한 아랍인의 마음속에 메카 지역과 그 주민들에 대한 존경심을 둠으로써 꾸라이쉬 부족에게 안전을 제공하신 분이 하나님이시기 때문이라.",
  107000: "알-마운 (사소한 일용품)\n계시 분류: 메카\n•    계시 목적    \n이 장은 심판과 내세를 부정하는 자들의 심성을 묘사함으로써 믿는 자들에게는 경고를, 불신하는 자들에게는 오명을 주고 있다.\n•    요약 주해",
  107001: "부활의 날에 있을 하나님의 심판을 부정하는 자가 있으니, 그대는 그를 알지 못하는가?",
  107002: "그는 처지가 어려운 고아를 매정하게 밀치며",
  107003: "가난한 자들에게 음식을 주지도 않고, 음식을 주자고 사람들에게 권유하지도 않는 자라.",
  107004: "그러니 위선적으로 예배 드리는 자들에게 파멸과 징벌이 있을 것이라; 그들은 정해진 예배 시간이 끝나기 직전까지 게으름을 부리는 자들이며",
  107005: "그러니 위선적으로 예배 드리는 자들에게 파멸과 징벌이 있을 것이라; 그들은 정해진 예배 시간이 끝나기 직전까지 게으름을 부리는 자들이며",
  107006: "그들은 실로 하나님을 위해서가 아닌, 사람들에게 보여줄 목적으로 예배와 선행을 행하는 자들로서",
  107007: "잠시 빌려준다고 해서 손해될 것이 없는 간단한 일상용품조차도 선뜻 빌려주지 않는 자들이라.",
  108000: "알-카우싸르 (카우싸르 호수)\n계시 분류: 메카\n•    계시 목적    \n이 장은 선지자에게 주어진 하나님의 은총을 상기시키면서, 적대적인 자들이 선지자에게 접근할 길은 단절되었음을 말하고 있다.\n•    요약 주해",
  108001: "실로 하나님께서는 그대 - 사도여! - 에게 훌륭한 것들을 많이 베풀어 주셨으니 그 중의 하나는 천국에 있는 카우싸르 호수라.",
  108002: "그러니 그대는 하나님의 이 커다란 은총에 보답하라: 그대는 하나님 한 분만을 위해 예배를 드리고, 우상에게 희생물을 바치는 저들과 달리 그대는 하나님만을 위해 희생 동물을 바치라.",
  108003: "실로 그대를 증오하는 자, 그야말로 좋은 것이 모두 차단된 자로, 그의 이름은 오직 악명으로만 기억될 것이라.",
  109000: "알-카피룬 (불신자들)\n계시 분류: 메카\n•    계시 목적    \n이 장은 경배의 대상은 오직 하나님 한 분 뿐이며 다신 사상은 이슬람의 믿음과 무관함을 말함으로써, 이슬람과 다신론은 완전히 다른 것임을 강조하고 있다.\n•    요약 주해",
  109001: "그대 - 사도여! - 는 말하라. “하나님을 불신하는 자들이여! ”",
  109002: "“나는 그대들이 숭배하는 우상들을 숭배하지 않고 앞으로도 저것들을 숭배하는 일은 없을 것이며”",
  109003: "“그대들 역시 내가 경배하는 하나님을 경배하지 않노라”",
  109004: "“그리고 나는 그대들이 숭배하던 우상들을 숭배하는 자가 아니며”",
  109005: "“그대들 역시 내가 경배하는 하나님을 경배하지 않노라”",
  109006: "“그대들에게는 그대들이 만들어낸 종교가 있고 나에게는 하나님께서 계시하신 종교가 있노라”",
  110000: "안-나쓰르 (도움)\n계시 분류: 메디나\n•    계시 목적    \n이 장은 이슬람의 결말은 도움과 승리임을 알리면서 그 때 무슬림이 해야 할 일이 무엇인지를 말하고 있다. 한편 이 장의 내용은 선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 의 타계가 가까워졌음을 암시하기도 한다.\n•    요약 주해",
  110001: "하나님께서 그대 - 사도여! - 를 도우시어 그대가 메카로 입성하고",
  110002: "많은 사람들이 군집을 이루어 이슬람으로 입교하는 것을 목격한다면",
  110003: "이때는 그대의 임무가 끝나 가는 시점임을 알라. 따라서 이때는 그대가 받은 도움과 승리에 감사하면서 하나님의 완벽한 영광을 드높이라. 또한 그대는 하나님께 용서를 구하라. 진실로 그분께서는 참회하는 종복들을 받아 주시고 그들의 죄를 용서해 주시는 분이라.",
  111000: "알-마사드 (질긴 밧줄)\n계시 분류: 메카\n•    계시 목적    \n이 장은 그 어떤 가문이나 명예도 하나님을 불신하는 자에게는 도움이 되지 못함을 밝히고 있다.\n•    요약 주해",
  111001: "선지자 (하나님께서 그에게 자비와 평화를 베푸시길) 의 삼촌 '아부 라합 이븐 압둘 뭇딸립'의 두 손은 파멸되었노라. 이는 선지자를 집요하게 박해하던 그의 행위 때문이니 그의 노력은 헛되었노라.",
  111002: "그의 재산과 자식은 (내세에서) 그가 받을 벌을 막아 주지도 못하고 그에게 자비를 가져다 주지도 못하는데 저것들이 도대체 그에게 무슨 도움이 된단 말인가?",
  111003: "그는 부활의 날 불길이 넘실거리는, 형언할 수 없이 뜨거운 지옥 속으로 들어갈 것이라.",
  111004: "그의 아내 ‘움무 자밀’도 지옥에 들어갈 것이니, 선지자가 지나가는 길에 가시를 뿌리는 등 그녀는 그를 모질게 학대했기 때문이라.",
  111005: "그녀의 목에는 견고하게 꼬아 만든 밧줄이 있어 그 밧줄이 그녀를 지옥으로 끌고 갈 것이라.",
  112000: "알-이클라쓰 (진실성)\n계시 분류: 메카\n•    계시 목적    \n이 장은 완벽하신 하나님 한 분만이 경배받을 권리가 있으며 그분께는 그 어떤 단점도 있을 수 없음을 밝히고 있다.\n•    요약 주해",
  112001: "그대 - 사도여! - 는 말하라. “그분은 하나님으로서, 신성을 지니신 유일한 분으로, 경배받을 권리는 그분만이 가지시노라”",
  112002: "“하나님께서는 궁극의 완벽함과 아름다움을 지니신 분으로서, 모든 피조물은 그분께 의지하노라”",
  112003: "“그분께서는 누구를 낳은 적이 없으며, 그분을 누군가가 낳은 적도 없노라: 그러하기에 그분에게는 아들도 아버지도 존재하지 않노라”",
  112004: "“그리고 그분과 유사한 것은 있을 수 없노라”",
  113000: "알-팔라끄 (새벽녘)\n계시 분류: 메카\n•    계시 목적    \n이 장은 밖으로 드러나는 해악으로부터 보호받기 위해 하나님께 보호를 간구해야 함을 말하고 있다.\n•    요약 주해",
  113001: "그대 - 사도여! - 는 말하라. “저는 새벽녘의 주님이신 하나님께 보호를 요청 드립니다”",
  113002: "“피조물에서 발생하는 해악으로부터”",
  113003: "“날이 어두워진 뒤에야 모습을 드러내는 짐승과 인간의 해악으로부터”",
  113004: "“매듭을 지은 뒤 그 안에 숨을 불어 넣음으로써 주술을 부리는 여주술사의 해악으로부터”",
  113005: "“시기심에 휩싸인 자가 저지르는 사악한 시기 행위로부터 하나님께 보호를 요청 드립니다”",
  114000: "안-나스 (인류)\n계시 분류: 메카\n•    계시 목적    \n이 장은 사탄과 그의 속삭임 등 보이지 않는 해악으로부터 보호받기 위해 하나님께 보호를 간구해야 함을 말하고 있다.\n•    요약 주해",
  114001: "그대 - 사도여! - 는 말하라. “저는 인류의 주님이신 하나님께 보호를 요청 드립니다”",
  114002: "“의지하시는 대로 행하시는 그분께서는 인류의 유일한 제왕이시며”",
  114003: "“인류의 경배를 받을 권리를 지닌 유일한 분이십니다”",
  114004: "“사탄은, 인간이 하나님을 떠올릴 때는 숨어들다가 인간이 부주의해지면 그에게 다시금 속삭이고”",
  114005: "“인간의 마음속에 저의 속삭임을 불어 넣습니다”",
  114006: "“진 (Jinn) 의 형태로, 그리고 인간의 형태로 나타나는 이러한 사탄의 해악으로부터 저는 하나님께 보호를 요청 드립니다”",
};

String? getTafsirMokhtasarKorean(int surah, int ayah) => _mokhtasarKorean[surah * 1000 + ayah];
